CBUGER_RADIAL_FADE_STATE = CBUGER_RADIAL_FADE_STATE or {}

local function CBUGER_FADE_NOW_MS()
    local ok, value = pcall(function()
        if ffi and ffi.C and ffi.C.GetTickCount then
            return tonumber(ffi.C.GetTickCount())
        end
        return nil
    end)
    if ok and value then return value end
    return os.clock() * 1000.0
end

local function CBUGER_FADE_SMOOTHSTEP(t)
    t = math.max(0.0, math.min(1.0, tonumber(t) or 0.0))
    return t * t * (3.0 - 2.0 * t)
end

function CBUGER_UPDATE_MODULE_FADE(id, target, speed)
    local key = tostring(id or 'module')
    local st = CBUGER_RADIAL_FADE_STATE[key]
    if type(st) ~= 'table' then
        st = {
            alpha = target and 1.0 or 0.0,
            from = target and 1.0 or 0.0,
            to = target and 1.0 or 0.0,
            started_ms = CBUGER_FADE_NOW_MS(),
            duration_ms = 180.0,
        }
        CBUGER_RADIAL_FADE_STATE[key] = st
    end

    target = target and true or false
    local desired = target and 1.0 or 0.0

    if not CBUGER_GET_SMOOTH_CLOSE() then
        st.alpha = desired
        st.from = desired
        st.to = desired
        st.started_ms = CBUGER_FADE_NOW_MS()
        return desired
    end

    local now_ms = CBUGER_FADE_NOW_MS()
    if st.to ~= desired then
        local sp = tonumber(speed) or CBUGER_GET_ANIM_RATE(15)
        if sp < 0.1 then sp = 0.1 end
                local duration = 180.0 * (15.0 / sp)
        duration = math.max(80.0, math.min(280.0, duration))
        st.from = tonumber(st.alpha) or 0.0
        st.to = desired
        st.started_ms = now_ms
        st.duration_ms = duration
    end

    local elapsed = math.max(0.0, now_ms - (tonumber(st.started_ms) or now_ms))
    local duration_ms = math.max(1.0, tonumber(st.duration_ms) or 180.0)
    local t = math.min(1.0, elapsed / duration_ms)
    local eased = CBUGER_FADE_SMOOTHSTEP(t)
    st.alpha = (tonumber(st.from) or 0.0) + ((st.to or desired) - (tonumber(st.from) or 0.0)) * eased

    if t >= 1.0 then
        st.alpha = desired
        st.from = desired
        st.to = desired
    end

    return math.max(0.0, math.min(1.0, tonumber(st.alpha) or desired))
end

function CBUGER_MODULE_ACTIVE(id, target, speed)
    local key = tostring(id or 'module')
    local st = CBUGER_RADIAL_FADE_STATE[key]
    if target then return true end
    if type(st) ~= 'table' then return false end
    local a = tonumber(st.alpha) or 0.0
    return a > 0.01
end
