Data.nfn.BeginStandardPopupStyle = function()
    local im = Lib.imgui
    im.PushStyleVarVec2(im.StyleVar.WindowPadding, im.ImVec2(18, 12))
    im.PushStyleVarVec2(im.StyleVar.ItemSpacing, im.ImVec2(8, 8))
    im.PushStyleVarVec2(im.StyleVar.FramePadding, im.ImVec2(8, 4))
    im.PushStyleVarFloat(im.StyleVar.WindowRounding, 6)
    return 4
end
Data.nfn.EndStandardPopupStyle = function(count)
    if count and count > 0 then Lib.imgui.PopStyleVar(count) end
end
Data.nfn.BeginColorPopupStyle = function()
    Lib.imgui.SetNextWindowSize(Lib.imgui.ImVec2(261, 0), Lib.imgui.Cond.Always)
end
Data.nfn.EndColorPopupStyle = function()
end
do
    local im = Lib.imgui
    if type(im) == 'table' and type(im.BeginPopup) == 'function'
        and not im.__CBUGER_STANDARD_POPUP_STYLE then
        im.__CBUGER_STANDARD_POPUP_STYLE = true
        local orig_begin_popup = im.BeginPopup
        local orig_begin_modal = im.BeginPopupModal
        local orig_end_popup = im.EndPopup
        local orig_ctx_item = im.BeginPopupContextItem
        local orig_ctx_window = im.BeginPopupContextWindow
        local orig_ctx_void = im.BeginPopupContextVoid
        local popup_style_stack = {}
        local context_depth = 0
        local popup_wrap = {}
        popup_wrap.BeginPopup = function(name, flags, ...)
            if context_depth > 0 then
                return orig_begin_popup(name, flags, ...)
            end
            local count = Data.nfn.BeginStandardPopupStyle()
            local ok, opened = pcall(orig_begin_popup, name, flags, ...)
            if not ok then
                Data.nfn.EndStandardPopupStyle(count)
                error(opened, 0)
            end
            if opened then
                popup_style_stack[#popup_style_stack + 1] = count
                return true
            end
            Data.nfn.EndStandardPopupStyle(count)
            return false
        end
        if type(orig_begin_modal) == 'function' then
            popup_wrap.BeginPopupModal = function(name, p_open, flags, ...)
                local count = Data.nfn.BeginStandardPopupStyle()
                local ok, opened = pcall(orig_begin_modal, name, p_open, flags, ...)
                if not ok then
                    Data.nfn.EndStandardPopupStyle(count)
                    error(opened, 0)
                end
                if opened then
                    popup_style_stack[#popup_style_stack + 1] = count
                    return true
                end
                Data.nfn.EndStandardPopupStyle(count)
                return false
            end
        end
        local function wrap_context(original, ...)
            local count = Data.nfn.BeginStandardPopupStyle()
            context_depth = context_depth + 1
            local ok, opened = pcall(original, ...)
            context_depth = math.max(0, context_depth - 1)
            if not ok then
                Data.nfn.EndStandardPopupStyle(count)
                error(opened, 0)
            end
            if opened then
                popup_style_stack[#popup_style_stack + 1] = count
                return true
            end
            Data.nfn.EndStandardPopupStyle(count)
            return false
        end
        if type(orig_ctx_item) == 'function' then
            popup_wrap.BeginPopupContextItem = function(...) return wrap_context(orig_ctx_item, ...) end
        end
        if type(orig_ctx_window) == 'function' then
            popup_wrap.BeginPopupContextWindow = function(...) return wrap_context(orig_ctx_window, ...) end
        end
        if type(orig_ctx_void) == 'function' then
            popup_wrap.BeginPopupContextVoid = function(...) return wrap_context(orig_ctx_void, ...) end
        end
        popup_wrap.EndPopup = function(...)
            local ok, err = pcall(orig_end_popup, ...)
            local count = table.remove(popup_style_stack)
            if count then Data.nfn.EndStandardPopupStyle(count) end
            if not ok then error(err, 0) end
        end
        for k, v in pairs(popup_wrap) do rawset(im, k, v) end
    end
end
Data.nfn.CustomColorPicker = function(label, id_string, color_ref, has_alpha, alpha_mult)
    local w, h = 24, 24
    local p  = Lib.imgui.GetCursorScreenPos()
    local dl = Lib.imgui.GetWindowDrawList()
    local center = Lib.imgui.ImVec2(p.x + w/2, p.y + h/2)
    local popup_id = "ncp_" .. id_string
   Lib.imgui.InvisibleButton("nbtn_"..id_string, Lib.imgui.ImVec2(w, h))
    local hovered = Lib.imgui.IsItemHovered()
    local clicked = Lib.imgui.IsItemClicked()
    if hovered then Data.nfn.set_hand_cursor() end
    if clicked  then Lib.imgui.OpenPopup(popup_id) end
    local u32_col = Data.nfn.pack_color(color_ref[1], color_ref[2], color_ref[3], color_ref[4] or 1.0, true, alpha_mult or 1.0)
    dl:AddCircleFilled(center, w/2 - 2, u32_col, 24)
    local bpc = neon_fx.button_border_color
    local bpu = Data.nfn.pack_color(bpc[1], bpc[2], bpc[3], hovered and (bpc[4] or 1) or (bpc[4] or 1) * 0.55, false, alpha_mult or 1.0)
    dl:AddCircle(center, w/2 - 2, bpu, 24, hovered and 1.8 or 1.5)
   Lib.imgui.SameLine(0, 10)
   Lib.imgui.SetCursorPosY(Lib.imgui.GetCursorPosY() + 2)
   Lib.imgui.Text(label)
   Data.nfn.record_width(Lib.imgui.CalcTextSize(label).x + 80)
    local changed = false
   Lib.imgui.PushStyleVarFloat(Lib.imgui.StyleVar.Alpha, alpha_mult or 1.0)
   Lib.imgui.PushStyleColor(Lib.imgui.Col.Text, Lib.imgui.ImVec4(1.0, 1.0, 1.0, 1.0))
    Data.nfn.BeginColorPopupStyle()
    if Lib.imgui.BeginPopup(popup_id) then
        local t_col = Data.neon_active_colors[Lib.imgui.Col.Text] or {1.0, 1.0, 1.0, 1.0}
       Lib.imgui.TextColored(Lib.imgui.ImVec4(t_col[1], t_col[2], t_col[3], 1.0), label)
       Lib.imgui.Separator()
        if not Data.neon_color_pickers[id_string] then
           Data.neon_color_pickers[id_string] = Lib.new.float[4](
                color_ref[1] or 1.0, color_ref[2] or 1.0, color_ref[3] or 1.0, color_ref[4] or 1.0)
        end
        local st = Data.neon_color_pickers[id_string]
        local _ga = CBUGER_GET_INTERFACE_ALPHA()
        local _base_a = math.max(0.0, math.min(1.0, tonumber(color_ref[4]) or 1.0))
        st[0] = color_ref[1] or 1.0
        st[1] = color_ref[2] or 1.0
        st[2] = color_ref[3] or 1.0
        st[3] = _base_a * _ga
        local cp_flags = 0
        if Lib.imgui.ColorEditFlags then
            cp_flags = (Lib.imgui.ColorEditFlags.NoSidePreview or 0) + (Lib.imgui.ColorEditFlags.NoSmallPreview or 0) + (Lib.imgui.ColorEditFlags.AlphaBar or 0)
        end
        if Lib.imgui.ColorPicker4("##npicker_"..id_string, st, cp_flags) then
            color_ref[1] = st[0]; color_ref[2] = st[1]
            color_ref[3] = st[2]
            if _ga > 0.0001 then
                color_ref[4] = math.max(0.0, math.min(1.0, st[3] / _ga))
            else
                color_ref[4] = 0.0
            end
            changed = true
        end
       Lib.imgui.EndPopup()
    end
    Data.nfn.EndColorPopupStyle()
   Lib.imgui.PopStyleColor(1)
   Lib.imgui.PopStyleVar(1)
    return changed
end
Data.nfn.ios_slider = function(label, val_ptr, min_v, max_v, alpha_mult, left_align)
    label = Fn.T(label)
    local pending_layout_dx = tonumber(Data.fixed_slider_pending_x or 0) or 0
    Data.fixed_slider_pending_x = 0
    local base_cursor_x = Lib.imgui.GetCursorPosX()
    local f_bg  = Data.neon_active_colors[Lib.imgui.Col.FrameBg]
    local f_act = Data.neon_active_colors[Lib.imgui.Col.FrameBgActive]
    if not f_bg or not f_act then Lib.imgui.SliderFloat("##"..label, val_ptr, min_v, max_v); return end
    local bg_col   = Data.nfn.pack_color(f_bg[1],f_bg[2],f_bg[3],f_bg[4],false,alpha_mult)
    local fill_col = Data.nfn.pack_color(f_act[1],f_act[2],f_act[3],f_act[4],false,alpha_mult)
    local glow_c   = {f_act[1],f_act[2],f_act[3],f_act[4]}
    local avail_w  = Lib.imgui.GetContentRegionAvail().x
    local w_orig   = avail_w*.8
    local offset_x = left_align and 0 or (avail_w-w_orig)/2
   Lib.imgui.SetCursorPosX(base_cursor_x + offset_x + pending_layout_dx)
   Lib.imgui.BeginGroup()
    local h_orig, p_orig, dl = 26, Lib.imgui.GetCursorScreenPos(), Lib.imgui.GetWindowDrawList()
   Lib.imgui.InvisibleButton("nslider_"..label, Lib.imgui.ImVec2(w_orig, h_orig))
    local active  = Lib.imgui.IsItemActive()
    local hovered = Lib.imgui.IsItemHovered()
    if active then
        neon.is_any_slider_active = true
        val_ptr[0] = math.max(min_v, math.min(max_v, (Lib.imgui.GetIO().MousePos.x-p_orig.x)/w_orig*(max_v-min_v)+min_v))
    end
    if hovered then Data.nfn.set_hand_cursor() end
   Data.neon_slider_anims[label] = Data.nfn.anim_update(Data.neon_slider_anims[label] or 1.0, active and 1.03 or 1.0, 15)
    local scale = Data.neon_slider_anims[label]
    local w, h = w_orig*scale, h_orig*scale
    local p = Lib.imgui.ImVec2(p_orig.x+(w_orig-w)/2, p_orig.y+(h_orig-h)/2)
    dl:AddRectFilled(p, Lib.imgui.ImVec2(p.x+w, p.y+h), bg_col, h/2)
    local progress = (val_ptr[0]-min_v)/(max_v-min_v)
    if progress > 0 then
        local fill_w = math.max(h, w*progress)
        dl:AddRectFilled(p, Lib.imgui.ImVec2(p.x+fill_w, p.y+h), fill_col, h/2)
        if active or hovered then Data.nfn.draw_neon_glow(dl, p, Lib.imgui.ImVec2(p.x+fill_w,p.y+h), glow_c, 5, 0.3, alpha_mult) end
    end
   Data.neon_button_anims[label] = Data.nfn.anim_update(Data.neon_button_anims[label] or 0.0, (hovered or active) and 1 or 0, 15)
    local t = Data.neon_button_anims[label]
    local _v = val_ptr[0]
    local val_text
    local _range_is_int = math.floor(min_v) == min_v and math.floor(max_v) == max_v
    local _range_over_one = (max_v - min_v) > 1
    if _range_is_int and _range_over_one and math.floor(_v) == _v then
        val_text = string.format("%d", math.floor(_v))
    else
        val_text = string.format("%d%%", _v * 100)
    end
    local label_size = Lib.imgui.CalcTextSize(label); local val_size = Lib.imgui.CalcTextSize(val_text)
   Data.nfn.record_width(label_size.x+100)
    local txt_col = Data.neon_active_colors[Lib.imgui.Col.Text] or {1,1,1,1}
    local c = progress > 0.5 and 0.1 or txt_col[1]
    if (1-t) > 0.01 then dl:AddText(Lib.imgui.ImVec2(p.x+(w-label_size.x)/2, p.y+(h-label_size.y)/2), Data.nfn.pack_color(txt_col[1],txt_col[2],txt_col[3],1-t,true,alpha_mult), label) end
    if t > 0.01     then dl:AddText(Lib.imgui.ImVec2(p.x+(w-val_size.x)/2,   p.y+(h-val_size.y)/2),   Data.nfn.pack_color(c,c,c,t,true,alpha_mult), val_text) end
   Lib.imgui.EndGroup()
   Lib.imgui.SetCursorPosX(base_cursor_x)
end
Data.nfn.DrawAutoText = function(text, wrapped, is_header)
    text = Fn.T(text)
    if is_header then
        local tc = neon_fx.title_color
       Lib.imgui.TextColored(Lib.imgui.ImVec4(tc[1] or 1.0, tc[2] or 1.0, tc[3] or 1.0,
            (tc[4] or 1.0) * neon.global_alpha), text)
       Data.nfn.record_width(Lib.imgui.CalcTextSize(text).x)
    elseif wrapped then
       Lib.imgui.TextWrapped(text)
    else
       Lib.imgui.Text(text)
       Data.nfn.record_width(Lib.imgui.CalcTextSize(text).x)
    end
end
Data.nfn.ios_toggle = function(label, bool_ptr, alpha_mult, txt_col_override)
    label = Fn.T(label)
    local dl  = Lib.imgui.GetWindowDrawList()
    local h, w = 18, 33
    local txt_col = txt_col_override or Data.neon_active_colors[Lib.imgui.Col.Text] or {1,1,1,1}
   Lib.imgui.BeginGroup()
   Lib.imgui.SetWindowFontScale(0.9)
   Lib.imgui.TextColored(Lib.imgui.ImVec4(txt_col[1] or 1, txt_col[2] or 1, txt_col[3] or 1, 0.7*neon.global_alpha*(alpha_mult or 1)), label)
   Lib.imgui.SetWindowFontScale(1.0)
   Data.nfn.record_width(Lib.imgui.CalcTextSize(label).x+100)
   Lib.imgui.SameLine(Lib.imgui.GetWindowContentRegionMax().x-w-25)
    local p, id = Lib.imgui.GetCursorScreenPos(), "ntoggle_"..label
   Lib.imgui.InvisibleButton(id, Lib.imgui.ImVec2(w, h))
    if Lib.imgui.IsItemClicked() then bool_ptr[0] = not bool_ptr[0] end
    if Lib.imgui.IsItemHovered() then Data.nfn.set_hand_cursor() end
   Data.neon_button_anims[id] = Data.nfn.anim_update(Data.neon_button_anims[id] or (bool_ptr[0] and 1 or 0), bool_ptr[0] and 1 or 0, 15)
    local t = Data.neon_button_anims[id]
    local bg_off = Data.neon_active_colors[Lib.imgui.Col.FrameBg]   or {0.2,0.2,0.2,1}
    local bg_on  = Data.neon_active_colors[Lib.imgui.Col.CheckMark] or {0,0.8,1,1}
    local cur_r = Data.nfn.lerp(bg_off[1],bg_on[1],t); local cur_g = Data.nfn.lerp(bg_off[2],bg_on[2],t); local cur_b = Data.nfn.lerp(bg_off[3],bg_on[3],t)
    local glow_c = {bg_on[1],bg_on[2],bg_on[3],bg_on[4] or 1}
    dl:AddRectFilled(p, Lib.imgui.ImVec2(p.x+w,p.y+h), Data.nfn.pack_color(cur_r,cur_g,cur_b,bg_off[4] or 1,false,alpha_mult), h/2)
    if t > 0.1 then Data.nfn.draw_neon_glow(dl, p, Lib.imgui.ImVec2(p.x+w,p.y+h), glow_c, 3, t*.1, alpha_mult) end
    dl:AddCircleFilled(Lib.imgui.ImVec2(Data.nfn.lerp(p.x+h/2, p.x+w-h/2, t), p.y+h/2), h/2-2,
       Data.nfn.pack_color(0.9,0.9,0.9,1,true,alpha_mult), 24)
   Lib.imgui.EndGroup()
end
Data.nfn.draw_neon_glow = function(draw_list, p_min, p_max, color_rgb, thickness, intensity, alpha_mult)
    local ab = color_rgb[4] or 1
    for i = 1, thickness do
        local alpha = (intensity/thickness)*(thickness-i+1)*0.3*ab
        local col   = Data.nfn.pack_color(color_rgb[1],color_rgb[2],color_rgb[3],alpha,true,alpha_mult)
        draw_list:AddRect(Lib.imgui.ImVec2(p_min.x-i,p_min.y-i), Lib.imgui.ImVec2(p_max.x+i,p_max.y+i), col, 20, 15, 1.0)
    end
end
Data.nfn.draw_neon_border = function(draw_list, p_min, p_max, alpha_mult)
    local bc = neon_fx.neon_border_color
    local border_color = Data.nfn.pack_color(bc[1], bc[2], bc[3], bc[4] or 1, true, alpha_mult)
    draw_list:AddRect(p_min, p_max, border_color, 20, 15, 2.0)
    local tc = neon_fx.tabs_color; local ab = tc[4] or 1
    for i = 1, 4 do
        local alpha  = 0.20 * (1 - (i / 4)) * ab
        local col    = Data.nfn.pack_color(tc[1], tc[2], tc[3], alpha, true, alpha_mult)
        local offset = 3 + i * 2.0
        draw_list:AddRect(
           Lib.imgui.ImVec2(p_min.x - offset, p_min.y - offset),
           Lib.imgui.ImVec2(p_max.x + offset, p_max.y + offset),
            col, 20 + offset, 15, 1.0)
    end
end
Data.nfn.draw_police_ambient = function(draw_list, p_min, p_max, alpha_mult)
    if not neon_fx.ambient_on[0] then return end
    local time  = os.clock() * neon_fx.ambient_speed[0]
    local a_var = neon_fx.ambient_var[0]
    local c1, c2 = neon_fx.ambient_color_1, neon_fx.ambient_color_2
    local cx = p_min.x + (p_max.x - p_min.x)/2
    local cy = p_min.y + (p_max.y - p_min.y)/2
    local max_r = math.max(p_max.x - p_min.x, p_max.y - p_min.y)
    if a_var == 0 then
        local phase = math.sin(time*3)
        local int1 = math.max(0, phase)*0.15*(c1[4] or 1)
        local int2 = math.max(0,-phase)*0.15*(c2[4] or 1)
        draw_list:AddRectFilledMultiColor(p_min, p_max,
           Data.nfn.pack_color(c1[1],c1[2],c1[3],int1,false,alpha_mult), Data.nfn.pack_color(c2[1],c2[2],c2[3],int2,false,alpha_mult),
           Data.nfn.pack_color(c2[1],c2[2],c2[3],int2,false,alpha_mult), Data.nfn.pack_color(c1[1],c1[2],c1[3],int1,false,alpha_mult))
    elseif a_var == 1 then
        local phase = time % 1.0; local is_red = phase < 0.5
        local int = (phase%0.25 > 0.125) and 0.2 or 0.0
        local c = is_red and c2 or c1
        draw_list:AddRectFilled(p_min, p_max, Data.nfn.pack_color(c[1],c[2],c[3],int*(c[4] or 1),false,alpha_mult), 15)
    elseif a_var == 2 then
        local y_pos = p_min.y + ((math.sin(time*2)+1)/2)*(p_max.y-p_min.y)
        local int = 0.3*(c1[4] or 1)
        draw_list:AddRectFilledMultiColor(Lib.imgui.ImVec2(p_min.x,y_pos-30), Lib.imgui.ImVec2(p_max.x,y_pos),
           Data.nfn.pack_color(c1[1],c1[2],c1[3],0,false,alpha_mult), Data.nfn.pack_color(c1[1],c1[2],c1[3],0,false,alpha_mult),
           Data.nfn.pack_color(c1[1],c1[2],c1[3],int,false,alpha_mult), Data.nfn.pack_color(c1[1],c1[2],c1[3],int,false,alpha_mult))
        draw_list:AddRectFilledMultiColor(Lib.imgui.ImVec2(p_min.x,y_pos), Lib.imgui.ImVec2(p_max.x,y_pos+30),
           Data.nfn.pack_color(c1[1],c1[2],c1[3],int,false,alpha_mult), Data.nfn.pack_color(c1[1],c1[2],c1[3],int,false,alpha_mult),
           Data.nfn.pack_color(c1[1],c1[2],c1[3],0,false,alpha_mult), Data.nfn.pack_color(c1[1],c1[2],c1[3],0,false,alpha_mult))
    elseif a_var == 3 then
        local int = ((math.sin(time*2)+1)/2)*0.2*(c1[4] or 1)
        draw_list:AddRectFilled(p_min, p_max, Data.nfn.pack_color(c1[1],c1[2],c1[3],int,false,alpha_mult), 15)
    elseif a_var == 4 then
        local flash = (time%1 < 0.1) and 0.4 or 0.0
        draw_list:AddRectFilled(p_min, p_max, Data.nfn.pack_color(c1[1],c1[2],c1[3],flash*(c1[4] or 1),false,alpha_mult), 15)
    elseif a_var == 5 then
        for i = 0, 3 do
            local x_pos = p_min.x + ((math.sin(time*.5+i)+1)/2)*(p_max.x-p_min.x)
            local int = 0.1*(c1[4] or 1)
            draw_list:AddRectFilledMultiColor(Lib.imgui.ImVec2(x_pos-50,p_min.y), Lib.imgui.ImVec2(x_pos,p_max.y),
               Data.nfn.pack_color(c1[1],c1[2],c1[3],0,false,alpha_mult), Data.nfn.pack_color(c1[1],c1[2],c1[3],int,false,alpha_mult),
               Data.nfn.pack_color(c1[1],c1[2],c1[3],int,false,alpha_mult), Data.nfn.pack_color(c1[1],c1[2],c1[3],0,false,alpha_mult))
        end
    elseif a_var == 6 then
        local radius = ((time*2)%1)*max_r; local int = (1-((time*2)%1))*0.2*(c1[4] or 1)
        draw_list:AddCircleFilled(Lib.imgui.ImVec2(cx,cy), radius, Data.nfn.pack_color(c1[1],c1[2],c1[3],int,false,alpha_mult), 32)
    elseif a_var == 7 then
        local angle = time*2; local px = cx+math.cos(angle)*(max_r*.3); local py = cy+math.sin(angle)*(max_r*.3)
        draw_list:AddCircleFilled(Lib.imgui.ImVec2(px,py), 100, Data.nfn.pack_color(c1[1],c1[2],c1[3],0.2*(c1[4] or 1),false,alpha_mult), 32)
    elseif a_var == 8 then
        local pulse = math.abs(math.sin(time*3))^10; local int = pulse*0.3*(c1[4] or 1)
        draw_list:AddRectFilled(p_min, p_max, Data.nfn.pack_color(c1[1],c1[2],c1[3],int,false,alpha_mult), 15)
    elseif a_var == 9 then
        if math.random() > 0.95 then
            draw_list:AddRectFilled(Lib.imgui.ImVec2(p_min.x,cy-10), Lib.imgui.ImVec2(p_max.x,cy+10), Data.nfn.pack_color(c1[1],c1[2],c1[3],0.3*(c1[4] or 1),false,alpha_mult))
        end
    elseif a_var == 10 then
        local flicker = (math.random() > 0.1) and 0.2 or 0.0
        draw_list:AddRectFilled(p_min, p_max, Data.nfn.pack_color(c1[1],c1[2],c1[3],flicker*(c1[4] or 1),false,alpha_mult), 15)
    elseif a_var == 11 then
        local sweep = (math.sin(time*2)+1)/2; local wx = p_min.x+sweep*(p_max.x-p_min.x)
        draw_list:AddRectFilled(Lib.imgui.ImVec2(wx-20,p_min.y), Lib.imgui.ImVec2(wx+20,p_max.y), Data.nfn.pack_color(c1[1],c1[2],c1[3],0.2*(c1[4] or 1),false,alpha_mult))
    elseif a_var == 12 then
        local shift = (math.sin(time)+1)/2; local c = (shift > 0.5) and c1 or c2
        draw_list:AddRectFilled(p_min, p_max, Data.nfn.pack_color(c[1],c[2],c[3],0.1*(c[4] or 1),false,alpha_mult), 15)
    elseif a_var == 13 then
        draw_list:AddCircle(Lib.imgui.ImVec2(cx,cy), max_r*.6, Data.nfn.pack_color(c1[1],c1[2],c1[3],0.3*(c1[4] or 1),false,alpha_mult), 32, 20)
    elseif a_var == 14 then
        local int = (math.sin(time*10) > 0.8) and 0.2*(c1[4] or 1) or 0
        draw_list:AddRectFilled(p_min, p_max, Data.nfn.pack_color(c1[1],c1[2],c1[3],int,false,alpha_mult), 15)
    elseif a_var == 15 then
        draw_list:AddRectFilledMultiColor(p_min, p_max,
           Data.nfn.pack_color(c1[1],c1[2],c1[3],0.2*(c1[4] or 1),false,alpha_mult), Data.nfn.pack_color(0,0,0,0),
           Data.nfn.pack_color(c2[1],c2[2],c2[3],0.2*(c2[4] or 1),false,alpha_mult), Data.nfn.pack_color(0,0,0,0))
    end
end
Data.nfn.draw_wave_strings = function(draw_list, p_min, p_max, color_rgb, alpha_mult)
    if not neon_fx.waves_on[0] then return end
    local time = os.clock()*2*neon_fx.waves_speed[0]
    local h, w = p_max.y-p_min.y, p_max.x-p_min.x
    local centerY = p_min.y + h/2
    local col_r, col_g, col_b, col_a = color_rgb[1], color_rgb[2], color_rgb[3], color_rgb[4] or 1
   Lib.imgui.PushClipRect(Lib.imgui.ImVec2(p_min.x+10,p_min.y+2), Lib.imgui.ImVec2(p_max.x-10,p_max.y-2), true)
    local w_var = neon_fx.waves_var[0]
    if w_var == 0 then
        for i = 1, 3 do
            local speed, amplitude, frequency = i*.5, h*.15, 0.05
            local prev_p = nil
            for x = p_min.x, p_max.x, 4 do
                local y = centerY + math.sin(time*speed+(x-p_min.x)*frequency)*amplitude
                local curr = Lib.imgui.ImVec2(x,y)
                if prev_p then draw_list:AddLine(prev_p, curr, Data.nfn.pack_color(col_r,col_g,col_b,(0.4-i*.1)*col_a,false,alpha_mult), 1) end
                prev_p = curr
            end
        end
    elseif w_var == 1 then
        local bars = 15; local step = w/bars
        for i = 0, bars do
            local x = p_min.x+i*step; local phase = math.sin(time+i*.4); local bh = h*.4*math.abs(phase)
            draw_list:AddRectFilled(Lib.imgui.ImVec2(x+2,centerY-bh), Lib.imgui.ImVec2(x+step-2,centerY+bh),
               Data.nfn.pack_color(col_r,col_g,col_b,0.4*math.abs(phase)*col_a,false,alpha_mult), 2)
        end
    elseif w_var == 2 then
        local num_circles = 3; local mr = w > h and w or h
        for i = 1, num_circles do
            local phase = (time*.5+i/num_circles)%1; local radius = phase*mr; local alpha = (1-phase)*.5*col_a
            draw_list:AddCircle(Lib.imgui.ImVec2(p_min.x+w/2,centerY), radius, Data.nfn.pack_color(col_r,col_g,col_b,alpha,false,alpha_mult), 24, 2)
        end
    elseif w_var == 3 then
        local bs = 8
        for x = p_min.x, p_max.x, bs*1.5 do
            for y = p_min.y, p_max.y, bs*1.5 do
                local noise = math.sin(x*12.3+y*4.5+time*3)
                if noise > 0.6 then draw_list:AddRectFilled(Lib.imgui.ImVec2(x,y), Lib.imgui.ImVec2(x+bs,y+bs), Data.nfn.pack_color(col_r,col_g,col_b,(noise-.6)*2*col_a*.5,false,alpha_mult), 2) end
            end
        end
    elseif w_var == 4 then
        local prev_p = nil
        for x = p_min.x, p_max.x, 2 do
            local norm_x = (x-p_min.x)/w; local phase = (norm_x-time*.5)%1; local y_offset = 0
            if phase > 0.45 and phase < 0.55 then y_offset = math.sin((phase-.45)*10*math.pi)*(h*.4) end
            local curr = Lib.imgui.ImVec2(x, centerY-y_offset)
            if prev_p then draw_list:AddLine(prev_p, curr, Data.nfn.pack_color(col_r,col_g,col_b,.5*col_a,false,alpha_mult), 1.5) end
            prev_p = curr
        end
    elseif w_var == 5 then
        for x = p_min.x, p_max.x, 8 do
            local y1 = centerY+math.sin(time*2+x*.05)*(h*.25); local y2 = centerY+math.sin(time*2+x*.05+math.pi)*(h*.25)
            draw_list:AddLine(Lib.imgui.ImVec2(x,y1), Lib.imgui.ImVec2(x,y2), Data.nfn.pack_color(col_r,col_g,col_b,.2*col_a,false,alpha_mult), 1)
            draw_list:AddCircleFilled(Lib.imgui.ImVec2(x,y1), 2, Data.nfn.pack_color(col_r,col_g,col_b,.6*col_a,false,alpha_mult), 8)
            draw_list:AddCircleFilled(Lib.imgui.ImVec2(x,y2), 2, Data.nfn.pack_color(col_r,col_g,col_b,.6*col_a,false,alpha_mult), 8)
        end
    elseif w_var == 6 then
        local ccx, ccy = p_min.x+w/2, centerY; local angle = time*3
        draw_list:AddCircle(Lib.imgui.ImVec2(ccx,ccy), h*.4, Data.nfn.pack_color(col_r,col_g,col_b,.3*col_a,false,alpha_mult), 24, 1)
        draw_list:AddLine(Lib.imgui.ImVec2(ccx,ccy), Lib.imgui.ImVec2(ccx+math.cos(angle)*h*.4, ccy+math.sin(angle)*h*.4), Data.nfn.pack_color(col_r,col_g,col_b,.8*col_a,false,alpha_mult), 2)
    elseif w_var == 7 then
        local hex_s = 10
        for x = p_min.x, p_max.x, hex_s*1.5 do
            for y = p_min.y, p_max.y, hex_s*1.732 do
                local off_y = (math.floor(x/(hex_s*1.5))%2 == 1) and (hex_s*.866) or 0
                local alpha = (math.sin(x*.1+y*.1+time)+1)*.25*col_a
                draw_list:AddCircle(Lib.imgui.ImVec2(x,y+off_y), hex_s*.9, Data.nfn.pack_color(col_r,col_g,col_b,alpha,false,alpha_mult), 6, 1)
            end
        end
    elseif w_var == 8 then
        for i = 1, 4 do
            local ccx = p_min.x+w/2+math.sin(time+i)*(w*.3); local ccy = centerY+math.cos(time*1.3+i*2)*(h*.3)
            draw_list:AddCircleFilled(Lib.imgui.ImVec2(ccx,ccy), h*.4, Data.nfn.pack_color(col_r,col_g,col_b,.15*col_a,false,alpha_mult), 24)
        end
    elseif w_var == 9 then
        local pp1, pp2, pp3 = nil, nil, nil
        for x = p_min.x, p_max.x, 3 do
            local n_x = x*.05
            local y1 = centerY+math.sin(time*3+n_x)*h*.3
            local y2 = centerY+math.sin(time*2-n_x*1.5)*h*.2
            local y3 = centerY+math.sin(time*4+n_x*2)*h*.1
            if pp1 then draw_list:AddLine(pp1, Lib.imgui.ImVec2(x,y1), Data.nfn.pack_color(col_r,col_g,col_b,.3*col_a,false,alpha_mult), 1) end
            if pp2 then draw_list:AddLine(pp2, Lib.imgui.ImVec2(x,y2), Data.nfn.pack_color(col_r,col_g,col_b,.4*col_a,false,alpha_mult), 1.5) end
            if pp3 then draw_list:AddLine(pp3, Lib.imgui.ImVec2(x,y3), Data.nfn.pack_color(col_r,col_g,col_b,.5*col_a,false,alpha_mult), 2) end
            pp1, pp2, pp3 = Lib.imgui.ImVec2(x,y1), Lib.imgui.ImVec2(x,y2), Lib.imgui.ImVec2(x,y3)
        end
    elseif w_var == 10 then
        local ccx, ccy = p_min.x+w/2, centerY; local prev_p = nil
        for a = 0, 30, 0.2 do
            local r = a*2; local px = ccx+math.cos(a+time*5)*r; local py = ccy+math.sin(a+time*5)*r
            local curr_pt = Lib.imgui.ImVec2(px,py)
            if prev_p then draw_list:AddLine(prev_p, curr_pt, Data.nfn.pack_color(col_r,col_g,col_b,.4*col_a,false,alpha_mult), 1.5) end
            prev_p = curr_pt
        end
    elseif w_var == 11 then
        local ccx = p_min.x+w/2; local angle = math.sin(time*2)*.8+math.pi/2
        local px = ccx+math.cos(angle)*h; local py = p_min.y+math.sin(angle)*h
        draw_list:AddLine(Lib.imgui.ImVec2(ccx,p_min.y), Lib.imgui.ImVec2(px,py), Data.nfn.pack_color(col_r,col_g,col_b,.5*col_a,false,alpha_mult), 2)
        draw_list:AddCircleFilled(Lib.imgui.ImVec2(px,py), 6, Data.nfn.pack_color(col_r,col_g,col_b,col_a,false,alpha_mult), 16)
    elseif w_var == 12 then
        for x = p_min.x, p_max.x, 15 do
            for y = p_min.y, p_max.y, 15 do
                local dir = math.floor(math.sin(x*y+time)*2)%2
                if dir == 0 then draw_list:AddLine(Lib.imgui.ImVec2(x,y), Lib.imgui.ImVec2(x+15,y+15), Data.nfn.pack_color(col_r,col_g,col_b,.4*col_a,false,alpha_mult), 1.5)
                else draw_list:AddLine(Lib.imgui.ImVec2(x+15,y), Lib.imgui.ImVec2(x,y+15), Data.nfn.pack_color(col_r,col_g,col_b,.4*col_a,false,alpha_mult), 1.5) end
            end
        end
    elseif w_var == 13 then
        for i = 1, 30 do
            local sx = p_min.x+((i*43+time*50)%w); local sy = p_min.y+((i*17)%h)
            draw_list:AddCircleFilled(Lib.imgui.ImVec2(sx,sy), 1.5, Data.nfn.pack_color(col_r,col_g,col_b,(math.sin(time*3+i)+1)*.4*col_a,false,alpha_mult), 8)
        end
    elseif w_var == 14 then
        for i = 1, 15 do
            local ccx = p_min.x+((i*101+math.sin(time)*20)%w); local ccy = p_min.y+((i*73+math.cos(time)*20)%h)
            draw_list:AddCircle(Lib.imgui.ImVec2(ccx,ccy), math.abs(math.sin(time*2+i))*10+2, Data.nfn.pack_color(col_r,col_g,col_b,.5*col_a,false,alpha_mult), 12, 1)
        end
    elseif w_var == 15 then
        for x = p_min.x, p_max.x, 20 do
            local y_off = math.sin(x*.05+time*3)*15; local y = centerY+y_off
            local col15 = Data.nfn.pack_color(col_r,col_g,col_b,.6*col_a,false,alpha_mult)
            local pp1=Lib.imgui.ImVec2(x,y-5); local pp2=Lib.imgui.ImVec2(x+4,y-2); local pp3=Lib.imgui.ImVec2(x+4,y+2)
            local pp4=Lib.imgui.ImVec2(x,y+5); local pp5=Lib.imgui.ImVec2(x-4,y+2); local pp6=Lib.imgui.ImVec2(x-4,y-2)
            draw_list:AddLine(pp1,pp2,col15,1.5); draw_list:AddLine(pp2,pp3,col15,1.5); draw_list:AddLine(pp3,pp4,col15,1.5)
            draw_list:AddLine(pp4,pp5,col15,1.5); draw_list:AddLine(pp5,pp6,col15,1.5); draw_list:AddLine(pp6,pp1,col15,1.5)
        end
    elseif w_var == 16 then
        for x = p_min.x, p_max.x, 6 do
            local val = math.abs(math.sin(x*.1+time*5)*math.cos(x*.02-time))
            draw_list:AddLine(Lib.imgui.ImVec2(x,p_max.y), Lib.imgui.ImVec2(x,p_max.y-val*h), Data.nfn.pack_color(col_r,col_g,col_b,.5*col_a,false,alpha_mult), 3)
        end
    elseif w_var == 17 then
        local prev_p = nil
        for t_p = 0, math.pi*2, 0.05 do
            local px = p_min.x+w/2+math.sin(t_p*3+time*2)*w*.4
            local py = centerY+math.sin(t_p*4+time*3)*h*.4
            local curr_pt = Lib.imgui.ImVec2(px,py)
            if prev_p then draw_list:AddLine(prev_p, curr_pt, Data.nfn.pack_color(col_r,col_g,col_b,.5*col_a,false,alpha_mult), 1.5) end
            prev_p = curr_pt
        end
    elseif w_var == 18 then
        for y = p_min.y, p_max.y, 10 do
            local prev_p = nil
            for x = p_min.x, p_max.x, 5 do
                local dy = y-centerY; local curr_y = y+math.sin(x*.05+time*3)*(dy*.3)
                local curr_pt = Lib.imgui.ImVec2(x, curr_y)
                if prev_p then draw_list:AddLine(prev_p, curr_pt, Data.nfn.pack_color(col_r,col_g,col_b,.3*col_a,false,alpha_mult), 1) end
                prev_p = curr_pt
            end
        end
    end
   Lib.imgui.PopClipRect()
end
Data.nfn.draw_animated_settings_icon = function(draw_list, center, radius, hover_factor, time, alpha_mult)
    local g_c = neon_fx.icon_gear_color; local ab = g_c[4] or 1
    local rot1 = time*(1.5+hover_factor*8)
    local rot2 = -time*(2+hover_factor*10)
    for i = 1, 3 do
        local angle_start = rot1+(i-1)*(math.pi*2/3)
        local angle_end   = angle_start+(math.pi*2/3)*.5
        draw_list:PathArcTo(center, radius, angle_start, angle_end, 15)
        local r_arc = .5+.5*math.sin(time*4+i*2)
        local g_arc = .5+.5*math.sin(time*4+i*2+2)
        local b_arc = .5+.5*math.sin(time*4+i*2+4)
        draw_list:PathStroke(Data.nfn.pack_color(r_arc,g_arc,b_arc,(0.4+0.6*hover_factor)*ab,false,alpha_mult), 0, 2+hover_factor)
    end
    for i = 1, 6 do
        local angle = rot2+(i-1)*(math.pi*2/6)
        local p_out = Lib.imgui.ImVec2(center.x+math.cos(angle)*(radius*.7), center.y+math.sin(angle)*(radius*.7))
        local p_in  = Lib.imgui.ImVec2(center.x+math.cos(angle+.3)*(radius*.3), center.y+math.sin(angle+.3)*(radius*.3))
        draw_list:AddLine(p_out, p_in, Data.nfn.pack_color(g_c[1],g_c[2],g_c[3],(0.6+0.4*hover_factor)*ab,false,alpha_mult), 1.5)
    end
    draw_list:AddCircleFilled(center, radius*.25, Data.nfn.pack_color(g_c[1],g_c[2],g_c[3],ab,false,alpha_mult), 12)
end
Data.nfn.draw_cross = function(dl, center, radius, hovered, alpha_mult)
    local hf = hovered and 1.0 or 0.0; local c_c = neon_fx.icon_cross_color
    local col = Data.nfn.pack_color(c_c[1],c_c[2],c_c[3],(0.4+hf*.6)*(c_c[4] or 1),false,alpha_mult)
    local r = radius*.45; local t = 2+hf*.8
    dl:AddLine(Lib.imgui.ImVec2(center.x-r,center.y-r), Lib.imgui.ImVec2(center.x+r,center.y+r), col, t)
    dl:AddLine(Lib.imgui.ImVec2(center.x+r,center.y-r), Lib.imgui.ImVec2(center.x-r,center.y+r), col, t)
end
Data.nfn.draw_cross_fa = function(center, hovered, scale)
    scale = scale or 1.35
    local hf  = hovered and 1.0 or 0.0
    local c_c = neon_fx.icon_cross_color
   Lib.imgui.SetWindowFontScale(scale)
    local gs = Lib.imgui.CalcTextSize(fa.XMARK)
   Lib.imgui.SetCursorScreenPos(Lib.imgui.ImVec2(center.x - gs.x/2, center.y - gs.y/2))
   Lib.imgui.TextColored(Lib.imgui.ImVec4(c_c[1], c_c[2], c_c[3], (0.5+hf*.5)*(c_c[4] or 1)), fa.XMARK)
   Lib.imgui.SetWindowFontScale(1.0)
end
Data.nfn.draw_eye = function(dl, center, radius, closed_t, hovered, alpha_mult)
    local hf = hovered and 1.0 or 0.0; local e_c = neon_fx.icon_eye_color
    local col = Data.nfn.pack_color(e_c[1],e_c[2],e_c[3],(0.4+hf*.6)*(e_c[4] or 1),false,alpha_mult)
    local p0  = Lib.imgui.ImVec2(center.x-radius, center.y)
    local p3  = Lib.imgui.ImVec2(center.x+radius, center.y)
    local ty  = radius*(1.1-closed_t*1.1)
   Data.nfn.draw_safe_bezier(dl, p0, Lib.imgui.ImVec2(center.x-radius/2,center.y-ty), Lib.imgui.ImVec2(center.x+radius/2,center.y-ty), p3, col, 2+hf*.5)
   Data.nfn.draw_safe_bezier(dl, p0, Lib.imgui.ImVec2(center.x-radius/2,center.y+ty), Lib.imgui.ImVec2(center.x+radius/2,center.y+ty), p3, col, 2+hf*.5)
    if closed_t < 0.9 then
        local mp  = Lib.imgui.GetIO().MousePos
        local dx  = mp.x-center.x; local dy = mp.y-center.y
        local dist = math.sqrt(dx*dx+dy*dy)
        local max_dist = radius*.4*(1-closed_t)
        local p_x, p_y = center.x, center.y
        if dist > 0 then local md = math.min(dist, max_dist); p_x=center.x+(dx/dist)*md; p_y=center.y+(dy/dist)*md end
        local cy2 = radius*.8*(1-closed_t)
        if p_y > center.y+cy2 then p_y=center.y+cy2 end
        if p_y < center.y-cy2 then p_y=center.y-cy2 end
        dl:AddCircleFilled(Lib.imgui.ImVec2(p_x,p_y), radius*.4*(1-closed_t),
           Data.nfn.pack_color(e_c[1],e_c[2],e_c[3],(1-closed_t)*(e_c[4] or 1),false,alpha_mult), 16)
    end
end
Data.nfn.draw_dots_toggle = function(dl, center, is_vertical, hover_t, color, alpha_mult)
    local fx = CBUGER_GET_EFFECTS()
    local waves_on = not fx or not fx.waves_on or fx.waves_on[0]
    local speed = CBUGER_GET_EFFECT_SPEED(1.0)
    local base_r  = 2.4 + (hover_t or 0) * 1.3
    local spacing = 7.5
    local CYCLE   = 1.1
    local SEG     = CYCLE / 3
    local t = (os.clock() * speed) % CYCLE
    if not waves_on then
        local static_a = (color[4] or 1) * (alpha_mult or 1)
        for i = 1, 3 do
            local off = (i - 2) * spacing
            local pos = is_vertical
                and Lib.imgui.ImVec2(center.x, center.y + off)
                or  Lib.imgui.ImVec2(center.x + off, center.y)
            dl:AddCircleFilled(pos, base_r, Data.nfn.pack_color(color[1], color[2], color[3], static_a, true, 1.0), 16)
        end
        return
    end
    for i = 1, 3 do
        local seg_start = (i - 1) * SEG
        local seg_start = (i - 1) * SEG
        local local_t   = t - seg_start
        local scale     = 1.0
        if local_t >= 0 and local_t < SEG then
            local u = local_t / SEG
            scale = 1.0 + 0.75 * math.sin(u * math.pi)
        end
        local off = (i - 2) * spacing
        local pos = is_vertical
            and Lib.imgui.ImVec2(center.x, center.y + off)
            or  Lib.imgui.ImVec2(center.x + off, center.y)
        local glow_t = (scale - 1.0) / 0.75
        local a = (0.55 + 0.45 * glow_t) * (color[4] or 1)
        dl:AddCircleFilled(pos, base_r * scale,
           Data.nfn.pack_color(color[1], color[2], color[3], a, false, alpha_mult), 16)
    end
end
Data.nfn.draw_enhanced_cursor = function(draw_list, alpha_mult, do_update)
    if not neon_fx.sparks_on[0] then return end
    local mouse_pos = Lib.imgui.GetIO().MousePos
    if mouse_pos.x <= 0 or mouse_pos.y <= 0 then return end
    if do_update then
        local dx = mouse_pos.x - neon.last_mouse_pos.x
        local dy = mouse_pos.y - neon.last_mouse_pos.y
        local speed = math.sqrt(dx*dx + dy*dy)
        neon.last_mouse_pos = {x = mouse_pos.x, y = mouse_pos.y}
        if speed > 0.5 then
            neon.particle_tick = neon.particle_tick + 1
            for i = 1, 2 do
                local color     = neon_fx.sparks_color
                local mult      = neon_fx.sparks_speed[0]
                local size_base = neon_fx.sparks_size[0]
                local p_size, vX, vY, shrink_rate
                local c_var = neon_fx.cursor_fx_var[0]
                if     c_var ==  0 then p_size=(math.random(5,15)/10)*size_base;  vX=(math.random()-.5)*1.8*mult; vY=(math.random()-.5)*1.8*mult; shrink_rate=1.6*mult
                elseif c_var ==  1 then p_size=(math.random(8,20)/10)*size_base;  vX=(math.random()-.5)*1.0*mult; vY=(math.random(10,25)/10)*mult; shrink_rate=2.0*mult
                elseif c_var ==  2 then p_size=(math.random(10,30)/10)*size_base; vX=(math.random()-.5)*2.0*mult; vY=-(math.random(10,20)/10)*mult; shrink_rate=1.0*mult
                elseif c_var ==  3 then p_size=(math.random(4,10)/10)*size_base;  vX=0; vY=(math.random(15,30)/10)*mult; shrink_rate=1.5*mult
                elseif c_var ==  4 then p_size=(math.random(3,8)/10)*size_base;   vX=(math.random()-.5)*.5*mult; vY=(math.random()-.5)*.5*mult; shrink_rate=0.8*mult
                elseif c_var ==  5 then p_size=(math.random(15,25)/10)*size_base; vX=(math.random()-.5)*1.0*mult; vY=-(math.random(10,25)/10)*mult; shrink_rate=2.5*mult
                elseif c_var ==  6 then p_size=(math.random(20,40)/10)*size_base; vX=0; vY=0; shrink_rate=4.0*mult
                elseif c_var ==  7 then p_size=(math.random(2,6)/10)*size_base;   vX=(math.random()-.5)*5.0*mult; vY=(math.random()-.5)*5.0*mult; shrink_rate=3.0*mult
                elseif c_var ==  8 then p_size=(math.random(4,12)/10)*size_base;  vX=(math.random()-.5)*.8*mult; vY=(math.random(5,15)/10)*mult; shrink_rate=0.5*mult
                elseif c_var ==  9 then p_size=(math.random(10,30)/10)*size_base; vX=(math.random()-.5)*1.5*mult; vY=0; shrink_rate=5.0*mult
                elseif c_var == 10 then p_size=(math.random(8,16)/10)*size_base;  vX=(math.random()-.5)*3.0; vY=(math.random()-.5)*3.0; shrink_rate=0.8*mult
                elseif c_var == 11 then p_size=(math.random(4,12)/10)*size_base;  vX=(math.random()-.5)*2.0; vY=(math.random()-.5)*2.0; shrink_rate=1.0*mult
                elseif c_var == 12 then p_size=(math.random(10,20)/10)*size_base; vX=0; vY=(math.random(5,15)/10)*mult; shrink_rate=2.0*mult
                elseif c_var == 13 then p_size=(math.random(10,25)/10)*size_base; vX=(math.random(15,30)/10)*mult; vY=(math.random(15,30)/10)*mult; shrink_rate=3.0*mult
                elseif c_var == 14 then p_size=(math.random(10,30)/10)*size_base; vX=(math.random()-.5)*5.0*mult; vY=(math.random()-.5)*5.0*mult; shrink_rate=4.0*mult
                elseif c_var == 15 then p_size=(math.random(5,15)/10)*size_base;  vX=(math.random()-.5)*3.0; vY=(math.random()-.5)*3.0; shrink_rate=1.2*mult
                elseif c_var == 16 then p_size=(math.random(10,40)/10)*size_base; vX=0; vY=0; shrink_rate=2.0*mult
                elseif c_var == 17 then p_size=(math.random(5,15)/10)*size_base;  vX=(math.random()-.5)*2.0; vY=(math.random()-.5)*2.0; shrink_rate=1.5*mult
                elseif c_var == 18 then p_size=(math.random(6,14)/10)*size_base;  vX=(math.random()-.5)*3.0*mult; vY=-(math.random(10,20)/10)*mult; shrink_rate=1.2*mult
                else                    p_size=(math.random(20,50)/10)*size_base; vX=0; vY=0; shrink_rate=5.0*mult
                end
                table.insert(Data.neon_trail_particles, {
                    x=mouse_pos.x, y=mouse_pos.y, life=1.0,
                    size=p_size, velX=vX, velY=vY, shrink=shrink_rate,
                    col={color[1], color[2], color[3], color[4] or 1.0}, mode=c_var
                })
            end
        end
        for i = #Data.neon_trail_particles, 1, -1 do
            local p = Data.neon_trail_particles[i]
            p.life = p.life - Data.neon_ui_anim.dt * p.shrink
            p.x = p.x + p.velX; p.y = p.y + p.velY
            if p.mode == 4  and p.life > 0.1 then p.velX = p.velX + math.sin(os.clock()*5+p.life*10)*0.05 end
            if p.mode == 8  and p.life > 0.1 then p.velX = p.velX + math.sin(os.clock()*2+p.y*0.05)*0.1 end
            if p.mode == 10 and p.life > 0.1 then p.velX=p.velX+(mouse_pos.x-p.x)*0.05; p.velY=p.velY+(mouse_pos.y-p.y)*0.05 end
            if p.mode == 11 and p.life > 0.1 then p.velX=p.velX+(math.random()-.5)*.5; p.velY=p.velY+(math.random()-.5)*.5 end
            if p.mode == 15 and p.life > 0.1 then local dX=mouse_pos.x-p.x; local dY=mouse_pos.y-p.y; p.velX=p.velX+dY*0.1; p.velY=p.velY-dX*0.1 end
            if p.mode == 17 and p.life > 0.1 then p.x=p.x+math.sin(p.life*20)*2.0 end
            if p.mode == 18 then p.velY=p.velY+0.1 end
            if p.life <= 0 then table.remove(Data.neon_trail_particles, i) end
        end
    end
    for i = 1, #Data.neon_trail_particles do
        local p   = Data.neon_trail_particles[i]
        local u32 = Data.nfn.pack_color(p.col[1], p.col[2], p.col[3], p.life*p.col[4], true, alpha_mult)
        local m   = p.mode
        if     m == 1  then
            draw_list:AddLine(Lib.imgui.ImVec2(p.x-p.size*p.life,p.y), Lib.imgui.ImVec2(p.x+p.size*p.life,p.y), u32, 1.5)
            draw_list:AddLine(Lib.imgui.ImVec2(p.x,p.y-p.size*p.life), Lib.imgui.ImVec2(p.x,p.y+p.size*p.life), u32, 1.5)
        elseif m == 2  then draw_list:AddCircle(Lib.imgui.ImVec2(p.x,p.y), p.size*p.life, u32, 12, 1.5)
        elseif m == 3  then draw_list:AddRectFilled(Lib.imgui.ImVec2(p.x,p.y), Lib.imgui.ImVec2(p.x+2,p.y+p.size*p.life), u32)
        elseif m == 5  then draw_list:AddCircleFilled(Lib.imgui.ImVec2(p.x,p.y), p.size*p.life, Data.nfn.pack_color(1.0,p.life*.8,0,p.life*p.col[4],true,alpha_mult), 8)
        elseif m == 6 or m == 16 then draw_list:AddCircle(Lib.imgui.ImVec2(p.x,p.y), p.size*(1-p.life), u32, 16, 2.0)
        elseif m == 7 or m == 13 or m == 14 then draw_list:AddLine(Lib.imgui.ImVec2(p.x,p.y), Lib.imgui.ImVec2(p.x+p.velX*2,p.y+p.velY*2), u32, 1.5)
        elseif m == 9 or m == 12 then draw_list:AddRectFilled(Lib.imgui.ImVec2(p.x-p.size,p.y-1), Lib.imgui.ImVec2(p.x+p.size,p.y+1), u32)
        elseif m == 18 then
            local col18 = Data.nfn.pack_color(math.random(),math.random(),math.random(),p.life,true,alpha_mult)
            draw_list:AddRectFilled(Lib.imgui.ImVec2(p.x-p.size*p.life,p.y-p.size*p.life), Lib.imgui.ImVec2(p.x+p.size*p.life,p.y+p.size*p.life), col18)
        elseif m == 19 then
            local s=p.size
            local pp1=Lib.imgui.ImVec2(p.x,p.y-s); local pp2=Lib.imgui.ImVec2(p.x+s*.866,p.y-s*.5)
            local pp3=Lib.imgui.ImVec2(p.x+s*.866,p.y+s*.5); local pp4=Lib.imgui.ImVec2(p.x,p.y+s)
            local pp5=Lib.imgui.ImVec2(p.x-s*.866,p.y+s*.5); local pp6=Lib.imgui.ImVec2(p.x-s*.866,p.y-s*.5)
            draw_list:AddLine(pp1,pp2,u32,1.5); draw_list:AddLine(pp2,pp3,u32,1.5); draw_list:AddLine(pp3,pp4,u32,1.5)
            draw_list:AddLine(pp4,pp5,u32,1.5); draw_list:AddLine(pp5,pp6,u32,1.5); draw_list:AddLine(pp6,pp1,u32,1.5)
        else draw_list:AddCircleFilled(Lib.imgui.ImVec2(p.x,p.y), p.size*p.life, u32, 6)
        end
    end
    draw_list:AddCircleFilled(mouse_pos, 2.5,
       Data.nfn.pack_color(neon_fx.sparks_color[1], neon_fx.sparks_color[2], neon_fx.sparks_color[3],
                       neon_fx.sparks_color[4] or 1.0, true, alpha_mult), 16)
end
 Fn.neon_FontCombo = function(label, idx_ptr)
    label = Fn.T(label)
    local names = Fn.translateList(Data.neon_loaded_font_names)
    if #names == 0 then return end
    local items_arr = Lib.ffi.new("const char*[?]", #names, names)
    if idx_ptr[0] >= #names then idx_ptr[0] = 0 end
   Lib.imgui.PushItemWidth(250)
   Lib.imgui.Combo(label, idx_ptr, items_arr, #names)
