Fn.L = function(ru, en)
    if ui and ui.interface_lang and ui.interface_lang[0] == 2 then return en end
    return ru
end
Fn.translateList = function(list)
    local out = {}
    for i, v in ipairs(list) do
        out[i] = Fn.T(v)
    end
    return out
end

