            {text = u8'ПКМ',    key = 0x02, width = S.cfg.mouse.rmb_width,  height = S.cfg.mouse.rmb_height, close_gap = true},
        }
        local comboVisualsActive = st.current_combo ~= nil
        for i, btn in ipairs(mouse_buttons) do
