               Data.wave_key_index = Data.wave_key_index + dt * speed * 8
                if Data.wave_key_index > #Data.wave_keys_list + 1 then
                   Data.wave_key_index = 1.0
                   Data.wave_cycle     = Data.wave_cycle + 1
                end
