local function parseConfigText(text)
    if type(text) ~= 'string' or text == '' then return {}, false end
    local cfg = {}
    local section = 'general'
    local saw_section = false
    for line in (text .. '\n'):gmatch('([^\r\n]*)\r?\n') do
        local sec = line:match('^%[(.-)%]$')
        if sec then
            section = sec
            cfg[section] = cfg[section] or {}
            saw_section = true
        else
            local k, v = line:match('^([^=]+)=(.*)$')
            if k then
                cfg[section] = cfg[section] or {}
                cfg[section][k] = v
            end
        end
    end
    return cfg, saw_section and cfg.general ~= nil
end
local function readConfig()
    local function valid_config_text(raw)
        if type(raw) ~= 'string' or raw == '' then return false end
        local parsed, valid = parseConfigText(raw)
        local general = parsed and parsed.general or nil
        return valid and type(general) == 'table'
            and general.script_enabled ~= nil
            and general.auto_enable_on_join ~= nil
            and general.active_tab ~= nil
    end
    local text = CBUGER_SAFE_READ_TEXT(config_path, valid_config_text)
    if type(text) == 'string' then
        local cfg, valid = parseConfigText(text)
        if valid then return cfg end
    end
    local backup = CBUGER_SAFE_READ_TEXT(config_path .. '.bak', valid_config_text)
    if type(backup) == 'string' then
        local cfg, valid = parseConfigText(backup)
        if valid then
            pcall(CBUGER_SAFE_RESTORE_FILE, config_path, backup)
            return cfg
        end
    end
    return {}
end
local function writeSection(f, name, tbl)
    local function checked_write(value)
        local ok, result, err = pcall(function() return f:write(value) end)
        if not ok or result == nil then
            error(tostring(err or result or 'write failed'))
        end
    end
    checked_write('[' .. name .. ']\n')
    for k, v in pairs(tbl) do
        checked_write(k .. '=' .. tostring(v) .. '\n')
    end
    checked_write('\n')
end
