local function iconButton(icon, id, size, offset_x, offset_y, scale)
    size = size or imgui.ImVec2(28, 22)
    local p = imgui.GetCursorScreenPos()
    local pressed = imgui.Button(Fn.T(u8("##" .. id)), size)
    local p2 = imgui.ImVec2(p.x + size.x, p.y + size.y)
    local DL = imgui.GetWindowDrawList()
    local font = hi_fa_font_small or imgui.GetFont()
    local base_fsz = hi_fa_font_small and 16.0 or imgui.GetFontSize()
    local fsz = base_fsz * (scale or 1.0)
    local ts = font:CalcTextSizeA(fsz, 1000, 0, icon)
    local cx = p.x + size.x / 2 - ts.x / 2 + (offset_x or 0)
    local cy = p.y + size.y / 2 - ts.y / 2 + (offset_y or 0)
    local txt_col = imgui.GetColorU32(imgui.Col.Text)
    DL:PushClipRect(p, p2, true)
    DL:AddTextFontPtr(font, fsz, imgui.ImVec2(cx, cy), txt_col, icon)
    DL:PopClipRect()
    return pressed
end
