local function refreshImages()
    local old_files = img_files
    local function oldName(idx)
        idx = tonumber(idx) or 0
        if idx <= 0 then return nil end
        return old_files[idx]
    end
    local remap = {}
    local function collect(u)
        if type(u) ~= 'table' then return end
        if u.img_idx ~= nil then
            remap[#remap+1] = { kind = 'ptr', t = u, name = oldName(u.img_idx[0]) }
        end
        if type(u.sequence) == 'table' then
            for _, it in ipairs(u.sequence) do
                remap[#remap+1] = { kind = 'seq', t = it, name = oldName(it.img_idx) }
            end
        end
    end
    if type(ui) == 'table' then collect(ui.death); collect(ui.kill); collect(ui.armor) end
    collect(rawget(_G, 'self_icon'))
    img_files    = {}
    img_names_u8 = { u8"[ Нет ]" }
    local ok_dir, mode = pcall(lfs.attributes, image_dir, 'mode')
    if ok_dir and mode == 'directory' then
        local iter, state, init = lfs.dir(image_dir)
        if type(iter) == 'function' then
            local step = init
            while true do
                local f; pcall(function() f = iter(state, step) end)
                if f == nil then break end
                step = f
                if type(f) == 'string' then
                    local lo = f:lower()
                    if lo:match('%.png$') or lo:match('%.jpg$') or
                       lo:match('%.jpeg$') or lo:match('%.bmp$') then
                        table.insert(img_files, f)
                    end
                end
            end
        end
    end
    table.sort(img_files, function(a, b)
        local la, lb = a:lower(), b:lower()
        if la == lb then return a < b end
        return la < lb
    end)
    for _, fname in ipairs(img_files) do table.insert(img_names_u8, u8(fname)) end
    for _, r in ipairs(remap) do
        if r.name then
            local ni = imgIndexOf(r.name)
            if r.kind == 'ptr' then r.t.img_idx[0] = ni else r.t.img_idx = ni end
        end
    end
end
