window_state = new.bool(false)
placement_mode = { active = false, target = nil, handled = false, freeze_time = nil }
pending_placement_target = nil
function startPlacementMode(target)
    if not target then return end
    placement_mode.active = true
    placement_mode.target = target
    placement_mode.handled = false
    placement_mode.freeze_time = os.clock()
    if window_state ~= nil then window_state[0] = false end
    pcall(sampSetCursorMode, 3)
end
local function finishPlacementMode()
    placement_mode.active = false
    placement_mode.target = nil
    placement_mode.handled = false
    placement_mode.freeze_time = nil
end
local function setPlacementField(target, field, value)
    if not target then return end
    local cur = target[field]
    local t = type(cur)
    if t == 'table' or t == 'cdata' or t == 'userdata' then
        pcall(function() cur[0] = value end)
    else
        target[field] = value
    end
end
local function updatePlacementTarget(target, sx, sy, ox, oy, cursor_y_fix)
    if not placement_mode.active or placement_mode.target ~= target then
        return false
    end
    local mx, my = getCursorPos()
    if mx ~= nil and my ~= nil then
        if target.offset_xy ~= nil then
            setPlacementField(target, 'offset_xy', mx - sx - ox)
        end
        if target.offset_y ~= nil then
            setPlacementField(target, 'offset_y', my - sy - oy)
        end
    end
    if isKeyJustPressed(1) then
        finishPlacementMode()
        if window_state ~= nil then window_state[0] = true end
        pcall(sampSetCursorMode, 0)
        saveSettings()
        return true
    end
    if isKeyJustPressed(2) then
        finishPlacementMode()
        if window_state ~= nil then window_state[0] = true end
        pcall(sampSetCursorMode, 0)
        return true
    end
    return false
end
local function sequenceItemLabel(item)
    if not item then return u8("[пусто]") end
    local c = tonumber(item.content) or 0
    local alpha = 1.0
    if c == 0 or c == 1 then
        alpha = tonumber(item.img_alpha) or 1.0
    elseif c == 2 then
        alpha = tonumber(item.opacity) or 1.0
    end
    local op_pct = math.max(0, math.min(100, math.floor(alpha * 100 + 0.5)))
    if c == 0 then
        local idx = (tonumber(item.icon) or 0) + 1
        local key = icon_list[idx] and icon_list[idx].key or 'QUESTION'
        return u8(string.format("FA %d%% ", op_pct)) .. getIcon(key)
    elseif c == 1 then
        local name = img_names_u8[(tonumber(item.img_idx) or 0) + 1] or u8("[ Нет ]")
        return u8(string.format("IMG %d%% ", op_pct)) .. name
    elseif c == 2 then
        local txt = unescapeSeqText(item.text_buf or '')
        if txt == '' then txt = '?' end
        return u8(string.format("TXT %d%% ", op_pct)) .. txt:sub(1, 54)
    end
    return u8("[пусто]")
end
local function serializeSequence(name, u)
    local seq = u.sequence or {}
    local lines = { '[' .. name .. '_sequence]', 'seq_count=' .. tostring(#seq) }
    for i, item in ipairs(seq) do
        lines[#lines+1] = string.format(
            'seq%d=%s;%s;%s;%s;%s;%s;%s;%s;%s;%s;%s;%s;%s;%s;%s',
            i,
            tostring(item.content or 0),
            tostring(item.icon or 0),
            tostring(item.img_idx or 0),
            tostring(item.img_alpha or 1.0),
            tostring(item.img_scale or 1.0),
            escapeSeqText(item.text_buf or ''),
            tostring(item.text_scale or 1.0),
            tostring(item.r or 1.0),
            tostring(item.g or 1.0),
            tostring(item.b or 1.0),
            tostring(item.a or 1.0),
            tostring(item.opacity or 1.0),
            tostring(item.offset_xy or 0.0),
            tostring(item.offset_y or 0.0),
            escapeSeqText(imgNameOf(item.img_idx) or '')
        )
    end
    return table.concat(lines, '\n') .. '\n'
end
local function parseSequenceSection(section)
    local seq = {}
    if not section then return seq end
    local count = tonumber(section.seq_count) or 0
    for i = 1, count do
        local raw = section['seq' .. i]
        if raw then
            local parts = {}
            local rawstr = tostring(raw) .. ';'
            for part in rawstr:gmatch('([^;]*);') do
                parts[#parts+1] = part
            end
            local saved_name = unescapeSeqText(parts[15] or '')
            local img_i = tonumber(parts[3]) or 0
            if saved_name ~= '' then
                img_i = imgIndexOf(saved_name)
            end
            seq[#seq+1] = {
                content    = tonumber(parts[1]) or 0,
                icon       = tonumber(parts[2]) or 0,
                img_idx    = img_i,
                img_alpha  = tonumber(parts[4]) or 1.0,
                img_scale  = tonumber(parts[5]) or 1.0,
                text_buf   = unescapeSeqText(parts[6] or ''),
                text_scale = tonumber(parts[7]) or 1.0,
                r          = tonumber(parts[8]) or 1.0,
                g          = tonumber(parts[9]) or 1.0,
                b          = tonumber(parts[10]) or 1.0,
                a          = tonumber(parts[11]) or 1.0,
                opacity    = tonumber(parts[12]) or 1.0,
                offset_xy  = tonumber(parts[13]) or 0.0,
                offset_y   = tonumber(parts[14]) or 0.0,
            }
        end
    end
    return seq
end
local function imgFilename(idx_val)
    if idx_val <= 0 or idx_val > #img_files then return nil end
    return img_files[idx_val]
end
local function getTexture(filename)
    if not filename or filename == "" then return nil end
    if img_textures[filename] then return img_textures[filename] end
    local path = image_dir .. filename
    local ok_f = false; pcall(function() ok_f = doesFileExist(path) end)
    if not ok_f then return nil end
    local ok, tex = pcall(imgui.CreateTextureFromFile, path)
    if ok and tex then img_textures[filename] = tex; return tex end
    return nil
end
