}
window_state = new.bool(false)
local active_tab   = new.int(0)
script_enabled = new.bool(false)
auto_enable_on_join = new.bool(false)
local function applyBlock(tbl, cfg)
    if not cfg then return end
    tbl.enable[0]    = tobool(cfg.enable, tbl.enable[0]) and true or false
    tbl.content[0]   = tonumber_or(cfg.content, tbl.content[0])
    tbl.icon[0]      = tonumber_or(cfg.icon, tbl.icon[0])
    tbl.img_idx[0]   = tonumber_or(cfg.img_idx, tbl.img_idx[0])
    if cfg.img_name ~= nil and cfg.img_name ~= '' then
        tbl.img_idx[0] = imgIndexOf(unescape_str(cfg.img_name))
    end
    tbl.img_alpha[0] = tonumber_or(cfg.img_alpha, tbl.img_alpha[0])
    tbl.img_scale[0] = tonumber_or(cfg.img_scale, tbl.img_scale[0])
    if cfg.text_buf ~= nil then setCharBuf(tbl.text_buf, unescape_str(cfg.text_buf)) end
    tbl.text_scale[0] = tonumber_or(cfg.text_scale, tbl.text_scale[0])
    tbl.size[0]      = tonumber_or(cfg.size, tbl.size[0])
    if tbl.time ~= nil then tbl.time[0] = tonumber_or(cfg.time, tbl.time[0]) end
    if tbl.height ~= nil then tbl.height[0] = tonumber_or(cfg.height, tbl.height[0]) end
    tbl.color[0]     = tonumber_or(cfg.r, tbl.color[0])
    tbl.color[1]     = tonumber_or(cfg.g, tbl.color[1])
    tbl.color[2]     = tonumber_or(cfg.b, tbl.color[2])
    tbl.color[3]     = tonumber_or(cfg.a, tbl.color[3])
    tbl.anim[0]      = tonumber_or(cfg.anim, tbl.anim[0])
    if tbl.anim[0] < 0 or tbl.anim[0] > #anim_list - 1 then tbl.anim[0] = 0 end
    if tbl.anim_speed ~= nil then tbl.anim_speed[0] = tonumber_or(cfg.anim_speed, tbl.anim_speed[0]) end
    if tbl.opacity ~= nil then tbl.opacity[0] = tonumber_or(cfg.opacity, tbl.opacity[0]) end
    if tbl.seq_speed ~= nil then tbl.seq_speed[0] = tonumber_or(cfg.seq_speed, tbl.seq_speed[0]) end
    if tbl.seq_enabled ~= nil and cfg.seq_enabled ~= nil then tbl.seq_enabled[0] = tobool(cfg.seq_enabled, tbl.seq_enabled[0]) and true or false end
    if tbl.seq_apply_img_color ~= nil and cfg.seq_apply_img_color ~= nil then tbl.seq_apply_img_color[0] = tobool(cfg.seq_apply_img_color, tbl.seq_apply_img_color[0]) and true or false end
    if tbl.preview_box_size ~= nil then tbl.preview_box_size[0] = tonumber_or(cfg.preview_box_size, tbl.preview_box_size[0]) end
    if tbl.preview_icon_scale ~= nil then tbl.preview_icon_scale[0] = tonumber_or(cfg.preview_icon_scale, tbl.preview_icon_scale[0]) end
    if tbl.offset_xy ~= nil then tbl.offset_xy[0] = tonumber_or(cfg.offset_xy or cfg.offset_x, tbl.offset_xy[0]) end
    if tbl.offset_y ~= nil then tbl.offset_y[0] = tonumber_or(cfg.offset_y, tbl.offset_y[0]) end
    if tbl.render_distance ~= nil then
        tbl.render_distance[0] = math.max(10.0, math.min(500.0, tonumber_or(cfg.render_distance, tbl.render_distance[0])))
    end
end
saveSettings = function()
    local buffer_path = config_path .. '.buffer'
    local f = io.open(buffer_path, 'w')
    if not f then return false end
    local build_ok = pcall(function()
        writeSection(f, 'general', {
            script_enabled = bool01(script_enabled[0]),
            auto_enable_on_join = bool01(auto_enable_on_join[0]),
            window_state = bool01(window_state[0]),
            active_tab = active_tab[0],
            render_distance = tonumber(ui.render_distance[0]) or 100.0,
        })
        local function dumpBlock(name, u)
            writeSection(f, name, {
                enable = bool01(u.enable[0]),
                content = u.content[0],
                icon = u.icon[0],
                img_idx = u.img_idx[0],
                img_name = escape_str(imgNameOf(u.img_idx[0]) or ''),
                img_alpha = u.img_alpha[0],
                img_scale = u.img_scale[0],
                text_buf = escape_str(getCharBuf(u.text_buf)),
                text_scale = u.text_scale[0],
                size = u.size[0],
                time = u.time and u.time[0] or '',
                height = u.height and u.height[0] or '',
                r = u.color[0], g = u.color[1], b = u.color[2], a = u.color[3],
                anim = u.anim[0],
                anim_speed = u.anim_speed and u.anim_speed[0] or '',
                opacity = u.opacity and u.opacity[0] or '',
                seq_speed = u.seq_speed and u.seq_speed[0] or '',
                seq_enabled = u.seq_enabled and bool01(u.seq_enabled[0]) or '',
                seq_apply_img_color = u.seq_apply_img_color and bool01(u.seq_apply_img_color[0]) or '',
                offset_xy = u.offset_xy and u.offset_xy[0] or '',
                offset_y = u.offset_y and u.offset_y[0] or '',
                render_distance = u.render_distance and u.render_distance[0] or '',
            })
            local seq_write_ok, seq_write_result, seq_write_err = pcall(function()
                return f:write(serializeSequence(name, u))
            end)
            if not seq_write_ok or seq_write_result == nil then
                error(tostring(seq_write_err or seq_write_result or 'sequence write failed'))
            end
        end
        dumpBlock('death', ui.death)
        dumpBlock('kill', ui.kill)
        dumpBlock('armor', ui.armor)
        dumpBlock('self', self_icon)
    end)
    local flush_ok, flush_result = pcall(function() return f:flush() end)
    local close_ok, close_result = pcall(function() return f:close() end)
    if not build_ok or not flush_ok or flush_result == nil or not close_ok or close_result == nil then
        pcall(os.remove, buffer_path)
        return false
    end
    local rf = io.open(buffer_path, 'rb')
    if not rf then pcall(os.remove, buffer_path); return false end
    local read_ok, content = pcall(function() return rf:read('*a') end)
    local close_ok, close_result = pcall(function() return rf:close() end)
    pcall(os.remove, buffer_path)
    if not read_ok or type(content) ~= 'string' or content == ''
        or not close_ok or close_result == nil then
        return false
    end
    return CBUGER_SAFE_WRITE_FILE(config_path, content)
end
local function loadSettings()
    local cfg = readConfig()
    local g = cfg.general or {}
    script_enabled[0] = tobool(g.script_enabled, script_enabled[0]) and true or false
    auto_enable_on_join[0] = tobool(g.auto_enable_on_join, auto_enable_on_join[0]) and true or false
    window_state[0] = false
    active_tab[0] = tonumber_or(g.active_tab, active_tab[0])
    if active_tab[0] < 0 or active_tab[0] > 4 then active_tab[0] = 0 end
    ui.render_distance[0] = math.max(10.0, math.min(500.0, tonumber_or(g.render_distance, ui.render_distance[0])))
    local legacy_render_distance = ui.render_distance[0]
    applyBlock(ui.death, cfg.death)
    applyBlock(ui.kill, cfg.kill)
    applyBlock(ui.armor, cfg.armor)
    if cfg.death == nil or cfg.death.render_distance == nil then ui.death.render_distance[0] = legacy_render_distance end
    if cfg.kill  == nil or cfg.kill.render_distance  == nil then ui.kill.render_distance[0]  = legacy_render_distance end
    if cfg.armor == nil or cfg.armor.render_distance == nil then ui.armor.render_distance[0] = legacy_render_distance end
    applyBlock(self_icon, cfg.self)
    ui.death.sequence  = parseSequenceSection(cfg.death_sequence)
    ui.kill.sequence   = parseSequenceSection(cfg.kill_sequence)
    ui.armor.sequence  = parseSequenceSection(cfg.armor_sequence)
    self_icon.sequence = parseSequenceSection(cfg.self_sequence)
    ensureSequenceDefaults(ui.death)
    ensureSequenceDefaults(ui.kill)
    ensureSequenceDefaults(ui.armor)
    ensureSequenceDefaults(self_icon)
end
loadSettings()
local BASE_ACCENT = { x=0.55, y=0.35, z=1.0, w=1.0 }
local function sequenceHasItem(seq, item)
    if not seq or not item then return false end
    for i = 1, #seq do
        if seq[i] == item then
            return true
        end
    end
    return false
end
local function getSequenceItem(u, now)
    local seq = u.sequence or {}
    if placement_mode.active and placement_mode.target and sequenceHasItem(seq, placement_mode.target) then
        return placement_mode.target
    end
    if not u.seq_enabled or not u.seq_enabled[0] then
        return nil
    end
    if #seq == 0 then
        return copyBlockSnapshot(u)
    end
    local speed = math.max(0.05, tonumber(u.seq_speed and u.seq_speed[0] or 1.0) or 1.0)
    local effective_now = now or os.clock()
    if placement_mode.active and placement_mode.freeze_time then
        effective_now = placement_mode.freeze_time
    end
    local index = math.floor(effective_now * speed) % #seq + 1
    return seq[index]
end
function getTabAccent()
    local c = active_colors and active_colors[imgui.Col.Border]
    if c then return {x=c[1], y=c[2], z=c[3], w=1.0} end
    local fc = (type(fx_cfg) == 'table') and fx_cfg.global_base_color
    if fc then return {x=fc[1], y=fc[2], z=fc[3], w=1.0} end
    return {x=0.0, y=0.8, z=1.0, w=1.0}
end
local function clamp01(v) return math.max(0, math.min(1, v)) end
function accentVec4(a, mult, alpha)
    mult  = mult  or 1.0
    alpha = alpha or 1.0
    local c = active_colors and active_colors[imgui.Col.Border]
    if c then
        return imgui.ImVec4(
            math.min(1, c[1] * mult),
            math.min(1, c[2] * mult),
            math.min(1, c[3] * mult),
            alpha)
    end
    local fc = (type(fx_cfg) == 'table') and fx_cfg.global_base_color
    local fr = fc and fc[1] or 0.0
    local fg = fc and fc[2] or 0.8
    local fb = fc and fc[3] or 1.0
    return imgui.ImVec4(math.min(1, fr * mult), math.min(1, fg * mult), math.min(1, fb * mult), alpha)
end
function accentU32(a, mult, alpha)
    return HI_U32(accentVec4(a, mult, alpha))
end
local active_markers = {}
local function headIconsRenderDistanceFor(kind)
    local u = kind and ui[kind]
    local v = u and u.render_distance and tonumber(u.render_distance[0]) or nil
    if not v or v ~= v then
        v = ui.render_distance and tonumber(ui.render_distance[0]) or 100.0
    end
    return math.max(10.0, math.min(500.0, v))
end
local function isWithinHeadIconsDistance(x, y, z, cx, cy, cz, max_distance)
    if x == nil or y == nil or z == nil then return false end
    if cx == nil or cy == nil or cz == nil then
        local ok, px, py, pz = pcall(getCharCoordinates, PLAYER_PED)
        if not ok then return false end
        cx, cy, cz = px, py, pz
    end
    if cx == nil or cy == nil or cz == nil then return false end
    local dx, dy, dz = cx - x, cy - y, cz - z
    local maxd = tonumber(max_distance) or 100.0
    if maxd < 10.0 then maxd = 10.0 elseif maxd > 500.0 then maxd = 500.0 end
    return (dx*dx + dy*dy + dz*dz) <= maxd * maxd
end
function addMarker(mtype, x, y, z, ped_handle)
    if not script_enabled[0] then return end
    local u = ui[mtype]
    if not u or not u.enable[0] then return end
    if x == nil or y == nil or z == nil then return end
    if not isWithinHeadIconsDistance(x, y, z, nil, nil, nil, headIconsRenderDistanceFor(mtype)) then return end
    local idx = u.icon[0] + 1
    local icon_key = icon_list[idx] and icon_list[idx].key or "QUESTION"
    table.insert(active_markers, {
        content     = u.content[0],
        fa_text     = getIcon(icon_key),
        img_file    = imgFilename(u.img_idx[0]),
        img_alpha   = u.img_alpha[0],
        img_scale   = u.img_scale[0],
        custom_text = getCharBuf(u.text_buf),
        text_scale  = u.text_scale[0],
        x = x, y = y, z = z,
        ped_handle  = ped_handle,
        start_time  = os.clock(),
        duration    = math.max(0.25, tonumber(u.time[0]) or 3.0),
        size        = u.size[0],
        max_height  = u.height[0],
        color       = { u.color[0], u.color[1], u.color[2], u.color[3] },
        anim        = animEntry(u.anim[0]).key,
        anim_speed  = u.anim_speed and u.anim_speed[0] or 1.0,
        opacity     = u.opacity and u.opacity[0] or 1.0,
        offset_xy   = u.offset_xy[0],
        offset_y    = u.offset_y and u.offset_y[0] or 0.0,
        sequence_item = getSequenceItem(u, os.clock()),
        seq_apply_img_color = u.seq_apply_img_color and u.seq_apply_img_color[0] or false,
        kind = mtype,
    })
end
local was_alive   = {}
local was_i_alive = true
local net_armor   = {}
local hit_time    = {}
local pending_deaths = {}
local KILL_CREDIT = 6.0
local my_samp_id  = -1
local last_known_pos = {}
local last_death_emit = {}
local DEATH_EMIT_GUARD = 0.85
function cacheKnownPos(playerId, x, y, z, ts)
    if playerId == nil or x == nil or y == nil or z == nil then return nil end
    local stamp = ts or os.clock()
    last_known_pos[playerId] = {
        x = x, y = y, z = z,
        t = stamp
    }
    return stamp
end
function resolveMarkerPos(playerId, ped_handle)
    if ped_handle and ped_handle ~= 0 then
        local ok, exists = pcall(doesCharExist, ped_handle)
        if ok and exists then
            local ok2, x, y, z = pcall(getCharCoordinates, ped_handle)
            if ok2 and x ~= nil and y ~= nil and z ~= nil then
                local ts = cacheKnownPos(playerId, x, y, z)
                return x, y, z, ts or os.clock()
            end
        end
    end
    local cached = last_known_pos[playerId]
    if cached then
        return cached.x, cached.y, cached.z, cached.t
    end
    return nil, nil, nil, nil
end
function hi_samp.onSendBulletSync(data)
    if not script_enabled[0] then return end
    if data and data.targetType == 1 and data.targetId ~= my_samp_id then
        hit_time[data.targetId] = os.clock()
    end
end
function hi_samp.onSendGiveDamage(playerId, damage, weaponId, bodypart)
    if not script_enabled[0] then return end
    if playerId ~= my_samp_id then hit_time[playerId] = os.clock() end
end
local function queueDeathEvent(playerId, killerId, ped_handle, is_self)
    if playerId == nil then return end
    local last_emit = last_death_emit[playerId]
    if last_emit ~= nil and (os.clock() - last_emit) < DEATH_EMIT_GUARD then
        return
    end
    local ev = pending_deaths[playerId]
    if ev == nil then
        pending_deaths[playerId] = {
            killerId = killerId,
            ped_handle = ped_handle,
            is_self = is_self and true or false,
            queued_at = os.clock(),
        }
    else
        if killerId ~= nil then ev.killerId = killerId end
        if ped_handle ~= nil and ped_handle ~= 0 then ev.ped_handle = ped_handle end
        ev.is_self = ev.is_self or (is_self and true or false)
    end
end
local function processDeathQueue(now)
    for playerId, ev in pairs(pending_deaths) do
        local ped = ev.is_self and PLAYER_PED or ev.ped_handle
        local x, y, z, pos_ts = resolveMarkerPos(playerId, ped)
        local stale_remote = (not ev.is_self) and (ped == nil or ped == 0)
            and (pos_ts == nil or (now - pos_ts) > 2.0)
        if x ~= nil and not stale_remote then
            local is_kill = (not ev.is_self) and (
                (ev.killerId ~= nil and ev.killerId == my_samp_id)
                or (hit_time[playerId] ~= nil and (now - hit_time[playerId]) < KILL_CREDIT)
            )
            local marker_kind = is_kill and 'kill' or 'death'
            if isWithinHeadIconsDistance(x, y, z, nil, nil, nil, headIconsRenderDistanceFor(marker_kind)) then
                if is_kill then
                    hit_time[playerId] = nil
                    addMarker('kill', x, y, z, ped)
                else
                    addMarker('death', x, y, z, ev.is_self and nil or ped)
                end
                last_death_emit[playerId] = now
                pending_deaths[playerId] = nil
                if ev.is_self then
                    was_i_alive = false
                else
                    was_alive[playerId] = false
                end
            elseif (now - ev.queued_at) > 1.5 then
                pending_deaths[playerId] = nil
            end
        elseif (now - ev.queued_at) > 1.5 then
            pending_deaths[playerId] = nil
        end
    end
end
function hi_samp.onPlayerDeath(playerId, killerId, reason)
    if not script_enabled[0] then return end
    if playerId == my_samp_id then
        queueDeathEvent(playerId, nil, PLAYER_PED, true)
        was_i_alive = false
        was_alive[playerId] = false
        return
    end
    local ok, ped = pcall(sampGetCharHandleBySampPlayerId, playerId)
    queueDeathEvent(playerId, killerId, (ok and ped or nil), false)
    was_alive[playerId] = false
end
local function emitDeathMarkerNow(killedId, killerId)
    if killedId == nil or killedId == 65535 then return false end
    if not script_enabled[0] then return false end
    local now = os.clock()
    local last_emit = last_death_emit[killedId]
    if last_emit ~= nil and (now - last_emit) < DEATH_EMIT_GUARD then
        return true
    end
    local is_self = (killedId == my_samp_id)
    local ped = nil
    if is_self then
        ped = PLAYER_PED
    else
        local ok_ped, ph = pcall(sampGetCharHandleBySampPlayerId, killedId)
        if ok_ped and ph and ph ~= 0 then ped = ph end
    end
    local x, y, z, pos_ts = resolveMarkerPos(killedId, ped)
    if x == nil then
        return false
    end
    local stale_remote = (not is_self) and (ped == nil or ped == 0)
        and (pos_ts == nil or (now - pos_ts) > 2.0)
    if stale_remote then
        return false
    end
    local is_kill = (not is_self) and (killerId ~= nil and killerId == my_samp_id)
    local marker_kind = is_kill and 'kill' or 'death'
    if not isWithinHeadIconsDistance(x, y, z, nil, nil, nil, headIconsRenderDistanceFor(marker_kind)) then
        return false
    end
    if is_kill then
        hit_time[killedId] = nil
        addMarker('kill', x, y, z, ped)
    else
        addMarker('death', x, y, z, is_self and nil or ped)
    end
    last_death_emit[killedId] = now
    if is_self then
        was_i_alive = false
    else
        was_alive[killedId] = false
    end
    pending_deaths[killedId] = nil
    return true
end
function CBUGER_HeadIconsDeathNotification(killerId, killedId, weaponId)
    if killedId == nil or killedId == 65535 then return end
    if killedId == my_samp_id then
        was_i_alive = false
        was_alive[killedId] = false
    else
        was_alive[killedId] = false
    end
    if not emitDeathMarkerNow(killedId, killerId) then
        local ok, ped = pcall(sampGetCharHandleBySampPlayerId, killedId)
        queueDeathEvent(killedId, killerId, (ok and ped or nil), killedId == my_samp_id)
    end
end
function CBUGER_HeadIconsPlayerSync(playerId, data)
    if not script_enabled[0] or playerId == nil or data == nil then return end
    local ok_pos, pos = pcall(function() return data.position end)
    if not ok_pos or pos == nil then return end
    local okx, x = pcall(function() return pos.x end)
    local oky, y = pcall(function() return pos.y end)
    local okz, z = pcall(function() return pos.z end)
    if okx and oky and okz and tonumber(x) ~= nil and tonumber(y) ~= nil and tonumber(z) ~= nil then
        cacheKnownPos(playerId, tonumber(x), tonumber(y), tonumber(z), os.clock())
    end
end
function onReceiveRpc(rpcId, bs)
    if rpcId ~= 55 and rpcId ~= 166 then return end
    if not script_enabled[0] then return end
    if bs == nil then return end
    local old_offset = nil
    pcall(function() old_offset = raknetBitStreamGetReadOffset(bs) end)
    pcall(function() raknetBitStreamResetReadPointer(bs) end)
    if rpcId == 55 then
        local ok, killerId, killedId, weaponId = pcall(function()
            return raknetBitStreamReadInt16(bs),
                   raknetBitStreamReadInt16(bs),
                   raknetBitStreamReadInt8(bs)
        end)
        if ok and killedId ~= nil and killedId ~= 65535 then
            CBUGER_HeadIconsDeathNotification(killerId, killedId, weaponId)
        end
    elseif rpcId == 166 then
        local ok, killedId = pcall(raknetBitStreamReadInt16, bs)
        if ok and killedId ~= nil and killedId ~= 65535 then
            CBUGER_HeadIconsDeathNotification(nil, killedId, nil)
        end
    end
    pcall(function()
        if old_offset ~= nil then
            raknetBitStreamSetReadOffset(bs, old_offset)
        else
            raknetBitStreamResetReadPointer(bs)
        end
    end)
end
function hi_samp.onPlayerSync(playerId, data)
    if not script_enabled[0] then return end
    if not ui.armor.enable[0] then return end
    if not data or data.armor == nil then return end
    local prev = net_armor[playerId]
    net_armor[playerId] = data.armor
    if prev == nil then return end
    if data.armor < 1 and prev >= 1 then
        local ok, ped = sampGetCharHandleBySampPlayerId(playerId)
        if ok and ped and ped ~= 0 and doesCharExist(ped) then
            local x, y, z = getCharCoordinates(ped)
            addMarker("armor", x, y, z, ped)
        end
    end
end
function hi_samp.onPlayerStreamIn(playerId)
    net_armor[playerId] = nil; was_alive[playerId] = nil
end
function hi_samp.onPlayerStreamOut(playerId)
    net_armor[playerId] = nil; was_alive[playerId] = nil
    hit_time[playerId] = nil
    pending_deaths[playerId] = nil
    last_known_pos[playerId] = nil
end
local function pushTabStyles()
    local function ac(id, r_fb, g_fb, b_fb, a_fb)
        local c = active_colors and active_colors[id]
        if c then
            return imgui.ImVec4(c[1], c[2], c[3], c[4] or a_fb or 1.0)
        end
        local h = G_HUE % 1.0
        local i6=math.floor(h*6); local f=h*6-i6
        local p=r_fb*(1-0); local q=r_fb; local tv=r_fb
        return imgui.ImVec4(r_fb, g_fb, b_fb, a_fb or 1.0)
    end
    local n = 0
    local function push(id, r_fb, g_fb, b_fb, a_fb)
        local c = active_colors and active_colors[id]
        local v
        if c then
            v = imgui.ImVec4(c[1], c[2], c[3], c[4] or a_fb or 1.0)
        else
            v = imgui.ImVec4(r_fb, g_fb, b_fb, a_fb or 1.0)
        end
        imgui.PushStyleColor(id, v)
        n = n + 1
    end
    push(imgui.Col.WindowBg,             0.02, 0.02, 0.05, 0.97)
