    push(imgui.Col.ResizeGripActive,     0.20, 0.55, 1.00, 1.00)
    push(imgui.Col.TitleBg,              0.02, 0.04, 0.10, 1.00)
    push(imgui.Col.TitleBgActive,        0.04, 0.08, 0.20, 1.00)
    push(imgui.Col.Header,               0.05, 0.10, 0.25, 0.80)
    push(imgui.Col.HeaderHovered,        0.10, 0.20, 0.45, 0.90)
    push(imgui.Col.HeaderActive,         0.15, 0.35, 0.70, 1.00)
