    push(imgui.Col.SeparatorActive,      0.25, 0.65, 1.00, 1.00)
    push(imgui.Col.Button,               0.06, 0.12, 0.28, 0.80)
    push(imgui.Col.ButtonHovered,        0.12, 0.24, 0.50, 0.90)
    push(imgui.Col.ButtonActive,         0.20, 0.45, 0.90, 1.00)
    return n
end
local function refreshHeadIconsFonts()
    if not (fa and fa.Init) then return false end
    local ok_small, small = pcall(fa.Init, 16.0)
    local ok_big, big = pcall(fa.Init, 40.0)
    if ok_small and small ~= nil then hi_fa_font_small = small end
    if ok_big and big ~= nil then hi_fa_font_big = big end
    return hi_fa_font_big ~= nil or hi_fa_font_small ~= nil
end
function CBUGER_HEADICONS_REFRESH_FONTS()
    return refreshHeadIconsFonts()
end
imgui.OnInitialize(function()
    imgui.GetIO().IniFilename = nil
    refreshHeadIconsFonts()
    ui.death.icon[0]    = iconIndex("SKULL")
    ui.kill.icon[0]     = iconIndex("CROSSHAIRS")
    ui.armor.icon[0]    = iconIndex("SHIELD_HALVED")
    self_icon.icon[0]   = iconIndex("STAR")
    local _bc = fx_cfg and fx_cfg.global_base_color
    if _bc and fn and fn.ApplyGlobalTheme then
        fn.ApplyGlobalTheme(_bc[1], _bc[2], _bc[3])
    end
end)
local function getFontForSize(target_size)
    return hi_fa_font_big or hi_fa_font_small or imgui.GetFont()
end
local function getTextFontForSize(target_size)
    return CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
end
animEntry = function(idx)
    local i = tonumber(idx) or 0
    i = math.max(1, math.min(#anim_list, i + 1))
    return anim_list[i]
end
local function calcAnim(anim_key, elapsed, duration, max_height, base_size, speed)
    local speed = math.max(0.05, tonumber(speed) or 1.0)
    local t    = math.max(0, math.min(1, (elapsed * speed) / duration))
    local now  = os.clock() * speed
    local ox, oy = 0, 0
    local scale_mul = 1.0
    local alpha_mul = 1.0 - t * t
    if anim_key == "NONE" then
        ox, oy, scale_mul, alpha_mul = 0, 0, 1.0, 1.0
    elseif anim_key == "FLOAT" then
        oy = -(1 - t) * base_size * 0.18 - math.abs(math.sin(now * 2.6)) * base_size * 0.06 * (1 - t)
    elseif anim_key == "PULSE" then
        local pulse = 0.75 + 0.25 * math.abs(math.sin(now * 4.0))
        scale_mul = pulse * (1 - t * 0.5)
    elseif anim_key == "SPIN" then
        local r_orb = base_size * 0.15
        ox = math.cos(now * 5.0) * r_orb
        oy = math.sin(now * 5.0) * r_orb * 0.5
    elseif anim_key == "WAVE" then
        ox = math.sin(now * 6.0) * base_size * 0.2 * (1 - t)
        oy = math.cos(now * 4.0) * base_size * 0.1 * (1 - t)
    elseif anim_key == "SHAKE" then
        local amp = (1 - t) * base_size * 0.15
        ox = (math.sin(now * 20.0) * 0.7 + math.sin(now * 13.3) * 0.3) * amp
        oy = (math.cos(now * 17.0) * 0.5 + math.cos(now * 9.7)  * 0.5) * amp * 0.6
    elseif anim_key == "SPIRAL" then
        local r_sp = (1 - t) * base_size * 0.35
        ox = math.cos(now * 8.0) * r_sp
        oy = math.sin(now * 8.0) * r_sp * 0.5
        scale_mul = 0.5 + 0.5 * (1 - t)
    end
    return ox, oy, scale_mul, alpha_mul
end
local function renderContent(DL, font, m, sx, sy, draw_size, alpha_mul)
    local alpha = m.color[4] * (m.opacity or 1.0) * alpha_mul
    if alpha <= 0.005 then return end
    if m.sequence_item then
        local it = m.sequence_item
        local item_alpha = math.max(0, math.min(1, (it.opacity or 1.0) * alpha_mul))
        local rr = it.r or m.color[1]
        local gg = it.g or m.color[2]
        local bb = it.b or m.color[3]
        local c = tonumber(it.content) or 0
        if c == 1 and not m.seq_apply_img_color then
            rr, gg, bb = 1.0, 1.0, 1.0
        end
        local fa_alpha = math.max(0, math.min(1, (tonumber(it.img_alpha) or 1.0) * item_alpha))
        local item_color = HI_OVERLAY_U32(imgui.ImVec4(rr, gg, bb, (it.a or m.color[4]) * fa_alpha))
        if c == 0 then
            local idx = (tonumber(it.icon) or 0) + 1
            local key = icon_list[idx] and icon_list[idx].key or "QUESTION"
            local ico = getIcon(key)
            local fa_alpha = math.max(0, math.min(1, (tonumber(it.img_alpha) or 1.0) * item_alpha))
            local item_color = HI_OVERLAY_U32(imgui.ImVec4(rr, gg, bb, (it.a or m.color[4]) * fa_alpha))
            local fsz = draw_size * math.max(0.2, tonumber(it.img_scale) or 1.0)
            local ts = font:CalcTextSizeA(fsz, 1000, 0, ico)
            DL:AddTextFontPtr(font, fsz, imgui.ImVec2(sx - ts.x/2, sy - ts.y/2), item_color, ico)
        elseif c == 1 then
            local fname = imgFilename(tonumber(it.img_idx) or 0)
            local tex = fname and getTexture(fname)
            if tex then
                local half = draw_size * (tonumber(it.img_scale) or 1.0) * 0.5
                local tex_a = math.max(0, math.min(1, (tonumber(it.img_alpha) or 1.0) * item_alpha))
                local col_img = HI_OVERLAY_U32(imgui.ImVec4(rr, gg, bb, tex_a))
                DL:AddImage(tex, imgui.ImVec2(sx-half, sy-half), imgui.ImVec2(sx+half, sy+half), imgui.ImVec2(0,0), imgui.ImVec2(1,1), col_img)
            end
        elseif c == 2 then
            local txt = unescapeSeqText(it.text_buf or '')
            if txt == '' then txt = '?' end
            local text_font = getTextFontForSize(draw_size)
            local fsz = draw_size * (tonumber(it.text_scale) or 1.0)
            local ts = text_font:CalcTextSizeA(fsz, 1000, 0, txt)
            DL:AddTextFontPtr(text_font, fsz, imgui.ImVec2(sx - ts.x/2, sy - ts.y/2), item_color, txt)
        end
    elseif m.content == 1 then
        local tex = m.img_file and getTexture(m.img_file)
        if tex then
            local half    = draw_size * m.img_scale * 0.5
            local tex_a   = math.max(0, math.min(1, m.img_alpha * (m.opacity or 1.0) * alpha_mul))
            local apply_c = m.seq_apply_img_color
            local ir = apply_c and m.color[1] or 1.0
            local ig = apply_c and m.color[2] or 1.0
            local ib = apply_c and m.color[3] or 1.0
            local col_img = HI_OVERLAY_U32(imgui.ImVec4(ir, ig, ib, tex_a))
            DL:AddImage(tex,
                imgui.ImVec2(sx - half, sy - half),
                imgui.ImVec2(sx + half, sy + half),
                imgui.ImVec2(0, 0), imgui.ImVec2(1, 1), col_img)
        else
            local col = HI_OVERLAY_U32(
                imgui.ImVec4(m.color[1], m.color[2], m.color[3], alpha))
            local fsz = draw_size * math.max(0.2, m.img_scale or 1.0)
            local ts = font:CalcTextSizeA(fsz, 1000, 0, m.fa_text)
            DL:AddTextFontPtr(font, fsz,
                imgui.ImVec2(sx - ts.x / 2, sy - ts.y / 2), col, m.fa_text)
        end
    elseif m.content == 2 then
        local tu8  = m.custom_text ~= "" and m.custom_text or "???"
        local text_font = getTextFontForSize(draw_size)
        local fsz  = draw_size * m.text_scale
        local col  = HI_OVERLAY_U32(
            imgui.ImVec4(m.color[1], m.color[2], m.color[3], alpha))
        local shad = HI_OVERLAY_U32(imgui.ImVec4(0, 0, 0, alpha * 0.7))
        local ts   = text_font:CalcTextSizeA(fsz, 1000, 0, tu8)
        DL:AddTextFontPtr(text_font, fsz,
            imgui.ImVec2(sx - ts.x / 2 + 1, sy - ts.y / 2 + 1), shad, tu8)
        DL:AddTextFontPtr(text_font, fsz,
            imgui.ImVec2(sx - ts.x / 2, sy - ts.y / 2), col, tu8)
    else
        local col = HI_OVERLAY_U32(
            imgui.ImVec4(m.color[1], m.color[2], m.color[3], alpha))
        local ts = font:CalcTextSizeA(draw_size, 1000, 0, m.fa_text)
        DL:AddTextFontPtr(font, draw_size,
            imgui.ImVec2(sx - ts.x / 2, sy - ts.y / 2), col, m.fa_text)
    end
end
imgui.OnFrame(
    function() return placement_mode.active or #active_markers > 0 or (script_enabled[0] and self_icon.enable[0]) end,
    function(self)
        self.HideCursor = true
        placement_mode.handled = false
        local now  = os.clock()
        if not script_enabled[0] and not placement_mode.active then return end
        local DL = imgui.GetBackgroundDrawList()
        local font = hi_fa_font_big or hi_fa_font_small or imgui.GetFont()
        local cx, cy, cz
        local ok_cam, _cx, _cy, _cz = pcall(getCameraPosition)
        if ok_cam then cx, cy, cz = _cx, _cy, _cz
        else cx, cy, cz = getCharCoordinates(PLAYER_PED) end
        local self_seq_placing = false
        if placement_mode.active and placement_mode.target then
            for _, _sit in ipairs(self_icon.sequence) do
                if _sit == placement_mode.target then self_seq_placing = true; break end
            end
        end
        if (script_enabled[0] and self_icon.enable[0]) or self_seq_placing then
            local px, py, pz = getCharCoordinates(PLAYER_PED)
            local ok_proj, res, sx, sy, sz = pcall(
                convert3DCoordsToScreenEx, px, py, pz + 1.0, false, false)
            if ok_proj and res and type(sx) == 'number' and type(sy) == 'number'
               and type(sz) == 'number' and sx == sx and sy == sy and sz == sz and sz > 0.0 then
                local anim_key = animEntry(self_icon.anim[0]).key
                local ox, oy, sm, _ = calcAnim(anim_key, 0, 1, 0, self_icon.size[0], self_icon.anim_speed[0])
                local p_ox = (placement_mode.active and placement_mode.target == self_icon) and 0 or ox
                local p_oy = (placement_mode.active and placement_mode.target == self_icon) and 0 or oy
                local seq_item = getSequenceItem(self_icon, now)
                local si_m = {
                    content     = self_icon.content[0],
                    fa_text     = getIcon(icon_list[self_icon.icon[0] + 1].key),
                    img_file    = imgFilename(self_icon.img_idx[0]),
                    img_alpha   = self_icon.img_alpha[0],
                    img_scale   = self_icon.img_scale[0],
                    custom_text = getCharBuf(self_icon.text_buf),
                    text_scale  = self_icon.text_scale[0],
                    color       = {
                        self_icon.color[0], self_icon.color[1],
                        self_icon.color[2], self_icon.color[3]
                    },
                    opacity     = self_icon.opacity[0],
                    sequence_item = seq_item,
                    seq_apply_img_color = self_icon.seq_apply_img_color and self_icon.seq_apply_img_color[0] or false,
                }
                local use_seq_offset = (seq_item ~= nil)
                local seq_ox = (use_seq_offset and tonumber(seq_item.offset_xy) or 0.0) or 0.0
                local seq_oy = (use_seq_offset and tonumber(seq_item.offset_y)  or 0.0) or 0.0
                local sx0 = sx + p_ox + self_icon.offset_xy[0] + seq_ox
                local sy0 = sy + p_oy + (self_icon.offset_y and self_icon.offset_y[0] or 0.0) + seq_oy
                updatePlacementTarget(self_icon, sx, sy, p_ox, p_oy, placementCursorYOffset(self_icon.size[0] * sm))
                if placement_mode.active and self_seq_placing and not placement_mode.handled then
                    local mx, my = getCursorPos()
                    if mx ~= nil and my ~= nil then
                        placement_mode.target.offset_xy = mx - sx - ox - self_icon.offset_xy[0]
                        placement_mode.target.offset_y  = my - sy - oy - (self_icon.offset_y and self_icon.offset_y[0] or 0.0)
                    end
                    if isKeyJustPressed(1) then
                        finishPlacementMode()
                        window_state[0] = true
                        pcall(sampSetCursorMode, 0)
                        saveSettings()
                    elseif isKeyJustPressed(2) then
                        finishPlacementMode()
                        window_state[0] = true
                        pcall(sampSetCursorMode, 0)
                    end
                    placement_mode.handled = true
                end
                renderContent(DL, font, si_m, sx0, sy0, self_icon.size[0] * sm, 1.0)
            end
        end
        local death_placing_main = placement_mode.active and placement_mode.target == ui.death
        local death_seq_placing = false
        if placement_mode.active and placement_mode.target and not death_placing_main then
            for _, _it in ipairs(ui.death.sequence) do
