                    custom_text = getCharBuf(ui.armor.text_buf),
                    text_scale  = ui.armor.text_scale[0],
                    color       = { ui.armor.color[0], ui.armor.color[1], ui.armor.color[2], ui.armor.color[3] },
                    opacity     = ui.armor.opacity and ui.armor.opacity[0] or 1.0,
                    sequence_item = seq_item,
                    seq_apply_img_color = ui.armor.seq_apply_img_color and ui.armor.seq_apply_img_color[0] or false,
                }
                local use_seq_offset = (seq_item ~= nil)
                local seq_ox = (use_seq_offset and tonumber(seq_item.offset_xy) or 0.0) or 0.0
                local seq_oy = (use_seq_offset and tonumber(seq_item.offset_y) or 0.0) or 0.0
                local sx0 = sx + a_p_ox + ui.armor.offset_xy[0] + seq_ox
                local sy0 = sy + a_p_oy + (ui.armor.offset_y and ui.armor.offset_y[0] or 0.0) + seq_oy
                if armor_placing_main then
                    updatePlacementTarget(ui.armor, sx, sy, a_p_ox, a_p_oy, placementCursorYOffset(ui.armor.size[0] * sm))
                elseif armor_seq_placing then
                    local mx, my = getCursorPos()
                    if mx ~= nil and my ~= nil then
                        placement_mode.target.offset_xy = mx - sx - ox - ui.armor.offset_xy[0]
                        placement_mode.target.offset_y  = my - sy - oy - (ui.armor.offset_y and ui.armor.offset_y[0] or 0.0)
                    end
                    if isKeyJustPressed(1) then
                        finishPlacementMode(); window_state[0] = true; pcall(sampSetCursorMode, 0); saveSettings()
                    elseif isKeyJustPressed(2) then
                        finishPlacementMode(); window_state[0] = true; pcall(sampSetCursorMode, 0)
                    end
                    placement_mode.handled = true
                end
                renderContent(DL, font, am, sx0, sy0, ui.armor.size[0] * sm, 1.0)
            end
        end
        if script_enabled[0] then
        for i = #active_markers, 1, -1 do
            local m       = active_markers[i]
            local elapsed = now - m.start_time
            if elapsed >= m.duration then
                table.remove(active_markers, i)
            else
                local t    = elapsed / m.duration
                local ease = 1.0 - (1.0 - t) ^ 2
                if m.ped_handle then
                    pcall(function()
                        if doesCharExist(m.ped_handle) then
                            m.x, m.y, m.z = getCharCoordinates(m.ped_handle)
                        end
                    end)
                end
                local dx   = cx - m.x; local dy = cy - m.y; local dz = cz - m.z
                local dist = math.sqrt(dx*dx + dy*dy + dz*dz)
                local marker_distance = headIconsRenderDistanceFor(m.kind)
                if dist <= marker_distance then
                    local ok_proj, res, sx, sy, sz = pcall(
                        convert3DCoordsToScreenEx,
                        m.x, m.y, m.z + 1.0 + m.max_height * ease, false, false)
                    if ok_proj and res and type(sx) == 'number' and type(sy) == 'number'
                       and type(sz) == 'number' and sx == sx and sy == sy and sz == sz and sz > 0.0 then
                    local dt   = math.max(0, math.min(1, (dist - 5) / 45))
                    local draw_size = m.size * math.max(0.25, 1.0 - dt * 0.75)
                    local ox, oy, sm, am = calcAnim( m.anim, elapsed, m.duration, m.max_height, draw_size, m.anim_speed or 1.0 )
                    if placement_mode.active and placement_mode.target and not placement_mode.handled then
                        local target_matches = false
                        if m.kind and ui[m.kind] and placement_mode.target == ui[m.kind] then
                            target_matches = true
                        elseif m.sequence_item and placement_mode.target == m.sequence_item then
                            target_matches = true
                        end
                        if target_matches then
                            if m.kind and ui[m.kind] and placement_mode.target == ui[m.kind] then
                                updatePlacementTarget(placement_mode.target, sx, sy, ox, oy, placementCursorYOffset(draw_size * sm))
                            else
                                local mx, my = getCursorPos()
                                if mx ~= nil and my ~= nil then
                                    local new_ox = mx - sx - ox
                                    local new_oy = my - sy - oy
                                    m.offset_xy = new_ox
                                    m.offset_y  = new_oy
                                    setPlacementField(placement_mode.target, "offset_xy", new_ox)
                                    setPlacementField(placement_mode.target, "offset_y", new_oy)
                                end
                                if isKeyJustPressed(1) then
                                    finishPlacementMode()
                                    window_state[0] = true
                                    pcall(sampSetCursorMode, 0)
                                    saveSettings()
                                elseif isKeyJustPressed(2) then
                                    finishPlacementMode()
                                    window_state[0] = true
                                    pcall(sampSetCursorMode, 0)
                                end
                            end
                            placement_mode.handled = true
                        end
                    end
                    local use_seq_offset = (m.sequence_item ~= nil)
                    local seq_ox = (use_seq_offset and tonumber(m.sequence_item.offset_xy) or 0.0) or 0.0
                    local seq_oy = (use_seq_offset and tonumber(m.sequence_item.offset_y) or 0.0) or 0.0
                    renderContent(DL, font, m,
                        sx + ox + m.offset_xy + seq_ox,
                        sy + oy + (m.offset_y or 0.0) + seq_oy,
                        draw_size * sm, am)
                    end
                end
            end
        end
        end
    end
)
local function findPlacementSequenceItem(base)
    if not placement_mode.active or not placement_mode.target then return nil end
    if type(base) ~= 'table' or type(base.sequence) ~= 'table' then return nil end
    for _, item in ipairs(base.sequence) do
        if item == placement_mode.target then
            return item
        end
    end
    return nil
end
local function resolvePlacementTarget(base)
    if type(base) ~= 'table' then
        return base
    end
    local seq_enabled = false
    local ok = pcall(function()
        seq_enabled = base.seq_enabled and base.seq_enabled[0] and true or false
    end)
    if not ok or not seq_enabled then
        return base
    end
    local seq = base.sequence or {}
    if #seq == 0 then
        return base
    end
    local seq_item = findPlacementSequenceItem(base)
    if not seq_item then
        local speed = math.max(0.05, tonumber(base.seq_speed and base.seq_speed[0] or 1.0) or 1.0)
        local index = math.floor(os.clock() * speed) % #seq + 1
        seq_item = seq[index]
    end
    return seq_item or base
end
local function renderPreviewBox(u)
    local function fieldScalar(obj, key, idx, default)
        if not obj then return default end
        local v = obj[key]
        if v == nil then return default end
        if type(v) == 'number' then return v end
        local ok, res = pcall(function()
            return v[idx or 0]
        end)
        if ok and res ~= nil then return res end
        return default
    end
    local function fieldBool(obj, key, default)
        if not obj then return default end
        local v = obj[key]
        if v == nil then return default end
        if type(v) == 'boolean' then return v end
        local ok, res = pcall(function()
            return v[0]
        end)
        if ok and res ~= nil then return res and true or false end
        return default
    end
    local function miniRenderItem(DL, item, base, x, y, sz, highlight)
        local content = fieldScalar(item, 'content', 0, fieldScalar(base, 'content', 0, 0))
        local icon_idx = fieldScalar(item, 'icon', 0, fieldScalar(base, 'icon', 0, 0))
        local img_idx = fieldScalar(item, 'img_idx', 0, fieldScalar(base, 'img_idx', 0, 0))
        local img_alpha = fieldScalar(item, 'img_alpha', 0, fieldScalar(base, 'img_alpha', 0, 1.0))
        local img_scale = fieldScalar(item, 'img_scale', 0, fieldScalar(base, 'img_scale', 0, 1.0))
        local text_scale = fieldScalar(item, 'text_scale', 0, fieldScalar(base, 'text_scale', 0, 1.0))
        local opacity = fieldScalar(item, 'opacity', 0, fieldScalar(base, 'opacity', 0, 1.0))
        local preview_opacity = math.max(0.0, math.min(1.0, opacity or 1.0))
        local preview_alpha = preview_opacity * preview_opacity
        local opacity_vis = preview_alpha
        local r = item.r ~= nil and item.r or fieldScalar(base, 'color', 0, 1.0)
        local g = item.g ~= nil and item.g or fieldScalar(base, 'color', 1, 1.0)
        local b = item.b ~= nil and item.b or fieldScalar(base, 'color', 2, 1.0)
        local a = item.a ~= nil and item.a or fieldScalar(base, 'color', 3, 1.0)
        local p = imgui.ImVec2(x, y)
        local p2 = imgui.ImVec2(x + sz, y + sz)
        local ac = getTabAccent()
        local alpha_pct = math.max(0, math.min(100, math.floor((preview_opacity * 100) + 0.5)))
        local border_mult = highlight and 1.35 or 0.72
        local border_alpha = (highlight and 1.0 or 0.50) * preview_alpha
        local bg_alpha = preview_alpha
        local mini_bg = active_colors and (active_colors[imgui.Col.FrameBg]
            or active_colors[imgui.Col.ChildBg]
            or active_colors[imgui.Col.WindowBg])
        local mbr = mini_bg and (mini_bg[1] or 0.05) or 0.05
        local mbg = mini_bg and (mini_bg[2] or 0.05) or 0.05
        local mbb = mini_bg and (mini_bg[3] or 0.05) or 0.05
        local mba = mini_bg and (mini_bg[4] or 0.95) or 0.95
        DL:AddRectFilled(p, p2, HI_U32(imgui.ImVec4(mbr, mbg, mbb, bg_alpha * mba)), 4)
        DL:AddRect(p, p2, accentU32(ac, border_mult, border_alpha), 4)
        local pad = math.max(2.0, sz * 0.10)
        local avail = math.max(1.0, sz - pad * 2)
        local cxb = x + sz * 0.5
        local cyb = y + sz * 0.5
        local col_base = HI_U32(imgui.ImVec4(r, g, b, a * opacity))
        local clip_p1 = imgui.ImVec2(x + 1, y + 1)
        local clip_p2 = imgui.ImVec2(x + sz - 1, y + sz - 1)
        local function fitText(font, text, wanted_size, min_size)
            local min_fs = min_size or 4.5
            local fsz = math.max(min_fs, wanted_size or 0)
            local ts = font:CalcTextSizeA(fsz, 1000, 0, text)
            local max_w = math.max(1.0, avail)
            local max_h = math.max(1.0, avail)
            if ts.x > max_w or ts.y > max_h then
                local scale_w = max_w / math.max(1.0, ts.x)
                local scale_h = max_h / math.max(1.0, ts.y)
                fsz = math.max(min_fs, fsz * math.min(scale_w, scale_h))
                ts = font:CalcTextSizeA(fsz, 1000, 0, text)
                while (ts.x > max_w or ts.y > max_h) and fsz > min_fs + 0.01 do
                    fsz = math.max(min_fs, fsz * 0.92)
                    ts = font:CalcTextSizeA(fsz, 1000, 0, text)
                end
            end
            return fsz, ts
        end
        if content == 0 then
            local key = icon_list[icon_idx + 1] and icon_list[icon_idx + 1].key or "QUESTION"
            local ico = getIcon(key)
            local font_use = getFontForSize(sz)
            local fsz, ts = fitText(font_use, ico, sz * 0.52, 4.5)
            local fa_alpha = math.max(0, math.min(1, img_alpha * opacity))
            local col = HI_U32(imgui.ImVec4(r, g, b, a * fa_alpha))
            DL:PushClipRect(clip_p1, clip_p2, true)
            DL:AddTextFontPtr(font_use, fsz, imgui.ImVec2(cxb - ts.x / 2, cyb - ts.y / 2), col, ico)
            DL:PopClipRect()
        elseif content == 1 then
            local fname = imgFilename(img_idx)
            local tex = fname and getTexture(fname)
            if tex then
                local apply_c = fieldBool(base, 'seq_apply_img_color', false)
                local pr = apply_c and r or 1.0
                local pg = apply_c and g or 1.0
                local pb = apply_c and b or 1.0
                local max_half = avail * 0.5
                local half = math.max(1.0, math.min(max_half, sz * 0.42 * math.max(0.1, img_scale)))
                DL:PushClipRect(clip_p1, clip_p2, true)
                DL:AddImage(tex,
                    imgui.ImVec2(cxb - half, cyb - half),
                    imgui.ImVec2(cxb + half, cyb + half),
                    imgui.ImVec2(0, 0), imgui.ImVec2(1, 1),
                    HI_U32(imgui.ImVec4(pr, pg, pb, img_alpha * opacity_vis)))
                DL:PopClipRect()
            else
                local f2 = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
                local no = u8"нет"
                local fsz, ts2 = fitText(f2, no, 11, 4.5)
                DL:PushClipRect(clip_p1, clip_p2, true)
                DL:AddTextFontPtr(f2, fsz, imgui.ImVec2(cxb - ts2.x / 2, cyb - ts2.y / 2),
                    HI_U32(imgui.ImVec4(1, 1, 1, opacity_vis)), no)
                DL:PopClipRect()
            end
        elseif content == 2 then
            local txt = tostring(item.text_buf or "")
            if txt == "" then txt = "???" end
            local font_use = getTextFontForSize(sz)
            local wanted = math.max(4.5, sz * 0.36 * text_scale)
            local fsz, ts = fitText(font_use, txt, wanted, 4.5)
            local col = HI_U32(imgui.ImVec4(r, g, b, a * opacity_vis))
            local shad = HI_U32(imgui.ImVec4(0, 0, 0, opacity_vis * 0.7))
            DL:PushClipRect(clip_p1, clip_p2, true)
            DL:AddTextFontPtr(font_use, fsz, imgui.ImVec2(cxb - ts.x / 2 + 1, cyb - ts.y / 2 + 1), shad, txt)
            DL:AddTextFontPtr(font_use, fsz, imgui.ImVec2(cxb - ts.x / 2, cyb - ts.y / 2), col, txt)
            DL:PopClipRect()
        end
    end
    local base = u
    local seq_enabled = fieldBool(base, 'seq_enabled', false)
    local seq = base.sequence or {}
    local active_seq_item = nil
    local ok_active, active_candidate = pcall(function()
        if seq_enabled and #seq > 0 then
            return getSequenceItem(base, os.clock())
        end
        return nil
    end)
    if ok_active then
        active_seq_item = active_candidate
    end
    local box_size = fieldScalar(base, 'preview_box_size', 0, 80.0)
    local p = imgui.GetCursorScreenPos()
    local DL = imgui.GetWindowDrawList()
    local p2 = imgui.ImVec2(p.x + box_size, p.y + box_size)
    local ac = getTabAccent()
    local preview_opacity = math.max(0.0, math.min(1.0, fieldScalar(base, 'opacity', 0, 1.0)))
    local preview_alpha = preview_opacity * preview_opacity
    local preview_bg = active_colors and (active_colors[imgui.Col.FrameBg]
        or active_colors[imgui.Col.ChildBg]
        or active_colors[imgui.Col.WindowBg])
    local pbr = preview_bg and (preview_bg[1] or 0.05) or 0.05
    local pbg = preview_bg and (preview_bg[2] or 0.05) or 0.05
    local pbb = preview_bg and (preview_bg[3] or 0.05) or 0.05
    local pba = preview_bg and (preview_bg[4] or 0.95) or 0.95
    DL:AddRectFilled(p, p2, HI_U32(imgui.ImVec4(pbr, pbg, pbb, preview_alpha * pba)), 6)
    DL:AddRect(p, p2, accentU32(ac, 1.0, preview_alpha * 0.7), 6)
    if seq_enabled then
        DL:PushClipRect(p, p2, true)
        if #seq > 0 then
            local cols = 4
            local rows = math.max(1, math.ceil(#seq / cols))
            local pad = 4.0
            local gap = 2.0
            local avail_w = math.max(1.0, box_size - pad * 2 - gap * (cols - 1))
            local avail_h = math.max(1.0, box_size - pad * 2 - gap * (rows - 1))
            local cell = math.max(4.0, math.min(avail_w / cols, avail_h / rows))
            local grid_w = cols * cell + gap * (cols - 1)
            local start_x = p.x + pad + math.max(0.0, (avail_w - grid_w) * 0.5)
            local start_y = p.y + pad
            for i, item in ipairs(seq) do
                local row = math.floor((i - 1) / cols)
                local col = (i - 1) % cols
                local x = start_x + col * (cell + gap)
                local y = start_y + row * (cell + gap)
                local highlight = (active_seq_item ~= nil and item == active_seq_item) or
                                  (placement_mode.active and placement_mode.target == item)
                miniRenderItem(DL, item, base, x, y, cell, highlight)
            end
        else
            local font = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
            local txt = u8"[ пусто ]"
            local ts = font:CalcTextSizeA(11, 1000, 0, txt)
            DL:AddTextFontPtr(font, 11,
                imgui.ImVec2(p.x + (box_size - ts.x) * 0.5, p.y + (box_size - ts.y) * 0.5),
                HI_U32(imgui.ImVec4(1, 1, 1, preview_alpha * 0.45)), txt)
        end
        DL:PopClipRect()
    else
        local size_val = fieldScalar(base, 'size', 0, 40.0)
        local sz_t = math.max(0, math.min(1, (size_val - 6) / 94))
        local ico_scale = 0.25 + sz_t * 0.35
        local content = fieldScalar(base, 'content', 0, 0)
        local icon_idx = fieldScalar(base, 'icon', 0, 0)
        local img_idx = fieldScalar(base, 'img_idx', 0, 0)
        local img_alpha = fieldScalar(base, 'img_alpha', 0, 1.0)
        local img_scale = fieldScalar(base, 'img_scale', 0, 1.0)
        local text_scale = fieldScalar(base, 'text_scale', 0, 1.0)
        local opacity = fieldScalar(base, 'opacity', 0, 1.0)
        local opacity_vis = math.max(0.0, math.min(1.0, opacity or 1.0))
        opacity_vis = opacity_vis * opacity_vis
        local r = fieldScalar(base, 'color', 0, 1.0)
        local g = fieldScalar(base, 'color', 1, 1.0)
        local b = fieldScalar(base, 'color', 2, 1.0)
        local a = fieldScalar(base, 'color', 3, 1.0)
        local cxb = p.x + box_size * 0.5
        local cyb = p.y + box_size * 0.5
        if content == 0 then
            local fsz = box_size * ico_scale
            local font = getFontForSize(fsz)
            local key = icon_list[icon_idx + 1] and icon_list[icon_idx + 1].key or "QUESTION"
            local ico = getIcon(key)
            local col = HI_U32(imgui.ImVec4(r, g, b, a * opacity_vis))
            local ts = font:CalcTextSizeA(fsz, 1000, 0, ico)
            DL:PushClipRect(imgui.ImVec2(p.x + 2, p.y + 2), imgui.ImVec2(p2.x - 2, p2.y - 2), true)
            DL:AddTextFontPtr(font, fsz, imgui.ImVec2(cxb - ts.x / 2, cyb - ts.y / 2), col, ico)
            DL:PopClipRect()
        elseif content == 1 then
            local fname = imgFilename(img_idx)
            local tex = fname and getTexture(fname)
            if tex then
                local apply_c = fieldBool(base, 'seq_apply_img_color', false)
                local pr = apply_c and r or 1.0
                local pg = apply_c and g or 1.0
                local pb = apply_c and b or 1.0
                local half = box_size * ico_scale * img_scale * 0.5
                DL:PushClipRect(imgui.ImVec2(p.x + 2, p.y + 2), imgui.ImVec2(p2.x - 2, p2.y - 2), true)
                DL:AddImage(tex,
                    imgui.ImVec2(cxb - half, cyb - half),
                    imgui.ImVec2(cxb + half, cyb + half),
                    imgui.ImVec2(0, 0), imgui.ImVec2(1, 1),
                    HI_U32(imgui.ImVec4(pr, pg, pb, img_alpha * opacity_vis)))
                DL:PopClipRect()
            else
                local f2 = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
                local no = u8"нет"
                local ts2 = f2:CalcTextSizeA(13, 1000, 0, no)
                DL:AddTextFontPtr(f2, 13,
                    imgui.ImVec2(cxb - ts2.x / 2, cyb - ts2.y / 2),
                    HI_U32(imgui.ImVec4(1, 1, 1, math.max(0.0, math.min(1.0, opacity or 1.0)))), no)
            end
        elseif content == 2 then
            local txt = tostring(base.text_buf and getCharBuf(base.text_buf) or "")
            if txt == "" then txt = "???" end
            local avail = box_size - 6
            local fsz = box_size * ico_scale * text_scale
            local font = getFontForSize(fsz)
            local ts = font:CalcTextSizeA(fsz, 1000, 0, txt)
            if ts.x > avail then fsz = fsz * (avail / ts.x) end
            if fsz > avail then fsz = avail end
            font = getTextFontForSize(fsz)
            ts = font:CalcTextSizeA(fsz, 1000, 0, txt)
            local col = HI_U32(imgui.ImVec4(r, g, b, a * opacity_vis))
            local shad = HI_U32(imgui.ImVec4(0, 0, 0, opacity_vis * 0.7))
            DL:PushClipRect(imgui.ImVec2(p.x + 2, p.y + 2), imgui.ImVec2(p2.x - 2, p2.y - 2), true)
            DL:AddTextFontPtr(font, fsz, imgui.ImVec2(cxb - ts.x / 2 + 1, cyb - ts.y / 2 + 1), shad, txt)
            DL:AddTextFontPtr(font, fsz, imgui.ImVec2(cxb - ts.x / 2, cyb - ts.y / 2), col, txt)
            DL:PopClipRect()
        end
    end
    imgui.Dummy(imgui.ImVec2(box_size, box_size))
end
local icon_search_bufs = {}
local icon_filtered    = {}
local function iconComboWithPreview(id, u)
    local idx = math.max(1, math.min(#icon_list, (u.icon[0] or 0) + 1))
    local cur = icon_list[idx]
    local ac  = getTabAccent()
    if not icon_search_bufs[id] then icon_search_bufs[id] = new.char[64]("") end
    local sbuf = icon_search_bufs[id]
    local changed = false
    imgui.SetNextItemWidth(220)
    if hi_fa_font_small then imgui.PushFont(hi_fa_font_small) end
    local opened = imgui.BeginCombo(u8("##ico_"..id), getIcon(cur.key) .. " " .. cur.label)
    if hi_fa_font_small then imgui.PopFont() end
    if opened then
        imgui.SetNextItemWidth(215)
        local input_changed = imgui.InputText(Fn.T(u8("##srch_"..id)), sbuf, ffi.sizeof(sbuf))
        local filter = ffi.string(sbuf):lower()
        if input_changed or not icon_filtered[id] or icon_filtered[id.."_f"] ~= filter then
            local t = {}
            for i, e in ipairs(icon_list) do
                if filter=="" or e.label:lower():find(filter,1,true) or e.key:lower():find(filter,1,true) then
                    t[#t+1] = {i=i-1, e=e}
                end
            end
            icon_filtered[id]       = t
            icon_filtered[id.."_f"] = filter
        end
        local list = icon_filtered[id] or {}
        local shown = 0
        for _, item in ipairs(list) do
            local sel = ((u.icon[0] or 0) == item.i)
            if sel then
                imgui.PushStyleColor(imgui.Col.Header,        accentVec4(ac,0.5,0.5))
                imgui.PushStyleColor(imgui.Col.HeaderHovered, accentVec4(ac,0.8,0.7))
            end
            if hi_fa_font_small then imgui.PushFont(hi_fa_font_small) end
            if imgui.Selectable(getIcon(item.e.key) .. " " .. item.e.label .. "##s_" .. id .. item.i, sel, 0, imgui.ImVec2(0,18)) then
                u.icon[0] = item.i
                icon_filtered[id] = nil
                changed = true
            end
            if hi_fa_font_small then imgui.PopFont() end
            if sel then imgui.PopStyleColor(2); imgui.SetItemDefaultFocus() end
            shown = shown + 1
            if shown >= 200 then
                imgui.TextDisabled(string.format(Fn.T(u8("... ещё %d — уточните поиск")), math.max(0, #list - 200)))
                break
            end
        end
        imgui.EndCombo()
    end
    return changed
end
local function animCombo(id, u)
    local ac = getTabAccent()
    local changed = false
    imgui.Text(Fn.T(u8"Анимация:"))
    imgui.SetNextItemWidth(220)
    local current = animEntry(u.anim[0] or 0)
    if imgui.BeginCombo(u8("##anim_"..id), Fn.T(u8(current.label))) then
        for ai, entry in ipairs(anim_list) do
            local sel = ((u.anim[0] or 0) == ai - 1)
            if sel then
                imgui.PushStyleColor(imgui.Col.Header,        accentVec4(ac,0.5,0.5))
                imgui.PushStyleColor(imgui.Col.HeaderHovered, accentVec4(ac,0.8,0.7))
            end
            if imgui.Selectable(Fn.T(u8(entry.label.."##asel_"..id..ai)), sel) then
                u.anim[0] = ai - 1
                changed = true
            end
            if sel then imgui.PopStyleColor(2); imgui.SetItemDefaultFocus() end
        end
        imgui.EndCombo()
    end
    return changed
end
local function contentTypeSwitcher(id, u)
    local labels = { u8"FA Иконка", u8"Изображение", u8"Текст" }
    local ac = getTabAccent()
    local changed = false
    for ti, lbl in ipairs(labels) do
        lbl = Fn.T(lbl)
        local ti_idx = ti - 1
        local active = (u.content[0] or 0) == ti_idx
        if active then
            imgui.PushStyleColor(imgui.Col.Button,        accentVec4(ac, 0.75, 1.0))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, accentVec4(ac, 0.95, 1.0))
            imgui.PushStyleColor(imgui.Col.ButtonActive,  accentVec4(ac, 1.1,  1.0))
        else
            imgui.PushStyleColor(imgui.Col.Button,        accentVec4(ac, 0.18, 0.70))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, accentVec4(ac, 0.45, 0.85))
            imgui.PushStyleColor(imgui.Col.ButtonActive,  accentVec4(ac, 0.65, 0.95))
        end
        if imgui.Button(lbl.."##ct_"..id..ti, imgui.ImVec2(100, 24)) then
            u.content[0] = ti_idx
            changed = true
        end
        imgui.PopStyleColor(3)
        if ti < 3 then imgui.SameLine(0, 4) end
    end
    return changed
end
local function renderContentPanel(id, u)
    local changed = false
    if contentTypeSwitcher(id, u) then changed = true end
    imgui.Spacing()
    renderPreviewBox(u)
    imgui.SameLine(0, 12)
    imgui.BeginGroup()
    if u.content[0] == 0 then
        imgui.Text(Fn.T(u8("Иконка:")))
        if iconComboWithPreview(id, u) then changed = true end
        imgui.SetNextItemWidth(200)
        if imgui.SliderFloat(Fn.T(u8("Размер иконки##sz_"..id)), u.size, 6, 100, "%.0f") then changed = true end
        imgui.SetNextItemWidth(200)
        if imgui.SliderFloat(Fn.T(u8("Прозрачность##opico_"..id)), u.opacity, 0.0, 1.0, "%.2f") then changed = true end
    elseif u.content[0] == 1 then
        imgui.TextDisabled(Fn.T(u8("Положите PNG/JPG/BMP в папку:")))
        CBUGER_MarqueeLabel(u8("moonloader\\CBUGER PRO\\icons_image\\"), 230)
        if CBUGER_MarqueeBeginCombo(u8("##img_"..id), img_names_u8[u.img_idx[0]+1] or u8("[ Нет ]"), 200) then
            for ni, nm in ipairs(img_names_u8) do
                local sel = (u.img_idx[0] == ni - 1)
                if CBUGER_MarqueeSelectable(nm, "im_"..id..ni, sel) then u.img_idx[0] = ni-1; changed = true end
                if sel then imgui.SetItemDefaultFocus() end
            end
            imgui.EndCombo()
        end
        imgui.SameLine(0, 4)
        if imgui.SmallButton(Fn.T(u8("Обн.##ri_"..id))) then refreshImages(); changed = true end
        imgui.Spacing()
        imgui.SetNextItemWidth(200)
        if imgui.SliderFloat(Fn.T(u8("Масштаб##is_"..id)), u.img_scale, 0.2, 3.0, "%.2f") then changed = true end
        imgui.SetNextItemWidth(200)
        if imgui.SliderFloat(Fn.T(u8("Прозрачность##ia_"..id)), u.img_alpha, 0.0, 1.0, "%.2f") then changed = true end
    elseif u.content[0] == 2 then
        imgui.Text(Fn.T(u8("Текст:")))
        imgui.SetNextItemWidth(200)
        if imgui.InputText(Fn.T(u8("##tx_"..id)), u.text_buf, ffi.sizeof(u.text_buf), imgui.InputTextFlags.AutoSelectAll) then changed = true end
        imgui.Spacing()
        imgui.SetNextItemWidth(200)
        if imgui.SliderFloat(Fn.T(u8("Масштаб##ts_"..id)), u.text_scale, 0.2, 3.0, "%.2f") then changed = true end
        imgui.SetNextItemWidth(200)
        if imgui.SliderFloat(Fn.T(u8("прозрачность##optxt_"..id)), u.opacity, 0.0, 1.0, "%.2f") then changed = true end
    end
    if renderSequenceControls(id, u) then changed = true end
    imgui.EndGroup()
    return changed
end
renderSequenceControls = function(id, u)
    ensureSequenceDefaults(u)
    local changed = false
    local function seqSetContent(item, new_content)
        new_content = tonumber(new_content) or 0
        if item.content ~= new_content then
            item.content = new_content
            if new_content == 0 and (item.icon == nil) then item.icon = 0 end
            if new_content == 1 and (item.img_idx == nil) then item.img_idx = 0 end
            if new_content == 2 and (item.text_buf == nil) then item.text_buf = "" end
            changed = true
        end
    end
    local function seqFieldValue(item, key, default)
        local v = item and item[key]
        if v == nil then return default end
        if type(v) == 'number' then return v end
        return default
    end
    local function seqContentButtons(item, row_id)
        local labels = { u8("FA"), u8("IMG"), u8("TXT") }
        for ci, lbl in ipairs(labels) do
            local active = (tonumber(item.content) or 0) == (ci - 1)
            if active then
                imgui.PushStyleColor(imgui.Col.Button,        accentVec4(getTabAccent(), 0.75, 1.0))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, accentVec4(getTabAccent(), 0.95, 1.0))
                imgui.PushStyleColor(imgui.Col.ButtonActive,  accentVec4(getTabAccent(), 1.10, 1.0))
            else
                imgui.PushStyleColor(imgui.Col.Button,        accentVec4(getTabAccent(), 0.18, 0.70))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, accentVec4(getTabAccent(), 0.45, 0.85))
                imgui.PushStyleColor(imgui.Col.ButtonActive,  accentVec4(getTabAccent(), 0.65, 0.95))
            end
            if imgui.Button(lbl.."##seqct_"..id.."_"..row_id.."_"..ci, imgui.ImVec2(44, 22)) then
                seqSetContent(item, ci - 1)
            end
            imgui.PopStyleColor(3)
            if ci < 3 then imgui.SameLine(0, 4) end
        end
    end
    local function seqIconCombo(item, row_id)
        local combo_key = id.."_"..row_id
        if not icon_search_bufs[combo_key] then icon_search_bufs[combo_key] = new.char[64]("") end
        local sbuf = icon_search_bufs[combo_key]
        local idx = math.max(1, math.min(#icon_list, (tonumber(item.icon) or 0) + 1))
        local cur = icon_list[idx]
        local ac  = getTabAccent()
        imgui.SetNextItemWidth(220)
        if hi_fa_font_small then imgui.PushFont(hi_fa_font_small) end
        local opened = imgui.BeginCombo(u8("##seqico_"..combo_key), getIcon(cur.key) .. " " .. cur.label)
        if hi_fa_font_small then imgui.PopFont() end
        if opened then
            imgui.SetNextItemWidth(215)
            local input_changed = imgui.InputText(Fn.T(u8("##seqsrch_"..combo_key)), sbuf, ffi.sizeof(sbuf))
            local filter = ffi.string(sbuf):lower()
            local fkey = combo_key.."_f"
            if input_changed or not icon_filtered[combo_key] or icon_filtered[fkey] ~= filter then
                local t = {}
                for ii, e in ipairs(icon_list) do
                    if filter == "" or e.label:lower():find(filter,1,true) or e.key:lower():find(filter,1,true) then
                        t[#t+1] = {i=ii-1, e=e}
                    end
                end
                icon_filtered[combo_key] = t
                icon_filtered[fkey]      = filter
            end
            local list = icon_filtered[combo_key] or {}
            local shown = 0
            for _, entry in ipairs(list) do
                local sel = ((tonumber(item.icon) or 0) == entry.i)
                if sel then
                    imgui.PushStyleColor(imgui.Col.Header,        accentVec4(ac, 0.5, 0.5))
                    imgui.PushStyleColor(imgui.Col.HeaderHovered, accentVec4(ac, 0.8, 0.7))
                end
                if hi_fa_font_small then imgui.PushFont(hi_fa_font_small) end
                if imgui.Selectable(getIcon(entry.e.key) .. " " .. entry.e.label .. "##seqicosel_"..combo_key.."_"..entry.i, sel, 0, imgui.ImVec2(0, 18)) then
                    item.icon = entry.i
                    icon_filtered[combo_key] = nil
                    changed = true
                end
                if hi_fa_font_small then imgui.PopFont() end
                if sel then imgui.PopStyleColor(2); imgui.SetItemDefaultFocus() end
                shown = shown + 1
                if shown >= 200 then
                    imgui.TextDisabled(string.format(Fn.T(u8("... ещё %d — уточните поиск")), math.max(0, #list - 200)))
                    break
                end
            end
            imgui.EndCombo()
        end
    end
    local function seqImageCombo(item, row_id)
        if CBUGER_MarqueeBeginCombo(u8("##seqimg_"..id.."_"..row_id), img_names_u8[(tonumber(item.img_idx) or 0) + 1] or u8("[ Нет ]"), 180) then
            for ni, nm in ipairs(img_names_u8) do
                local sel = ((tonumber(item.img_idx) or 0) == ni - 1)
                if CBUGER_MarqueeSelectable(nm, "seqimgsel_"..id.."_"..row_id.."_"..ni, sel) then
                    item.img_idx = ni - 1
                    changed = true
                end
                if sel then imgui.SetItemDefaultFocus() end
            end
            imgui.EndCombo()
        end
        imgui.SameLine(0, 4)
        if imgui.SmallButton(Fn.T(u8("Обн.##seqri_"..id.."_"..row_id))) then
            refreshImages()
            changed = true
        end
    end
    local function seqEditPopup(item, row_id)
        if imgui.BeginPopup(Fn.T(u8("seqedit_"..id.."_"..row_id))) then
            imgui.Text(Fn.T(u8("Тип:")))
            imgui.SameLine(0, 8)
            if seqContentButtons(item, row_id .. "_pop") then changed = true end
            imgui.Spacing()
            if (tonumber(item.content) or 0) == 0 then
                imgui.Text(Fn.T(u8("Иконка:")))
                seqIconCombo(item, row_id .. "_pop")
                imgui.SetNextItemWidth(200)
                local is = new.float[1](seqFieldValue(item, 'img_scale', 1.0))
                if imgui.SliderFloat(Fn.T(u8("Размер иконки##seqfais_"..id.."_"..row_id)), is, 0.2, 3.0, "%.2f") then
                    item.img_scale = is[0]; changed = true
                end
                imgui.SetNextItemWidth(200)
                local ia = new.float[1](seqFieldValue(item, 'img_alpha', 1.0))
                if imgui.SliderFloat(Fn.T(u8("Прозрачность##seqfaia_"..id.."_"..row_id)), ia, 0.0, 1.0, "%.2f") then
                    item.img_alpha = ia[0]; changed = true
                end
            elseif (tonumber(item.content) or 0) == 1 then
                imgui.TextDisabled(Fn.T(u8("Положите PNG/JPG/BMP в папку:")))
        CBUGER_MarqueeLabel(u8("moonloader\\CBUGER PRO\\icons_image\\"), 230)
                seqImageCombo(item, row_id .. "_pop")
                imgui.SetNextItemWidth(200)
                local is = new.float[1](seqFieldValue(item, 'img_scale', 1.0))
                if imgui.SliderFloat(Fn.T(u8("Масштаб##seqis_"..id.."_"..row_id)), is, 0.2, 3.0, "%.2f") then
                    item.img_scale = is[0]; changed = true
                end
                imgui.SetNextItemWidth(200)
                local ia = new.float[1](seqFieldValue(item, 'img_alpha', 1.0))
                if imgui.SliderFloat(Fn.T(u8("Прозрачность изобр.##seqia_"..id.."_"..row_id)), ia, 0.0, 1.0, "%.2f") then
                    item.img_alpha = ia[0]; changed = true
                end
                imgui.Spacing()
                if u.seq_apply_img_color ~= nil then
                    if imgui.Checkbox(Fn.T(u8("Применять цвет к изображению##seqimgclrseq_"..id.."_"..row_id)), u.seq_apply_img_color) then
                        changed = true
                    end
                end
            elseif (tonumber(item.content) or 0) == 2 then
                imgui.Text(Fn.T(u8("Текст:")))
                local buf = new.char[64](tostring(item.text_buf or ""))
                imgui.SetNextItemWidth(220)
                if imgui.InputText(Fn.T(u8("##seqtxt_"..id.."_"..row_id)), buf, ffi.sizeof(buf), imgui.InputTextFlags.AutoSelectAll) then
                    item.text_buf = ffi.string(buf); changed = true
                end
                imgui.SetNextItemWidth(200)
                local ts = new.float[1](seqFieldValue(item, 'text_scale', 1.0))
                if imgui.SliderFloat(Fn.T(u8("Масштаб текста##seqts_"..id.."_"..row_id)), ts, 0.2, 3.0, "%.2f") then
                    item.text_scale = ts[0]; changed = true
                end
                imgui.SetNextItemWidth(200)
                local op = new.float[1](seqFieldValue(item, 'opacity', 1.0))
                if imgui.SliderFloat(Fn.T(u8("Прозрачность текста##seqtop_"..id.."_"..row_id)), op, 0.0, 1.0, "%.2f") then
                    item.opacity = op[0]; changed = true
                end
            end
            imgui.Spacing()
            if imgui.Button(Fn.T(u8("Закрыть##seqeditclose_"..id.."_"..row_id)), imgui.ImVec2(130, 28)) then
                imgui.CloseCurrentPopup()
            end
            imgui.EndPopup()
        end
    end
    local seq_color_open = seq_color_open or {}
    local function seqColorPopup(item, row_id)
        local key = tostring(id) .. "_" .. tostring(row_id)
        if seq_color_open[key] == nil then seq_color_open[key] = false end
        if seq_color_open[key] then
            imgui.BeginChild(u8("##seqcolpanel_"..id.."_"..row_id), imgui.ImVec2(0, 0), true)
            imgui.Text(Fn.T(u8("Цвет иконки:")))
            imgui.Spacing()
            local col = new.float[4](
                seqFieldValue(item, 'r', 1.0),
                seqFieldValue(item, 'g', 1.0),
                seqFieldValue(item, 'b', 1.0),
                seqFieldValue(item, 'a', 1.0)
            )
            if imgui.ColorPicker4(Fn.T(u8("##seqpk_"..id.."_"..row_id)), col,
                imgui.ColorEditFlags.AlphaBar +
                imgui.ColorEditFlags.NoSidePreview +
                imgui.ColorEditFlags.PickerHueBar) then
                item.r, item.g, item.b, item.a = col[0], col[1], col[2], col[3]
                changed = true
            end
            imgui.Separator()
            imgui.SetNextItemWidth(200)
            local op = new.float[1](seqFieldValue(item, 'opacity', 1.0))
            if imgui.SliderFloat(Fn.T(u8("Прозрачность##seqop_"..id.."_"..row_id)), op, 0.0, 1.0, "%.2f") then
                item.opacity = op[0]; changed = true
            end
            imgui.Spacing()
            if imgui.Button(Fn.T(u8("Закрыть##seqcolclose_"..id.."_"..row_id)), imgui.ImVec2(130, 28)) then
                seq_color_open[key] = false
            end
            imgui.EndChild()
        end
    end
    imgui.Separator()
    imgui.Spacing()
    imgui.Text(Fn.T(u8("Переливание:")))
    if imgui.Checkbox(Fn.T(u8("Включить##seqen_"..id)), u.seq_enabled) then changed = true end
    imgui.SameLine(0, 10)
    local seq_popup_title = u8("Настройки##seqpopup_"..id)
    if imgui.Button(Fn.T(u8("Настройки##seqopen_"..id)), imgui.ImVec2(120, 24)) then
        u.seq_open = true
        imgui.OpenPopup(seq_popup_title)
        changed = true
    end
    imgui.SameLine(0, 10)
    imgui.TextDisabled(Fn.T(u8("Эл.: ")) .. tostring(#(u.sequence or {})))
    imgui.SetNextWindowSize(imgui.ImVec2(610, 470), imgui.Cond.Appearing)
    if u.seq_open then
        local p_open = new.bool(true)
        if imgui.BeginPopupModal(seq_popup_title, p_open, imgui.WindowFlags.NoResize) then
            if imgui.Checkbox(Fn.T(u8("Включить переливание##seqen2_"..id)), u.seq_enabled) then changed = true end
            imgui.SetNextItemWidth(220)
            if imgui.SliderFloat(Fn.T(u8("Скорость смены##seqsp_"..id)), u.seq_speed, 0.10, 10.0, "%.2f") then changed = true end
            imgui.Spacing()
            if imgui.Button(iconOrFallback("PLUS", "+") .. Fn.T(u8(" Добавить##seqadd_"..id)), imgui.ImVec2(210, 26)) then
                table.insert(u.sequence, copyBlockSnapshot(u))
                changed = true
            end
            imgui.SameLine(0, 8)
            if imgui.Button(iconOrFallback("BROOM", "?") .. Fn.T(u8(" Очистить##seqclr_"..id)), imgui.ImVec2(120, 26)) then
                u.sequence = {}
                changed = true
            end
            imgui.Spacing()
            imgui.BeginChild(u8("##seqlist_"..id), imgui.ImVec2(0, 310), true)
            for i, item in ipairs(u.sequence) do
                local cr = seqFieldValue(item, 'r', 1.0)
                local cg = seqFieldValue(item, 'g', 1.0)
                local cb = seqFieldValue(item, 'b', 1.0)
                local ca = seqFieldValue(item, 'a', 1.0)
                local lbl = sequenceItemLabel(item)
                local ctype = tonumber(item.content) or 0
                local row_op = math.max(0.0, math.min(1.0,
                    (ctype == 0 or ctype == 1) and seqFieldValue(item, 'img_alpha', 1.0) or seqFieldValue(item, 'opacity', 1.0)))
                imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(cr, cg, cb, ca * row_op))
                if CBUGER_MarqueeButton(lbl, "seqicobtn_"..id.."_"..i, 180, 22, true) then
                    imgui.OpenPopup(Fn.T(u8("seqedit_"..id.."_"..i)))
                end
                imgui.PopStyleColor()
                imgui.SameLine(0, 4)
                if imgui.InvisibleButton(u8("##seqcolbtn_"..id.."_"..i), imgui.ImVec2(22, 22)) then
                    seq_color_open[tostring(id) .. "_" .. tostring(i)] = not seq_color_open[tostring(id) .. "_" .. tostring(i)]
                end
                local DLcol = imgui.GetWindowDrawList()
                local pcol = imgui.GetItemRectMin()
                local pcol2 = imgui.GetItemRectMax()
                DLcol:AddRectFilled(pcol, pcol2, HI_U32(imgui.ImVec4(cr, cg, cb, ca)), 4)
                DLcol:AddRect(pcol, pcol2, HI_U32(imgui.ImVec4(1,1,1,0.25)), 4)
                imgui.SameLine(0, 4)
                seqContentButtons(item, i)
                imgui.SameLine(0, 4)
                if iconButton(moveIcon("¦"), "seqmovebtn_"..id.."_"..i, imgui.ImVec2(28, 22), 0, 2, 0.95) then
                    pending_placement_target = item
                    changed = true
                end
                imgui.SameLine(0, 4)
                if imgui.Button(iconOrFallback("COPY", "?") .. "##seqcpy_"..id.."_"..i, imgui.ImVec2(28, 22)) then
                    table.insert(u.sequence, i + 1, copySequenceItem(item))
                    changed = true
                end
                imgui.SameLine(0, 4)
                if imgui.Button(iconOrFallback("TRASH_CAN", "?") .. "##seqdel_"..id.."_"..i, imgui.ImVec2(28, 22)) then
                    table.remove(u.sequence, i)
                    changed = true
                    break
                end
                seqEditPopup(item, i)
                seqColorPopup(item, i)
                imgui.Spacing()
            end
            imgui.EndChild()
            if imgui.Button(Fn.T(u8("Закрыть##seqclose_"..id)), imgui.ImVec2(130, 28)) then
                u.seq_open = false
                imgui.CloseCurrentPopup()
            end
            imgui.EndPopup()
        end
        if not p_open[0] then
            u.seq_open = false
        end
    end
    return changed
end
local function colorPopup(id, color_arr)
    local r = color_arr[0]; local g = color_arr[1]
    local b = color_arr[2]; local a = color_arr[3]
    local changed = false
    imgui.Text(Fn.T(u8"Цвет:"))
    imgui.SameLine(0, 8)
    local DL = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local h, w = 22, 80
    local pressed = imgui.InvisibleButton(u8("##cbtn_"..id), imgui.ImVec2(w, h))
    local p2 = imgui.GetItemRectMax()
    DL:AddRectFilled(p, p2,
        HI_U32(imgui.ImVec4(r, g, b, 1.0)), 4)
    DL:AddRect(p, p2,
        HI_U32(imgui.ImVec4(1, 1, 1, 0.25)), 4)
    if pressed then
        imgui.OpenPopup(Fn.T(u8("##cpop_" .. id)))
    end
    imgui.SetNextWindowSize(imgui.ImVec2(220, 310), imgui.Cond.Appearing)
    if imgui.BeginPopup(Fn.T(u8("##cpop_" .. id))) then
        imgui.Text(Fn.T(u8("Цвет:")))
        imgui.Spacing()
        changed = imgui.ColorPicker4(Fn.T(u8("##cpk_"..id)), color_arr,
            imgui.ColorEditFlags.AlphaBar +
            imgui.ColorEditFlags.NoSidePreview +
            imgui.ColorEditFlags.PickerHueBar) or changed
        imgui.Spacing()
        if imgui.Button(Fn.T(u8("Закрыть##cclose_"..id)), imgui.ImVec2(130, 28)) then
            imgui.CloseCurrentPopup()
        end
        imgui.EndPopup()
    end
    return changed
end
local function renderEventTab(id, u)
    local changed = false
    imgui.Spacing()
    if imgui.Checkbox(Fn.T(u8("Включить##en_"..id)), u.enable) then changed = true end
    imgui.Separator(); imgui.Spacing()
    if renderContentPanel(id, u) then changed = true end
    imgui.Separator(); imgui.Spacing()
    if animCombo(id, u) then changed = true end
    imgui.Separator(); imgui.Spacing()
    if colorPopup(id, u.color) then changed = true end
    if u.offset_xy ~= nil or u.offset_y ~= nil then
        imgui.SameLine(0, 8)
        if iconButton(moveIcon("¦"), "mv_"..id, imgui.ImVec2(28, 22), 0, 2, 0.95) then
            pending_placement_target = resolvePlacementTarget(u)
            changed = true
        end
        if u.render_distance ~= nil then
            imgui.SameLine(0, 5)
            imgui.TextDisabled(Fn.T(u8("Дал.:")))
            imgui.SameLine(0, 4)
            imgui.SetNextItemWidth(112)
            if imgui.SliderFloat("##dist_"..id, u.render_distance, 10.0, 500.0, "%.0f") then
                u.render_distance[0] = math.max(10.0, math.min(500.0, u.render_distance[0]))
                changed = true
            end
            imgui.SameLine(0, 4)
            imgui.TextDisabled(Fn.T(u8("м")))
        end
        imgui.Spacing()
    end
    imgui.Separator(); imgui.Spacing()
    imgui.SetNextItemWidth(230)
    if imgui.SliderFloat(Fn.T(u8("Время (сек)##tm_"..id)), u.time, 0.5, 10, "%.1f") then changed = true end
    imgui.SetNextItemWidth(230)
