function renderHeadIcons()
    local module_alpha = CBUGER_UPDATE_MODULE_FADE('headicons', window_state[0], CBUGER_GET_ANIM_RATE(15))
    if module_alpha <= 0.01 then return end
    local sw, sh = getScreenResolution()
    imgui.SetNextWindowPos(imgui.ImVec2(sw/2-290, sh/2-260), imgui.Cond.FirstUseEver)
    local hi_rst = CBUGER_APPLY_WINDOW_SIZE("headicons", 580, 470)
