    imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, CBUGER_GET_INTERFACE_ALPHA() * module_alpha)
    local _gc = active_colors or {}
    local function _pushGlobalStyleColor(id, fallback)
        if id == nil then return end
        local c = _gc[id] or fallback
        imgui.PushStyleColor(id, imgui.ImVec4(c[1] or 0, c[2] or 0, c[3] or 0, c[4] or 1))
    end
    _pushGlobalStyleColor(imgui.Col.WindowBg,          {0.02, 0.02, 0.02, 0.95})
    _pushGlobalStyleColor(imgui.Col.ChildBg,           {0.01, 0.01, 0.01, 0.40})
    _pushGlobalStyleColor(imgui.Col.PopupBg,           {0.02, 0.02, 0.02, 0.98})
    _pushGlobalStyleColor(imgui.Col.Border,            {0.20, 0.20, 0.20, 0.60})
    _pushGlobalStyleColor(imgui.Col.TitleBg,           {0.02, 0.02, 0.02, 0.95})
    _pushGlobalStyleColor(imgui.Col.TitleBgActive,     {0.08, 0.08, 0.08, 1.00})
    _pushGlobalStyleColor(imgui.Col.Separator,         {0.15, 0.15, 0.15, 0.80})
    _pushGlobalStyleColor(imgui.Col.SeparatorHovered,  {0.25, 0.25, 0.25, 1.00})
    _pushGlobalStyleColor(imgui.Col.SeparatorActive,   {0.40, 0.40, 0.40, 1.00})
    local _ac = active_colors and active_colors[imgui.Col.Border]
    local ac = _ac and {x=_ac[1],y=_ac[2],z=_ac[3],w=1.0}
              or {x=0.2,y=0.6,z=1.0,w=1.0}
    local hi_open_ptr = window_state[0] and window_state or nil
    imgui.Begin(u8"by Pryanix x Panteon", hi_open_ptr, imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoResize)
    CBUGER_DRAW_INVISIBLE_RESIZER("headicons", hi_rst, 420, 330, CBUGER_GET_INTERFACE_ALPHA(), true)
    do
        local hdl = imgui.GetWindowDrawList()
        local hp  = imgui.GetWindowPos()
        local hs  = imgui.GetWindowSize()
        CBUGER_DRAW_GLOBAL_AMBIENT(hdl, hp, imgui.ImVec2(hp.x + hs.x, hp.y + hs.y), CBUGER_GET_INTERFACE_ALPHA())
    end
    imgui.TextColored(accentVec4(ac, 1.0, 1.0), Fn.T(u8"  HeadIcons"))
    imgui.SameLine()
    imgui.TextDisabled(u8"/icons")
    imgui.Separator(); imgui.Spacing()
    imgui.BeginChild(u8"##sidebar", imgui.ImVec2(148, 0), true)
    imgui.TextColored(accentVec4(ac, 1.0, 1.0), Fn.T(u8" РАЗДЕЛЫ"))
    imgui.Separator(); imgui.Spacing()
    local tab_defs = {
        { idx=0, id="death",    label="Смерть",         icon_key="SKULL",         u=ui.death     },
        { idx=1, id="kill",     label="Убийство",       icon_key="CROSSHAIRS",    u=ui.kill      },
        { idx=2, id="armor",    label="Броня",          icon_key="SHIELD_HALVED", u=ui.armor     },
        { idx=3, id="self",     label="Мои иконки",     icon_key="STAR",          u=self_icon    },
        { idx=4, id="settings", label="Настройки",      icon_key="GEAR",          u=nil          },
    }
    for _, td in ipairs(tab_defs) do
        local is_active = active_tab[0] == td.idx
        if is_active then
            imgui.PushStyleColor(imgui.Col.Button,        accentVec4(ac, 0.45, 0.90))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, accentVec4(ac, 0.75, 0.95))
            imgui.PushStyleColor(imgui.Col.ButtonActive,  accentVec4(ac, 1.00, 1.00))
        else
            imgui.PushStyleColor(imgui.Col.Button,        accentVec4(ac, 0.08, 0.55))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, accentVec4(ac, 0.35, 0.75))
            imgui.PushStyleColor(imgui.Col.ButtonActive,  accentVec4(ac, 0.55, 0.90))
        end
        local txt_col = is_active and imgui.ImVec4(1,1,1,1) or imgui.ImVec4(0.75,0.75,0.75,1)
        imgui.PushStyleColor(imgui.Col.Text, txt_col)
        local ico = getIcon(td.icon_key)
        if hi_fa_font_small then imgui.PushFont(hi_fa_font_small) end
        if imgui.Button(ico .. " " .. Fn.T(u8(td.label)) .. "##tab_" .. td.id, imgui.ImVec2(-1, 28)) then
            active_tab[0] = td.idx
        end
        if is_active then
            local hdl = imgui.GetWindowDrawList()
            drawAnimatedTabGlow(hdl, imgui.GetItemRectMin(), imgui.GetItemRectMax(), os.clock())
        end
        imgui.PopStyleColor(1)
        if hi_fa_font_small then imgui.PopFont() end
        imgui.PopStyleColor(3)
        imgui.Spacing()
    end
    imgui.EndChild()
    imgui.SameLine(0, 8)
    imgui.BeginChild(u8"##content", imgui.ImVec2(0, 0), true)
    if     active_tab[0] == 0 then renderEventTab("death", ui.death)
    elseif active_tab[0] == 1 then renderEventTab("kill",  ui.kill)
    elseif active_tab[0] == 2 then renderEventTab("armor", ui.armor)
    elseif active_tab[0] == 3 then renderSelfTab()
    elseif active_tab[0] == 4 then
        imgui.Spacing()
        if imgui.Checkbox(Fn.T(u8("Включить скрипт##master")), script_enabled) then saveSettings() end
        imgui.Spacing()
        if imgui.Checkbox(Fn.T(u8("Автовключение при входе в игру##auto")), auto_enable_on_join) then saveSettings() end
        imgui.Spacing()
    end
    imgui.EndChild()
    imgui.End()
    imgui.PopStyleColor(9)
    imgui.PopStyleVar(7)
end
local function runHeadIconsLoop()
    while not isSampAvailable() do wait(100) end
    CBUGER_WAIT_RUNTIME_READY()
    pcall(function() my_samp_id = select(2, sampGetPlayerIdByCharHandle(PLAYER_PED)) end)
    local was_in_game = false
    local scan_accum = 0.0
    while true do
        wait(50)
        local now = os.clock()
        local in_game = doesCharExist(PLAYER_PED)
        if in_game and not was_in_game then
            if auto_enable_on_join[0] then script_enabled[0] = true end
            was_i_alive = true
        elseif not in_game then
            was_i_alive = true
        end
        was_in_game = in_game
        local ok_id, sid = pcall(function() return select(2, sampGetPlayerIdByCharHandle(PLAYER_PED)) end)
        if ok_id and sid ~= nil then my_samp_id = sid end
        if in_game then
            local ok_self_dead, self_dead = pcall(isCharDead, PLAYER_PED)
            if ok_self_dead then
                local self_alive = not self_dead
                if not self_alive and was_i_alive then
                    queueDeathEvent(my_samp_id, nil, PLAYER_PED, true)
                    was_i_alive = false
                elseif self_alive then
                    was_i_alive = true
                end
            end
            local ok_self_pos, x, y, z = pcall(getCharCoordinates, PLAYER_PED)
            if ok_self_pos and x ~= nil and y ~= nil and z ~= nil then
                cacheKnownPos(my_samp_id, x, y, z, now)
            end
        end
        for pid, t in pairs(hit_time) do
            if (now - t) > KILL_CREDIT * 2 then hit_time[pid] = nil end
        end
        for pid, p in pairs(last_known_pos) do
            if not p or not p.t or (now - p.t) > 20.0 then last_known_pos[pid] = nil end
        end
        scan_accum = scan_accum + 0.05
        if scan_accum >= 0.10 then
            scan_accum = 0.0
            for i = 0, 1000 do
                local ok_con, connected = pcall(sampIsPlayerConnected, i)
                if ok_con and connected and i ~= my_samp_id then
                    local ok, ped = pcall(sampGetCharHandleBySampPlayerId, i)
                    if ok and ped and ped ~= 0 then
                        local ok_ex, exists = pcall(doesCharExist, ped)
                        if ok_ex and exists then
                            local ok_pos, x, y, z = pcall(getCharCoordinates, ped)
                            if ok_pos and x ~= nil and y ~= nil and z ~= nil then cacheKnownPos(i, x, y, z, now) end
                            local ok_d, dead = pcall(isCharDead, ped)
                            if ok_d then
                                local alive = not dead
                                if not alive and was_alive[i] ~= false then
                                    queueDeathEvent(i, nil, ped, false)
                                    was_alive[i] = false
                                elseif alive then
                                    was_alive[i] = true
                                end
                            end
                        elseif pending_deaths[i] == nil then
                            if was_alive[i] ~= true then
                                was_alive[i] = nil
                            end
                        end
                    elseif pending_deaths[i] == nil then
                        if was_alive[i] ~= true then
                            was_alive[i] = nil
                        end
                    end
                else
                    was_alive[i] = nil
                    hit_time[i] = nil
                end
            end
        end
        processDeathQueue(now)
    end
end
lua_thread.create(runHeadIconsLoop)
end
do
local function CBU_U32(c) return CBUGER_ApplyOverlayAlphaU32(imgui.ColorConvertFloat4ToU32(c)) end
local function cbug_join_argb(a, r, g, b)
    local v = b
    v = bit.bor(v, bit.lshift(g, 8))
    v = bit.bor(v, bit.lshift(r, 16))
    return bit.bor(v, bit.lshift(a, 24))
end
local function SliderFloatOD(label, id, var, lo, hi, fmt)
    label = Fn.T(label)
    fmt = fmt or "%.2f"
    local ok = pcall(function() imgui.SliderFloat("##"..id, var, lo, hi, " ") end)
    if not ok then imgui.SliderFloat("##"..id, var, lo, hi) end
    local mi, ma = imgui.GetItemRectMin(), imgui.GetItemRectMax()
    local displayTxt = imgui.IsItemActive() and string.format(fmt, var[0]) or label
    local dl2 = imgui.GetWindowDrawList()
    if dl2 then
        local tw = imgui.CalcTextSize(displayTxt).x
        local th = imgui.CalcTextSize(displayTxt).y
        dl2:AddText(imgui.ImVec2(mi.x + (ma.x-mi.x-tw)/2, mi.y + (ma.y-mi.y-th)/2), CBUGER_ApplyGlobalAlphaU32(0xFFFFFFFF), displayTxt)
    end
end
local function drawCbugHud()
    local hud_font = CBUGER_GET_GLOBAL_FONT() or imgui.GetFont()
    if not hud_font then return end
    if cbug_session.active and
       (os.clock() - cbug_session.last_shot_time) > cbug_cfg.settings.fail_timeout then
        cbug_session.active = false
        cbug_session.shots  = 0
    end
    local r = cbug_hud_color[0]; local g = cbug_hud_color[1]
    local b = cbug_hud_color[2]; local a = cbug_hud_color[3]
    local colH    = CBU_U32(imgui.ImVec4(r, g, b, a))
    local colBg   = CBU_U32(imgui.ImVec4(0.08, 0.08, 0.08, 0.85))
    local colDim  = CBU_U32(imgui.ImVec4(r*0.5, g*0.5, b*0.5, a*0.7))
    local dl2     = imgui.GetBackgroundDrawList()
    local scale   = cbug_cfg.settings.indicator_scale or 1.0
    local draw_size = cbug_cfg.settings.font_size * scale
    local hud_mode  = cbug_cfg.settings.hud_mode or 1
    local hx = cbug_cfg.settings.hud_x; local hy = cbug_cfg.settings.hud_y
    local total_ms = cbug_session.active and math.floor((os.clock()-cbug_session.start_time)*1000) or 0
    local progress = math.min(cbug_session.shots / math.max(cbug_cfg.settings.required_shots,1), 1)
    if hud_mode == 3 then
        local barW = 80*scale; local barH = 8*scale; local bx = hx-barW/2
        dl2:AddRectFilled(imgui.ImVec2(bx,hy), imgui.ImVec2(bx+barW,hy+barH), colBg, 3)
        if progress > 0 then
            dl2:AddRectFilled(imgui.ImVec2(bx,hy), imgui.ImVec2(bx+barW*progress,hy+barH), colH, 3)
        end
    elseif hud_mode == 2 then
        local shots_str = string.format("%d / %d", cbug_session.shots, cbug_cfg.settings.required_shots)
        local ms_str    = cbug_session.active and string.format("%.0f ms", total_ms) or "--"
        local streak_str = cbug_run.streak > 0 and ("x"..cbug_run.streak) or ""
        local sz   = hud_font:CalcTextSizeA(draw_size, 1000, 0, shots_str)
        local px   = hx - sz.x/2
        local barW = math.max(sz.x, 80*scale); local barH = 5*scale
        local barX = hx-barW/2; local barY = hy-barH-2
        dl2:AddRectFilled(imgui.ImVec2(barX,barY), imgui.ImVec2(barX+barW,barY+barH), colBg, 3)
        if progress > 0 then
            dl2:AddRectFilled(imgui.ImVec2(barX,barY), imgui.ImVec2(barX+barW*progress,barY+barH), colH, 3)
        end
        dl2:AddTextFontPtr(hud_font, draw_size, imgui.ImVec2(px+1,hy+1), CBUGER_ApplyOverlayAlphaU32(0xFF000000), shots_str)
        dl2:AddTextFontPtr(hud_font, draw_size, imgui.ImVec2(px,hy),   colH, shots_str)
        local sz2 = hud_font:CalcTextSizeA(draw_size*0.55, 1000, 0, ms_str)
        dl2:AddTextFontPtr(hud_font, draw_size*0.55, imgui.ImVec2(hx-sz2.x/2,hy+sz.y+2), colDim, ms_str)
        if cbug_cfg.settings.show_streak and streak_str ~= "" then
            local sz3 = hud_font:CalcTextSizeA(draw_size*0.45, 1000, 0, streak_str)
            dl2:AddTextFontPtr(hud_font, draw_size*0.45,
                imgui.ImVec2(hx-sz3.x/2, barY-sz3.y-2),
                CBU_U32(imgui.ImVec4(1,0.85,0.1,1)), streak_str)
        end
    elseif hud_mode == 4 then
        local info = string.format("%d / %d  |  %.0f ms", cbug_session.shots, cbug_cfg.settings.required_shots, total_ms)
        local sz   = hud_font:CalcTextSizeA(draw_size, 1000.0, 0.0, info)
        local px   = hx - sz.x/2
        dl2:AddTextFontPtr(hud_font, draw_size, imgui.ImVec2(px+1,hy+1), CBUGER_ApplyOverlayAlphaU32(0xFF000000), info)
        dl2:AddTextFontPtr(hud_font, draw_size, imgui.ImVec2(px,hy),   colH, info)
        if cbug_cfg.settings.show_streak and cbug_run.streak > 0 then
            local streakStr = "x"..cbug_run.streak
            local sz2 = hud_font:CalcTextSizeA(draw_size*0.4, 1000.0, 0.0, streakStr)
            dl2:AddTextFontPtr(hud_font, draw_size*0.4,
                imgui.ImVec2(hx-sz2.x/2, hy+sz.y+2),
                CBU_U32(imgui.ImVec4(1,0.85,0.1,1)), streakStr)
        end
    else
        local info = string.format("%d / %d  |  %.0f ms", cbug_session.shots, cbug_cfg.settings.required_shots, total_ms)
        local sz   = hud_font:CalcTextSizeA(draw_size, 1000.0, 0.0, info)
        local px   = hx - sz.x/2
        local barW = sz.x; local barH = 6; local barX = px; local barY = hy-barH-4
        dl2:AddRectFilled(imgui.ImVec2(barX,barY), imgui.ImVec2(barX+barW,barY+barH), colBg, 3)
        if progress > 0 then
            dl2:AddRectFilled(imgui.ImVec2(barX,barY), imgui.ImVec2(barX+barW*progress,barY+barH), colH, 3)
        end
        dl2:AddTextFontPtr(hud_font, draw_size, imgui.ImVec2(px+1,hy+1), CBUGER_ApplyOverlayAlphaU32(0xFF000000), info)
        dl2:AddTextFontPtr(hud_font, draw_size, imgui.ImVec2(px,hy),   colH, info)
        if cbug_cfg.settings.show_streak and cbug_run.streak > 0 then
            local streakStr = "x"..cbug_run.streak
            local sz2 = hud_font:CalcTextSizeA(draw_size*0.4, 1000.0, 0.0, streakStr)
            dl2:AddTextFontPtr(hud_font, draw_size*0.4,
                imgui.ImVec2(hx-sz2.x/2, barY-sz2.y-2),
                CBU_U32(imgui.ImVec4(1,0.85,0.1,1)), streakStr)
        end
    end
end
local function crdHud()
    while true do
        wait(0)
        sampSetCursorMode(3)
        cbug_cfg.settings.hud_x, cbug_cfg.settings.hud_y = getCursorPos()
        if isKeyJustPressed(1) then
            sampSetCursorMode(0)
            mainWindow[0] = true
            inicfg.save(cbug_cfg, cbug_cfg_name)
            break
        end
    end
end
local cbug_ui_hud = imgui.OnFrame(
