            + imgui.ColorEditFlags.NoSmallPreview
            + imgui.ColorEditFlags.AlphaBar
            + imgui.ColorEditFlags.AlphaPreview
        if imgui.ColorPicker4("##cbug_picker", cbug_hud_color, flags) then
            cbug_cfg.settings.text_color_r = cbug_hud_color[0]
            cbug_cfg.settings.text_color_g = cbug_hud_color[1]
            cbug_cfg.settings.text_color_b = cbug_hud_color[2]
            cbug_cfg.settings.text_color_a = cbug_hud_color[3]
            inicfg.save(cbug_cfg, cbug_cfg_name)
        end
        imgui.EndPopup()
    end
    imgui.Separator()
    imgui.PushItemWidth(160)
    local req = new.int(cbug_cfg.settings.required_shots)
    if imgui.InputInt(Fn.T(u8"Нужно выстрелов##cb"), req) then
        if req[0] >= 1 then
            cbug_cfg.settings.required_shots = req[0]
            inicfg.save(cbug_cfg, cbug_cfg_name)
        end
    end
    imgui.PopItemWidth()
    if imgui.Button(Fn.T(u8"Позиция HUD##cb"), imgui.ImVec2(-1, 22)) then
        mainWindow[0] = false
        lua_thread.create(crdHud)
    end
    imgui.PushItemWidth(imgui.GetContentRegionAvail().x * 0.55)
    do
        local sc = new.float(cbug_cfg.settings.indicator_scale)
        SliderFloatOD(u8"Масштаб HUD", "scale_cb", sc, 0.3, 4.0)
        if sc[0] ~= cbug_cfg.settings.indicator_scale then
            cbug_cfg.settings.indicator_scale = sc[0]
            inicfg.save(cbug_cfg, cbug_cfg_name)
        end
    end
    do
        local ft = new.float(cbug_cfg.settings.fail_timeout)
        SliderFloatOD(u8"Таймаут сброса (сек)", "ft_cb", ft, 0.1, 3.0, "%.1f")
        if ft[0] ~= cbug_cfg.settings.fail_timeout then
            cbug_cfg.settings.fail_timeout = ft[0]
            inicfg.save(cbug_cfg, cbug_cfg_name)
        end
    end
    imgui.PopItemWidth()
    imgui.Spacing()
    imgui.Text(Fn.T(u8"Стиль HUD:"))
    local modeSeq = {
        {3, u8"Мин"}, {1, u8"Базовый"},
        {4, u8"Стандарт"}, {2, u8"Расшир"},
    }
    local bc  = active_colors[imgui.Col.Button]        or {0.3, 0.3, 0.3, 0.8}
    local bch = active_colors[imgui.Col.ButtonHovered] or {0.55,0.55,0.55,0.9}
    local bca = active_colors[imgui.Col.ButtonActive]  or {0.8, 0.8, 0.8, 1.0}
    local avail = imgui.GetContentRegionAvail().x
    local gap   = 4
    local bW    = (avail - gap * 3) / 4
    for idx, pair in ipairs(modeSeq) do
        local mi2, lbl = pair[1], Fn.T(pair[2])
        local act = (cbug_cfg.settings.hud_mode == mi2)
        local btnCol = act
            and imgui.ImVec4(bc[1],  bc[2],  bc[3],  1.0)
            or  imgui.ImVec4(bc[1]*0.4, bc[2]*0.4, bc[3]*0.4, 0.7)
        local hvrCol = imgui.ImVec4(bch[1], bch[2], bch[3], 1.0)
        local actCol = imgui.ImVec4(bca[1], bca[2], bca[3], 1.0)
        local txtCol = act
            and imgui.ImVec4(1.0, 1.0, 1.0, 1.0)
            or  imgui.ImVec4(0.6, 0.6, 0.6, 1.0)
        imgui.PushStyleColor(imgui.Col.Button,        btnCol)
        imgui.PushStyleColor(imgui.Col.ButtonHovered, hvrCol)
        imgui.PushStyleColor(imgui.Col.ButtonActive,  actCol)
        imgui.PushStyleColor(imgui.Col.Text,          txtCol)
        if imgui.Button(lbl, imgui.ImVec2(bW, 26)) then
            cbug_cfg.settings.hud_mode = mi2
            inicfg.save(cbug_cfg, cbug_cfg_name)
        end
        imgui.PopStyleColor(4)
        if idx < #modeSeq then imgui.SameLine(0, gap) end
    end
    imgui.Spacing()
    do
        local b2 = new.bool(cbug_cfg.settings.show_streak)
        if imgui.Checkbox(Fn.T(u8"Стрик на HUD##cb"), b2) then
            cbug_cfg.settings.show_streak = b2[0]
            inicfg.save(cbug_cfg, cbug_cfg_name)
        end
    end
    imgui.SameLine()
    do
        local b2 = new.bool(cbug_cfg.settings.notify_record)
        if imgui.Checkbox(Fn.T(u8"Уведомление о рекорде##cb"), b2) then
            cbug_cfg.settings.notify_record = b2[0]
            inicfg.save(cbug_cfg, cbug_cfg_name)
        end
    end
    imgui.Separator()
    imgui.Text(Fn.T(u8"Рекорды CBug:"))
    imgui.BeginChild("cb_records", imgui.ImVec2(-1, 56), true)
    local hasRec = false
    for k, v in pairs(cbug_cfg.records) do
        hasRec = true
        imgui.TextColored(imgui.ImVec4(0.2,0.9,0.2,1),
            string.format(Fn.T(u8"Выстрелов: %s | Время: %d ms"), k, v))
    end
    if not hasRec then imgui.TextDisabled(Fn.T(u8"Рекордов нет")) end
    imgui.EndChild()
    if imgui.Button(Fn.T(u8"Очистить рекорды##cb"), imgui.ImVec2(-1, 22)) then
        cbug_cfg.records = {}; inicfg.save(cbug_cfg, cbug_cfg_name)
    end
    imgui.End()
    imgui.PopStyleVar()
end
function CBUGSPEED_onSendBulletSync(data)
    if cbug_cfg.settings.active and not cbug_session.blocked then
        if data and data.weaponId == 24 then
            if cbug_run.session_start == 0 then cbug_run.session_start = os.clock() end
            cbug_run.session_shots = cbug_run.session_shots + 1
            if cbug_session.shots == 0 then
                cbug_session.start_time = os.clock(); cbug_session.active = true
            end
            cbug_session.shots = cbug_session.shots + 1
            cbug_session.last_shot_time = os.clock()
            if cbug_session.shots >= cbug_cfg.settings.required_shots then
                local final_ms = math.floor((os.clock()-cbug_session.start_time)*1000)
                local key      = tostring(cbug_cfg.settings.required_shots)
                local old_rec  = cbug_cfg.records[key]
                if not old_rec or final_ms < tonumber(old_rec) then
                    cbug_cfg.records[key] = final_ms
                    inicfg.save(cbug_cfg, cbug_cfg_name)
                    if cbug_cfg.settings.notify_record then
                        local diff = old_rec
                            and (" (лучше на " .. (old_rec-final_ms) .. " ms)")
                            or  " (первый рекорд!)"
                        sampAddChatMessage("{32CD32}[CBug Speed]{FFFFFF} Рекорд для "..key..
                            " выстрелов: {32CD32}"..final_ms.." ms{FFFFFF}"..diff, -1)
                    end
                end
                cbug_run.session_combos = cbug_run.session_combos + 1
                cbug_run.streak = cbug_run.streak + 1
                if cbug_run.streak > (cbug_cfg.stats.best_streak or 0) then
                    cbug_cfg.stats.best_streak = cbug_run.streak
                end
                cbug_session.active = false; cbug_session.shots = 0; cbug_session.blocked = true
                lua_thread.create(function()
                    wait(cbug_cfg.settings.reset_delay); cbug_session.blocked = false
                end)
            end
        end
    end
end
function CBUGSPEED_onSendGiveDamage(targetId, damage, weapon, bodypart)
    if weapon == 24 and cbug_cfg.settings.active then
        cbug_run.session_hits = cbug_run.session_hits + 1
    end
end
local function saveCbugRunStats(cfg, cfg_name, run, playtime_start)
    cfg.stats = cfg.stats or {}
    local st = cfg.stats
    local session_shots = tonumber(run.session_shots) or 0
    local session_hits = tonumber(run.session_hits) or 0
    st.total_shots = (tonumber(st.total_shots) or 0) + session_shots
    st.total_hits = (tonumber(st.total_hits) or 0) + session_hits
    st.total_misses = (tonumber(st.total_misses) or 0)
        + math.max(0, session_shots - session_hits)
    st.total_combos = (tonumber(st.total_combos) or 0) + (tonumber(run.session_combos) or 0)
    st.total_playtime = (tonumber(st.total_playtime) or 0)
        + (playtime_start > 0 and math.max(0, os.clock() - playtime_start) or 0)
    run.session_shots, run.session_hits, run.session_combos = 0, 0, 0

    local ok, result = pcall(inicfg.save, cfg, cfg_name)
    run._stats_dirty = not (ok and result == true)
    return not run._stats_dirty
end

function cbugerSaveCbugHzStats()
    local all_saved = true

    if not saveCbugRunStats(cbug_cfg, cbug_cfg_name, cbug_run, cbug_playtime_start or 0) then
        all_saved = false
    end
    cbug_playtime_start = os.clock()

    if ksChatNotify then hz_cfg.main.ks_chat_notify = ksChatNotify[0] end
    local hz_cfg_ok, hz_cfg_result = pcall(inicfg.save, hz_cfg, HZ_CFG_FILE)
    if not hz_cfg_ok or hz_cfg_result ~= true then all_saved = false end

    if not saveCbugRunStats(hz_cbug_cfg, hz_cbug_cfg_name, hz_cbug_run, hz_cbug_playtime_start or 0) then
        all_saved = false
    end
    hz_cbug_playtime_start = os.clock()

    local total_shots = tonumber(hz_cbug_cfg.stats.total_shots) or 0
    local total_hits = tonumber(hz_cbug_cfg.stats.total_hits) or 0
    local kpd = total_shots > 0 and math.floor(total_hits / total_shots * 100) or 0
    if kpd > (tonumber(hz_cbug_cfg.stats.best_kpd) or 0) then
        hz_cbug_cfg.stats.best_kpd = kpd
        local ok, result = pcall(inicfg.save, hz_cbug_cfg, hz_cbug_cfg_name)
        if not ok or result ~= true then all_saved = false end
    end

    if not saveStreaks(killStreaks) then all_saved = false end
    return all_saved
end
end
