utf8_to_cp1251_map = {}
do
    for i = 0, 31 do utf8_to_cp1251_map[0x0410 + i] = 0xC0 + i end
    for i = 0, 31 do utf8_to_cp1251_map[0x0430 + i] = 0xE0 + i end
    utf8_to_cp1251_map[0x0401] = 0xA8
    utf8_to_cp1251_map[0x0451] = 0xB8
end
function utf8ToCP1251(str)
    if not str or str == "" then return str end
    local result = {}
    local i = 1
    while i <= #str do
        local b = string.byte(str, i)
        if b < 0x80 then
            result[#result+1] = string.char(b)
            i = i + 1
        elseif b >= 0xC2 and b <= 0xDF then
            local b2 = string.byte(str, i+1) or 0
            local cp = (b - 0xC0) * 64 + (b2 - 0x80)
            local mapped = utf8_to_cp1251_map[cp]
            result[#result+1] = mapped and string.char(mapped) or "?"
            i = i + 2
        elseif b >= 0xE0 then
            local b2 = string.byte(str, i+1) or 0
            local b3 = string.byte(str, i+2) or 0
            local cp = (b - 0xE0) * 4096 + (b2 - 0x80) * 64 + (b3 - 0x80)
            local mapped = utf8_to_cp1251_map[cp]
            result[#result+1] = mapped and string.char(mapped) or "?"
            i = i + 3
        else
            i = i + 1
        end
    end
    return table.concat(result)
end
