function explode_argb(c)
    local a = bit.band(bit.rshift(c, 24), 255)
    local r = bit.band(bit.rshift(c, 16), 255)
    local g = bit.band(bit.rshift(c, 8),  255)
    local b = bit.band(c, 255)
    return a, r, g, b
end
function argb2imvec4(a, r, g, b)
    return r/255, g/255, b/255, a/255
end
function join_argb(a, r, g, b)
    local v = b
    v = bit.bor(v, bit.lshift(g, 8))
    v = bit.bor(v, bit.lshift(r, 16))
    return bit.bor(v, bit.lshift(a, 24))
end
function argb2abgr(c)
    local a, r, g, b = explode_argb(c)
    return join_argb(a, b, g, r)
end
function LimitInputInt(lo, hi, v)
    if v < lo then v = lo end
    if v > hi then v = hi end
    return v
end
local function SliderFloatOD(label, id, var, lo, hi, fmt)
    label = Fn.T(label)
    fmt = fmt or "%.2f"
    local ok = pcall(function() imgui.SliderFloat("##"..id, var, lo, hi, " ") end)
    if not ok then imgui.SliderFloat("##"..id, var, lo, hi) end
    local mi, ma = imgui.GetItemRectMin(), imgui.GetItemRectMax()
    local displayTxt = (imgui.IsItemActive() and imgui.IsItemActive()) and string.format(fmt, var[0]) or label
    local dl = imgui.GetWindowDrawList()
    if dl then
        local tw = imgui.CalcTextSize(displayTxt).x
        local th = imgui.CalcTextSize(displayTxt).y
        local dx = mi.x + (ma.x - mi.x - tw) / 2
        local dy = mi.y + (ma.y - mi.y - th) / 2
        dl:AddText(imgui.ImVec2(dx, dy), CBUGER_ApplyGlobalAlphaU32(0xFFFFFFFF), displayTxt)
    end
end
local function hz_SliderIntOD(label, id, var, lo, hi)
    label = Fn.T(label)
    local ok = pcall(function() imgui.SliderInt("##"..id, var, lo, hi, " ") end)
    if not ok then imgui.SliderInt("##"..id, var, lo, hi) end
    local mi, ma = imgui.GetItemRectMin(), imgui.GetItemRectMax()
    local displayTxt = imgui.IsItemActive() and tostring(var[0]) or label
    local dl = imgui.GetWindowDrawList()
    if dl then
        local tw = imgui.CalcTextSize(displayTxt).x
        local th = imgui.CalcTextSize(displayTxt).y
        local dx = mi.x + (ma.x - mi.x - tw) / 2
        local dy = mi.y + (ma.y - mi.y - th) / 2
        dl:AddText(imgui.ImVec2(dx, dy), CBUGER_ApplyGlobalAlphaU32(0xFFFFFFFF), displayTxt)
    end
end
local function SliderFloatLabel(label, display, var, lo, hi, fmt)
    fmt = fmt or "%.2f"
    display = Fn.T(display)
    imgui.TextDisabled(display)
    local changed = imgui.SliderFloat("##sl_"..label, var, lo, hi, "")
    if imgui.IsItemHovered() or imgui.IsItemActive() then
        imgui.BeginTooltip()
        imgui.Text(string.format(fmt, var.v))
        imgui.EndTooltip()
    end
    return changed
end
local function SliderIntLabel(label, display, var, lo, hi)
    display = Fn.T(display)
    imgui.TextDisabled(display)
    local changed = imgui.SliderInt("##sli_"..label, var, lo, hi, "")
    if imgui.IsItemHovered() or imgui.IsItemActive() then
        imgui.BeginTooltip()
        imgui.Text(tostring(var.v))
        imgui.EndTooltip()
    end
    return changed
end
