function getStreakForKills(k)
    table.sort(killStreaks, function(a, b) return a.kills > b.kills end)
    for _, s in ipairs(killStreaks) do
        if k >= s.kills then return s end
    end
    return nil
end
function checkStreakAnnounce()
    local s = getStreakForKills(killsLife)
    if s and s.kills ~= ksLastTriggered then
        ksLastTriggered = s.kills
        local nameUtf = s.name or ""
        if ksChatNotify[0] then
            local hexcol = bit.tohex(bit.band(s.color, 0xFFFFFFFF))
            sampAddChatMessage(
                "{1E90FF}[HitZones]{" .. string.sub(hexcol, 3) ..
                "} Kill Streak: " .. utf8ToCP1251(nameUtf) .. " (" .. killsLife .. " kills)", -1)
        end
        if pluskillType[0] == 1 then
            local a2,r2,g2,b2 = explode_argb(s.color)
            pkillStreakText   = nameUtf
            pkillStreakColorR  = r2/255
            pkillStreakColorG  = g2/255
            pkillStreakColorB  = b2/255
            pkillStreakColorA  = a2/255
            pkillActive = true
            pkillReset  = true
        elseif pluskillType[0] == 0 then
            lua_thread.create(function()
                wait(0)
                printStyledString("~"..hz_cfg.main.pluskillcolortypefvar.."~~h~"..utf8ToCP1251(nameUtf),
                    hz_cfg.main.pkilltud * 1000, 7)
            end)
        end
        return true
    end
    return false
end
function hz_drawCbugHud()
    local hud_font = CBUGER_GET_GLOBAL_FONT() or imgui.GetFont()
    if not hud_font then return end
    if hz_cbug_session.active and
       (os.clock() - hz_cbug_session.last_shot_time) > hz_cbug_cfg.settings.fail_timeout then
        hz_cbug_session.active = false
        hz_cbug_session.shots  = 0
    end
    local r = hz_cbug_hud_color[0]
    local g = hz_cbug_hud_color[1]
    local b = hz_cbug_hud_color[2]
    local a = hz_cbug_hud_color[3]
    local col    = HZ_OVERLAY_U32(imgui.ImVec4(r, g, b, a))
    local colBg  = HZ_OVERLAY_U32(accentVec4(nil, 0.08, 0.72))
    local colDim = HZ_OVERLAY_U32(imgui.ImVec4(r*0.5, g*0.5, b*0.5, a*0.7))
    local dl     = imgui.GetBackgroundDrawList()
    local scale  = hz_cbug_cfg.settings.indicator_scale or 1.0
    local draw_size = hz_cbug_cfg.settings.font_size * scale
    local hud_mode  = hz_cbug_cfg.settings.hud_mode or 1
    local hx = hz_cbug_cfg.settings.hud_x
    local hy = hz_cbug_cfg.settings.hud_y
    local total_ms = hz_cbug_session.active
        and math.floor((os.clock() - hz_cbug_session.start_time) * 1000) or 0
    local progress = math.min(hz_cbug_session.shots / math.max(hz_cbug_cfg.settings.required_shots, 1), 1)
    if hud_mode == 3 then
        local barW = 80 * scale
        local barH = 8  * scale
        local bx   = hx - barW/2
        local by   = hy
        dl:AddRectFilled(imgui.ImVec2(bx, by), imgui.ImVec2(bx+barW, by+barH), colBg, 3)
        if progress > 0 then
            dl:AddRectFilled(imgui.ImVec2(bx, by), imgui.ImVec2(bx+barW*progress, by+barH), col, 3)
        end
    elseif hud_mode == 2 then
        local shots_str = string.format("%d / %d", hz_cbug_session.shots, hz_cbug_cfg.settings.required_shots)
        local ms_str    = hz_cbug_session.active and string.format("%.0f ms", total_ms) or "--"
        local streak_str= hz_cbug_run.streak > 0 and ("x"..hz_cbug_run.streak) or ""
        local sz    = hud_font:CalcTextSizeA(draw_size, 1000, 0, shots_str)
        local px    = hx - sz.x/2
        local barW  = math.max(sz.x, 80*scale)
        local barH  = 5 * scale
        local barX  = hx - barW/2
        local barY  = hy - barH - 2
        dl:AddRectFilled(imgui.ImVec2(barX, barY), imgui.ImVec2(barX+barW, barY+barH), colBg, 3)
        if progress > 0 then
            dl:AddRectFilled(imgui.ImVec2(barX, barY), imgui.ImVec2(barX+barW*progress, barY+barH), col, 3)
        end
        dl:AddTextFontPtr(hud_font, draw_size, imgui.ImVec2(px+1, hy+1), CBUGER_ApplyOverlayAlphaU32(0xFF000000), shots_str)
        dl:AddTextFontPtr(hud_font, draw_size, imgui.ImVec2(px,   hy),   col,         shots_str)
        local sz2 = hud_font:CalcTextSizeA(draw_size*0.55, 1000, 0, ms_str)
        local tx2 = hx - sz2.x/2
        local ty2 = hy + sz.y + 2
        dl:AddTextFontPtr(hud_font, draw_size*0.55, imgui.ImVec2(tx2, ty2), colDim, ms_str)
        if hz_cbug_cfg.settings.show_streak and streak_str ~= "" then
            local sz3 = hud_font:CalcTextSizeA(draw_size*0.45, 1000, 0, streak_str)
            dl:AddTextFontPtr(hud_font, draw_size*0.45,
                imgui.ImVec2(hx - sz3.x/2, barY - sz3.y - 2),
                HZ_OVERLAY_U32(imgui.ImVec4(1,0.85,0.1,1)), streak_str)
        end
    else
        if hud_mode == 1 then
            local info = string.format("%d / %d  |  %.0f ms",
                hz_cbug_session.shots, hz_cbug_cfg.settings.required_shots, total_ms)
            local sz   = hud_font:CalcTextSizeA(draw_size, 1000.0, 0.0, info)
            local px   = hx - sz.x / 2
            local barW = sz.x
            local barH = 6
            local barX = px
            local barY = hy - barH - 4
            dl:AddRectFilled(imgui.ImVec2(barX, barY), imgui.ImVec2(barX+barW, barY+barH), colBg, 3)
            if progress > 0 then
                dl:AddRectFilled(imgui.ImVec2(barX, barY), imgui.ImVec2(barX+barW*progress, barY+barH), col, 3)
            end
            dl:AddTextFontPtr(hud_font, draw_size, imgui.ImVec2(px+1, hy+1), CBUGER_ApplyOverlayAlphaU32(0xFF000000), info)
            dl:AddTextFontPtr(hud_font, draw_size, imgui.ImVec2(px,   hy),   col,         info)
            if hz_cbug_cfg.settings.show_streak and hz_cbug_run.streak > 0 then
                local streakStr = "x"..hz_cbug_run.streak
                local sz2 = hud_font:CalcTextSizeA(draw_size * 0.4, 1000.0, 0.0, streakStr)
                dl:AddTextFontPtr(hud_font, draw_size * 0.4,
                    imgui.ImVec2(hx - sz2.x/2, barY - sz2.y - 2),
                    HZ_OVERLAY_U32(imgui.ImVec4(1,0.85,0.1,1)), streakStr)
            end
        else
            local info = string.format("%d / %d  |  %.0f ms",
                hz_cbug_session.shots, hz_cbug_cfg.settings.required_shots, total_ms)
            local sz   = hud_font:CalcTextSizeA(draw_size, 1000.0, 0.0, info)
            local px   = hx - sz.x / 2
            dl:AddTextFontPtr(hud_font, draw_size, imgui.ImVec2(px+1, hy+1), CBUGER_ApplyOverlayAlphaU32(0xFF000000), info)
            dl:AddTextFontPtr(hud_font, draw_size, imgui.ImVec2(px,   hy),   col,         info)
            if hz_cbug_cfg.settings.show_streak and hz_cbug_run.streak > 0 then
                local streakStr = "x"..hz_cbug_run.streak
                local sz2 = hud_font:CalcTextSizeA(draw_size * 0.4, 1000.0, 0.0, streakStr)
                dl:AddTextFontPtr(hud_font, draw_size * 0.4,
                    imgui.ImVec2(hx - sz2.x/2, hy + sz.y + 2),
                    HZ_OVERLAY_U32(imgui.ImVec4(1,0.85,0.1,1)), streakStr)
            end
        end
    end
end
