function hz_crdHud()
    while true do
        wait(0)
        sampSetCursorMode(3)
        hz_cbug_cfg.settings.hud_x, hz_cbug_cfg.settings.hud_y = getCursorPos()
        if isKeyJustPressed(1) then
            sampSetCursorMode(0)
            hz_mainWindow[0] = true
            inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
            break
        end
    end
end
local _mainWinWarmedUp = false
function renderHzWindow()
    local fade_speed = CBUGER_GET_ANIM_RATE(15)
    local main_alpha = CBUGER_UPDATE_MODULE_FADE('hitzones_main', hz_mainWindow[0], fade_speed)
    local stats_alpha = CBUGER_UPDATE_MODULE_FADE('hitzones_stats', statsWindowOpen[0], fade_speed)
    local compare_alpha = CBUGER_UPDATE_MODULE_FADE('hitzones_compare', compareOpen[0], fade_speed)
    if math.max(main_alpha, stats_alpha, compare_alpha) <= 0.01 then return end
    if icons_tex_path and not icons_tex_ready then
        icons_tex = imgui.CreateTextureFromFile(icons_tex_path)
        icons_tex_ready = true
        icons_tex_path = nil
    end
    if main_alpha > 0.01 then
        imgui.SetNextWindowPos(
            imgui.ImVec2(imgui.GetIO().DisplaySize.x/2, imgui.GetIO().DisplaySize.y/2),
            imgui.Cond.FirstUseEver, imgui.ImVec2(0.5, 0.5))
        local hz_rst = CBUGER_APPLY_WINDOW_SIZE("hitzones_main", 420, 520)
        imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, CBUGER_GET_INTERFACE_ALPHA() * main_alpha)
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(12, 8))
        imgui.PushStyleVarVec2(imgui.StyleVar.FramePadding,  imgui.ImVec2(12, 4))
        local hz_open_ptr = hz_mainWindow[0] and hz_mainWindow or nil
        imgui.Begin(u8"HitZones", hz_open_ptr, imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoResize)
        CBUGER_DRAW_INVISIBLE_RESIZER("hitzones_main", hz_rst, 340, 360, CBUGER_GET_INTERFACE_ALPHA(), true)
        imgui.PopStyleVar(2)
        do
            local zdl = imgui.GetWindowDrawList()
            local zp  = imgui.GetWindowPos()
            local zs  = imgui.GetWindowSize()
            CBUGER_DRAW_GLOBAL_AMBIENT(zdl, zp, imgui.ImVec2(zp.x + zs.x, zp.y + zs.y), CBUGER_GET_INTERFACE_ALPHA())
        end
        if imgui.BeginTabBar("##main_tabs") then
            if imgui.BeginTabItem(u8"KillZone") then
                drawAnimatedTabGlow(imgui.GetWindowDrawList(), imgui.GetItemRectMin(), imgui.GetItemRectMax(), os.clock())
                drawKillStateTab()
                imgui.EndTabItem()
            end
            if imgui.BeginTabItem(u8"My Stats") then
                drawAnimatedTabGlow(imgui.GetWindowDrawList(), imgui.GetItemRectMin(), imgui.GetItemRectMax(), os.clock())
                drawMyStatsTab()
                imgui.EndTabItem()
            end
            if imgui.BeginTabItem(u8"Kill Streak") then
                drawAnimatedTabGlow(imgui.GetWindowDrawList(), imgui.GetItemRectMin(), imgui.GetItemRectMax(), os.clock())
                drawKillStreakTab()
                imgui.EndTabItem()
            end
            if imgui.BeginTabItem(u8"Zone") then
                drawAnimatedTabGlow(imgui.GetWindowDrawList(), imgui.GetItemRectMin(), imgui.GetItemRectMax(), os.clock())
                drawZonesTab()
                imgui.EndTabItem()
            end
            imgui.EndTabBar()
        end
        imgui.End()
        imgui.PopStyleVar()
    end
    if stats_alpha > 0.01 then drawStatsWindow(stats_alpha) end
    if compare_alpha > 0.01 then drawCompareWindow(compare_alpha) end
end
local _playersSorted  = false
local _playersSortKey = 0
local function ensurePlayersSorted()
    local key = hz_cfg.main.sr * 2 + (showSRev[0] and 1 or 0)
    if _playersSorted and _playersSortKey == key then return end
    _playersSortKey = key
    _playersSorted  = true
    local rev = showSRev[0]
    if hz_cfg.main.sr == 1 then
        table.sort(players, function(a,b)
            local an = (a.nick or ""):lower()
            local bn = (b.nick or ""):lower()
            if an == bn then return false end
            if rev then return an > bn else return an < bn end
        end)
    elseif hz_cfg.main.sr == 2 then
        table.sort(players, function(a,b)
            local ak, bk = a.kills or 0, b.kills or 0
            local ad, bd = a.deaths or 0, b.deaths or 0
            local an, bn = (a.nick or ""):lower(), (b.nick or ""):lower()
            if ak ~= bk then if rev then return ak < bk else return ak > bk end end
            if ad ~= bd then if rev then return ad > bd else return ad < bd end end
            if an == bn then return false end
            return an < bn
        end)
    elseif hz_cfg.main.sr == 3 then
        table.sort(players, function(a,b)
            local ak, bk = a.kills or 0, b.kills or 0
            local ad, bd = a.deaths or 0, b.deaths or 0
            local an, bn = (a.nick or ""):lower(), (b.nick or ""):lower()
            if ad ~= bd then if rev then return ad < bd else return ad > bd end end
            if ak ~= bk then if rev then return ak < bk else return ak > bk end end
            if an == bn then return false end
            return an < bn
        end)
    elseif hz_cfg.main.sr == 4 then
        table.sort(players, function(a,b)
            local akd = type(a.kd)=="number" and a.kd or 0
            local bkd = type(b.kd)=="number" and b.kd or 0
            local ak, bk = a.kills or 0, b.kills or 0
            local an, bn = (a.nick or ""):lower(), (b.nick or ""):lower()
            if akd ~= bkd then if rev then return akd < bkd else return akd > bkd end end
            if ak  ~= bk  then if rev then return ak  < bk  else return ak  > bk  end end
            if an  == bn  then return false end
            return an < bn
        end)
    end
end
function drawKillStateTab()
    local hz_cfg_dirty = false
    if imgui.Button(Fn.T(u8("Сбросить статистику"))) then
        imgui.OpenPopup("statistic")
    end
    if imgui.BeginPopup("statistic", 0) then
        if imgui.Button(Fn.T(u8("Личную"))) then
            dmgTotal=0; dmgLife=0; dmgLifeMax=0
            kills=0; killsLife=0; killsLifeMax=0
            deaths=0; shots_stat=0; hits_stat=0; ksLastTriggered=0
            sampAddChatMessage("{1E90FF}[HitZones]{ffffff} " ..
                "Личная статистика сброшена.", -1)
            imgui.CloseCurrentPopup()
        end
        if imgui.Button(Fn.T(u8("Общую"))) then
            players = {}
            sampAddChatMessage("{1E90FF}[HitZones]{ffffff} " ..
                "Общая статистика сброшена.", -1)
            imgui.CloseCurrentPopup()
        end
        if imgui.Button(Fn.T(u8("Всё"))) then
            players = {}
            dmgTotal=0; dmgLife=0; dmgLifeMax=0
            kills=0; killsLife=0; killsLifeMax=0
            deaths=0; shots_stat=0; hits_stat=0; ksLastTriggered=0
            sampAddChatMessage("{1E90FF}[HitZones]{ffffff} " ..
                "Вся статистика сброшена.", -1)
            imgui.CloseCurrentPopup()
        end
        imgui.EndPopup()
    end
    imgui.SameLine()
    if imgui.Button(Fn.T(u8("Сортировка"))) then imgui.OpenPopup("sort") end
    if imgui.BeginPopup("sort", 0) then
        local sortItems = {u8("По алфавиту"), u8("По убийствам"), u8("По смертям"), u8("По K/D")}
        for i, lbl in ipairs(sortItems) do
            local sel = (hz_cfg.main.sr == i)
            if imgui.Selectable(lbl, sel) then
                hz_cfg.main.sr = i
                hz_cfg_dirty = true
                _playersSorted = false
            end
            if sel then imgui.SetItemDefaultFocus() end
        end
        if icons_tex then
            imgui.Image(icons_tex, imgui.ImVec2(10,10), imgui.ImVec2(0.87,0.59), imgui.ImVec2(0.97,0.69))
            imgui.SameLine()
        end
        if imgui.Checkbox("##srt", showSRev) then
            _playersSorted = false
        end
        if showSRev[0] ~= hz_cfg.main.srt then hz_cfg.main.srt = showSRev[0]; hz_cfg_dirty = true end
        if icons_tex then
            imgui.SameLine()
            imgui.Image(icons_tex, imgui.ImVec2(10,10), imgui.ImVec2(0.87,0.72), imgui.ImVec2(0.97,0.82))
        end
        imgui.EndPopup()
    end
    imgui.SameLine()
    if imgui.Button("Save", imgui.ImVec2(40, 0)) then
        hz_cfg.main.ks_chat_notify = ksChatNotify[0]
        hz_cfg_dirty = true
        inicfg.save(hz_cfg, HZ_CFG_FILE)
        inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
        saveStreaks(killStreaks)
        hz_mainWindow[0] = false
        sampAddChatMessage("{1E90FF}[HitZones]{ffffff} " ..
            "Настройки сохранены.", -1)
        addOneOffSound(0, 0, 0, 1057)
    end
    if imgui.IsItemHovered() then
        imgui.BeginTooltip()
        imgui.PushTextWrapPos(450)
        imgui.TextUnformatted(Fn.T(u8("Специально для тех, у кого не сохраняются настройки.")))
        imgui.PopTextWrapPos()
        imgui.EndTooltip()
    end
    imgui.InputText("Search", searchBuf, 256)
    imgui.Text("Nick")
    imgui.SameLine(200) imgui.Text("Kills")
    imgui.SameLine(260) imgui.Text("Deaths")
    imgui.SameLine(325) imgui.Text("K/D")
    imgui.Separator()
    ensurePlayersSorted()
    local searchStr = ffi.string(searchBuf)
    for i, pl in ipairs(players) do
        if historyState[pl.nick] == nil then
            historyState[pl.nick] = {
                ac         = imgui.new.bool(false),
                showkills  = imgui.new.bool(true),
                showdeaths = imgui.new.bool(true),
            }
        end
        local a, r, g, b = explode_argb(pl.col)
        local cr, cg, cb, ca = argb2imvec4(a, r, g, b)
        local show = (searchStr == "") or (pl.nick:lower():find(searchStr:lower()))
        if show then
            local hcol = (searchStr ~= "") and accentVec4(nil, 0.65, 0.95) or accentVec4(nil, 0.28, 0.85)
            imgui.PushStyleColor(imgui.Col.Text,          imgui.ImVec4(1, 1, 1, 1))
            imgui.PushStyleColor(imgui.Col.HeaderHovered, hcol)
            imgui.PushStyleColor(imgui.Col.HeaderActive,  accentVec4(nil, 0.90, 1.0))
            imgui.Selectable(
                (searchStr ~= "" and Fn.T(u8(pl.nick)) or pl.nick) .. "[" .. pl.id .. "]", false)
            imgui.PopStyleColor(3)
            if imgui.IsItemHovered() and imgui.IsMouseClicked(1) then
                imgui.OpenPopup("popup_" .. pl.nick)
            end
            if imgui.IsItemHovered() and imgui.IsMouseClicked(0) then
                local entry = {nick=pl.nick, kills=pl.kills, deaths=pl.deaths, kd=pl.kd, col=pl.col}
                if compareSlots[1] == nil then
                    compareSlots[1] = entry
                    compareMsg = Fn.T(u8("Выбран ")) .. pl.nick .. Fn.T(u8(". Выбери второго игрока."))
                elseif compareSlots[2] == nil then
                    if compareSlots[1].nick ~= pl.nick then
                        compareSlots[2] = entry
                        compareOpen[0]  = true
                        compareMsg = ""
                    end
                else
                    compareSlots[1] = compareSlots[2]
                    compareSlots[2] = entry
                    compareOpen[0]  = true
                    compareMsg = ""
                end
            end
            imgui.SameLine(200) imgui.Text(tostring(pl.kills))
            imgui.SameLine(260) imgui.Text(tostring(pl.deaths))
            imgui.SameLine(325) imgui.Text(string.format("%.2f", pl.kd))
            imgui.Separator()
        end
        if imgui.BeginPopup("popup_" .. pl.nick, 0) then
            imgui.TextColored(imgui.ImVec4(1,1,1,1), pl.nick.."["..pl.id.."]")
            imgui.Separator()
            imgui.Text(Fn.T(u8("Скопировать")))
            if imgui.Button("ID") then
                if pl.id ~= "off" then imgui.SetClipboardText(tostring(pl.id))
                else sampAddChatMessage("{1E90FF}[HitZones]{ffffff} " ..
                    "Игрок вышел.", -1) end
                imgui.CloseCurrentPopup()
            end
            imgui.SameLine()
            if imgui.Button(Fn.T(u8("Ник"))) then
                imgui.SetClipboardText(tostring(pl.nick)); imgui.CloseCurrentPopup()
            end
            imgui.SameLine()
            if imgui.Button(Fn.T(u8("Ник[ID]"))) then
                imgui.SetClipboardText(pl.nick.."["..pl.id.."]"); imgui.CloseCurrentPopup()
            end
            if imgui.Button(Fn.T(u8("Ник[ID] и статистику"))) then
                imgui.SetClipboardText(pl.nick.."["..pl.id.."] | Kills:"..pl.kills..
                    " | Deaths:"..pl.deaths.." | KD:"..string.format("%.2f",pl.kd))
                imgui.CloseCurrentPopup()
            end
            imgui.Separator()
            if imgui.Button(Fn.T(u8("История")), imgui.ImVec2(127, 20)) then
                historyState[pl.nick].ac[0] = not historyState[pl.nick].ac[0]
                math.randomseed(os.time())
                historyOffset.x = "-0." .. math.random(7,8) .. math.random(10)
                historyOffset.y = "0."  .. math.random(7,8) .. math.random(10)
            end
            imgui.EndPopup()
        end
    end
    if compareMsg ~= "" then
        imgui.Spacing()
        imgui.TextColored(accentVec4(nil, 0.85, 1.0), compareMsg)
    end
    if compareSlots[1] ~= nil then
        imgui.Spacing()
        local sl1name = compareSlots[1] and compareSlots[1].nick or "—"
        local sl2name = compareSlots[2] and compareSlots[2].nick or Fn.T(u8("(не выбран)"))
        imgui.TextDisabled(Fn.T(u8("Сравнение: ")) .. sl1name .. " vs " .. sl2name)
        imgui.SameLine()
        if imgui.SmallButton(Fn.T(u8("Сброс##cmp"))) then
            compareSlots[1]=nil; compareSlots[2]=nil
            compareOpen[0]=false; compareMsg=""
        end
        if compareSlots[2] ~= nil then
            imgui.SameLine()
            if imgui.SmallButton(Fn.T(u8("Открыть##cmp"))) then compareOpen[0]=true end
        end
    end
    historywindow()
    if hz_cfg_dirty then hz_saveMainCfg() end
end
local _ksSorted = false
local function ensureKsSorted()
    if not _ksSorted then
        table.sort(killStreaks, function(a,b) return a.kills < b.kills end)
        _ksSorted = true
    end
end
function drawKillStreakTab()
    local hz_cfg_dirty = false
    ensureKsSorted()
    imgui.Text(Fn.T(u8("Kills"))); imgui.SameLine(50)
    imgui.Text(Fn.T(u8("Название"))); imgui.SameLine(185)
    imgui.Text(Fn.T(u8("Цвет"))); imgui.SameLine(245)
    imgui.Text(Fn.T(u8("Действие")))
    imgui.Separator()
    if _ksListHCount ~= #killStreaks then
        _ksListHCount = #killStreaks
        local visRows = math.max(3, math.min(#killStreaks, 6))
        _ksListH = 22 * visRows + 6
    end
    imgui.BeginChild("##ks_list", imgui.ImVec2(-1, _ksListH), true)
    local toDelete = nil
    for idx, s in ipairs(killStreaks) do
        local ci1, ci2, ci3, ci4 = 1.0, 1.0, 1.0, 1.0
        pcall(function()
            local a2, r2, g2, b2 = explode_argb(s.color or 0xFFFFFFFF)
            ci1 = r2/255; ci2 = g2/255; ci3 = b2/255; ci4 = a2/255
        end)
        local name_str = (s.name and s.name ~= "") and u8(s.name) or ("Streak "..tostring(s.kills))
        imgui.Text(tostring(s.kills)); imgui.SameLine(50)
        if ksEditIdx == idx then
            imgui.PushItemWidth(90)
            imgui.InputText("##en"..idx, ksEditName, 64)
            imgui.PopItemWidth()
            imgui.SameLine()
            if imgui.Button("-##ekm"..idx, imgui.ImVec2(18,0)) then
                if ksEditKills[0] > 1 then ksEditKills[0] = ksEditKills[0] - 1 end
            end
            imgui.SameLine()
            imgui.Text(tostring(ksEditKills[0]))
            imgui.SameLine()
            if imgui.Button("+##ekp"..idx, imgui.ImVec2(18,0)) then
                ksEditKills[0] = ksEditKills[0] + 1
            end
            imgui.SameLine()
            imgui.PushItemWidth(16)
            imgui.ColorEdit4("##ec"..idx, ksEditColor, imgui.ColorEditFlags.NoInputs)
            imgui.PopItemWidth()
            imgui.SameLine()
            if imgui.Button("OK##ok"..idx, imgui.ImVec2(26,0)) then
                local nameOk, res = pcall(ffi.string, ksEditName)
                if nameOk and res and res ~= "" then
                    killStreaks[idx].name = res
                end
                killStreaks[idx].kills = ksEditKills[0]
                pcall(function() killStreaks[idx].color = colorVec4ToArgb(ksEditColor) end)
                ksEditIdx = -1
                saveStreaks(killStreaks)
                _ksSorted = false
                ensureKsSorted()
            end
            imgui.SameLine()
            if imgui.Button("X##cx"..idx, imgui.ImVec2(18,0)) then ksEditIdx = -1 end
        else
            imgui.TextColored(imgui.ImVec4(ci1,ci2,ci3,ci4), name_str)
            imgui.SameLine(185)
            imgui.ColorButton("##cpke"..idx, imgui.ImVec4(ci1,ci2,ci3,ci4),
                imgui.ColorEditFlags.NoTooltip, imgui.ImVec2(14,14))
            imgui.SameLine(245)
            if imgui.Button(Fn.T(u8("Ред##re"))..idx, imgui.ImVec2(34,0)) then
