local function sectionHdr(txt)
    txt = Fn.T(txt)
    imgui.Spacing()
    imgui.PushStyleColor(imgui.Col.Text, accentVec4(nil, 0.85, 1.0))
    imgui.Text(txt); imgui.PopStyleColor()
    imgui.Separator(); imgui.Spacing()
end
local function fmtTime(secs)
    local s = math.floor(secs)
    local m = math.floor(s/60); s = s - m*60
    local h = math.floor(m/60); m = m - h*60
    if h > 0 then return string.format("%dh %02dm %02ds", h, m, s) end
    return string.format("%dm %02ds", m, s)
end
local function col32z(r, g, b, a)
    return HZ_U32(imgui.ImVec4(r, g, b, a))
end
local function accentU32(mult, alpha)
    return HZ_U32(accentVec4(mult, alpha))
end
local function drawEllFill(draw, cx, cy, rx, ry, color)
    local N = 24
    local pts = {}
    for i = 0, N-1 do
        local a = (i/N)*math.pi*2
        pts[#pts+1] = imgui.ImVec2(cx + math.cos(a)*rx, cy + math.sin(a)*ry)
    end
    for i = 1, #pts do
        draw:AddTriangleFilled(imgui.ImVec2(cx,cy), pts[i], pts[(i%#pts)+1], color)
    end
end
local function drawEllLine(draw, cx, cy, rx, ry, color, thick)
    local N = 24; thick = thick or 1.5
    for i = 0, N-1 do
        local a1 = (i/N)*math.pi*2
        local a2 = ((i+1)/N)*math.pi*2
        draw:AddLine(
            imgui.ImVec2(cx+math.cos(a1)*rx, cy+math.sin(a1)*ry),
            imgui.ImVec2(cx+math.cos(a2)*rx, cy+math.sin(a2)*ry),
            color, thick)
    end
end
local function drawBodySilhouette(draw, ox, oy, sc, bh)
    initZonesDef()
    local maxH = 1
    for _, z in ipairs(ZONES_DEF) do
        local v = bh[z.hk] or 0; if v > maxH then maxH = v end
    end
    local mp = imgui.GetMousePos()
    local mx, my = mp.x, mp.y
    local hov = nil
    draw:AddRectFilled(imgui.ImVec2(ox-5*sc,oy+34*sc), imgui.ImVec2(ox+5*sc,oy+38*sc),
        accentU32(0.30, 0.90))
    for _, z in ipairs(ZONES_DEF) do
        local hits = bh[z.hk] or 0
        local cx = ox + z.cx*sc
        local cy = oy + z.cy*sc
        local rx = z.rx*sc
        local ry = z.ry*sc
        local t  = math.min(hits/maxH, 1.0)
        drawEllFill(draw, cx, cy, rx, ry, accentU32(0.20, 0.92))
        if hits > 0 then
            local hr = math.min(0.10+t*0.90, 1.0)
            local hg = math.max(0.65-t*0.55, 0.0)
            local hb = math.max(0.90-t*0.90, 0.0)
            drawEllFill(draw, cx, cy, rx*0.88, ry*0.88, col32z(hr,hg,hb, 0.15+t*0.70))
        end
        local dx = (mx-cx)/rx
        local dy = (my-cy)/ry
        local in_z = (dx*dx+dy*dy) <= 1.0
        if in_z then hov = {z=z, hits=hits} end
        drawEllLine(draw, cx, cy, rx, ry,
            in_z and accentU32(1.5, 1.0) or accentU32(0.75, 0.85),
            in_z and 2.2 or 1.3)
        if in_z then drawEllFill(draw, cx, cy, rx, ry, accentU32(1.3, 0.08)) end
    end
    return hov
end
local function drawZoneTable(bh)
    initZonesDef()
    local maxH = 1; local tot = 0
    for _, z in ipairs(ZONES_DEF) do
        local v = bh[z.hk] or 0
        if v > maxH then maxH = v end
        tot = tot + v
    end
    imgui.Columns(4, "zonecols", false)
    imgui.SetColumnWidth(0, 100)
    imgui.SetColumnWidth(1, 55)
    imgui.SetColumnWidth(2, 65)
    imgui.SetColumnWidth(3, 65)
    imgui.PushStyleColor(imgui.Col.Text, accentVec4(1.0, 1.0))
    imgui.Text(Fn.T(u8("Зона")));  imgui.NextColumn()
    imgui.Text(Fn.T(u8("Поп.")));  imgui.NextColumn()
    imgui.Text(Fn.T(u8("%макс"))); imgui.NextColumn()
    imgui.Text(Fn.T(u8("%всех"))); imgui.NextColumn()
    imgui.PopStyleColor()
    imgui.Separator()
    for _, z in ipairs(ZONES_DEF) do
        local hits = bh[z.hk] or 0
        local t2   = maxH > 0 and math.min(hits/maxH,1.0) or 0
        local pPop = tot  > 0 and math.floor(hits/tot*100)  or 0
        local pMax = maxH > 0 and math.floor(hits/maxH*100) or 0
        local row_mult = 0.55 + 0.45 * t2
        local row_col  = accentVec4(nil, row_mult, 1.0)
        if hits > 0 then
            row_col = accentVec4(nil, 0.70 + 0.30 * t2, 1.0)
        end
        imgui.TextColored(row_col, Fn.T(z.label)); imgui.NextColumn()
        imgui.TextColored(row_col, tostring(hits)); imgui.NextColumn()
        imgui.TextColored(row_col, pMax.."%");     imgui.NextColumn()
        imgui.TextColored(row_col, pPop.."%");     imgui.NextColumn()
    end
    imgui.Columns(1)
    imgui.Separator()
    imgui.TextColored(accentVec4(0.85, 1.0), Fn.T(u8("Итого: "))..tot)
end
function drawZonesTab()
    initZonesDef()
    imgui.Spacing()
    local zEnBool = imgui.new.bool(zones_enabled)
    if imgui.Checkbox(Fn.T(u8("Трекинг зон активен")), zEnBool) then
        zones_enabled = zEnBool[0]
    end
    imgui.SameLine()
    if zones_enabled then
        imgui.TextColored(imgui.ImVec4(0.20,0.90,0.35,1), Fn.T(u8("[ON]")))
    else
        imgui.TextColored(imgui.ImVec4(0.90,0.30,0.30,1), Fn.T(u8("[OFF]")))
    end
    imgui.Separator()
    imgui.Spacing()
    local _zy = imgui.GetCursorPosY()
    imgui.SetCursorPosY(math.max(0, _zy - 7))
    imgui.BeginChild("zone_tabs", imgui.ImVec2(-1, 42), false, imgui.WindowFlags.HorizontalScrollbar)
    imgui.SetCursorPosY(4)
    local noPlayerAct = (zones_player == nil)
    local myBtn_lbl = Fn.T(zones_my_mode == 1 and u8("Мои v") or u8("Чужие v"))
    imgui.PushStyleColor(imgui.Col.Button,
        noPlayerAct and accentVec4(nil, 0.55, 1.0) or accentVec4(nil, 0.16, 0.90))
    imgui.PushStyleColor(imgui.Col.ButtonHovered,
        noPlayerAct and accentVec4(nil, 0.80, 1.0) or accentVec4(nil, 0.30, 0.95))
    imgui.PushStyleColor(imgui.Col.ButtonActive, accentVec4(nil, 1.00, 1.0))
    if imgui.Button(myBtn_lbl, imgui.ImVec2(80,24)) then
        if zones_player ~= nil then
            zones_player = nil
        else
            zones_my_mode = zones_my_mode == 1 and 2 or 1
        end
    end
    imgui.PopStyleColor(3)
    local sorted = {}
    for nick in pairs(zones_cfg.players) do table.insert(sorted, nick) end
    table.sort(sorted)
    for _, nick in ipairs(sorted) do
        imgui.SameLine()
        local act = (zones_player == nick)
        imgui.PushStyleColor(imgui.Col.Button,
            act and accentVec4(nil, 0.55, 1.0) or accentVec4(nil, 0.16, 0.90))
        imgui.PushStyleColor(imgui.Col.ButtonHovered,
            act and accentVec4(nil, 0.80, 1.0) or accentVec4(nil, 0.30, 0.95))
        imgui.PushStyleColor(imgui.Col.ButtonActive, accentVec4(nil, 1.00, 1.0))
        if CBUGER_MarqueeButton(nick, "z"..nick, 118, 24) then
            zones_player = nick
        end
        imgui.PopStyleColor(3)
    end
    imgui.EndChild()
    if zones_player and not zones_cfg.players[zones_player] then zones_player = nil end
    imgui.Spacing()
    if zones_player then
        local m1 = (zones_view_mode == 1)
        imgui.PushStyleColor(imgui.Col.Button,
            m1 and accentVec4(nil, 0.55, 1.0) or accentVec4(nil, 0.16, 0.90))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, accentVec4(nil, 0.80, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive,  accentVec4(nil, 1.00, 1.0))
        if imgui.Button(Fn.T(u8("Мои по нему")), imgui.ImVec2(155,24)) then zones_view_mode=1 end
        imgui.PopStyleColor(3)
        imgui.SameLine()
        local m2 = (zones_view_mode == 2)
        imgui.PushStyleColor(imgui.Col.Button,
            m2 and accentVec4(nil, 0.55, 1.0) or accentVec4(nil, 0.16, 0.90))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, accentVec4(nil, 0.80, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive,  accentVec4(nil, 1.00, 1.0))
        if imgui.Button(Fn.T(u8("Его по мне")), imgui.ImVec2(155,24)) then zones_view_mode=2 end
        imgui.PopStyleColor(3)
        imgui.SameLine()
        if zones_view_mode == 1 then
            imgui.TextColored(accentVec4(nil, 0.75, 0.85), Fn.T(u8("  вы по нему")))
        else
            imgui.TextColored(accentVec4(nil, 0.95, 0.85), Fn.T(u8("  он по вам")))
        end
    else
        if zones_my_mode == 1 then
            imgui.TextColored(accentVec4(nil, 0.85, 0.95), Fn.T(u8("Мои попадания по всем игрокам")))
        else
            imgui.TextColored(accentVec4(nil, 1.00, 0.95), Fn.T(u8("Попадания всех игроков по мне")))
        end
    end
    imgui.Spacing()
    local bh
    if zones_player == nil then
        bh = zones_my_mode == 1 and zones_cfg.my_zones or zones_cfg.recv_zones
    elseif zones_view_mode == 1 then
        bh = (zones_cfg.players[zones_player] and zones_cfg.players[zones_player].zones) or newBodyHits()
    else
        bh = (zones_cfg.players[zones_player] and zones_cfg.players[zones_player].recv_zones) or newBodyHits()
    end
    local avail_h = imgui.GetContentRegionAvail().y - 44
    imgui.BeginChild("bodyview_z", imgui.ImVec2(175, avail_h), false)
    local p    = imgui.GetCursorScreenPos()
    local draw = imgui.GetWindowDrawList()
    local hov  = drawBodySilhouette(draw, p.x+87, p.y+8, 1.601, bh)
    if hov then
        local tot2 = 0
        for _, z in ipairs(ZONES_DEF) do tot2 = tot2 + (bh[z.hk] or 0) end
        local pct = tot2 > 0 and math.floor(hov.hits/tot2*100) or 0
        imgui.SetTooltip(string.format("%s\n%s: %d  (%d%%)",
            Fn.T(hov.z.label), Fn.T(u8("Попаданий")), hov.hits, pct))
    end
    imgui.Dummy(imgui.ImVec2(171, avail_h-4))
    imgui.EndChild()
    imgui.SameLine()
    imgui.BeginChild("zonetable_z", imgui.ImVec2(-1, avail_h), true)
    drawZoneTable(bh)
    imgui.EndChild()
    imgui.Spacing()
    imgui.PushStyleColor(imgui.Col.Button,        accentVec4(nil, 0.40, 1.0))
    imgui.PushStyleColor(imgui.Col.ButtonHovered, accentVec4(nil, 0.65, 1.0))
    imgui.PushStyleColor(imgui.Col.ButtonActive,  accentVec4(nil, 0.90, 1.0))
    if imgui.Button(Fn.T(u8("Сбросить зоны")), imgui.ImVec2(-1, 26)) then
        if zones_player and zones_cfg.players[zones_player] then
            if zones_view_mode == 1 then
                zones_cfg.players[zones_player].zones = newBodyHits()
            else
                zones_cfg.players[zones_player].recv_zones = newBodyHits()
            end
        else
            if zones_my_mode == 1 then
                zones_cfg.my_zones = newBodyHits()
            else
                zones_cfg.recv_zones = newBodyHits()
            end
        end
        saveZonesCfg()
    end
    imgui.PopStyleColor(3)
end
function drawCbugTab()
    if imgui.BeginTabBar("##cbug_inner") then
        if imgui.BeginTabItem(Fn.T(u8("Настройки"))) then
            local statusColor = hz_cbug_cfg.settings.active
                and accentVec4(nil, 1.0, 1.0) or imgui.ImVec4(0.9, 0.3, 0.3, 1)
            local statusText = hz_cbug_cfg.settings.active
                and Fn.T(u8("[ON] CBug АКТИВЕН"))
                or  Fn.T(u8("[OFF] CBug ВЫКЛЮЧЕН"))
            imgui.TextColored(statusColor, statusText)
            imgui.SameLine(); imgui.TextDisabled(Fn.T(u8("(/hz)")))
            imgui.Separator()
            local cbug_active_b = imgui.new.bool(hz_cbug_cfg.settings.active)
            if imgui.Checkbox(Fn.T(u8("Трекер активен##cb")), cbug_active_b) then
                hz_cbug_cfg.settings.active = cbug_active_b[0]
                hz_cbug_session.shots = 0; hz_cbug_session.active = false
                inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
            end
            imgui.SameLine()
            if imgui.Button(Fn.T(u8("Цвет HUD##cbclr"))) then
                imgui.OpenPopup("cbug_color_popup")
            end
            if imgui.BeginPopup("cbug_color_popup") then
                imgui.Text(Fn.T(u8("Цвет индикатора:")))
                local flags = imgui.ColorEditFlags.NoSidePreview
                    + imgui.ColorEditFlags.NoSmallPreview
                    + imgui.ColorEditFlags.AlphaBar
                    + imgui.ColorEditFlags.AlphaPreview
                if imgui.ColorPicker4("##cbug_picker", hz_cbug_hud_color, flags) then
                    hz_cbug_cfg.settings.text_color_r = hz_cbug_hud_color[0]
                    hz_cbug_cfg.settings.text_color_g = hz_cbug_hud_color[1]
                    hz_cbug_cfg.settings.text_color_b = hz_cbug_hud_color[2]
                    hz_cbug_cfg.settings.text_color_a = hz_cbug_hud_color[3]
                    inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
                end
                imgui.EndPopup()
            end
            imgui.Separator()
            imgui.PushItemWidth(200)
            local req = imgui.new.int(hz_cbug_cfg.settings.required_shots)
            if imgui.InputInt(Fn.T(u8("Нужно выстрелов##cb")), req) then
                if req[0] >= 1 then
                    hz_cbug_cfg.settings.required_shots = req[0]
                    inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
                end
            end
            imgui.PopItemWidth()
            if imgui.Button(Fn.T(u8("Позиция HUD##cb")), imgui.ImVec2(-1, 22)) then
                hz_mainWindow[0] = false
                lua_thread.create(hz_crdHud)
            end
            imgui.PushItemWidth(200)
            do
                local sc = imgui.new.float(hz_cbug_cfg.settings.indicator_scale)
                SliderFloatOD(u8("Масштаб HUD"), "scale_cb", sc, 0.3, 4.0)
                if sc[0] ~= hz_cbug_cfg.settings.indicator_scale then
                    hz_cbug_cfg.settings.indicator_scale = sc[0]
                    inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
                end
            end
            do
                local ft = imgui.new.float(hz_cbug_cfg.settings.fail_timeout)
                SliderFloatOD(u8("Таймаут сброса (сек)"), "ft_cb", ft, 0.1, 3.0, "%.1f")
                if ft[0] ~= hz_cbug_cfg.settings.fail_timeout then
                    hz_cbug_cfg.settings.fail_timeout = ft[0]
                    inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
                end
            end
            imgui.PopItemWidth()
            imgui.Spacing()
            imgui.Text(Fn.T(u8("Стиль HUD:")))
            local modeSeq = {
                {3, u8("Минимальный")},
                {1, u8("Базовый")},
                {4, u8("Стандартный")},
                {2, u8("Расширенный")},
            }
            local bW = (imgui.GetContentRegionAvail().x - 12) / 4
            for _, pair in ipairs(modeSeq) do
                local mi, lbl = pair[1], Fn.T(pair[2])
                local act = (hz_cbug_cfg.settings.hud_mode == mi)
                imgui.PushStyleColor(imgui.Col.Button,
                    act and accentVec4(nil, 0.55, 1.0) or accentVec4(nil, 0.16, 0.90))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, accentVec4(nil, 0.80, 1.0))
                imgui.PushStyleColor(imgui.Col.ButtonActive,  accentVec4(nil, 1.00, 1.0))
                imgui.PushStyleColor(imgui.Col.Text,
                    act and accentVec4(nil, 1.10, 1.0) or accentVec4(nil, 0.62, 0.95))
                if imgui.Button(lbl, imgui.ImVec2(bW, 24)) then
                    hz_cbug_cfg.settings.hud_mode = mi
                    inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
                end
                imgui.PopStyleColor(4)
                imgui.SameLine()
            end
            imgui.NewLine()
            imgui.Spacing()
            do
                local b = imgui.new.bool(hz_cbug_cfg.settings.show_streak)
                if imgui.Checkbox(Fn.T(u8("Стрик на HUD##cb")), b) then
                    hz_cbug_cfg.settings.show_streak = b[0]
                    inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
                end
            end
            imgui.SameLine()
            do
                local b = imgui.new.bool(hz_cbug_cfg.settings.notify_record)
                if imgui.Checkbox(Fn.T(u8("Уведомление о рекорде##cb")), b) then
                    hz_cbug_cfg.settings.notify_record = b[0]
                    inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
                end
            end
            imgui.Separator()
            imgui.Text(Fn.T(u8("Рекорды CBug:")))
            imgui.BeginChild("cb_records", imgui.ImVec2(-1, 65), true)
            local hasRec = false
            for k, v in pairs(hz_cbug_cfg.records) do
                hasRec = true
                imgui.TextColored(accentVec4(nil, 0.85, 1.0),
                    string.format(Fn.T(u8("Выстрелов: %s | Время: %d ms")), k, v))
            end
            if not hasRec then imgui.TextDisabled(Fn.T(u8("Рекордов нет"))) end
            imgui.EndChild()
            if imgui.Button(Fn.T(u8("Очистить рекорды##cb")), imgui.ImVec2(-1, 22)) then
                hz_cbug_cfg.records = {}; inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
            end
            imgui.EndTabItem()
        end
        imgui.EndTabBar()
    end
end
function drawMyStatsTab()
    local kd  = (deaths == 0) and kills or kills/deaths
    local acc = shots_stat > 0 and (hits_stat/(shots_stat/100)) or 0
    local pt  = hz_cbug_cfg.stats.total_playtime + (hz_cbug_playtime_start > 0 and (os.clock()-hz_cbug_playtime_start) or 0)
    local allKills  = hz_cbug_cfg.stats.kills  or 0
    local allDeaths = hz_cbug_cfg.stats.deaths or 0
    local allKD     = allDeaths == 0 and allKills or allKills/allDeaths
    imgui.Columns(2, "mystats_cols", true)
    imgui.SetColumnWidth(0, 240)
    local startY = imgui.GetCursorPosY()
    sectionHdr(u8("Всё время"))
    statRow(u8("Убийств"),         allKills,                                      0.30,1.00,0.55)
    statRow(u8("Смертей"),         allDeaths,                                     1.00,0.30,0.30)
    statRow(u8("K/D"),             string.format("%.2f", allKD),                  1.00,0.85,0.20)
    statRow(u8("Лучший стрик"),    hz_cbug_cfg.stats.best_streak or 0,               1.00,0.80,0.20)
    statRow(u8("Урон всего"),      math.floor(hz_cbug_cfg.stats.dmg_total or 0),     1.00,0.60,0.20)
    statRow(u8("Макс.урон/жизнь"), math.floor(hz_cbug_cfg.stats.dmg_max_life or 0), 1.00,0.40,0.10)
    statRow(u8("Время"),           fmtTime(pt),                                   0.70,0.70,1.00)
    imgui.NextColumn()
    imgui.SetCursorPosY(startY)
    sectionHdr(u8("Текущая сессия"))
    statRow(u8("Убийств"),         kills,                             0.30,1.00,0.55)
    statRow(u8("Смертей"),         deaths,                            1.00,0.30,0.30)
    statRow(u8("K/D"),             string.format("%.2f", kd),         1.00,0.85,0.20)
    statRow(u8("Уб./жизнь"),       killsLife,                         0.40,1.00,0.60)
    statRow(u8("Макс.уб./жизнь"),  killsLifeMax,                      0.40,1.00,0.60)
    statRow(u8("Урон всего"),      math.floor(dmgTotal),              1.00,0.60,0.20)
    statRow(u8("Урон/жизнь"),      math.floor(dmgLife),               1.00,0.55,0.15)
    statRow(u8("Макс.урон/жизнь"), math.floor(dmgLifeMax),            1.00,0.40,0.10)
    statRow(u8("Выстрелов"),       shots_stat,                        0.90,0.90,0.50)
    statRow(u8("Попаданий"),       hits_stat,                         0.30,1.00,0.50)
    statRow(u8("Промахов"),        shots_stat - hits_stat,            1.00,0.40,0.40)
    statRow(u8("Точность"),        string.format("%.1f%%", acc),      0.50,1.00,0.80)
    statRow(u8("Время сессии"),    fmtTime(hz_cbug_run.session_start > 0 and os.clock()-hz_cbug_run.session_start or 0), 0.70,0.70,0.80)
    imgui.Columns(1)
    imgui.Separator(); imgui.Spacing()
    if imgui.Button(Fn.T(u8("Личная статистика...")), imgui.ImVec2(-1, 22)) then
        statsWindowOpen[0] = not statsWindowOpen[0]
    end
    imgui.Spacing()
    local hw = (imgui.GetContentRegionAvail().x - 8)/2
    if imgui.Button(Fn.T(u8("Сбросить сессию")), imgui.ImVec2(hw, 26)) then
        kills=0; killsLife=0; killsLifeMax=0; deaths=0
        shots_stat=0; hits_stat=0
        dmgTotal=0; dmgLife=0; dmgLifeMax=0; ksLastTriggered=0
        hz_cbug_run.session_shots=0; hz_cbug_run.session_hits=0
        hz_cbug_run.session_combos=0; hz_cbug_run.streak=0
        hz_cbug_run.session_start=os.clock()
        hz_cbug_session.shots=0; hz_cbug_session.active=false
    end
    imgui.SameLine()
    if imgui.Button(Fn.T(u8("Сбросить ВСЁ")), imgui.ImVec2(hw, 26)) then
        hz_cbug_cfg.stats = {
            total_shots=0,total_hits=0,total_misses=0,total_combos=0,
            best_kpd=0,best_streak=0,total_playtime=0,deaths=0,kills=0,
            dmg_total=0,dmg_max_life=0
        }
        kills=0; killsLife=0; killsLifeMax=0; deaths=0
        shots_stat=0; hits_stat=0
        dmgTotal=0; dmgLife=0; dmgLifeMax=0; ksLastTriggered=0
        hz_cbug_run.session_shots=0; hz_cbug_run.session_hits=0
        hz_cbug_run.session_combos=0; hz_cbug_run.streak=0
        hz_cbug_run.session_start=os.clock()
        hz_cbug_playtime_start = os.clock()
        hz_cbug_session.shots=0; hz_cbug_session.active=false
        inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
    end
end
function drawCompareWindow(module_alpha)
    module_alpha = tonumber(module_alpha) or CBUGER_UPDATE_MODULE_FADE('hitzones_compare', compareOpen[0], CBUGER_GET_ANIM_RATE(15))
    if module_alpha <= 0.01 then return end
    local p1 = compareSlots[1]
    local p2 = compareSlots[2]
    if not p1 or not p2 then return end
    local compare_rst = CBUGER_APPLY_WINDOW_SIZE("hitzone_compare", 480, 380)
    imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, CBUGER_GET_INTERFACE_ALPHA() * module_alpha)
    imgui.SetNextWindowPos(
        imgui.ImVec2(imgui.GetIO().DisplaySize.x/2, imgui.GetIO().DisplaySize.y/2 + 180),
        imgui.Cond.FirstUseEver, imgui.ImVec2(0.5, 0.5))
    local compare_open_ptr = compareOpen[0] and compareOpen or nil
    if not imgui.Begin(Fn.T(u8("Сравнение: ")) .. p1.nick .. " vs " .. p2.nick,
            compare_open_ptr, imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoResize) then
        imgui.End(); imgui.PopStyleVar(); return
    end
    CBUGER_DRAW_INVISIBLE_RESIZER("hitzone_compare", compare_rst, 360, 300, CBUGER_GET_INTERFACE_ALPHA(), true)
    do
        local cdl = imgui.GetWindowDrawList()
        local cp  = imgui.GetWindowPos()
        local cs  = imgui.GetWindowSize()
        CBUGER_DRAW_GLOBAL_AMBIENT(cdl, cp, imgui.ImVec2(cp.x + cs.x, cp.y + cs.y), CBUGER_GET_INTERFACE_ALPHA())
    end
    imgui.PushStyleColor(imgui.Col.Separator,      accentVec4(nil, 0.55, 0.80))
    imgui.PushStyleColor(imgui.Col.SeparatorHovered, accentVec4(nil, 0.80, 1.0))
    imgui.PushStyleColor(imgui.Col.SeparatorActive,  accentVec4(nil, 1.00, 1.0))
    local function pcol(pl)
        local a,r,g,b = explode_argb(pl.col)
        local c1,c2,c3 = argb2imvec4(a,r,g,b)
        return imgui.ImVec4(c1,c2,c3,1)
    end
    local function findPl(nick)
        for _, pl in ipairs(players) do
            if pl.nick == nick then return pl end
        end
        return nil
    end
    local function calcPersonal(n1, n2)
        local i_killed_him = 0
        local he_killed_me = 0
        local pl1 = findPl(n1)
        local src = pl1
        if not src then src = findPl(n2) end
        if src and src.history then
            for _, h in ipairs(src.history) do
                if h.killer.nick == n1 and h.killed.nick == n2 then
                    i_killed_him = i_killed_him + 1
                elseif h.killer.nick == n2 and h.killed.nick == n1 then
                    he_killed_me = he_killed_me + 1
                end
            end
        end
        return i_killed_him, he_killed_me
    end
    local W = imgui.GetContentRegionAvail().x
    local cW0 = W * 0.38
    local cW1 = W * 0.31
    local cW2 = W * 0.31
    local rowH = imgui.GetTextLineHeightWithSpacing()
    local function cmpRow(label, v1, v2, fmtFn, higherBetter)
        fmtFn = fmtFn or tostring
        local eq     = (v1 == v2)
        local p1wins = higherBetter and (v1 > v2) or (v1 < v2)
        local clr1   = eq and 0xFFFFFFFF or (p1wins and 0xFF40E060 or 0xFF3333FF)
        local clr2   = eq and 0xFFFFFFFF or (p1wins and 0xFF3333FF or 0xFF40E060)
        local draw   = imgui.GetWindowDrawList()
        local fs     = imgui.GetTextLineHeight()
        local pos    = imgui.GetCursorScreenPos()
        draw:AddTextFontPtr(CBUGER_GET_GLOBAL_FONT() or imgui.GetFont(), fs,
            imgui.ImVec2(pos.x,       pos.y), HZ_U32(accentVec4(nil,1.0,1.0)), label)
        draw:AddTextFontPtr(CBUGER_GET_GLOBAL_FONT() or imgui.GetFont(), fs,
            imgui.ImVec2(pos.x+cW0,  pos.y), CBUGER_ApplyGlobalAlphaU32(clr1), fmtFn(v1))
        draw:AddTextFontPtr(CBUGER_GET_GLOBAL_FONT() or imgui.GetFont(), fs,
            imgui.ImVec2(pos.x+cW0+cW1, pos.y), CBUGER_ApplyGlobalAlphaU32(clr2), fmtFn(v2))
        imgui.Dummy(imgui.ImVec2(W - 8, rowH))
        if not eq then
            local total  = v1 + v2
            local ratio1 = total > 0 and (v1/total) or 0.5
            local bW = W - 8; local bH = 3
            local bp = imgui.GetCursorScreenPos()
            draw:AddRectFilled(
                imgui.ImVec2(bp.x, bp.y), imgui.ImVec2(bp.x+bW, bp.y+bH),
                HZ_U32(accentVec4(nil, 0.12, 1.0)), 1)
            draw:AddRectFilled(
                imgui.ImVec2(bp.x, bp.y),
                imgui.ImVec2(bp.x + bW*ratio1, bp.y+bH),
                HZ_U32(
                    p1wins and imgui.ImVec4(0.2,0.85,0.35,1) or imgui.ImVec4(0.85,0.2,0.2,1)), 1)
            imgui.Dummy(imgui.ImVec2(bW, bH + 1))
        end
    end
    local fmt2 = function(v) return string.format("%.2f", v) end
    if imgui.BeginTabBar("##cmp_tabs") then
        if imgui.BeginTabItem(Fn.T(u8("Общая"))) then
            drawAnimatedTabGlow(imgui.GetWindowDrawList(), imgui.GetItemRectMin(), imgui.GetItemRectMax(), os.clock())
            imgui.Spacing()
            do
                local draw = imgui.GetWindowDrawList()
                local pos  = imgui.GetCursorScreenPos()
                local fs   = imgui.GetTextLineHeight()
                local fnt  = CBUGER_GET_GLOBAL_FONT() or imgui.GetFont()
                draw:AddTextFontPtr(fnt, fs, imgui.ImVec2(pos.x,pos.y),         HZ_U32(accentVec4(nil, 1.0, 1.0)), u8("Параметр"))
                draw:AddTextFontPtr(fnt, fs, imgui.ImVec2(pos.x+cW0,pos.y),     CBUGER_ApplyGlobalAlphaU32(0xFFFFFFFF), p1.nick)
                draw:AddTextFontPtr(fnt, fs, imgui.ImVec2(pos.x+cW0+cW1,pos.y), CBUGER_ApplyGlobalAlphaU32(0xFFFFFFFF), p2.nick)
                imgui.Dummy(imgui.ImVec2(W-8, rowH))
            end
            imgui.Separator(); imgui.Spacing()
            cmpRow("Kills",  p1.kills,  p2.kills,  nil,  true)
            cmpRow("Deaths", p1.deaths, p2.deaths, nil,  false)
            cmpRow("K/D",    p1.kd,     p2.kd,     fmt2, true)
            imgui.EndTabItem()
        end
        if imgui.BeginTabItem(Fn.T(u8("Личная"))) then
            drawAnimatedTabGlow(imgui.GetWindowDrawList(), imgui.GetItemRectMin(), imgui.GetItemRectMax(), os.clock())
            imgui.Spacing()
            local k12, k21 = calcPersonal(p1.nick, p2.nick)
            local kd12 = k21 > 0 and k12/k21 or k12
            local kd21 = k12 > 0 and k21/k12 or k21
            do
                local draw = imgui.GetWindowDrawList()
                local pos  = imgui.GetCursorScreenPos()
                local fs   = imgui.GetTextLineHeight()
                local fnt  = CBUGER_GET_GLOBAL_FONT() or imgui.GetFont()
                draw:AddTextFontPtr(fnt, fs, imgui.ImVec2(pos.x,pos.y),         HZ_U32(accentVec4(nil, 1.0, 1.0)), u8("Параметр"))
                draw:AddTextFontPtr(fnt, fs, imgui.ImVec2(pos.x+cW0,pos.y),     CBUGER_ApplyGlobalAlphaU32(0xFFFFFFFF), p1.nick)
                draw:AddTextFontPtr(fnt, fs, imgui.ImVec2(pos.x+cW0+cW1,pos.y), CBUGER_ApplyGlobalAlphaU32(0xFFFFFFFF), p2.nick)
                imgui.Dummy(imgui.ImVec2(W-8, rowH))
            end
            imgui.Separator(); imgui.Spacing()
            cmpRow(u8("Убийств"),        k12,  k21,  nil,  true)
            cmpRow(u8("Смертей от него"), k21,  k12,  nil,  false)
            cmpRow(u8("K/D (vs него)"),   kd12, kd21, fmt2, true)
            imgui.Spacing(); imgui.Separator(); imgui.Spacing()
            local total = k12 + k21
            if total == 0 then
                imgui.TextColored(imgui.ImVec4(1,1,1,1),
                    Fn.T(u8("Встреч между этими игроками не зафиксировано")))
            else
                local bW  = W - 8
                local bH  = 18
                local r1  = total > 0 and (k12/total) or 0.5
                local draw= imgui.GetWindowDrawList()
                local pos = imgui.GetCursorScreenPos()
                local a1,r,g,b_ = explode_argb(p1.col)
                local pc1r,pc1g,pc1b = argb2imvec4(a1,r,g,b_)
                local a2,r2,g2,b2   = explode_argb(p2.col)
                local pc2r,pc2g,pc2b= argb2imvec4(a2,r2,g2,b2)
                draw:AddRectFilled(imgui.ImVec2(pos.x,pos.y),
                    imgui.ImVec2(pos.x+bW,pos.y+bH),
                    HZ_U32(accentVec4(nil, 0.12, 1.0)), 4)
                if r1 > 0 then
                    draw:AddRectFilled(imgui.ImVec2(pos.x,pos.y),
                        imgui.ImVec2(pos.x+bW*r1,pos.y+bH),
                        HZ_U32(imgui.ImVec4(0.15,0.65,0.30,1)), 4)
                end
                if r1 < 1 then
                    draw:AddRectFilled(imgui.ImVec2(pos.x+bW*r1,pos.y),
                        imgui.ImVec2(pos.x+bW,pos.y+bH),
                        HZ_U32(imgui.ImVec4(0.65,0.15,0.15,1)), 4)
                end
                draw:AddRect(imgui.ImVec2(pos.x,pos.y),
                    imgui.ImVec2(pos.x+bW,pos.y+bH),
                    HZ_U32(accentVec4(nil, 0.75, 0.60)), 4)
                local lbl1 = p1.nick .. " " .. k12
                local lbl2 = k21 .. " " .. p2.nick
                local fs   = 13.0
                local cmp_font = CBUGER_GET_GLOBAL_FONT() or imgui.GetFont()
                if cmp_font then
                    local sz1 = cmp_font:CalcTextSizeA(fs,1000,0,lbl1)
                    local sz2 = cmp_font:CalcTextSizeA(fs,1000,0,lbl2)
                    local ty  = pos.y + (bH - sz1.y)*0.5
                    draw:AddTextFontPtr(cmp_font, fs,
                        imgui.ImVec2(pos.x+6, ty), CBUGER_ApplyGlobalAlphaU32(0xFFFFFFFF), lbl1)
                    draw:AddTextFontPtr(cmp_font, fs,
                        imgui.ImVec2(pos.x+bW-sz2.x-6, ty), CBUGER_ApplyGlobalAlphaU32(0xFFFFFFFF), lbl2)
                end
                imgui.Dummy(imgui.ImVec2(bW, bH + 4))
                imgui.Spacing()
                local leads = " \xd0\xb2\xd0\xb5\xd0\xb4\xd1\x91\xd1\x82  "
