                elseif k21 > k12 then
                    imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.30,1.00,0.50,1))
                    imgui.Text(p2.nick .. leads .. k21 .. " : " .. k12)
                    imgui.PopStyleColor()
                else
                    imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1,1,1,1))
                    imgui.Text("\xd0\xa1\xd1\x87\xd1\x91\xd1\x82 \xd1\x80\xd0\xb0\xd0\xb2\xd0\xbd\xd1\x8b\xd0\xb9  "
                        .. k12 .. " : " .. k21)
                    imgui.PopStyleColor()
                end
            end
            imgui.EndTabItem()
