    imgui.Spacing(); imgui.Separator(); imgui.Spacing()
    local bw = (imgui.GetContentRegionAvail().x - 8) / 2
    if imgui.Button(Fn.T(u8("Новое сравнение")), imgui.ImVec2(bw, 24)) then
        compareSlots[1]=nil; compareSlots[2]=nil
