    end
    imgui.SameLine()
    if imgui.Button(Fn.T(u8("Закрыть")), imgui.ImVec2(bw, 24)) then
        compareOpen[0] = false
    end
    imgui.PopStyleColor(3)
    imgui.End()
    imgui.PopStyleVar()
end
function historywindow()
    for nick, state in pairs(historyState) do
        if state.ac[0] then
            for i, pl in ipairs(players) do
                if pl.nick == nick then
                    local a, r, g, b = explode_argb(pl.col)
                    local c1, c2, c3, c4 = argb2imvec4(a, r, g, b)
                    imgui.SetNextWindowPos(
                        imgui.ImVec2(imgui.GetIO().DisplaySize.x/2, imgui.GetIO().DisplaySize.y/2),
                        imgui.Cond.FirstUseEver, imgui.ImVec2(0.5, 0.5))
                    local detail_rst = CBUGER_APPLY_WINDOW_SIZE("hitzone_player_" .. tostring(pl.id), 431, 300)
                    imgui.Begin(nick.."["..pl.id.."]", state.ac,
                        imgui.WindowFlags.NoCollapse + imgui.WindowFlags.MenuBar + imgui.WindowFlags.NoResize)
                    CBUGER_DRAW_INVISIBLE_RESIZER("hitzone_player_" .. tostring(pl.id), detail_rst, 340, 240, CBUGER_GET_INTERFACE_ALPHA(), true)
                    do
                        local hdl = imgui.GetWindowDrawList()
                        local hp  = imgui.GetWindowPos()
                        local hs  = imgui.GetWindowSize()
                        CBUGER_DRAW_GLOBAL_AMBIENT(hdl, hp, imgui.ImVec2(hp.x + hs.x, hp.y + hs.y), CBUGER_GET_INTERFACE_ALPHA())
                    end
                    if imgui.BeginMenuBar() then
                        if imgui.BeginMenu(Fn.T(u8("Сортировка"))) then
                            imgui.Checkbox(Fn.T(u8("Показывать убийства")), state.showkills)
                            imgui.Checkbox(Fn.T(u8("Показывать смерти")), state.showdeaths)
                            imgui.EndMenu()
                        end
                        imgui.EndMenuBar()
                    end
                    imgui.Text(Fn.T(u8("Убийца")))
                    imgui.SameLine()
                    imgui.SetCursorPosX((imgui.GetWindowWidth() - imgui.CalcTextSize(u8("Оружие")).x)/2)
                    imgui.Text(Fn.T(u8("Оружие")))
                    imgui.SameLine()
                    imgui.SetCursorPosX(imgui.GetWindowWidth() - imgui.CalcTextSize(u8("Убитый")).x - 22)
                    imgui.Text(Fn.T(u8("Убитый")))
                    imgui.Separator()
                    for _, h in ipairs(pl.history) do
                        local show = (state.showkills[0] and pl.nick == h.killer.nick)
                                  or (state.showdeaths[0] and pl.nick == h.killed.nick)
                        if show then
                            if h.killer.nick ~= nil then
                                imgui.TextColored(imgui.ImVec4(1,1,1,1), h.killer.nick)
                            else imgui.Text("Suicide") end
                            imgui.SameLine()
                            imgui.SetCursorPosX(imgui.GetWindowWidth()/2 - 6)
                            if icons_tex and weapIcons[tonumber(h.weap)] then
                                local w = weapIcons[tonumber(h.weap)]
                                imgui.Image(icons_tex, imgui.ImVec2(20,20),
                                    imgui.ImVec2(w.x1,w.y1), imgui.ImVec2(w.x2,w.y2))
                            end
                            imgui.SameLine()
                            imgui.SetCursorPosX(imgui.GetWindowWidth() - imgui.CalcTextSize(h.killed.nick).x - 22)
                            imgui.TextColored(imgui.ImVec4(1,1,1,1), h.killed.nick)
                            imgui.Separator()
                        end
                    end
                    imgui.End()
                    break
                end
            end
        end
    end
end
function pkill()
    CBUGER_WAIT_RUNTIME_READY()
    while true do
        wait(0)
        if pkillActive then
            if pkillReset then
                pkillYAnim   = hz_cfg.main.pkillcy
                pkillDisolVal = 1
                pkillClock   = os.clock()
                pkillReset   = false
            end
            local drawColor = HZ_U32(
                imgui.ImVec4(pkillStreakColorR, pkillStreakColorG,
                             pkillStreakColorB, pkillDisolVal))
            if hz_cbug_font_hud == nil and pkillFont then
                renderFontDrawText(pkillFont, pkillStreakText, hz_cfg.main.pkillcx, pkillYAnim, drawColor)
            end
            if os.clock() - pkillClock >= pkillTUU[0] then
                pkillYAnim = pkillYAnim - pkillUp[0]
            end
            if pkillDisol[0] > 0 then
                if os.clock() - pkillClock >= pkillTUD[0] and pkillDisolVal > 0 then
                    pkillDisolVal = pkillDisolVal - pkillDisol[0]
                elseif pkillDisolVal <= 0 then
                    pkillReset = true; pkillActive = false
                    pkillStreakText   = "+KILL"
                    pkillStreakColorR  = pkillColor[0]
                    pkillStreakColorG  = pkillColor[1]
                    pkillStreakColorB  = pkillColor[2]
                    pkillStreakColorA  = pkillColor[3]
                end
            elseif os.clock() - pkillClock >= pkillTUD[0] then
                pkillReset = true; pkillActive = false
                pkillStreakText   = "+KILL"
                pkillStreakColorR  = pkillColor[0]
                pkillStreakColorG  = pkillColor[1]
                pkillStreakColorB  = pkillColor[2]
                pkillStreakColorA  = pkillColor[3]
            end
        end
    end
end
function crd()
    while true do
        wait(0)
        sampSetCursorMode(3)
        hz_cfg.main.px, hz_cfg.main.py = getCursorPos()
        if isKeyJustPressed(1) then
            sampSetCursorMode(0)
            hz_mainWindow[0] = true
            hz_saveMainCfg()
            break
        end
    end
end
function crdpkill()
    while true do
        wait(0)
        sampSetCursorMode(3)
        pkillActive = true; pkillReset = true
        hz_cfg.main.pkillcx, hz_cfg.main.pkillcy = getCursorPos()
        if isKeyJustPressed(1) then
            sampSetCursorMode(0)
            hz_mainWindow[0] = true
            ksEditorOpen[0] = true
            hz_saveMainCfg()
            break
        end
    end
end
function buildOwnStateText()
    local lines = {}
    local function add(label, val, vr, vg, vb)
        table.insert(lines, {label..": "..tostring(val), vr, vg, vb})
    end
    if showKills[0]      then add("Kills",         kills,                                      0.30,1.00,0.55) end
    if showKillsPL[0]    then add("K/life",         killsLife.."  max:"..killsLifeMax,          0.50,1.00,0.60) end
    if showDeaths[0]     then add("Deaths",         deaths,                                     1.00,0.35,0.35) end
    if showDmg[0]        then add("Damage",         math.floor(dmgTotal),                       1.00,0.60,0.20) end
    if showDmgPL[0]      then add("Dmg/life",       math.floor(dmgLife),                        1.00,0.55,0.15) end
    if showMaxDmg[0]     then add("Max dmg/life",   math.floor(dmgLifeMax),                     1.00,0.40,0.10) end
    if showKillStreak[0] then add("Max K/life",     killsLifeMax,                               0.40,1.00,0.60) end
    if showShots[0]      then add("Shots",          shots_stat,                                 0.90,0.90,0.50) end
    if showHits[0]       then add("Hits",           hits_stat,                                  0.30,1.00,0.50) end
    if showMisses[0]     then add("Misses",         shots_stat - hits_stat,                     1.00,0.40,0.40) end
    if showAccuracy[0]   then add("Accuracy",       (shots_stat > 0 and ("%.1f"):format(hits_stat/(shots_stat/100)) or "0.0").."%", 0.50,1.00,0.80) end
    return lines
end
