function colorVec4ToArgb(col)
    local r = math.floor(col[0] * 255 + 0.5)
    local g = math.floor(col[1] * 255 + 0.5)
    local b = math.floor(col[2] * 255 + 0.5)
    local a = math.floor(col[3] * 255 + 0.5)
    return join_argb(a, r, g, b)
end
function sampev.onSendBulletSync(data)
    if DMG and DMG.onBullet then
        local dmg_ok, dmg_err = pcall(DMG.onBullet, data)
        if not dmg_ok and not DMG.object_target_error_reported then
            DMG.object_target_error_reported = true
            pcall(function()
                sampAddChatMessage('{FF5555}[CBUGER] Ошибка обработки цели-объекта: ' .. tostring(dmg_err), -1)
            end)
        end
    end
    if SC_onSendBulletSync then pcall(SC_onSendBulletSync, data) end
    if CBUGSPEED_onSendBulletSync then pcall(CBUGSPEED_onSendBulletSync, data) end
    local _, myId = sampGetPlayerIdByCharHandle(playerPed)
    if ptOnSendBulletSync then pcall(ptOnSendBulletSync, data) end
    if HM_onSendBulletSync then pcall(HM_onSendBulletSync, data) end
    if not sampIsPlayerPaused(myId) then
        shots_stat = shots_stat + 1
    end
    if hz_cbug_cfg.settings.active and not hz_cbug_session.blocked then
        if data and data.weaponId == 24 then
            if hz_cbug_run.session_start == 0 then hz_cbug_run.session_start = os.clock() end
            hz_cbug_run.session_shots = hz_cbug_run.session_shots + 1
            if hz_cbug_session.shots == 0 then
                hz_cbug_session.start_time = os.clock()
                hz_cbug_session.active     = true
            end
            hz_cbug_session.shots          = hz_cbug_session.shots + 1
            hz_cbug_session.last_shot_time = os.clock()
            if hz_cbug_session.shots >= hz_cbug_cfg.settings.required_shots then
                local final_ms  = math.floor((os.clock() - hz_cbug_session.start_time) * 1000)
                local key       = tostring(hz_cbug_cfg.settings.required_shots)
                local old_rec   = hz_cbug_cfg.records[key]
                if not old_rec or final_ms < tonumber(old_rec) then
                    hz_cbug_cfg.records[key] = final_ms
                    inicfg.save(hz_cbug_cfg, hz_cbug_cfg_name)
                    if hz_cbug_cfg.settings.notify_record then
                        local diff = old_rec
                            and (" (лучше на ".. (old_rec - final_ms) .." ms)")
                            or  " (первый рекорд!)"
                        sampAddChatMessage("{32CD32}[CBug Pro]{FFFFFF} Рекорд для "..key..
                            " выстрелов: {32CD32}"..final_ms.." ms{FFFFFF}"..diff, -1)
                    end
                end
                hz_cbug_run.session_combos = hz_cbug_run.session_combos + 1
                hz_cbug_run.streak = hz_cbug_run.streak + 1
                if hz_cbug_run.streak > (hz_cbug_cfg.stats.best_streak or 0) then
                    hz_cbug_cfg.stats.best_streak = hz_cbug_run.streak
                end
                hz_cbug_session.active  = false
                hz_cbug_session.shots   = 0
                hz_cbug_session.blocked = true
                lua_thread.create(function()
                    wait(hz_cbug_cfg.settings.reset_delay)
                    hz_cbug_session.blocked = false
                end)
            end
        end
    end
end
function HZ_onSendGiveDamage(targetId, damage, weapon, bodypart)
    local _, myId = sampGetPlayerIdByCharHandle(playerPed)
    if not sampIsPlayerPaused(myId) then
        if weapon > 21 and weapon < 35 or weapon == 38 then
            hits_stat = hits_stat + 1
            if weapon == 24 and hz_cbug_cfg.settings.active then
                hz_cbug_run.session_hits = hz_cbug_run.session_hits + 1
            end
        end
        local hp  = sampGetPlayerHealth(myId)
        local dmg = damage > hp and hp or damage
        dmgTotal = dmgTotal + dmg
        dmgLife  = dmgLife  + dmg
        if dmgLife > dmgLifeMax then dmgLifeMax = dmgLife end
    end
    if zones_enabled then
        local zk = BODYPART_KEY[bodypart]
        if zk then
            zones_cfg.my_zones[zk] = (zones_cfg.my_zones[zk] or 0) + 1
            if sampIsPlayerConnected(targetId) then
                local ok, nick = pcall(sampGetPlayerNickname, targetId)
                if ok and nick and nick ~= "" then
                    ensureZonePlayer(nick)
                    zones_cfg.players[nick].zones[zk] = (zones_cfg.players[nick].zones[zk] or 0) + 1
                end
            end
            saveZonesCfg()
        end
    end
end
function HZ_onSendTakeDamage(issuerId, damage, weapon, bodypart)
    if zones_enabled then
        local zk = BODYPART_KEY[bodypart]
        if zk then
            zones_cfg.recv_zones[zk] = (zones_cfg.recv_zones[zk] or 0) + 1
            if issuerId ~= 65535 and sampIsPlayerConnected(issuerId) then
                local ok, nick = pcall(sampGetPlayerNickname, issuerId)
                if ok and nick and nick ~= "" then
                    ensureZonePlayer(nick)
                    zones_cfg.players[nick].recv_zones[zk] = (zones_cfg.players[nick].recv_zones[zk] or 0) + 1
                end
            end
            saveZonesCfg()
        end
    end
end
function sampev.onPlayerQuit(id)
    for _, pl in ipairs(players) do
