    end
end
function sampev.onPlayerDeath(playerId, killerId, reason)
    if CBUGER_HeadIconsDeathNotification then
        pcall(CBUGER_HeadIconsDeathNotification, killerId, playerId, reason)
    end
end
function sampev.onPlayerDeathNotification(killerId, killedId, weapon)
    local _, myId = sampGetPlayerIdByCharHandle(playerPed)
    if killerId == myId then
        kills      = kills + 1
        killsLife  = killsLife + 1
        if killsLife > killsLifeMax then killsLifeMax = killsLife end
        hz_cbug_cfg.stats.kills = (hz_cbug_cfg.stats.kills or 0) + 1
        checkStreakAnnounce()
    elseif killedId == myId then
        dmgLife  = 0; killsLife = 0; ksLastTriggered = 0
        deaths   = deaths + 1
        hz_cbug_cfg.stats.deaths = (hz_cbug_cfg.stats.deaths or 0) + 1
        hz_cbug_run.streak = 0
    end
    if CBUGER_HeadIconsDeathNotification then
        pcall(CBUGER_HeadIconsDeathNotification, killerId, killedId, weapon)
    end
    if not sampIsPlayerConnected(killerId) and not sampIsPlayerConnected(killedId) then return end
    local knick  = killerId ~= 65535 and sampGetPlayerNickname(killerId) or nil
    local knickd = sampGetPlayerNickname(killedId)
    local kcol   = sampGetPlayerColor(killerId)
    local kcold  = sampGetPlayerColor(killedId)
    local function findOrInsert(nick, id, col, isKill)
        for _, pl in ipairs(players) do
            if pl.nick == nick then
                if pl.id  ~= id  then pl.id  = id  end
                if pl.col ~= col then pl.col = col end
                if isKill then
                    pl.kills  = pl.kills + 1
                    pl.kd     = pl.deaths ~= 0 and pl.kills/pl.deaths or pl.kills
                else
                    pl.deaths = pl.deaths + 1
                    pl.kd     = pl.kills  ~= 0 and pl.kills/pl.deaths or 0
                end
                _playersSorted = false
                return pl
            end
        end
        local np = {
            nick=nick, id=id, col=col,
            kills  = isKill and 1 or 0,
            deaths = isKill and 0 or 1,
            kd     = isKill and 1 or 0,
            history= {}
        }
        table.insert(players, np)
        _playersSorted = false
        return np
    end
    local entry = {
        killer = knick and {nick=knick, col=kcol} or {},
        killed = {nick=knickd, col=kcold},
        weap   = weapon,
    }
    if knick then
        local kpl = findOrInsert(knick, killerId, kcol, true)
        table.insert(kpl.history, entry)
    end
    local dpl = findOrInsert(knickd, killedId, kcold, false)
    table.insert(dpl.history, entry)
end
end
imgui.OnInitialize(function()
    local io_ptr = imgui.GetIO()
    if not (io_ptr and io_ptr.Fonts) then return end
    local dir = (os.getenv('WINDIR') or 'C:\\Windows') .. '\\Fonts\\'
    for _, fn in ipairs({'arial.ttf','tahoma.ttf','verdana.ttf','calibri.ttf'}) do
        local f = io.open(dir..fn,'rb')
        if f then f:close()
            local ok,fnt = pcall(function()
                return io_ptr.Fonts:AddFontFromFileTTF(dir..fn, 14.0, nil, _glyph_ranges)
            end)
            if ok and fnt and fnt ~= nil then font_main = fnt end
            local ok2,fnt2 = pcall(function()
                return io_ptr.Fonts:AddFontFromFileTTF(dir..fn, 28.0, nil, _glyph_ranges)
            end)
            if ok2 and fnt2 and fnt2 ~= nil then font_label = fnt2; break end
        end
    end
    if fa and fa.Init then fa.Init(26.0) end
    pcall(function()
        local fonts = io_ptr.Fonts
        local trebuc_path = getFolderPath(20) .. "\\trebucbd.ttf"
        local f_test = io.open(trebuc_path, "rb")
        if f_test then f_test:close()
            local ok_c, fnt_c = pcall(function()
                return fonts:AddFontFromFileTTF(trebuc_path, 60, nil, fonts:GetGlyphRangesCyrillic())
            end)
            if ok_c and fnt_c and fnt_c ~= nil then
                cbug_font_hud    = fnt_c
                hz_cbug_font_hud = fnt_c
            end
            local ok_cy, fnt_cy = pcall(function()
                return fonts:AddFontFromFileTTF(trebuc_path, 16, nil, fonts:GetGlyphRangesCyrillic())
            end)
            if ok_cy and fnt_cy and fnt_cy ~= nil then cyrilFont = fnt_cy end
        end
    end)
    CB.ui.death.icon[0]  = iconIndex('SKULL')
    CB.ui.kill.icon[0]   = iconIndex('CROSSHAIRS')
    CB.ui.armor.icon[0]  = iconIndex('SHIELD_HALVED')
    self_icon.icon[0] = iconIndex('STAR')
    local fonts_dir = (os.getenv("WINDIR") or "C:\\Windows") .. "\\Fonts\\"
    local font_files = {
        { name = u8"Arial",          file = "arial.ttf"    },
        { name = u8"Arial Bold",     file = "arialbd.ttf"  },
        { name = u8"Tahoma",         file = "tahoma.ttf"   },
        { name = u8"Tahoma Bold",    file = "tahomabd.ttf" },
        { name = u8"Verdana",        file = "verdana.ttf"  },
        { name = u8"Segoe UI",       file = "segoeui.ttf"  },
        { name = u8"Calibri",        file = "calibri.ttf"  },
        { name = u8"Times New Roman",file = "times.ttf"    },
        { name = u8"Consolas",       file = "consola.ttf"  },
    }
    local neon_glyph_ranges = ffi.new("unsigned short[9]",
        0x0020, 0x00FF, 0x0400, 0x04FF, 0x2000, 0x206F, 0x2DE0, 0x2DFF, 0x0000)
    for _, fd in ipairs(font_files) do
        local path = fonts_dir .. fd.file
        local f = io.open(path, "rb")
        if f then f:close()
            local ok, font = pcall(function()
                return io_ptr.Fonts:AddFontFromFileTTF(path, 16.0, nil, neon_glyph_ranges)
            end)
            if ok and font and font ~= nil then
                table.insert(loaded_fonts, font)
                table.insert(loaded_font_names, fd.name)
            end
        end
    end
end)
