function UT.bool(v)
    if type(v) == 'boolean' then return v end
    if type(v) == 'number'  then return v ~= 0 end
    if type(v) == 'string'  then return v == '1' or v:lower() == 'true' end
    return false
end
function UT.int(v, d) return math.floor(tonumber(v) or d or 0) end
function UT.argb(a, r, g, b)
    local A = math.floor(math.max(0, math.min(1, a)) * 255)
    local R = math.floor(math.max(0, math.min(1, r)) * 255)
    local G = math.floor(math.max(0, math.min(1, g)) * 255)
    local B = math.floor(math.max(0, math.min(1, b)) * 255)
    return bit.bor(R, bit.lshift(G, 8), bit.lshift(B, 16), bit.lshift(A, 24))
end
function UT.cf(t)
    return imgui.new.float[4](UT.int(t.r, 255) / 255, UT.int(t.g, 255) / 255,
        UT.int(t.b, 255) / 255, UT.int(t.a, 255) / 255)
end
function UT.fileExists(path)
    local f = io.open(path, 'r')
    if f then f:close(); return true end
    return false
end
function UT.ensureDir(path)
    local ok, mode = pcall(lfs.attributes, path, 'mode')
    if ok and mode == 'directory' then return true end
    cbugerEnsureDir(path)
    local ok2, mode2 = pcall(lfs.attributes, path, 'mode')
    return ok2 and mode2 == 'directory'
end
function UT.isImage(name)
    local lo = name:lower()
    return lo:match('%.png$') or lo:match('%.jpg$') or lo:match('%.jpeg$') or lo:match('%.bmp$') or lo:match('%.webp$')
end
UT.ffi_u = ffi.new('uint32_t[1]')
function UT.f2i(v)
    ffi.cast('float*', UT.ffi_u)[0] = v
    return tonumber(UT.ffi_u[0])
end
GTA.ADDRS = {
    R = {0x58E301, 0x58E3DA, 0x58E433, 0x58E47C},
    G = {0x58E2F6, 0x58E3D1, 0x58E42A, 0x58E473},
    B = {0x58E2F1, 0x58E3C8, 0x58E425, 0x58E466},
    A = {0x58E2EC, 0x58E3BF, 0x58E420, 0x58E461},
}
GTA.ORIG   = {R = 255, G = 200, B = 0, A = 200}
GTA.HUD    = 0x58E020
GTA.MEM_X  = nil
GTA.MEM_Y  = nil
GTA.ORIG_X = 0xBD8360
GTA.ORIG_Y = 0xBD8364
function GTA.ensureMem()
    if GTA.MEM_X and GTA.MEM_Y then return true end
    local ok, mem = pcall(allocateMemory, 16)
    if not ok or type(mem) ~= 'number' or mem == 0 then return false end
    pcall(function()
        writeMemory(mem,     4, readMemory(GTA.ORIG_X, 4, true), true)
        writeMemory(mem + 4, 4, readMemory(GTA.ORIG_Y, 4, true), true)
    end)
    GTA.MEM_X, GTA.MEM_Y = mem, mem + 4
    return true
end
function GTA.chan(name, val)
    for _, addr in ipairs(GTA.ADDRS[name]) do
        pcall(memory.setuint8, addr, val, true)
    end
end
function GTA.patchColor(r, g, b, a)
    GTA.chan('R', math.floor(math.max(0, math.min(1, r)) * 255))
    GTA.chan('G', math.floor(math.max(0, math.min(1, g)) * 255))
    GTA.chan('B', math.floor(math.max(0, math.min(1, b)) * 255))
    GTA.chan('A', math.floor(math.max(0, math.min(1, a)) * 255))
end
function GTA.restoreColor()
    GTA.chan('R', GTA.ORIG.R)
    GTA.chan('G', GTA.ORIG.G)
    GTA.chan('B', GTA.ORIG.B)
    GTA.chan('A', GTA.ORIG.A)
end
function GTA.zeroColor()
    GTA.chan('R', 0)
    GTA.chan('G', 0)
    GTA.chan('B', 0)
    GTA.chan('A', 0)
end
function GTA.setVisible(on)
    pcall(memory.setuint8, GTA.HUD, on and 0x83 or 0xC3, true)
    if not on then GTA.zeroColor() end
end
function GTA.applySizePatch()
    if CV.cr_type[0] ~= 3 then
        pcall(writeMemory, 0x58E2FA + 2, 4, GTA.ORIG_X, true)
        pcall(writeMemory, 0x58E319 + 2, 4, GTA.ORIG_Y, true)
        pcall(writeMemory, 0x609D80, 2, 0x087A, true)
        return
    end
    if not GTA.ensureMem() then
        pcall(writeMemory, 0x58E2FA + 2, 4, GTA.ORIG_X, true)
        pcall(writeMemory, 0x58E319 + 2, 4, GTA.ORIG_Y, true)
        pcall(writeMemory, 0x609D80, 2, 0x087A, true)
        return
    end
    if CV.gta_no_resize[0] then
        pcall(writeMemory, 0x609D80, 2, 0x9090, true)
    else
        pcall(writeMemory, 0x609D80, 2, 0x087A, true)
    end
    local screenX, screenY = 0, 0
    pcall(function()
        screenX = readMemory(0xC17044, 2, true)
        screenY = readMemory(0xC17048, 2, true)
    end)
    local rw, rh = getScreenResolution()
    if screenX == 0 then screenX = rw end
    if screenY == 0 then screenY = rh end
    local szX, szY
    if CV.gta_use_xy[0] then
        szX = math.max(0.01, CV.gta_size_x[0])
        szY = math.max(0.01, CV.gta_size_y[0])
    else
        szX = math.max(0.01, CV.gta_size[0])
        szY = szX
    end
    local ix = (szX / screenX) * rw * 0.0015625
    local iy = (szY / screenY) * rh * 0.0015625
    pcall(writeMemory, GTA.MEM_X, 4, UT.f2i(ix), true)
    pcall(writeMemory, GTA.MEM_Y, 4, UT.f2i(iy), true)
    pcall(writeMemory, 0x58E2FA + 2, 4, GTA.MEM_X, true)
    pcall(writeMemory, 0x58E319 + 2, 4, GTA.MEM_Y, true)
end
function GTA.fullRestore()
    GTA.setVisible(true)
    pcall(writeMemory, 0x58E2FA + 2, 4, GTA.ORIG_X, true)
    pcall(writeMemory, 0x58E319 + 2, 4, GTA.ORIG_Y, true)
    pcall(writeMemory, 0x609D80, 2, 0x087A, true)
    GTA.restoreColor()
end
function GTA.aimScreenPos()
    if not CBUGER_NATIVE_READY then return nil end
    local ped = PLAYER_PED
    local ok_ped, exists = pcall(doesCharExist, ped)
    if not ok_ped or not exists then return nil end
    local wx, wy, wz
    pcall(function()
        local vec_out = ffi.new('float[3]')
        local tmp_vec = ffi.new('float[3]')
        ffi.cast('void (__thiscall*)(void*, float, float, float, float, float*, float*)', 0x514970)(
            ffi.cast('void*', 0xB6F028),
            500.0,
            tmp_vec[0], tmp_vec[1], tmp_vec[2],
            tmp_vec,
            vec_out
        )
        wx, wy, wz = vec_out[0], vec_out[1], vec_out[2]
    end)
    if not wx or not wy or not wz then return nil end
    local function fin(v) return v == v and v ~= math.huge and v ~= -math.huge end
    if not fin(wx) or not fin(wy) or not fin(wz) then return nil end
    local ok, sx, sy = pcall(convert3DCoordsToScreen, wx, wy, wz)
    if not ok or not sx or not sy then return nil end
    if not fin(sx) or not fin(sy) then return nil end
    local rw, rh = getScreenResolution()
    if sx < 0 or sx > rw or sy < 0 or sy > rh then return nil end
    return math.floor(sx), math.floor(sy)
end
function GTA.syncNative()
    if not CV.enabled[0] then
        GTA.fullRestore()
        RT.custom_alpha = 0.0
        return
    end
    local ct = CV.cr_type[0]
    GTA.applySizePatch()
    if ct == 3 then
        GTA.restoreColor()
        GTA.setVisible(true)
    else
        GTA.setVisible(false)
        if ct == 4 then GTA.restoreColor() end
    end
end
FS.base   = CBUGER_ROOT .. 'SmartCrosshair/'
FS.image  = FS.base .. 'crosshair/'
FS.marker = FS.base .. 'marker/'
FS.cfg    = CBUGER_CONFIG
FS.ini    = 'SmartCrosshair.ini'
UT.ensureDir(FS.base)
UT.ensureDir(FS.image)
UT.ensureDir(FS.marker)
function FS.scan(dir)
    local names, files = {}, {}
    local ok, iter, st, init = pcall(function() return lfs.dir(dir) end)
    if not ok then return names, files end
    local step = init
    while true do
        local f
        pcall(function() f = iter(st, step) end)
        if not f then break end
        step = f
        if type(f) == 'string' and UT.isImage(f) then
            local ok2, enc = pcall(function() return u8(f) end)
            if ok2 and enc then
                table.insert(names, enc)
                table.insert(files, f)
            end
        end
    end
    return names, files
end
function TEX.safeCreate(path)
    local ok, tex = pcall(imgui.CreateTextureFromFile, path)
    if ok and tex then return tex end
    return nil
end
function TEX.inCache(tex)
    if not tex then return false end
    for _, t in pairs(CACHE.img) do
        if t == tex then return true end
    end
    return false
end
function TEX.scheduleRelease()
    if not TEX.current then return end
    if TEX.inCache(TEX.current) then
        TEX.current = nil
        TEX.valid = false
    else
        TEX.pending = TEX.current
        TEX.current = nil
        TEX.valid = false
        TEX.pending_delay = 3
    end
end
function TEX.processPending()
    if not TEX.pending then return end
    if TEX.inCache(TEX.pending) then
        TEX.pending = nil
    elseif TEX.pending_delay > 0 then
        TEX.pending_delay = TEX.pending_delay - 1
    else
        pcall(function() imgui.ReleaseTexture(TEX.pending) end)
        TEX.pending = nil
    end
end
function TEX.refresh()
    TEX.names, TEX.files = FS.scan(FS.image)
    table.insert(TEX.names, 1, u8'\xCD\xE5\xF2')
end
function HM.refresh()
    HM.names, HM.files = FS.scan(FS.marker)
    table.insert(HM.names, 1, u8'\xCD\xE5\xF2')
end
function TEX.load(filename)
    TEX.scheduleRelease()
    if not filename or filename == ' ' then return end
    local full = FS.image .. filename
    if not UT.fileExists(full) then return end
    local tex = TEX.safeCreate(full)
    if tex then
        TEX.current = tex
        TEX.valid = true
    else
        TEX.current = nil
        TEX.valid = false
    end
end
function HM.load(filename)
    if HM.current then pcall(function() imgui.ReleaseTexture(HM.current) end) end
    HM.current = nil
    HM.valid = false
    if not filename or filename == ' ' then return end
    local tex = TEX.safeCreate(FS.marker .. filename)
    if tex then
        HM.current = tex
        HM.valid = true
    end
end
function CACHE.get(filename)
    if not filename or filename == ' ' then return nil end
    local cached = CACHE.img[filename]
    if cached ~= nil then
        return cached ~= false and cached or nil
    end
    local full = FS.image .. filename
    if not UT.fileExists(full) then
        CACHE.img[filename] = false
        return nil
    end
    local tex = TEX.safeCreate(full)
    if tex then
        CACHE.img[filename] = tex
        return tex
    end
    CACHE.img[filename] = false
    return nil
end
function CACHE.release()
    for name, tex in pairs(CACHE.img) do
        if tex and tex ~= false then
            pcall(function() imgui.ReleaseTexture(tex) end)
        end
        CACHE.img[name] = nil
    end
end
TEX.refresh()
HM.refresh()
