function FS.store.ser(v, out, depth, seen)
    local t = type(v)
    if t == 'number' then
        if v ~= v or v == math.huge or v == -math.huge then
            out[#out + 1] = '0'
        elseif v == math.floor(v) and math.abs(v) < 1e15 then
            out[#out + 1] = string.format('%d', v)
        else
            out[#out + 1] = string.format('%.9g', v)
        end
    elseif t == 'string' then
        out[#out + 1] = string.format('%q', v)
    elseif t == 'boolean' then
        out[#out + 1] = v and 'true' or 'false'
    elseif t == 'table' and depth < 12 and not seen[v] then
        seen[v] = true
        out[#out + 1] = '{'
        local n = #v
        for i = 1, n do
            FS.store.ser(v[i], out, depth + 1, seen)
            out[#out + 1] = ','
        end
        for k, val in pairs(v) do
            local tv = type(val)
            local skip = (type(k) == 'number' and k >= 1 and k <= n and k == math.floor(k))
            if not skip and (tv == 'number' or tv == 'string' or tv == 'boolean' or tv == 'table') then
                if type(k) == 'number' then
                    out[#out + 1] = '[' .. string.format('%d', k) .. ']='
                else
                    out[#out + 1] = '[' .. string.format('%q', tostring(k)) .. ']='
                end
                FS.store.ser(val, out, depth + 1, seen)
                out[#out + 1] = ','
            end
        end
        out[#out + 1] = '}'
        seen[v] = nil
    else
        out[#out + 1] = 'nil'
    end
end
function FS.store.save(ini)
    local data = {}
    for _, k in ipairs(FS.store.keys) do data[k] = ini[k] end
    if type(ini.image_queue) == 'table' then data.image_queue_by_mode = ini.image_queue.by_mode end
    local out = { 'return ' }
    FS.store.ser(data, out, 0, {})
    local str = table.concat(out)
    if str == FS.store.last then return true end
    local ok = CBUGER_SAFE_WRITE_FILE(FS.store.path, str)
    if ok then FS.store.last = str end
    return ok
end
function FS.store.load()
    for _, candidate in ipairs({FS.store.path, FS.store.path .. '.bak'}) do
        local f = io.open(candidate, 'rb')
        if f then
            local str = f:read('*a'); f:close()
            if str and str ~= '' then
                local fn = (loadstring or load)(str, '=scr_modes')
                if type(fn) == 'function' then
                    if setfenv then pcall(setfenv, fn, {}) end
                    local ok, res = pcall(fn)
                    if ok and type(res) == 'table' then
                        FS.store.last = str
                        if candidate ~= FS.store.path then pcall(CBUGER_SAFE_RESTORE_FILE, FS.store.path, str) end
                        return res
                    end
                end
            end
        end
    end
    return nil
end
function FS.store.saveIni(ini, name)
    local nested_call_ok, nested_saved = pcall(FS.store.save, ini)
    local stash = {}
    for _, k in ipairs(FS.store.keys) do stash[k] = ini[k]; ini[k] = nil end
    local bym
    if type(ini.image_queue) == 'table' then bym = ini.image_queue.by_mode; ini.image_queue.by_mode = nil end
    local ini_call_ok, ini_saved = pcall(inicfg.save, ini, name)
    for _, k in ipairs(FS.store.keys) do ini[k] = stash[k] end
    if type(ini.image_queue) == 'table' then ini.image_queue.by_mode = bym end
    return nested_call_ok and nested_saved == true and ini_call_ok and ini_saved == true
end
