            (tonumber(src.r) or 0) / 255, (tonumber(src.g) or 0) / 255,
            (tonumber(src.b) or 0) / 255, (tonumber(src.a) or 255) / 255)
    end
    return imgui.new.float[4](src and src[0] or 0, src and src[1] or 0, src and src[2] or 0, src and src[3] or 1)
end
function CL.copyColor(dst, src)
    dst[0], dst[1], dst[2], dst[3] = src[0], src[1], src[2], src[3]
end
function CL.colorSnapshot(src, fallback)
    local f = fallback or {1, 1, 1, 1}
    if type(src) == 'table' then
        if src[1] ~= nil then
            return {tonumber(src[1]) or f[1], tonumber(src[2]) or f[2], tonumber(src[3]) or f[3], tonumber(src[4]) or f[4]}
        end
        if src.r ~= nil then
            return {(tonumber(src.r) or 255) / 255, (tonumber(src.g) or 255) / 255, (tonumber(src.b) or 255) / 255, (tonumber(src.a) or 255) / 255}
        end
    end
    return {f[1], f[2], f[3], f[4]}
end
