function CL.cloneSettings(src)
    src = src or {}
    local base = CL.snapshotSettings()
    local function n(k, d)
        local v = src[k]
        if v == nil then return d end
        return tonumber(v) or d
    end
    local function b(k, d)
        local v = src[k]
        if v == nil then return d and 1 or 0 end
        return UT.bool(v) and 1 or 0
    end
    return {
        scale_on = b('scale_on', base.scale_on), scale = n('scale', base.scale),
        recoil_on = b('recoil_on', base.recoil_on), recoil_scale = n('recoil_scale', base.recoil_scale), recoil_spd = n('recoil_spd', base.recoil_spd),
        grad_on = b('grad_on', base.grad_on), grad_spd = n('grad_spd', base.grad_spd),
        pulse_on = b('pulse_on', base.pulse_on), pulse_spd = n('pulse_spd', base.pulse_spd), pulse_min = n('pulse_min', base.pulse_min), pulse_max = n('pulse_max', base.pulse_max),
        cross_gap = n('cross_gap', base.cross_gap), cross_size = n('cross_size', base.cross_size), cross_thick = n('cross_thick', base.cross_thick), cross_t = b('cross_t', base.cross_t),
        circle_r = n('circle_r', base.circle_r), circle_hole = b('circle_hole', base.circle_hole), circle_hole_sz = n('circle_hole_sz', base.circle_hole_sz),
        tri_r = n('tri_r', base.tri_r), tri_rot = n('tri_rot', base.tri_rot), tri_out_rot = n('tri_out_rot', base.tri_out_rot), tri_hole = b('tri_hole', base.tri_hole), tri_hole_sz = n('tri_hole_sz', base.tri_hole_sz),
        outline_on = b('outline_on', base.outline_on), outline_px = n('outline_px', base.outline_px), outline_center = n('outline_center', base.outline_center),
        dot_on = b('dot_on', base.dot_on), dot_sz = n('dot_sz', base.dot_sz),
        color = CL.colorSnapshot(src.color, base.color),
        color2 = CL.colorSnapshot(src.color2, base.color2),
        outline_color = CL.colorSnapshot(src.outline_color, base.outline_color),
        dot_color = CL.colorSnapshot(src.dot_color, base.dot_color),
        ui_accent = CL.colorSnapshot(src.ui_accent, base.ui_accent),
    }
end
function CL.makeClone(ec)
    ec = ec or {}
    local imgsrc = type(ec.image) == 'table' and ec.image or ec
    local stsrc = type(ec.settings) == 'table' and ec.settings or ec
    local rawQ = type(ec.image_queue) == 'table' and ec.image_queue or {}
    local cloneQ = {}
    for _, v in ipairs(rawQ) do
        if type(v) == 'string' then cloneQ[#cloneQ + 1] = v end
    end
    return {
        enabled = imgui.new.bool(UT.bool(ec.enabled)),
        offset_x = imgui.new.int(UT.int(ec.offset_x, 0)),
        offset_y = imgui.new.int(UT.int(ec.offset_y, 0)),
        settings = CL.cloneSettings(stsrc),
        image = CL.cloneImage(imgsrc),
        image_queue = cloneQ,
        image_queue_idx = math.max(1, UT.int(ec.image_queue_idx, 1)),
    }
end
function CL.duplicate(ec)
    local img = ec.image or {}
    local q = {}
    for _, v in ipairs(ec.image_queue or {}) do q[#q + 1] = v end
    return CL.makeClone({
        enabled = ec.enabled[0] and 1 or 0,
        offset_x = ec.offset_x[0] + 10,
        offset_y = ec.offset_y[0] + 10,
        settings = ec.settings,
        image = {
            enabled = img.enabled and (img.enabled[0] and 1 or 0) or 0,
            alpha = img.alpha and img.alpha[0] or 100,
            scale = img.scale and img.scale[0] or 100,
            offset_x = img.offset_x and img.offset_x[0] or 0,
            offset_y = img.offset_y and img.offset_y[0] or 0,
            selected_idx = img.selected_idx or 1,
            image_name = img.image_name or ' ',
        },
        image_queue = q,
        image_queue_idx = ec.image_queue_idx or 1,
    })
end
function CL.loadList(src)
    local out = {}
    if type(src) == 'table' then
        for _, ec in ipairs(src) do
            if type(ec) == 'table' and (ec.enabled ~= nil or ec.offset_x ~= nil or ec.offset_y ~= nil or ec.settings ~= nil or ec.image ~= nil) then
                out[#out + 1] = CL.makeClone(ec)
            end
        end
    end
    if #out == 0 then out[1] = CL.makeClone() end
    return out
end
function CL.serializeList(list)
    local out = {}
    for _, ec in ipairs(list or {}) do
        local st = ec.settings or CL.snapshotSettings()
        local img = ec.image or {}
        out[#out + 1] = {
            enabled = ec.enabled[0] and 1 or 0,
            offset_x = ec.offset_x[0],
            offset_y = ec.offset_y[0],
            settings = st,
            image = {
                enabled = img.enabled and (img.enabled[0] and 1 or 0) or 0,
                alpha = img.alpha and img.alpha[0] or 100,
                scale = img.scale and img.scale[0] or 100,
                offset_x = img.offset_x and img.offset_x[0] or 0,
                offset_y = img.offset_y and img.offset_y[0] or 0,
                selected_idx = img.selected_idx or 1,
                image_name = img.image_name or ' ',
            },
            image_queue = ec.image_queue or {},
            image_queue_idx = ec.image_queue_idx or 1,
        }
    end
    if #out == 0 then
        out[1] = {enabled = 0, offset_x = 0, offset_y = 0, settings = CL.snapshotSettings(), image = {enabled = 0, alpha = 100, scale = 100, offset_x = 0, offset_y = 0, selected_idx = 1, image_name = ' '}}
    end
    return out
end
function CL.makeImguiVars(st)
    st = st or {}
    local function n(k, d)
        local v = st[k]
        return tonumber(v) ~= nil and tonumber(v) or (d or 0)
    end
    local function b(k, d)
        local v = st[k]
        if v == nil then return d and 1 or 0 end
        return UT.bool(v) and 1 or 0
    end
    local function c(k, d)
        local v = st[k]
        if type(v) == 'table' and v[1] ~= nil then
            return imgui.new.float[4](tonumber(v[1]) or d[1], tonumber(v[2]) or d[2], tonumber(v[3]) or d[3], tonumber(v[4]) or d[4])
        end
        return imgui.new.float[4](d[1], d[2], d[3], d[4])
    end
    local dc  = {CV.color[0], CV.color[1], CV.color[2], CV.color[3]}
    local dc2 = {CV.color2[0], CV.color2[1], CV.color2[2], CV.color2[3]}
    local doc = {CV.outline_color[0], CV.outline_color[1], CV.outline_color[2], CV.outline_color[3]}
    local ddc = {CV.dot_color[0], CV.dot_color[1], CV.dot_color[2], CV.dot_color[3]}
    local dua = {CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2], CV.ui_accent[3]}
    return {
        scale_on       = imgui.new.bool(b('scale_on', CV.scale_on[0]) ~= 0),
        scale          = imgui.new.int(n('scale', CV.scale[0])),
        recoil_on      = imgui.new.bool(b('recoil_on', CV.recoil_on[0]) ~= 0),
        recoil_scale   = imgui.new.int(n('recoil_scale', CV.recoil_scale[0])),
        recoil_spd     = imgui.new.int(n('recoil_spd', CV.recoil_spd[0])),
        grad_on        = imgui.new.bool(b('grad_on', CV.grad_on[0]) ~= 0),
        grad_spd       = imgui.new.int(n('grad_spd', CV.grad_spd[0])),
        pulse_on       = imgui.new.bool(b('pulse_on', CV.pulse_on[0]) ~= 0),
        pulse_spd      = imgui.new.int(n('pulse_spd', CV.pulse_spd[0])),
        pulse_min      = imgui.new.int(n('pulse_min', CV.pulse_min[0])),
        pulse_max      = imgui.new.int(n('pulse_max', CV.pulse_max[0])),
        cross_gap      = imgui.new.int(n('cross_gap', CV.cross_gap[0])),
        cross_size     = imgui.new.int(n('cross_size', CV.cross_size[0])),
        cross_thick    = imgui.new.int(n('cross_thick', CV.cross_thick[0])),
        cross_t        = imgui.new.bool(b('cross_t', CV.cross_t[0]) ~= 0),
        circle_r       = imgui.new.int(n('circle_r', CV.circle_r[0])),
        circle_hole    = imgui.new.bool(b('circle_hole', CV.circle_hole[0]) ~= 0),
        circle_hole_sz = imgui.new.int(n('circle_hole_sz', CV.circle_hole_sz[0])),
        tri_r          = imgui.new.int(n('tri_r', CV.tri_r[0])),
        tri_rot        = imgui.new.int(n('tri_rot', CV.tri_rot[0])),
        tri_out_rot    = imgui.new.int(n('tri_out_rot', CV.tri_out_rot[0])),
        tri_hole       = imgui.new.bool(b('tri_hole', CV.tri_hole[0]) ~= 0),
        tri_hole_sz    = imgui.new.int(n('tri_hole_sz', CV.tri_hole_sz[0])),
        outline_on     = imgui.new.bool(b('outline_on', CV.outline_on[0]) ~= 0),
        outline_px     = imgui.new.int(n('outline_px', CV.outline_px[0])),
        outline_center = imgui.new.int(n('outline_center', CV.outline_center[0])),
        dot_on         = imgui.new.bool(b('dot_on', CV.dot_on[0]) ~= 0),
        dot_sz         = imgui.new.int(n('dot_sz', CV.dot_sz[0])),
        color          = c('color', dc),
        color2         = c('color2', dc2),
        outline_color  = c('outline_color', doc),
        dot_color      = c('dot_color', ddc),
        ui_accent      = c('ui_accent', dua),
    }
end
function CL.syncVarsBack(ec, vars)
    if not ec or not vars then return end
    local st = ec.settings or {}
    st.scale_on       = vars.scale_on[0] and 1 or 0
