    st.color2         = {vars.color2[0], vars.color2[1], vars.color2[2], vars.color2[3]}
    st.outline_color  = {vars.outline_color[0], vars.outline_color[1], vars.outline_color[2], vars.outline_color[3]}
    st.dot_color      = {vars.dot_color[0], vars.dot_color[1], vars.dot_color[2], vars.dot_color[3]}
