    ec.settings = st
end
function CL.editContext()
    local midx = MD.currentIdx()
    local selected = MD.selected[midx] or 0
    if selected == 0 then return CV, nil, nil end
    local ec = (MD.clones[midx] or {})[selected]
    if not ec then return CV, nil, nil end
    local key = tostring(ec)
    local vars = CL.cache[key]
    if not vars then
        vars = CL.makeImguiVars(ec.settings or {})
        CL.cache[key] = vars
    end
    return vars, ec, key
end
function CL.flushEdit()
    local midx = MD.currentIdx()
    local selected = MD.selected[midx] or 0
    if selected == 0 then return end
    local ec = (MD.clones[midx] or {})[selected]
    if not ec then return end
    local vars = CL.cache[tostring(ec)]
    if vars then CL.syncVarsBack(ec, vars) end
end
