function MD.setSelectedIdx(mode, idx)
    local _, list, midx = MD.selectedCloneIdx(mode)
    if idx == nil or idx < 0 then idx = 0 end
    if #list == 0 then
        MD.selected[midx] = 0
        return 0
    end
    idx = math.max(0, math.min(#list, idx))
    MD.selected[midx] = idx
    return idx
end
