                if srcp.outline_center ~= nil then MD.palettes[mode].outline_center = UT.int(srcp.outline_center, MD.palettes[mode].outline_center) end
                if srcp.dot_on ~= nil then MD.palettes[mode].dot_on = UT.bool(srcp.dot_on) end
                if srcp.dot_sz ~= nil then MD.palettes[mode].dot_sz = UT.int(srcp.dot_sz, MD.palettes[mode].dot_sz) end
