function Q.activeModeIdx()
    return math.max(1, math.min(SC.MODE_COUNT, CV.cr_type[0] + 1))
end
function Q.active() return MD.queue[Q.activeModeIdx()] end
function Q.pos(name, queue)
    queue = queue or Q.active()
    for i, n in ipairs(queue) do
        if n == name then return i end
    end
    return nil
end
function Q.toggle(name, queue)
    queue = queue or Q.active()
    local p = Q.pos(name, queue)
    if p then
        table.remove(queue, p)
    else
        queue[#queue + 1] = name
    end
    Q.dirty = true
end
function Q.applyStep(queue, idx_ref, cfg)
    if #queue == 0 then return idx_ref end
    local newIdx = (idx_ref % #queue) + 1
    local name = queue[newIdx]
    local foundIdx = nil
    for i = 2, #TEX.names do
        if TEX.files[i - 1] == name then foundIdx = i; break end
    end
    if not foundIdx then return newIdx end
    cfg.selected_idx = foundIdx
    local tn = TEX.names[foundIdx]
    local ok, dec = pcall(function() return u8:decode(tn) end)
    cfg.image_name = (ok and dec) or ' '
    local cached = CACHE.img[cfg.image_name] or CACHE.img[name]
    if cached and cached ~= false then
        TEX.current = cached
        TEX.valid = true
        TEX.selected_idx = foundIdx
    else
        Q.dirty = true
        TEX.selected_idx = foundIdx
    end
    return newIdx
end
function Q.advance()
    local ct = CV.cr_type[0]
    local midx = math.max(1, math.min(SC.MODE_COUNT, ct + 1))
    local queue = MD.queue[midx]
    local qidx = MD.queue_idx[midx] or 1
    if #queue == 0 then qidx = 1
    elseif qidx > #queue then qidx = 1 end
    if #queue > 0 then
        local cfg = MD.imageCfg(ct)
        if cfg and ((ct == 4) or (cfg.enabled and cfg.enabled[0])) then
            qidx = Q.applyStep(queue, qidx, cfg)
        end
    end
    MD.queue_idx[midx] = qidx
    for _, clone in ipairs(MD.clones[midx] or {}) do
        if clone.enabled[0] and clone.image and #(clone.image_queue or {}) > 0 then
            if (ct == 4) or (clone.image.enabled and clone.image.enabled[0]) then
                clone.image_queue_idx = Q.applyStep(clone.image_queue, clone.image_queue_idx, clone.image)
            end
        end
    end
end
function MD.syncImageSelection(mode)
    local cfg = MD.activeImageCfg(mode)
    local idx = 1
    if cfg.image_name and cfg.image_name ~= ' ' then
        for i, tn in ipairs(TEX.names) do
            local ok, dec = pcall(function() return u8:decode(tn) end)
            if ok and dec == cfg.image_name then idx = i; break end
        end
    end
    cfg.selected_idx = idx
    return cfg
end
function MD.loadTexture(mode)
    local cfg = MD.syncImageSelection(mode)
    local idx = cfg.selected_idx or 1
    local fn = TEX.files[idx - 1]
    if idx <= 1 or not fn then
        TEX.scheduleRelease()
        TEX.selected_idx = 1
        TEX.valid = false
        return
    end
    TEX.selected_idx = idx
    local tn = TEX.names[idx]
    local ok, dec = pcall(function() return u8:decode(tn) end)
    cfg.image_name = (ok and dec) or ' '
    TEX.load(fn)
end
function MD.updateImageSelection(mode, idx)
    local cfg = MD.activeImageCfg(mode)
    idx = math.max(1, math.min(#TEX.names, idx or 1))
    cfg.selected_idx = idx
    if idx <= 1 then
        cfg.image_name = ' '
        TEX.selected_idx = 1
        TEX.scheduleRelease()
        return
    end
    local tn = TEX.names[idx]
    local ok, dec = pcall(function() return u8:decode(tn) end)
    cfg.image_name = (ok and dec) or ' '
    TEX.selected_idx = idx
    MD.loadTexture(mode)
    if RT then RT.last_save = -100 end
end
