function AIM.check()
    RT.aim_ped_ptr = nil
    if not CV.ac_on[0] and not CV.dl_on[0] and not CV.hm_enabled[0] then
        RT.aim_on_player = false
        return
    end
    local camMode = 0
    pcall(function() camMode = memory.getint16(0xB6F1A8, false) end)
    if not AIM.cam_modes[camMode] then RT.aim_on_player = false; return end
    local ok1, cx, cy, cz = pcall(getActiveCameraCoordinates)
    if not ok1 then RT.aim_on_player = false; return end
    local ok2, wx, wy = pcall(convertGameScreenCoordsToWindowScreenCoords, 339.1, 179.1)
    if not ok2 then RT.aim_on_player = false; return end
    local ok3, tx, ty, tz = pcall(convertScreenCoordsToWorld3D, wx, wy, 100)
    if not ok3 then RT.aim_on_player = false; return end
    local result, ptr
    local ok4 = pcall(function()
        result, ptr = processLineOfSight(cx, cy, cz, tx, ty, tz, false, false, true, false, false, false, false)
    end)
    if not ok4 or not result or not ptr then RT.aim_on_player = false; return end
    if ptr.entityType ~= 3 then RT.aim_on_player = false; return end
    local ok5, ppPtr = pcall(getCharPointer, PLAYER_PED)
    if ok5 and ptr.entity == ppPtr then RT.aim_on_player = false; return end
    RT.aim_on_player = true
    pcall(function()
        if not RT.aim_ped_ptr then RT.aim_ped_ptr = getCharPointerHandle(ptr.entity) end
    end)
    if CV.hm_enabled[0] and not CV.hm_onhit[0] and RT.aim_ped_ptr then
        if RT.hm_aim.handle ~= RT.aim_ped_ptr then
            RT.hm_aim.handle = RT.aim_ped_ptr
            RT.hm_aim.time = os.clock()
            RT.hm_aim.bodypart = 3
        end
    end
end
function SYS.colorTable(c)
    return {
        r = math.floor(c[0] * 255), g = math.floor(c[1] * 255),
        b = math.floor(c[2] * 255), a = math.floor(c[3] * 255),
    }
end
function SYS.writeColor(t, c)
    t.r = math.floor(c[0] * 255)
    t.g = math.floor(c[1] * 255)
    t.b = math.floor(c[2] * 255)
    t.a = math.floor(c[3] * 255)
end
