function SYS.autoSave()
    if os.clock() - RT.last_save > 5 then
        local saved = SYS.saveIni()
        RT.last_save = os.clock()
        return saved
    end
    return true
end
function SYS.updateLiveColor()
    if not CV.enabled[0] then GTA.restoreColor(); return end
    local ct = CV.cr_type[0]
    if ct == 4 then GTA.restoreColor() end
    local tr, tg, tb, ta
    if CV.grad_on[0] then
        local spd = math.max(1, math.min(150, CV.grad_spd[0])) / 1000.0
        RT.grad_pos = RT.grad_pos + spd
        if RT.grad_pos > 1 then RT.grad_pos = RT.grad_pos - 1 end
        tr = CV.color[0] + (CV.color2[0] - CV.color[0]) * RT.grad_pos
        tg = CV.color[1] + (CV.color2[1] - CV.color[1]) * RT.grad_pos
        tb = CV.color[2] + (CV.color2[2] - CV.color[2]) * RT.grad_pos
        ta = CV.color[3] + (CV.color2[3] - CV.color[3]) * RT.grad_pos
    elseif CV.ac_on[0] and RT.aim_on_player then
        tr, tg, tb, ta = CV.enemy_color[0], CV.enemy_color[1], CV.enemy_color[2], CV.enemy_color[3]
    else
        tr, tg, tb, ta = CV.color[0], CV.color[1], CV.color[2], CV.color[3]
    end
    if CV.ac_smooth[0] and not CV.grad_on[0] then
        local sp = math.max(1, math.min(20, CV.ac_spd[0])) / 100.0
        RT.live_r = RT.live_r + (tr - RT.live_r) * sp
        RT.live_g = RT.live_g + (tg - RT.live_g) * sp
        RT.live_b = RT.live_b + (tb - RT.live_b) * sp
        RT.live_a = RT.live_a + (ta - RT.live_a) * sp
    else
        RT.live_r, RT.live_g, RT.live_b, RT.live_a = tr, tg, tb, ta
    end
    if ct ~= 4 then GTA.patchColor(RT.live_r, RT.live_g, RT.live_b, RT.live_a) end
end
function SYS.updatePulsation()
    if CV.cr_type[0] == 3 or not CV.pulse_on[0] then
        RT.pulse_scale = 1.0
        return
    end
    RT.pulse_scale = 0.5 + 0.5 * math.sin(os.clock() * (math.max(5, CV.pulse_spd[0]) / 100.0))
end
function SYS.resetAllPos()
    local gx, gy = GTA.aimScreenPos()
    if gx and gy then
        for m = 1, SC.MODE_COUNT do
            local mp = MD.pos[m]
            if mp then mp.x[0] = gx; mp.y[0] = gy end
        end
    end
end
RD.NO_AMMO = {[0] = true, [1] = true, [2] = true, [3] = true, [4] = true,
              [5] = true, [6] = true, [7] = true, [8] = true, [9] = true}
function RD.ammoInfo()
    local wid = 0
    pcall(function() wid = getCurrentCharWeapon(PLAYER_PED) end)
    if RD.NO_AMMO[wid] then return 0, 0, wid end
    local total = 0
    pcall(function() total = getAmmoInCharWeapon(PLAYER_PED, wid) end)
    local clip = 0
    pcall(function()
        local ptr = getCharPointer(PLAYER_PED)
        if ptr and ptr ~= 0 then
            local slot = getWeapontypeSlot(wid)
            clip = memory.getuint32(ptr + 0x5A0 + slot * 0x1C + 0x8)
        end
    end)
    return clip, total, wid
end
function RD.updateAmmo()
    RT.ammo_clip, RT.ammo_total, RT.ammo_wid = RD.ammoInfo()
    RT.ammo_reserve = math.max(0, (RT.ammo_total or 0) - (RT.ammo_clip or 0))
end
function RD.renderAmmo()
    if not CV.ammo_on[0] then return end
    if RD.NO_AMMO[RT.ammo_wid] or RT.ammo_wid == 0 or (RT.ammo_total or 0) <= 0 then return end
    local dl = imgui.GetBackgroundDrawList()
    local font = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
    local txt = ('%d / %d'):format(math.max(0, RT.ammo_clip or 0), math.max(0, RT.ammo_reserve or 0))
    local ts = font:CalcTextSizeA(CV.ammo_font_sz[0], 1000, 0, txt)
    local tx = CV.ammo_pos_x[0] - ts.x * 0.5
    local ty = CV.ammo_pos_y[0] - ts.y * 0.5
    local col = UT.argb(CV.ammo_color[3], CV.ammo_color[0], CV.ammo_color[1], CV.ammo_color[2])
    local shad = UT.argb(math.max(0, CV.ammo_color[3] * 0.65), 0, 0, 0)
    dl:AddTextFontPtr(font, CV.ammo_font_sz[0], imgui.ImVec2(tx + 1, ty + 1), shad, txt)
    dl:AddTextFontPtr(font, CV.ammo_font_sz[0], imgui.ImVec2(tx, ty), col, txt)
end
function RD.rotPt(cx, cy, x, y, deg)
    local r = math.rad(deg)
    local sin, cos = math.sin(r), math.cos(r)
    x, y = x - cx, y - cy
    return imgui.ImVec2(x * cos - y * sin + cx, x * sin + y * cos + cy)
end
function RD.val(state, key, fallback)
    local v = state and state[key]
    if v == nil then return fallback end
    return tonumber(v) or fallback
end
function RD.flag(state, key, fallback)
    local v = state and state[key]
    if v == nil then return fallback end
    return UT.bool(v)
end
function RD.derivedSizes(state)
    local rm = RT.recoil
    local scale = CV.scale_on[0] and math.max(1, CV.scale[0]) / 100.0 or 1.0
    if RD.flag(state, 'pulse_on', CV.pulse_on[0]) and CV.cr_type[0] ~= 3 then
        local mn = math.max(10, RD.val(state, 'pulse_min', CV.pulse_min[0])) / 100.0
        local mx = math.max(50, RD.val(state, 'pulse_max', CV.pulse_max[0])) / 100.0
        scale = scale * (mn + (mx - mn) * RT.pulse_scale)
    end
    local sf = scale * rm
    local function s(v, mn) return math.max(mn or 1, math.floor(v * sf)) end
    local ch = 0
    if RD.flag(state, 'circle_hole', CV.circle_hole[0]) then
        ch = math.min(math.max(0, math.floor(RD.val(state, 'circle_hole_sz', CV.circle_hole_sz[0]) * scale)),
            math.max(0, RD.val(state, 'circle_r', CV.circle_r[0]) - 1))
    end
    local th = 0
    if RD.flag(state, 'tri_hole', CV.tri_hole[0]) then
        th = math.min(math.max(0, math.floor(RD.val(state, 'tri_hole_sz', CV.tri_hole_sz[0]) * scale)),
            math.max(0, RD.val(state, 'tri_r', CV.tri_r[0]) - 1))
    end
    local oth = RD.flag(state, 'outline_on', CV.outline_on[0]) and s(RD.val(state, 'outline_px', CV.outline_px[0])) or 0
    return {
        cross = {size = s(RD.val(state, 'cross_size', CV.cross_size[0])), thick = s(RD.val(state, 'cross_thick', CV.cross_thick[0])), oth = oth, oc = s(RD.val(state, 'outline_center', CV.outline_center[0]))},
        circle = {r = s(RD.val(state, 'circle_r', CV.circle_r[0])), hole = ch, oth = oth, oc = s(RD.val(state, 'outline_center', CV.outline_center[0]))},
        tri = {r = s(RD.val(state, 'tri_r', CV.tri_r[0])), hole = th, oth = oth, oc = s(RD.val(state, 'outline_center', CV.outline_center[0]))},
        dot = {sz = RD.flag(state, 'dot_on', CV.dot_on[0]) and s(RD.val(state, 'dot_sz', CV.dot_sz[0]), 0) or 0},
    }
end
function RD.drawAt(dl, px, py, state, overrideCfg, anim)
    local ct = CV.cr_type[0]
    local function n(k, f) return RD.val(state, k, f) end
    local function b(k, f) return RD.flag(state, k, f) end
    local c1 = (state and state.color) or {RT.live_r, RT.live_g, RT.live_b, RT.live_a}
    local ocl = (state and state.outline_color) or {CV.outline_color[0], CV.outline_color[1], CV.outline_color[2], CV.outline_color[3]}
    local dcl = (state and state.dot_color) or {CV.dot_color[0], CV.dot_color[1], CV.dot_color[2], CV.dot_color[3]}
    local grad_on = b('grad_on', CV.grad_on[0])
    local pulse_on = b('pulse_on', CV.pulse_on[0])
    local recoil_on = b('recoil_on', CV.recoil_on[0])
    local cross_gap = n('cross_gap', CV.cross_gap[0])
    local cross_t = b('cross_t', CV.cross_t[0])
    local circle_hole = b('circle_hole', CV.circle_hole[0])
    local tri_hole = b('tri_hole', CV.tri_hole[0])
    local tri_rot = n('tri_rot', CV.tri_rot[0])
    local tri_out_rot = n('tri_out_rot', CV.tri_out_rot[0])
    local imgcfg = overrideCfg or MD.imageCfg(ct)
    local aMul = anim.alpha
    local col = UT.argb((c1[4] or RT.live_a) * aMul, c1[1], c1[2], c1[3])
    local ocol = UT.argb((ocl[4] or 1) * aMul, ocl[1], ocl[2], ocl[3])
    local dcol = grad_on and col or UT.argb((dcl[4] or 1) * aMul, dcl[1], dcl[2], dcl[3])
    local dsh
    if grad_on then
        dsh = UT.argb(math.max(0, (c1[4] or RT.live_a) * aMul - 0.25), math.max(0, c1[1] - 0.25), math.max(0, c1[2] - 0.25), math.max(0, c1[3] - 0.25))
    else
        dsh = UT.argb(math.max(0, (dcl[4] or 1) * aMul - 0.25), math.max(0, dcl[1] - 0.25), math.max(0, dcl[2] - 0.25), math.max(0, dcl[3] - 0.25))
    end
    local rawTex = CACHE.get(imgcfg and imgcfg.image_name or nil)
    local safeCurrent = (TEX.current and not TEX.pending) and TEX.current or nil
    local img_tex = (rawTex and rawTex ~= false and rawTex) or (overrideCfg == nil and safeCurrent or nil)
    local use_tex = (imgcfg.enabled and imgcfg.enabled[0]) and img_tex ~= nil
    local tex_alpha = math.max(0, math.min(1, ((imgcfg.alpha and imgcfg.alpha[0] or 100) / 100) * aMul))
    local tex_col = UT.argb(tex_alpha, c1[1], c1[2], c1[3])
    local img_base = math.max(0.01, (imgcfg.scale and imgcfg.scale[0] or 100) / 100.0)
    local img_mul = 1.0
    if CV.scale_on[0] then img_mul = img_mul * math.max(1, CV.scale[0]) / 100.0 end
    if pulse_on and ct ~= 3 then
        local mn = math.max(10, n('pulse_min', CV.pulse_min[0])) / 100.0
        local mx = math.max(50, n('pulse_max', CV.pulse_max[0])) / 100.0
        img_mul = img_mul * (mn + (mx - mn) * RT.pulse_scale)
    end
    if recoil_on then img_mul = img_mul * math.max(0.02, RT.recoil) end
    local img_size_px = math.max(1, math.floor((imgcfg.scale and imgcfg.scale[0] or 100) * img_mul))
    local iox = imgcfg.offset_x and imgcfg.offset_x[0] or 0
    local ioy = imgcfg.offset_y and imgcfg.offset_y[0] or 0
    local sz = RD.derivedSizes(state)
    px = px + anim.ox
    py = py + anim.oy
    local function rp(x, y)
        if anim.rot == 0 then return imgui.ImVec2(x, y) end
        return RD.rotPt(px, py, x, y, anim.rot)
    end
    local function fRect(x, y, w, h, c)
        if anim.rot == 0 then
            dl:AddRectFilled(imgui.ImVec2(x, y), imgui.ImVec2(x + w, y + h), c)
        else
            dl:AddQuadFilled(rp(x, y), rp(x + w, y), rp(x + w, y + h), rp(x, y + h), c)
        end
    end
    local function tRect(x, y, w, h, u0, v0, usc)
        if anim.rot == 0 then
            pcall(function()
                dl:AddImage(img_tex, imgui.ImVec2(x, y), imgui.ImVec2(x + w, y + h), imgui.ImVec2(u0, v0), imgui.ImVec2(u0 + usc, v0 + usc), tex_col)
            end)
        else
            pcall(function()
                dl:AddImageQuad(img_tex, rp(x, y), rp(x + w, y), rp(x + w, y + h), rp(x, y + h),
                    imgui.ImVec2(u0, v0), imgui.ImVec2(u0 + usc, v0), imgui.ImVec2(u0 + usc, v0 + usc), imgui.ImVec2(u0, v0 + usc), tex_col)
            end)
        end
    end
    if ct == 3 then
        return
    elseif ct == 4 then
        if imgcfg and imgcfg.enabled and imgcfg.enabled[0] and img_tex then
            local half = img_size_px * 0.5 * anim.scale
            local usc = 1 / img_base
            local u0 = 0.5 - usc * 0.5 - ((imgcfg.offset_x and imgcfg.offset_x[0] or 0) * 0.01 / img_base)
            local v0 = 0.5 - usc * 0.5 - ((imgcfg.offset_y and imgcfg.offset_y[0] or 0) * 0.01 / img_base)
            local live_tex_col = UT.argb(tex_alpha, RT.live_r, RT.live_g, RT.live_b)
            if anim.rot == 0 then
                pcall(function()
                    dl:AddImage(img_tex, imgui.ImVec2(px - half, py - half), imgui.ImVec2(px + half, py + half), imgui.ImVec2(u0, v0), imgui.ImVec2(u0 + usc, v0 + usc), live_tex_col)
                end)
            else
                local q1 = rp(px - half, py - half)
                local q2 = rp(px + half, py - half)
                local q3 = rp(px + half, py + half)
                local q4 = rp(px - half, py + half)
                pcall(function()
                    dl:AddImageQuad(img_tex, q1, q2, q3, q4,
                        imgui.ImVec2(u0, v0), imgui.ImVec2(u0 + usc, v0),
                        imgui.ImVec2(u0 + usc, v0 + usc), imgui.ImVec2(u0, v0 + usc), live_tex_col)
                end)
            end
        end
        return
    end
    if ct == 0 then
        local s2 = sz.cross
        local thr = s2.thick * anim.scale
        local gap = cross_gap * anim.scale
        local arm = s2.size * anim.scale
        local oth = s2.oth * anim.scale
        local half = thr / 2
        if oth > 0 then
            local function oR(x, y, w, h) fRect(x - oth, y - oth, w + oth * 2, h + oth * 2, ocol) end
            if not cross_t then oR(px - half, py - gap - arm, thr, arm) end
            oR(px - half, py + gap, thr, arm)
            oR(px - gap - arm, py - half, arm, thr)
            oR(px + gap, py - half, arm, thr)
        end
        if not cross_t then fRect(px - half, py - gap - arm, thr, arm, col) end
        fRect(px - half, py + gap, thr, arm, col)
        fRect(px - gap - arm, py - half, arm, thr, col)
        fRect(px + gap, py - half, arm, thr, col)
        if use_tex then
            local usc = 1 / img_base
            local du = (iox * 0.01) / img_base
            local dv = (ioy * 0.01) / img_base
            local u0 = 0.5 - usc * 0.5 - du
            local v0 = 0.5 - usc * 0.5 - dv
            if not cross_t then tRect(px - half, py - gap - arm, thr, arm, u0, v0, usc) end
            tRect(px - half, py + gap, thr, arm, u0, v0, usc)
            tRect(px - gap - arm, py - half, arm, thr, u0, v0, usc)
            tRect(px + gap, py - half, arm, thr, u0, v0, usc)
        end
    elseif ct == 1 then
        local s2 = sz.circle
        local r = s2.r * anim.scale
        local oth = s2.oth * anim.scale
        local oc = s2.oc * anim.scale
        if oth > 0 then dl:AddCircle(imgui.ImVec2(px, py), oc, ocol, 64, oth) end
        if circle_hole and s2.hole > 0 then
            local hole = s2.hole * anim.scale
            local rw2 = r - hole
            local rr = hole + rw2 * 0.5
            dl:AddCircle(imgui.ImVec2(px, py), rr, col, 64, rw2)
        else
            dl:AddCircleFilled(imgui.ImVec2(px, py), r, col, 64)
        end
        if use_tex then
            local usc = 1 / img_base
            local u0 = 0.5 - usc * 0.5 - (iox * 0.01 / img_base)
            local v0 = 0.5 - usc * 0.5 - (ioy * 0.01 / img_base)
            pcall(function()
                dl:AddImageRounded(img_tex, imgui.ImVec2(px - r, py - r), imgui.ImVec2(px + r, py + r), imgui.ImVec2(u0, v0), imgui.ImVec2(u0 + usc, v0 + usc), tex_col, r, 15)
            end)
        end
    elseif ct == 2 then
        local s2 = sz.tri
        local r = s2.r * anim.scale
        local rot = tri_rot + anim.rot
        local oth = s2.oth * anim.scale
        local p1 = RD.rotPt(px, py, px, py - r, rot)
        local p2 = RD.rotPt(px, py, px + r * 0.866, py + r * 0.5, rot)
        local p3 = RD.rotPt(px, py, px - r * 0.866, py + r * 0.5, rot)
        if oth > 0 then
            local or_ = s2.oc * anim.scale
            local orot = tri_out_rot + anim.rot
            local op1 = RD.rotPt(px, py, px, py - or_, orot)
            local op2 = RD.rotPt(px, py, px + or_ * 0.866, py + or_ * 0.5, orot)
            local op3 = RD.rotPt(px, py, px - or_ * 0.866, py + or_ * 0.5, orot)
            dl:AddTriangle(op1, op2, op3, ocol, oth)
        end
        if tri_hole and s2.hole > 0 then
            local cx = (p1.x + p2.x + p3.x) / 3
            local cy = (p1.y + p2.y + p3.y) / 3
            local hole = math.min(s2.hole, r * 0.95)
            local function getInner(p)
                local dx, dy = p.x - cx, p.y - cy
                local len = math.sqrt(dx * dx + dy * dy)
                local k = hole / math.max(0.1, len)
                return imgui.ImVec2(cx + dx * k, cy + dy * k)
            end
            local ip1, ip2, ip3 = getInner(p1), getInner(p2), getInner(p3)
            dl:AddQuadFilled(p1, p2, ip2, ip1, col)
            dl:AddQuadFilled(p2, p3, ip3, ip2, col)
            dl:AddQuadFilled(p3, p1, ip1, ip3, col)
            if use_tex then
                local usc = 1 / img_base
                local u0 = 0.5 - usc * 0.5 - (iox * 0.01 / img_base)
                local v0 = 0.5 - usc * 0.5 - (ioy * 0.01 / img_base)
                local function getUV(p)
                    return imgui.ImVec2(u0 + usc * 0.5 + (p.x - px) / (r * 2) * usc, v0 + usc * 0.5 + (p.y - py) / (r * 2) * usc)
                end
                local u1, u2, u3 = getUV(p1), getUV(p2), getUV(p3)
                local ui1, ui2, ui3 = getUV(ip1), getUV(ip2), getUV(ip3)
                pcall(function() dl:AddImageQuad(img_tex, p1, p2, ip2, ip1, u1, u2, ui2, ui1, tex_col) end)
                pcall(function() dl:AddImageQuad(img_tex, p2, p3, ip3, ip2, u2, u3, ui3, ui2, tex_col) end)
                pcall(function() dl:AddImageQuad(img_tex, p3, p1, ip1, ip3, u3, u1, ui1, ui3, tex_col) end)
            end
        else
            dl:AddTriangleFilled(p1, p2, p3, col)
            if use_tex then
                local usc = 1 / img_base
                local u0 = 0.5 - usc * 0.5 - (iox * 0.01 / img_base)
                local v0 = 0.5 - usc * 0.5 - (ioy * 0.01 / img_base)
                local function getUV(p)
                    return imgui.ImVec2(u0 + usc * 0.5 + (p.x - px) / (r * 2) * usc, v0 + usc * 0.5 + (p.y - py) / (r * 2) * usc)
                end
                local uv1, uv2, uv3 = getUV(p1), getUV(p2), getUV(p3)
                pcall(function() dl:AddImageQuad(img_tex, p1, p2, p3, p3, uv1, uv2, uv3, uv3, tex_col) end)
            end
        end
    end
    if sz.dot.sz > 0 then
        dl:AddCircleFilled(imgui.ImVec2(px, py), sz.dot.sz + 1, dsh, 16)
        dl:AddCircleFilled(imgui.ImVec2(px, py), sz.dot.sz, dcol, 16)
    end
end
function RD.renderCrosshair(aMul)
    aMul = type(aMul) == 'number' and aMul or RT.custom_alpha
    if aMul <= 0.001 then return end
    TEX.processPending()
    local ct = CV.cr_type[0]
    if ct == 3 then return end
    local dl = imgui.GetBackgroundDrawList()
    local mp = MD.currentPos()
    local posX, posY = mp.x[0], mp.y[0]
    local anim = {scale = 1.0, rot = 0.0, ox = 0.0, oy = 0.0, alpha = aMul}
    do
        local ma = MD.anim[math.max(1, math.min(SC.MODE_COUNT, ct + 1))]
        if ma and ma.on[0] then
            local t = os.clock()
            local spd = math.max(1, ma.speed[0]) / 10.0
            local st = ma.style[0]
            if st == 1 then
                anim.scale = 0.82 + 0.38 * (0.5 + 0.5 * math.sin(t * 10 * spd))
            elseif st == 2 then
                anim.rot = (t * 360 * spd) % 360
            elseif st == 3 then
                anim.scale = 0.7 + 0.3 * (0.5 + 0.5 * math.sin(t * 5 * spd))
            elseif st == 4 then
                local shake = math.sin(t * 50 * spd) * 3
                anim.ox, anim.oy = shake, shake
            elseif st == 5 then
                anim.alpha = aMul * ((math.sin(t * 20 * spd) > 0.5) and 1.0 or 0.0)
            end
        end
    end
    if anim.alpha <= 0.001 then return end
    RD.drawAt(dl, posX, posY, nil, MD.imageCfg(ct), anim)
    for _, ec in ipairs(MD.currentClones()) do
        if ec.enabled[0] then
            RD.drawAt(dl, posX + ec.offset_x[0], posY + ec.offset_y[0], ec.settings, ec.image, anim)
        end
    end
end
function UI.pushColor(idx, r, g, b, a)
    if idx == nil then return end
    if pcall(imgui.PushStyleColor, idx, imgui.ImVec4(r, g, b, a)) then UI.pc = UI.pc + 1 end
end
function UI.pushVar(idx, v)
    if idx == nil then return end
    local ok
    if type(v) == 'number' then ok = pcall(imgui.PushStyleVarFloat, idx, v)
    else ok = pcall(imgui.PushStyleVarVec2, idx, v) end
    if ok then UI.pv = UI.pv + 1 end
end
function UI.popTheme()
    for i = 1, UI.pv do pcall(imgui.PopStyleVar) end
    for i = 1, UI.pc do pcall(imgui.PopStyleColor) end
    UI.pc, UI.pv = 0, 0
end
SC_syncGlobalTheme = function()
    local bc = type(fx_cfg) == 'table' and fx_cfg.global_base_color
    if type(bc) == 'table' then
        local r = tonumber(bc[1]) or CV.ui_accent[0]
        local g = tonumber(bc[2]) or CV.ui_accent[1]
        local b = tonumber(bc[3]) or CV.ui_accent[2]
        local a = tonumber(bc[4]) or 1.0
        CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2], CV.ui_accent[3] = r, g, b, a
    end
end
function UI.pushTheme()
    UI.pc, UI.pv = 0, 0
    SC_syncGlobalTheme()
    local ar, ag, ab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
    UI.pushColor(imgui.Col.WindowBg, ar * 0.1 + 0.03, ag * 0.1 + 0.03, ab * 0.1 + 0.04, 0.99)
    UI.pushColor(imgui.Col.ChildBg, ar * 0.05 + 0.04, ag * 0.05 + 0.04, ab * 0.05 + 0.05, 0.80)
    UI.pushColor(imgui.Col.PopupBg, ar * 0.08 + 0.02, ag * 0.08 + 0.02, ab * 0.1 + 0.03, 0.98)
    UI.pushColor(imgui.Col.Border, ar, ag, ab, 0.6)
    UI.pushColor(imgui.Col.BorderShadow, 0, 0, 0, 0)
    UI.pushColor(imgui.Col.TitleBg, ar * 0.1 + 0.02, ag * 0.1 + 0.02, ab * 0.1 + 0.03, 1.00)
    UI.pushColor(imgui.Col.TitleBgActive, ar * 0.2 + 0.03, ag * 0.2 + 0.03, ab * 0.2 + 0.04, 1.00)
    UI.pushColor(imgui.Col.Button, ar * 0.3, ag * 0.3, ab * 0.3, 0.8)
    UI.pushColor(imgui.Col.ButtonHovered, ar * 0.55, ag * 0.55, ab * 0.55, 0.9)
    UI.pushColor(imgui.Col.ButtonActive, ar * 0.8, ag * 0.8, ab * 0.8, 1.0)
    UI.pushColor(imgui.Col.FrameBg, ar * 0.15, ag * 0.15, ab * 0.15, 0.8)
    UI.pushColor(imgui.Col.FrameBgHovered, ar * 0.35, ag * 0.35, ab * 0.35, 0.9)
    UI.pushColor(imgui.Col.FrameBgActive, ar * 0.6, ag * 0.6, ab * 0.6, 1.0)
    UI.pushColor(imgui.Col.CheckMark, ar, ag, ab, 1.00)
    UI.pushColor(imgui.Col.SliderGrab, ar * 0.7, ag * 0.7, ab * 0.7, 1.00)
    UI.pushColor(imgui.Col.SliderGrabActive, ar, ag, ab, 1.00)
    UI.pushColor(imgui.Col.Text, 0.92, 0.93, 0.95, 1.00)
    UI.pushColor(imgui.Col.TextDisabled, ar * 0.5 + 0.15, ag * 0.5 + 0.15, ab * 0.5 + 0.17, 1.00)
    UI.pushColor(imgui.Col.Header, ar * 0.25, ag * 0.25, ab * 0.25, 0.8)
    UI.pushColor(imgui.Col.HeaderHovered, ar * 0.45, ag * 0.45, ab * 0.45, 0.9)
    UI.pushColor(imgui.Col.HeaderActive, ar * 0.7, ag * 0.7, ab * 0.7, 1.0)
    UI.pushColor(imgui.Col.Separator, ar * 0.5, ag * 0.5, ab * 0.5, 0.4)
    UI.pushColor(imgui.Col.SeparatorHovered, ar * 0.7, ag * 0.7, ab * 0.7, 0.7)
    UI.pushColor(imgui.Col.SeparatorActive, ar, ag, ab, 1.0)
    UI.pushColor(imgui.Col.ResizeGrip, 0, 0, 0, 0)
    UI.pushColor(imgui.Col.ResizeGripHovered, 0, 0, 0, 0)
    UI.pushColor(imgui.Col.ResizeGripActive, 0, 0, 0, 0)
    if imgui.Col.Tab then
        UI.pushColor(imgui.Col.Tab, ar * 0.2, ag * 0.2, ab * 0.2, 0.9)
        UI.pushColor(imgui.Col.TabHovered, ar * 0.5, ag * 0.5, ab * 0.5, 1.0)
        UI.pushColor(imgui.Col.TabActive, ar * 0.35, ag * 0.35, ab * 0.35, 1.0)
    end
    if imgui.Col.ScrollbarGrab then
        UI.pushColor(imgui.Col.ScrollbarGrab, ar * 0.5, ag * 0.5, ab * 0.5, 0.7)
        UI.pushColor(imgui.Col.ScrollbarGrabHovered, ar * 0.7, ag * 0.7, ab * 0.7, 0.9)
        UI.pushColor(imgui.Col.ScrollbarGrabActive, ar, ag, ab, 1.0)
    end
    UI.pushVar(imgui.StyleVar.WindowRounding, 8.0)
    UI.pushVar(imgui.StyleVar.ChildRounding, 6.0)
    UI.pushVar(imgui.StyleVar.FrameRounding, 5.0)
    UI.pushVar(imgui.StyleVar.PopupRounding, 10.0)
    UI.pushVar(imgui.StyleVar.GrabRounding, 4.0)
    UI.pushVar(imgui.StyleVar.ScrollbarRounding, 4.0)
    UI.pushVar(imgui.StyleVar.WindowPadding, imgui.ImVec2(13, 10))
    UI.pushVar(imgui.StyleVar.FramePadding, imgui.ImVec2(8, 5))
    UI.pushVar(imgui.StyleVar.ItemSpacing, imgui.ImVec2(8, 7))
end
function UI.hdr(txt)
    txt = Fn.T(txt)
    imgui.Spacing()
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local ar, ag, ab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
    dl:AddRectFilled(imgui.ImVec2(p.x, p.y + 2), imgui.ImVec2(p.x + 3, p.y + 14),
        SC_UI_U32(imgui.ImVec4(ar, ag, ab, 0.90)), 2)
    imgui.SetCursorPosX(imgui.GetCursorPosX() + 8)
    imgui.TextColored(imgui.ImVec4(ar * 0.55 + 0.50, ag * 0.55 + 0.50, ab * 0.60 + 0.50, 1.0), txt)
    local p2 = imgui.GetCursorScreenPos()
    local w = imgui.GetContentRegionAvail().x
    dl:AddLine(imgui.ImVec2(p2.x, p2.y), imgui.ImVec2(p2.x + w, p2.y),
        SC_UI_U32(imgui.ImVec4(ar * 0.12 + 0.12, ag * 0.12 + 0.12, ab * 0.14 + 0.14, 0.70)), 1)
    imgui.Spacing()
end
function UI.CP(label, colVar, pid)
    label = Fn.T(label)
    local changed = imgui.ColorEdit4('##ce ' .. pid, colVar,
        imgui.ColorEditFlags.NoInputs + imgui.ColorEditFlags.AlphaBar + imgui.ColorEditFlags.AlphaPreview)
    if imgui.IsItemEdited() then
        MD.savePalette(CV.cr_type[0])
        RT.live_r, RT.live_g, RT.live_b, RT.live_a = CV.color[0], CV.color[1], CV.color[2], CV.color[3]
    end
    imgui.SameLine(0, 7)
    imgui.Text(label)
    return changed
end
function UI.SI(label, v, vmin, vmax)
    label = Fn.T(label)
    local ch = imgui.SliderInt('##si ' .. tostring(v), v, vmin, vmax, '     ')
    local hov = imgui.IsItemHovered()
    local act = imgui.IsItemActive()
    local dl = imgui.GetWindowDrawList()
    local rm = imgui.GetItemRectMin()
    local rx = imgui.GetItemRectMax()
    local fnt = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
    local fsz = imgui.GetFontSize()
    local ar, ag, ab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
    local txt = (hov or act) and tostring(v[0]) or label
    local col = (hov or act) and SC_UI_U32(imgui.ImVec4(ar * 0.5 + 0.6, ag * 0.5 + 0.6, ab * 0.5 + 0.6, 1))
        or SC_UI_U32(imgui.ImVec4(0.88, 0.89, 0.92, 1))
    local ts = fnt:CalcTextSizeA(fsz, 1000, 0, txt)
    dl:AddTextFontPtr(fnt, fsz, imgui.ImVec2(rm.x + (rx.x - rm.x) * 0.5 - ts.x * 0.5, rm.y + (rx.y - rm.y) * 0.5 - ts.y * 0.5), col, txt)
    return ch
end
function UI.SF(label, v, vmin, vmax, fmt)
    label = Fn.T(label)
    fmt = fmt or '%.2f'
    local ch = imgui.SliderFloat('##sf ' .. tostring(v), v, vmin, vmax, '     ')
    local hov = imgui.IsItemHovered()
    local act = imgui.IsItemActive()
    local dl = imgui.GetWindowDrawList()
    local rm = imgui.GetItemRectMin()
    local rx = imgui.GetItemRectMax()
    local fnt = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
    local fsz = imgui.GetFontSize()
    local ar, ag, ab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
    local txt = (hov or act) and fmt:format(v[0]) or label
    local col = (hov or act) and SC_UI_U32(imgui.ImVec4(ar * 0.5 + 0.6, ag * 0.5 + 0.6, ab * 0.5 + 0.6, 1))
        or SC_UI_U32(imgui.ImVec4(0.88, 0.89, 0.92, 1))
    local ts = fnt:CalcTextSizeA(fsz, 1000, 0, txt)
    dl:AddTextFontPtr(fnt, fsz, imgui.ImVec2(rm.x + (rx.x - rm.x) * 0.5 - ts.x * 0.5, rm.y + (rx.y - rm.y) * 0.5 - ts.y * 0.5), col, txt)
    return ch
end
function UI.centeredBtnLabel(lbl)
    lbl = Fn.T(lbl)
    local vis = lbl:match('^(.-)##') or lbl
    if vis == '' then return end
    local dl = imgui.GetWindowDrawList()
    local rm = imgui.GetItemRectMin()
    local rx = imgui.GetItemRectMax()
    local fnt = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
    local fsz = imgui.GetFontSize()
    local ts = fnt:CalcTextSizeA(fsz, 1000, 0, vis)
    local col = SC_UI_U32(imgui.ImVec4(0.88, 0.89, 0.92, 1))
    dl:AddTextFontPtr(fnt, fsz, imgui.ImVec2(rm.x + (rx.x - rm.x) * 0.5 - ts.x * 0.5, rm.y + (rx.y - rm.y) * 0.5 - ts.y * 0.5), col, vis)
end
function UI.accentBtn(lbl, w, h)
    local ar, ag, ab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
    imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(ar * 0.18 + 0.05, ag * 0.18 + 0.05, ab * 0.18 + 0.06, 0.92))
    imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(ar * 0.35 + 0.08, ag * 0.35 + 0.08, ab * 0.38 + 0.10, 1.00))
    imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(ar * 0.55 + 0.06, ag * 0.55 + 0.06, ab * 0.58 + 0.08, 1.00))
    local r = imgui.Button('##btn_' .. lbl, imgui.ImVec2(w or 0, h or 0))
    imgui.PopStyleColor(3)
    UI.centeredBtnLabel(lbl)
    return r
end
function UI.dangerBtn(lbl, w, h)
    imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.08, 0.08, 0.92))
    imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.30, 0.11, 0.11, 1.00))
    imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(0.42, 0.10, 0.10, 1.00))
    local r = imgui.Button('##btn_' .. lbl, imgui.ImVec2(w or 0, h or 0))
    imgui.PopStyleColor(3)
    UI.centeredBtnLabel(lbl)
    return r
end
function UI.scrollModeBtn(label, id, w, h, is_active)
    label = Fn.T(label)
    local ar, ag, ab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
    if is_active then
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(ar * 0.55, ag * 0.55, ab * 0.55, 0.95))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(ar * 0.75, ag * 0.75, ab * 0.75, 1.00))
    else
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(ar * 0.22, ag * 0.22, ab * 0.22, 0.90))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(ar * 0.38, ag * 0.38, ab * 0.38, 0.96))
    end
    imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0, 0, 0, 0))
    local clicked = imgui.Button('##smb' .. id, imgui.ImVec2(w, h))
    imgui.PopStyleColor(3)
    pcall(function()
        local rm = imgui.GetItemRectMin()
        local rx = imgui.GetItemRectMax()
        local dl = imgui.GetWindowDrawList()
        local fnt = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
        if not fnt then return end
        local fsz = imgui.GetFontSize()
        local ts = fnt:CalcTextSizeA(fsz, 1000, 0, label)
        local bw = rx.x - rm.x
        local ty = rm.y + math.floor((rx.y - rm.y - fsz) * 0.5)
        local gap = 10
        local step = ts.x + gap
        local speed = 30.0
        local scroll_dur = step / speed
        local pause_dur = 5.0
        local cycle = scroll_dur + pause_dur
        local id_n = tonumber(tostring(id)) or 0
        local phase_sec = cycle * ((id_n - 2) / 3.0)
        local t_in_cycle = (os.clock() + phase_sec) % cycle
        local tx_paused = rm.x + math.max(0, math.floor((bw - ts.x) * 0.5))
        local scroll = 0
        if t_in_cycle >= pause_dur then
            scroll = ((t_in_cycle - pause_dur) / scroll_dur) * step
        end
        local tx_base = tx_paused - scroll
        local tcol = SC_UI_U32(imgui.ImVec4(1, 1, 1, 1))
        dl:PushClipRect(rm, rx, true)
        local copies = math.ceil(bw / step) + 2
        for k = 0, copies do
            dl:AddTextFontPtr(fnt, fsz, imgui.ImVec2(tx_base + k * step, ty), tcol, label)
        end
        dl:PopClipRect()
    end)
    return clicked
end
function UI.imageQueueSection(uid)
    local s = tostring(uid or 0)
    local midx = math.max(1, math.min(SC.MODE_COUNT, (uid or 0) + 1))
    local queue = MD.queue[midx]
    if #queue > 0 then
        imgui.Spacing()
        if AC.enabled then
            local now_ms = tonumber(ffi.C.GetTickCount()) or AC.last_ms
            local rem = math.max(0, AC.speed_ms - (now_ms - AC.last_ms))
            imgui.TextColored(imgui.ImVec4(0.3, 1.0, 0.45, 1.0),
                Fn.T(u8'\xD1\xEB\xE5\xE4\xF3\xFE\xF9\xE5\xE5 \xF7\xE5\xF0\xE5\xE7: ') .. ('%.1f s'):format(rem / 1000.0))
        end
        imgui.Spacing()
        if UI.accentBtn(u8'\xD1\xEB\xE5\xE4\xF3\xFE\xF9\xE5\xE5##iqnext' .. s, -1, 22) then
            Q.advance()
            AC.last_ms = tonumber(ffi.C.GetTickCount()) or 0
        end
        if UI.dangerBtn(u8'\xCE\xF7\xE8\xF1\xF2\xE8\xF2\xFC \xEE\xF7\xE5\xF0\xE5\xE4\xFC##iqclear' .. s, -1, 22) then
            MD.queue[midx] = {}
            MD.queue_idx[midx] = 1
            Q.dirty = true
        end
    end
    imgui.Spacing()
end
function UI.modeAnimControls(ct)
