            u8'\xD1\xE6\xE0\xF2\xE8\xE5',
            u8'\xC4\xF0\xEE\xE6\xE0\xED\xE8\xE5',
            u8'\xCC\xE5\xF0\xF6\xE0\xED\xE8\xE5',
        }
