            if active then
                local aar,aag,aab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
                imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(aar*0.8, aag*0.8, aab*0.8, 0.95))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(math.min(1,aar*0.95+0.05), math.min(1,aag*0.95+0.05), math.min(1,aab*0.95+0.05), 1.00))
                imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(aar, aag, aab, 1.00))
                imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.95, 0.95, 0.97, 1.00))
            else
                local aar,aag,aab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
                imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(aar*0.3, aag*0.3, aab*0.3, 0.95))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(aar*0.55, aag*0.55, aab*0.55, 1.00))
                imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(aar*0.65, aag*0.65, aab*0.65, 1.00))
                imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.80, 0.80, 0.82, 1.00))
            end
            if imgui.Button(name .. '##mast ' .. tostring(i), imgui.ImVec2(bw, 26)) then
                ma.style[0] = i - 1
            end
            imgui.PopStyleColor(4)
        end
    end
end
function UI.modeImageControls(mode)
    local cfg = MD.activeImageCfg(mode)
    local midx = math.max(1, math.min(SC.MODE_COUNT, (mode or 0) + 1))
    local clone, clone_idx = nil, nil
    if midx == 5 then clone, clone_idx = MD.selectedClone(mode) end
    local label = Fn.T(u8'\xC8\xF1\xEF\xEE\xEB\xFC\xE7\xEE\xE2\xE0\xF2\xFC \xEA\xE0\xF0\xF2\xE8\xED\xEA\xF3')
    if clone and clone_idx then
        label = label .. Fn.T(u8' (\xCA\xEB\xEE\xED %d)'):format(clone_idx)
    end
    local changed = imgui.Checkbox(label .. '##modeimg' .. tostring(mode), cfg.enabled)
    if changed and cfg.enabled[0] then
        MD.loadTexture(mode)
    elseif changed and not cfg.enabled[0] then
        TEX.scheduleRelease()
    end
    imgui.SameLine(0, 12)
    if imgui.Checkbox(Fn.T(u8'\xD1\xEB\xE0\xE9\xE4\xF8\xEE\xF3##acimg') .. tostring(mode), AC.on_img) then
        AC.enabled = AC.on_img[0]
        AC.last_ms = tonumber(ffi.C.GetTickCount()) or 0
    end
    if AC.on_img[0] then
        imgui.SameLine(0, 8)
        imgui.SetNextItemWidth(100)
        if UI.SI(u8'\xC8\xED\xF2\xE5\xF0\xE2\xE0\xEB (ms)', AC.ms_img, 100, 30000) then
            AC.speed_ms = AC.ms_img[0]
        end
    end
    if cfg.enabled[0] then
        imgui.Spacing()
        UI.SI(u8'\xCF\xF0\xEE\xE7\xF0\xE0\xF7\xED\xEE\xF1\xF2\xFC %', cfg.alpha, 0, 100)
        UI.SI(u8'\xCC\xE0\xF1\xF8\xF2\xE0\xE1 %', cfg.scale, 10, 300)
        UI.SI(u8'\xD1\xEC\xE5\xF9\xE5\xED\xE8\xE5 X', cfg.offset_x, -100, 100)
        UI.SI(u8'\xD1\xEC\xE5\xF9\xE5\xED\xE8\xE5 Y', cfg.offset_y, -100, 100)
        local tex = CACHE.get(cfg.image_name) or TEX.current
        if tex then
            imgui.Spacing()
            pcall(function() imgui.Image(tex, imgui.ImVec2(56, 56)) end)
        end
        imgui.Spacing()
        if UI.accentBtn(u8'\xCE\xE1\xED\xEE\xE2\xE8\xF2\xFC \xF1\xEF\xE8\xF1\xEE\xEA', 150, 22) then
            TEX.refresh()
            MD.syncImageSelection(mode)
            MD.loadTexture(mode)
        end
        imgui.Spacing()
        imgui.BeginChild('##il' .. tostring(mode), imgui.ImVec2(0, 110), true)
        local modeQueue = MD.queue[midx]
        for i, tn in ipairs(TEX.names) do
            imgui.PushIDInt(1000 + midx * 100 + i)
            local sel = (cfg.selected_idx == i)
            local itemName = (i > 1) and TEX.files[i - 1] or nil
            local qpos = itemName and Q.pos(itemName, modeQueue) or nil
            if sel then
                local har,hag,hab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
                imgui.PushStyleColor(imgui.Col.Header, imgui.ImVec4(har*0.24+0.10, hag*0.24+0.10, hab*0.27+0.12, 0.65))
                imgui.PushStyleColor(imgui.Col.HeaderHovered, imgui.ImVec4(har*0.32+0.12, hag*0.32+0.12, hab*0.36+0.14, 0.85))
            end
            local lbl = qpos and ('[' .. qpos .. '] ' .. tn) or tn
            if CBUGER_MarqueeSelectable(lbl, "scimg" .. tostring(midx) .. "_" .. tostring(i), sel, 18) then
                MD.updateImageSelection(mode, i)
            end
            if imgui.IsItemClicked(1) and itemName then
                Q.toggle(itemName, modeQueue)
            end
            if sel then imgui.PopStyleColor(2) end
            imgui.PopID()
        end
        imgui.EndChild()
        CBUGER_ImageFolderHint('SmartCrosshair\\crosshair')
    end
end
function UI.cloneEditor(mode)
    local midx = math.max(1, math.min(SC.MODE_COUNT, (mode or 0) + 1))
    local list = MD.clones[midx] or MD.clones[1]
    local modePos = MD.pos[midx] or MD.pos[1]
    local selected = MD.selected[midx] or 0
    UI.hdr(u8'\xCA\xEB\xEE\xED\xFB')
    imgui.TextDisabled(Fn.T(u8'\xC1\xE0\xE7\xE0 ') .. (' X:%d Y:%d'):format(modePos.x[0], modePos.y[0]))
    if UI.accentBtn(u8'\xCF\xE5\xF0\xE5\xF2\xE0\xF9\xE8\xF2\xFC \xE2\xF1\xE5', -1, 24) then
        RT.window[0] = false
        RT.drag_mode_pos = true
        RT.drag_mode_mode = mode
    end
    if UI.dangerBtn(u8'\xD1\xE1\xF0\xEE\xF1\xE8\xF2\xFC \xEF\xEE\xE7\xE8\xF6\xE8\xFE', -1, 24) then
        SYS.resetAllPos()
    end
    if UI.accentBtn(u8'\xC4\xEE\xE1\xE0\xE2\xE8\xF2\xFC \xEA\xEB\xEE\xED', -1, 24) then
        list[#list + 1] = CL.makeClone({enabled = 0, offset_x = 0, offset_y = 0})
        selected = #list
        MD.selected[midx] = selected
    end
    imgui.BeginChild('##clones' .. tostring(mode), imgui.ImVec2(0, 150), true)
    imgui.PushIDInt(5000 + midx * 100)
    local base_sel = (selected == 0)
    if base_sel then
        local car,cag,cab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
        imgui.PushStyleColor(imgui.Col.Header, imgui.ImVec4(car*0.24+0.10, cag*0.24+0.10, cab*0.27+0.12, 0.75))
        imgui.PushStyleColor(imgui.Col.HeaderHovered, imgui.ImVec4(car*0.32+0.12, cag*0.32+0.12, cab*0.36+0.14, 0.90))
    end
    if imgui.Selectable(Fn.T(u8'\xCA\xEB\xEE\xED 1'), base_sel, 0, imgui.ImVec2(0, 18)) then
        CL.flushEdit()
        selected = MD.setSelectedIdx(mode, 0)
        MD.loadTexture(mode)
    end
    if base_sel then imgui.PopStyleColor(2) end
    imgui.Checkbox(Fn.T(u8'\xC2\xEA\xEB\xFE\xF7\xE8\xF2\xFC##base_en'), CV.enabled)
    imgui.SameLine(0, 6)
    if UI.accentBtn(u8'\xCF\xE5\xF0\xE5\xF2\xE0\xF9\xE8\xF2\xFC##base', 96, 0) then
        RT.window[0] = false
        RT.drag_mode_pos = true
        RT.drag_mode_mode = mode
    end
    imgui.SameLine(0, 4)
    if UI.dangerBtn(u8'\xD1\xE1\xF0\xEE\xF1##base_rst', 52, 0) then
        SYS.resetAllPos()
    end
    imgui.SameLine(0, 4)
    if UI.accentBtn(u8'\xC4\xF3\xE1\xEB\xE8\xF0\xEE\xE2\xE0\xF2\xFC##base_dup', 96, 0) then
        table.insert(list, 1, CL.makeClone({enabled = 1, offset_x = 0, offset_y = 0}))
        Q.dirty = true
        MD.selected[midx] = 1
        selected = 1
        imgui.PopID()
        imgui.EndChild()
        return
    end
    imgui.Separator()
    imgui.PopID()
    for i = 1, #list do
        local ec = list[i]
        local is_selected = (selected == i)
        imgui.PushIDInt(5000 + midx * 100 + i)
        if is_selected then
            local car2,cag2,cab2 = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
            imgui.PushStyleColor(imgui.Col.Header, imgui.ImVec4(car2*0.24+0.10, cag2*0.24+0.10, cab2*0.27+0.12, 0.75))
            imgui.PushStyleColor(imgui.Col.HeaderHovered, imgui.ImVec4(car2*0.32+0.12, cag2*0.32+0.12, cab2*0.36+0.14, 0.90))
        end
        if imgui.Selectable(Fn.T(u8'\xCA\xEB\xEE\xED ') .. tostring(i + 1), is_selected, 0, imgui.ImVec2(0, 18)) then
            CL.flushEdit()
            selected = MD.setSelectedIdx(mode, i)
            if midx == 5 then MD.loadTexture(mode) end
        end
        if is_selected then imgui.PopStyleColor(2) end
        imgui.Checkbox(Fn.T(u8'\xC2\xEA\xEB\xFE\xF7\xE8\xF2\xFC##clone') .. tostring(i), ec.enabled)
        imgui.SameLine(0, 6)
        if UI.dangerBtn(u8'\xD3\xE4\xE0\xEB\xE8\xF2\xFC##del' .. tostring(i), 76, 0) then
            table.remove(list, i)
            if selected > #list then selected = #list end
            MD.selected[midx] = math.max(0, selected)
            imgui.PopID()
            break
        end
        imgui.SameLine(0, 4)
        if UI.accentBtn(u8'\xC4\xF3\xE1\xEB\xE8\xF0\xEE\xE2\xE0\xF2\xFC##dup' .. tostring(i), 96, 0) then
            local copy = CL.duplicate(ec)
            table.insert(list, i + 1, copy)
            Q.dirty = true
            selected = i + 1
            MD.selected[midx] = selected
            imgui.PopID()
            break
        end
        if UI.accentBtn(u8'\xCF\xE5\xF0\xE5\xF2\xE0\xF9\xE8\xF2\xFC##drag' .. tostring(i), 96, 0) then
            RT.window[0] = false
            RT.drag_clone = true
            RT.drag_clone_idx = i
            RT.drag_clone_mode = mode or 0
            MD.selected[midx] = i
            if midx == 5 then MD.loadTexture(mode) end
        end
        imgui.SameLine(0, 4)
        if UI.dangerBtn(u8'\xD1\xE1\xF0\xEE\xF1##crst' .. tostring(i), 52, 0) then
            local gx, gy = GTA.aimScreenPos()
            if gx and gy then
                local bp = MD.pos[midx] or MD.pos[1]
                ec.offset_x[0] = math.floor(gx - bp.x[0])
                ec.offset_y[0] = math.floor(gy - bp.y[0])
            end
        end
        imgui.SameLine(0, 8)
        imgui.TextDisabled(('X:%d  Y:%d'):format(ec.offset_x[0], ec.offset_y[0]))
        imgui.Spacing()
        if midx == 5 then
            local img = ec.image or {}
            imgui.TextDisabled(('Img: %s'):format(tostring(img.image_name or ' ')))
        end
        if i < #list then imgui.Separator() end
        imgui.PopID()
    end
    imgui.EndChild()
end
function UI.tab1()
    local EC = CL.editContext()
    local outline_on = EC.outline_on[0] ~= 0
    local dot_on = EC.dot_on[0] ~= 0
    local grad_on = EC.grad_on[0]
    do
        local midx = MD.currentIdx()
        local sel = MD.selected[midx] or 0
        if sel > 0 then
            imgui.TextColored(imgui.ImVec4(1.0, 0.85, 0.2, 1.0),
                Fn.T(u8'\xD0\xE5\xE4\xE0\xEA\xF2\xE8\xF0\xF3\xE5\xF2\xF1\xFF: \xCA\xEB\xEE\xED ') .. tostring(sel))
            imgui.Spacing()
        end
    end
    UI.hdr(u8'\xC2\xE8\xE4 \xEF\xF0\xE8\xF6\xE5\xEB\xE0')
    local names = {u8'\xCA\xF0\xE5\xF1\xF2', u8'\xCA\xF0\xF3\xE3', u8'\xD2\xF0\xE5\xF3\xE3\xEE\xEB\xFC\xED\xE8\xEA', u8'\xD1\xF2\xE0\xED\xE4\xE0\xF0\xF2\xED\xFB\xE9', u8'\xC8\xE7\xEE\xE1\xF0\xE0\xE6\xE5\xED\xE8\xE5'}
    local avail = imgui.GetContentRegionAvail().x
    local bw = math.floor((avail - 16) / 5)
    local scroll_modes = {[2] = true, [3] = true, [4] = true}
    for i, name in ipairs(names) do
        name = Fn.T(name)
        local idx = i - 1
        local active = CV.cr_type[0] == idx
        if i > 1 then imgui.SameLine(0, 4) end
        local clicked
        if scroll_modes[idx] then
            clicked = UI.scrollModeBtn(name, tostring(idx), bw, 28, active)
        else
            if active then
                local tar,tag,tb = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
                imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(tar*0.8, tag*0.8, tb*0.8, 0.95))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(math.min(1,tar*0.95+0.05), math.min(1,tag*0.95+0.05), math.min(1,tb*0.95+0.05), 1.00))
                imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(tar, tag, tb, 1.00))
            else
                local tar,tag,tb = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
                imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(tar*0.3, tag*0.3, tb*0.3, 0.90))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(tar*0.55, tag*0.55, tb*0.55, 0.96))
                imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(tar*0.65, tag*0.65, tb*0.65, 1.00))
            end
            clicked = imgui.Button(name, imgui.ImVec2(bw, 28))
            imgui.PopStyleColor(3)
        end
        if clicked then
            MD.savePalette(CV.cr_type[0])
            MD.saveEffects(MD.currentIdx())
            CV.cr_type[0] = idx
            AC.enabled = false
            AC.on_img[0] = false
            MD.loadPalette(idx)
            MD.loadEffects(math.max(1, math.min(SC.MODE_COUNT, idx + 1)))
            SC.pendingTexLoad = idx
            GTA.syncNative()
        end
    end
    imgui.Spacing()
    local ct = CV.cr_type[0]
    local function ui_crosshairType0()
        UI.hdr(u8'\xCA\xF0\xE5\xF1\xF2')
        UI.SI(u8'\xD0\xE0\xE7\xEC\xE5\xF0', EC.cross_size, 1, 240)
        UI.SI(u8'\xD2\xEE\xEB\xF9\xE8\xED\xE0', EC.cross_thick, 1, 80)
