    local function ui_crosshairType4()
        local imgcfg4 = MD.activeImageCfg(ct)
        local changed4 = imgui.Checkbox(Fn.T(u8'\xC8\xF1\xEF\xEE\xEB\xFC\xE7\xEE\xE2\xE0\xF2\xFC \xEA\xE0\xF0\xF2\xE8\xED\xEA\xF3##modeimg4'), imgcfg4.enabled)
        if changed4 and imgcfg4.enabled[0] then
            MD.loadTexture(ct)
        elseif changed4 and not imgcfg4.enabled[0] then
            TEX.scheduleRelease()
        end
        imgui.SameLine(0, 12)
        if imgui.Checkbox(Fn.T(u8'\xD1\xEB\xE0\xE9\xE4\xF8\xEE\xF3##acimg4'), AC.on_img) then
            AC.enabled = AC.on_img[0]
            AC.last_ms = tonumber(ffi.C.GetTickCount()) or 0
        end
        if AC.on_img[0] then
            imgui.SameLine(0, 8)
            imgui.SetNextItemWidth(100)
            if UI.SI(u8'\xC8\xED\xF2\xE5\xF0\xE2\xE0\xEB (ms)', AC.ms_img, 100, 30000) then
                AC.speed_ms = AC.ms_img[0]
            end
        end
        if imgcfg4.enabled[0] then
            imgui.Spacing()
            UI.SI(u8'\xCF\xF0\xEE\xE7\xF0\xE0\xF7\xED\xEE\xF1\xF2\xFC %', imgcfg4.alpha, 0, 100)
            UI.SI(u8'\xCC\xE0\xF1\xF8\xF2\xE0\xE1 %', imgcfg4.scale, 10, 300)
            UI.SI(u8'\xD1\xEC\xE5\xF9\xE5\xED\xE8\xE5 X', imgcfg4.offset_x, -100, 100)
            UI.SI(u8'\xD1\xEC\xE5\xF9\xE5\xED\xE8\xE5 Y', imgcfg4.offset_y, -100, 100)
            local tex4 = CACHE.get(imgcfg4.image_name) or TEX.current
            if tex4 then
                imgui.Spacing()
                pcall(function() imgui.Image(tex4, imgui.ImVec2(48, 48)) end)
            end
            imgui.Spacing()
            if UI.accentBtn(u8'\xCE\xE1\xED\xEE\xE2\xE8\xF2\xFC \xF1\xEF\xE8\xF1\xEE\xEA', 150, 22) then
                TEX.refresh()
                MD.syncImageSelection(ct)
                MD.loadTexture(ct)
            end
            imgui.BeginChild('##il4b', imgui.ImVec2(0, 90), true)
            local activeClone4 = MD.selectedClone(ct)
            local midx4 = math.max(1, math.min(SC.MODE_COUNT, ct + 1))
            local activeQueue4 = (activeClone4 and activeClone4.image_queue) or MD.queue[midx4]
            for i, tn in ipairs(TEX.names) do
                imgui.PushIDInt(1000 + 5 * 100 + i)
                local sel4 = (imgcfg4.selected_idx == i)
                local itemName4 = (i > 1) and TEX.files[i - 1] or nil
                local qpos4 = itemName4 and Q.pos(itemName4, activeQueue4) or nil
                if sel4 then
                    local h2ar,h2ag,h2ab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
                    imgui.PushStyleColor(imgui.Col.Header, imgui.ImVec4(h2ar*0.24+0.10, h2ag*0.24+0.10, h2ab*0.27+0.12, 0.65))
                    imgui.PushStyleColor(imgui.Col.HeaderHovered, imgui.ImVec4(h2ar*0.32+0.12, h2ag*0.32+0.12, h2ab*0.36+0.14, 0.85))
                end
                local label4 = qpos4 and ('[' .. qpos4 .. '] ' .. tn) or tn
                if CBUGER_MarqueeSelectable(label4, "scimg4_" .. tostring(i), sel4, 18) then
                    MD.updateImageSelection(ct, i)
                end
                if imgui.IsItemClicked(1) and itemName4 then
                    Q.toggle(itemName4, activeQueue4)
                end
                if sel4 then imgui.PopStyleColor(2) end
                imgui.PopID()
            end
            imgui.EndChild()
            CBUGER_ImageFolderHint('SmartCrosshair\\crosshair')
            UI.hdr(u8'\xD6\xE2\xE5\xF2\xE0')
            UI.CP(u8'\xCE\xF1\xED\xEE\xE2\xED\xEE\xE9', EC.color, 'm4')
            imgui.SameLine(0, 10)
            UI.CP(u8'\xC2\xF2\xEE\xF0\xEE\xE9', EC.color2, 's4')
            UI.hdr(u8'\xDD\xF4\xF4\xE5\xEA\xF2\xFB')
            imgui.Checkbox(Fn.T(u8'\xCF\xE5\xF0\xE5\xEB\xE8\xE2\xE0\xED\xE8\xE5'), EC.grad_on)
            imgui.SameLine(0, 12)
            if EC.grad_on[0] then
                imgui.Spacing()
                UI.SI(u8'\xD1\xEA\xEE\xF0. \xEF\xE5\xF0\xE5\xEB\xE8\xE2\xE0\xED\xE8\xFF', EC.grad_spd, 1, 150)
            end
            UI.imageQueueSection(ct)
            UI.modeAnimControls(ct)
            UI.cloneEditor(ct)
        end
    end
    if ct == 0 then
        ui_crosshairType0()
    elseif ct == 1 then
        ui_crosshairType1()
    elseif ct == 2 then
        ui_crosshairType2()
    elseif ct == 3 then
        ui_crosshairType3()
    elseif ct == 4 then
        ui_crosshairType4()
    end
end
