function UI.tabDmg()
    UI.hdr(u8'\xD3\xF0\xEE\xED \xEF\xEE \xEF\xF0\xEE\xF2\xE8\xE2\xED\xE8\xEA\xF3')
    imgui.Checkbox(Fn.T(u8'\xC2\xEA\xEB\xFE\xF7\xE8\xF2\xFC##dmg'), CV.dmg_on)
    if CV.dmg_on[0] then
        imgui.Spacing()
        imgui.TextDisabled(Fn.T(u8'\xD1\xF2\xE8\xEB\xFC'))
        local styles = {u8'\xD7\xE8\xF1\xEB\xEE', u8'\xD1\xF2\xE0\xF2\xF3\xF1', u8'\xC4\xE5\xF2\xE0\xEB\xFC\xED\xFB\xE9'}
        for i, label in ipairs(styles) do
            if i > 1 then imgui.SameLine(0, 6) end
            local active = (CV.dmg_style[0] == i - 1)
            if active then
                local dar,dag,dab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
                imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(dar*0.8, dag*0.8, dab*0.8, 0.95))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(math.min(1,dar*0.95+0.05), math.min(1,dag*0.95+0.05), math.min(1,dab*0.95+0.05), 1))
                imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(dar, dag, dab, 1))
                imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.95, 0.95, 0.97, 1))
            else
