function UI.build()
    if SC.pendingTexLoad ~= nil then
        local m = SC.pendingTexLoad
        SC.pendingTexLoad = nil
        MD.loadTexture(m)
    end
    local sw, sh = getScreenResolution()
    imgui.SetNextWindowPos(imgui.ImVec2(sw / 2 - 320, sh / 2 - 260), imgui.Cond.FirstUseEver)
    imgui.SetNextWindowSize(imgui.ImVec2(620, 470), imgui.Cond.FirstUseEver)
    UI.pushTheme()
    imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, CBUGER_GET_INTERFACE_ALPHA())
    local gt_rst = CBUGER_APPLY_WINDOW_SIZE("gametweaker_main", 620, 470)
    local rt_open_ptr = RT.window[0] and RT.window or nil
    local open = imgui.Begin(u8'by Pryanix', rt_open_ptr, imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoResize)
    if open then CBUGER_DRAW_INVISIBLE_RESIZER("gametweaker_main", gt_rst, 480, 360, CBUGER_GET_INTERFACE_ALPHA(), true) end
    if open then
        local ar, ag, ab = CV.ui_accent[0], CV.ui_accent[1], CV.ui_accent[2]
        local navW = 155
        imgui.BeginChild('##nav', imgui.ImVec2(navW, 0), true)
        imgui.SetWindowFontScale(0.78)
