        imgui.SetCursorPosX(math.floor((navW - titleW) * 0.5))
        imgui.TextColored(imgui.ImVec4(ar * 0.6 + 0.35, ag * 0.6 + 0.35, ab * 0.65 + 0.35, 1), u8'SMART CROSSHAIR')
        imgui.SetWindowFontScale(1.0)
        imgui.Spacing()
        local dl = imgui.GetWindowDrawList()
