            SC_U32(imgui.ImVec4(ar * 0.25 + 0.10, ag * 0.25 + 0.10, ab * 0.28 + 0.12, 0.80)), 1)
        imgui.Spacing()
        imgui.Spacing()
        local tabs = {
            u8'\xC2\xE8\xE4 / \xDD\xF4\xF4\xE5\xEA\xF2',
            u8'\xCE\xE1\xF9\xE8\xE5',
