            u8'\xCC\xE0\xF0\xEA\xE5\xF0',
        }
        for i, name in ipairs(tabs) do
            name = Fn.T(name)
            local idx = i - 1
            local act = RT.cur_tab[0] == idx
            if act then
                imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(ar * 0.14 + 0.06, ag * 0.14 + 0.06, ab * 0.16 + 0.08, 0.95))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(ar * 0.20 + 0.07, ag * 0.20 + 0.07, ab * 0.23 + 0.09, 1.00))
                imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(ar * 0.35 + 0.65, ag * 0.35 + 0.65, ab * 0.40 + 0.60, 1.00))
            else
                imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0, 0, 0, 0))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(ar * 0.08 + 0.08, ag * 0.08 + 0.08, ab * 0.10 + 0.09, 0.60))
                imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.68, 0.70, 0.74, 1.00))
            end
            local btnPos = imgui.GetCursorScreenPos()
            if imgui.Button(name, imgui.ImVec2(-1, 30)) then
                RT.cur_tab[0] = idx
            end
            if act then
                drawAnimatedTabGlow(
                    dl,
                    btnPos,
                    imgui.ImVec2(btnPos.x + nw, btnPos.y + 30),
                    os.clock()
                )
                dl:AddRectFilled(imgui.ImVec2(btnPos.x, btnPos.y + 4), imgui.ImVec2(btnPos.x + 3, btnPos.y + 26),
                    SC_U32(imgui.ImVec4(ar, ag, ab, 0.95)), 2)
            end
