        imgui.SetCursorPosY(imgui.GetWindowHeight() - 14)
        local sep2p = imgui.GetCursorScreenPos()
        dl:AddLine(imgui.ImVec2(sep2p.x, sep2p.y), imgui.ImVec2(sep2p.x + nw, sep2p.y),
            SC_U32(imgui.ImVec4(ar * 0.15 + 0.10, ag * 0.15 + 0.10, ab * 0.18 + 0.12, 0.55)), 1)
        imgui.EndChild()
        imgui.SameLine(0, 6)
        imgui.BeginChild('##content', imgui.ImVec2(0, 0), true)
        imgui.PushItemWidth(-1)
        local t = RT.cur_tab[0]
        if t == 0 then UI.tab1()
        elseif t == 1 then UI.tab2()
        elseif t == 2 then UI.tab3()
        elseif t == 3 then UI.tabDmg()
        else UI.tabMarker() end
        imgui.PopItemWidth()
        imgui.EndChild()
    end
    imgui.End()
    imgui.PopStyleVar()
    UI.popTheme()
end
function SYS.needQueueProcessing()
    if not CV.enabled[0] then return false end
    if AC.enabled or AC.pending_advance then return true end
    if Q.dirty then return true end
    if SC.pendingTexLoad ~= nil then return true end
    if TEX.pending ~= nil then return true end
    return false
end
imgui.OnFrame(
    function() return CBUGER_MODULE_ACTIVE('smart_crosshair', RT.window[0], CBUGER_GET_ANIM_RATE(15)) end,
    function()
        local module_alpha = CBUGER_UPDATE_MODULE_FADE('smart_crosshair', RT.window[0], CBUGER_GET_ANIM_RATE(15))
        if module_alpha <= 0.01 then return end
        imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, module_alpha)
        UI.build()
        imgui.PopStyleVar()
    end
)
SC.bgFrame = imgui.OnFrame(
function()
    return CV.enabled[0] and (RT.custom_alpha > 0.001 or CV.ammo_on[0] or SYS.needQueueProcessing())
end,
function()
    local rw, rh = getScreenResolution()
    imgui.SetNextWindowPos(imgui.ImVec2(0, 0))
    imgui.SetNextWindowSize(imgui.ImVec2(rw, rh))
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, 0)
    imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0, 0, 0, 0))
    if imgui.Begin('##overlay', nil,
        imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove +
        imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoInputs + imgui.WindowFlags.NoBackground) then
        if RT.custom_alpha <= 0.001 then TEX.processPending() end
        if SC.pendingTexLoad ~= nil then
            local m = SC.pendingTexLoad
            SC.pendingTexLoad = nil
            MD.loadTexture(m)
        end
        if RT.custom_alpha > 0.001 then RD.renderCrosshair(RT.custom_alpha) end
        RD.renderAmmo()
        local activeMidx = math.max(1, math.min(SC.MODE_COUNT, CV.cr_type[0] + 1))
        if AC.pending_advance and #(MD.queue[activeMidx] or {}) > 0 then
            AC.pending_advance = false
            AC.last_ms = tonumber(ffi.C.GetTickCount()) or AC.last_ms
            Q.advance()
        end
        if Q.dirty then
            local allQueues = {MD.queue[activeMidx]}
            for _, clone in ipairs(MD.clones[activeMidx] or {}) do
                if clone.image_queue and #clone.image_queue > 0 then
                    allQueues[#allQueues + 1] = clone.image_queue
                end
            end
            local loaded_one = false
            for _, queue in ipairs(allQueues) do
                for _, qname in ipairs(queue) do
                    if CACHE.img[qname] == nil then
                        CACHE.get(qname)
                        loaded_one = true
                        break
                    end
                end
                if loaded_one then break end
            end
            local allDone = true
            for _, queue in ipairs(allQueues) do
                for _, qname in ipairs(queue) do
                    if CACHE.img[qname] == nil then allDone = false; break end
                end
                if not allDone then break end
            end
            if allDone then Q.dirty = false end
        end
    end
    imgui.End()
    imgui.PopStyleColor()
    imgui.PopStyleVar()
end)
SC.bgFrame.HideCursor = true
imgui.OnFrame(
function()
    return CV.ammo_on[0] and CV.enabled[0]
end,
