end)
imgui.OnFrame(
function()
    return CV.dl_on[0] and RT.aim_on_player and CV.enabled[0]
end,
function(self)
    self.HideCursor = true
    if not RT.aim_ped_ptr then return end
    local ok, px, py, pz = pcall(getCharCoordinates, RT.aim_ped_ptr)
    if not ok then return end
    local res, sx, sy = pcall(convert3DCoordsToScreen, px, py, pz + 1.1)
    if not res or type(sx) ~= 'number' or sx == 0 then return end
    local ok2, ppx, ppy, ppz = pcall(getCharCoordinates, PLAYER_PED)
    if not ok2 then return end
    local dist = math.sqrt((px - ppx)^2 + (py - ppy)^2 + (pz - ppz)^2)
    local txt = ('%.1f m'):format(dist)
    local dl = imgui.GetBackgroundDrawList()
    local font = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
    local fsz = CV.dl_font_sz[0] * 1.0
    local ts = font:CalcTextSizeA(fsz, 1000, 0, txt)
    local tx = sx - ts.x * 0.5
    local ty = sy - ts.y * 0.5 + CV.dl_oy[0]
    local col = SC_U32(imgui.ImVec4(CV.dl_color[0], CV.dl_color[1], CV.dl_color[2], CV.dl_color[3]))
    local shad = SC_U32(imgui.ImVec4(0, 0, 0, CV.dl_color[3] * 0.7))
    dl:AddTextFontPtr(font, fsz, imgui.ImVec2(tx + 1, ty + 1), shad, txt)
    dl:AddTextFontPtr(font, fsz, imgui.ImVec2(tx, ty), col, txt)
end)
DMG.z_offsets = {
    [0] = 0.82, [1] = 0.78, [2] = 0.78, [3] = 0.74, [4] = 0.56,
    [5] = 0.64, [6] = 0.64, [7] = 0.30, [8] = 0.30, [9] = 1.02,
}
DMG.bodypart_names = {
    [0] = 'chest', [1] = 'chest', [2] = 'chest', [3] = 'chest', [4] = 'belly',
    [5] = 'larm', [6] = 'rarm', [7] = 'lleg', [8] = 'rleg', [9] = 'head',
}
function DMG.anchor(handle, bodypart)
    if not handle or not doesCharExist(handle) then return nil end
    local ok, x, y, z = pcall(getCharCoordinates, handle)
    if not ok then return nil end
    return x, y, z + (DMG.z_offsets[tonumber(bodypart) or 3] or 0.8)
end
function DMG.formatText(kind, damage, weapon, bodypart)
    local dmg = math.floor(tonumber(damage) or 0)
    local bp = DMG.bodypart_names[tonumber(bodypart) or 3] or tostring(bodypart or 0)
    local st = CV.dmg_style[0]
    if st == 0 then return tostring(dmg)
    elseif st == 1 then return kind == 'in' and '-TAKED' or '+DAMAGED'
    elseif st == 2 then return ('Damage: %d'):format(dmg) .. '\n' .. ('Hit: %s'):format(bp)
    else return tostring(dmg) end
end
function DMG.push(kind, playerId, damage, weapon, bodypart)
    if not CV.dmg_on[0] then return end
    local dmg = math.floor(tonumber(damage) or 0)
    if dmg <= 0 then return end
    RT.dmg_events[#RT.dmg_events + 1] = {
        kind = kind,
        pid = tonumber(playerId) or 0,
        damage = dmg,
        weapon = weapon,
        bodypart = bodypart,
        text = DMG.formatText(kind, dmg, weapon, bodypart),
        ttl = 1.35,
        max_ttl = 1.35,
    }
end

function DMG.safeField(value, key)
    if value == nil then return nil end
    local ok, result = pcall(function() return value[key] end)
    if ok then return result end
    return nil
end

function DMG.readVec(v)
    if v == nil then return nil end
    local ok, x, y, z = pcall(function()
        local vx, vy, vz
        vx = v.x
        vy = v.y
        vz = v.z
        if vx == nil then vx = v[1] end
        if vy == nil then vy = v[2] end
        if vz == nil then vz = v[3] end
        return tonumber(vx), tonumber(vy), tonumber(vz)
    end)
    if ok and x ~= nil and y ~= nil and z ~= nil then return x, y, z end
    return nil
end

function DMG.getBulletWeaponId(data)
    local current = data
    for _ = 1, 3 do
        local id = DMG.safeField(current, 'weaponId') or DMG.safeField(current, 'weaponID') or DMG.safeField(current, 'weapon')
        if id ~= nil then return tonumber(id) end
        current = DMG.safeField(current, 'data') or DMG.safeField(current, 'bulletSync') or DMG.safeField(current, 'bullet')
        if current == nil then break end
    end
    return nil
end

function DMG.objectCoordinates(handle)
    local ok, a, b, c, d = pcall(function() return getObjectCoordinates(handle) end)
    if not ok then return nil end
    if type(a) == 'boolean' then
        if not a then return nil end
        return b, c, d
    end
    if type(a) == 'number' and type(b) == 'number' and type(c) == 'number' then
        return a, b, c
    end
    return nil
end

function DMG.bulletEndpoint(data)
    local payload = data
    for _ = 1, 3 do
        local target_vec = DMG.safeField(payload, 'target')
            or DMG.safeField(payload, 'targetPos')
            or DMG.safeField(payload, 'targetPosition')
        if target_vec ~= nil then
            return DMG.readVec(target_vec)
        end
        payload = DMG.safeField(payload, 'data')
            or DMG.safeField(payload, 'bulletSync')
            or DMG.safeField(payload, 'bullet')
        if payload == nil then break end
    end
    return nil
end

function DMG.objectFromBullet(data)
    if data == nil then return nil, 'invalid_bullet_data:nil' end

    local payload = data
    local origin, target_vec
    for _ = 1, 3 do
        origin = DMG.safeField(payload, 'origin') or DMG.safeField(payload, 'start') or DMG.safeField(payload, 'originPos')
        target_vec = DMG.safeField(payload, 'target') or DMG.safeField(payload, 'targetPos') or DMG.safeField(payload, 'targetPosition')
        if origin ~= nil and target_vec ~= nil then break end
        local nested = DMG.safeField(payload, 'data') or DMG.safeField(payload, 'bulletSync') or DMG.safeField(payload, 'bullet')
        if nested == nil then break end
        payload = nested
    end

    if origin == nil or target_vec == nil then
        return nil, 'invalid_bullet_data:' .. tostring(type(data))
    end
    local ox, oy, oz = DMG.readVec(origin)
    local tx, ty, tz = DMG.readVec(target_vec)
    if ox == nil or oy == nil or oz == nil or tx == nil or ty == nil or tz == nil then
        return nil, 'missing_bullet_vectors:' .. tostring(type(payload))
    end

    local dx, dy, dz = tx - ox, ty - oy, tz - oz
    local length = math.sqrt(dx * dx + dy * dy + dz * dz)
    if length < 0.05 then return nil, 'short_bullet_ray' end
    local extension = math.min(3.0, math.max(0.75, length * 0.015))
    local ex = tx + dx / length * extension
    local ey = ty + dy / length * extension
    local ez = tz + dz / length * extension

    if type(processLineOfSight) ~= 'function' then
        return nil, 'processLineOfSight_unavailable'
    end
    local ok, hit, col = pcall(function()
        return processLineOfSight(ox, oy, oz, ex, ey, ez,
            true, false, false, true, false, false, false)
    end)
    if not ok then
        return nil, 'los_error:' .. tostring(hit)
    end
    if not hit then
        return nil, 'los_no_hit'
    end
    if type(col) ~= 'table' then
        return nil, 'los_result_' .. type(col)
    end

    local ptr = tonumber(col.entity) or col.entity
    if ptr == 0 then ptr = nil end
    local hx, hy, hz = DMG.readVec(col.position)
    if type(hx) ~= 'number' or type(hy) ~= 'number' or type(hz) ~= 'number' then
        hx, hy, hz = tx, ty, tz
    end

    if ptr ~= nil then
        local okHandle, handle = pcall(getObjectPointerHandle, ptr)
        if okHandle and handle then
            local okExists, exists = pcall(doesObjectExist, handle)
            if okExists and exists then
                return {
                    kind = 'object', handle = handle, entity = ptr,
                    key = 'object:' .. tostring(handle), x = hx, y = hy, z = hz
                }
            end
        end
    end

    if ptr ~= nil then
        local okPed, pedHandle = pcall(getCharPointerHandle, ptr)
        if okPed and pedHandle then
            local okExists, exists = pcall(doesCharExist, pedHandle)
            if okExists and exists then return nil, 'ped_collision' end
        end
        local okVeh, vehHandle = pcall(getVehiclePointerHandle, ptr)
        if okVeh and vehHandle then
            local okExists, exists = pcall(doesVehicleExist, vehHandle)
            if okExists and exists then return nil, 'vehicle_collision' end
        end
    end

    local key = ptr and ('world:' .. tostring(ptr)) or
        ('world-pos:' .. tostring(math.floor(hx * 2)) .. ':' .. tostring(math.floor(hy * 2)) .. ':' .. tostring(math.floor(hz * 2)))
    return {
        kind = 'world', entity = ptr, key = key,
        x = hx, y = hy, z = hz
    }
end

function DMG.chatObjectTarget(message)
    pcall(function()
        sampAddChatMessage('{00D7FF}[CBUGER]{FFFFFF} ' .. tostring(message or ''), -1)
    end)
end

function DMG.pushObjectScore(target, shot_x, shot_y, shot_z)
    if type(target) ~= 'table' then return end
    local x = tonumber(shot_x) or tonumber(target.x)
    local y = tonumber(shot_y) or tonumber(target.y)
    local z = tonumber(shot_z) or tonumber(target.z)
    if x == nil or y == nil or z == nil then return end

    local event = nil
    for _, e in ipairs(RT.dmg_events) do
        if e.kind == 'object_score' and e.target_counter then
            event = e
            break
        end
    end
    if not event then
        event = { kind = 'object_score', target_counter = true }
        RT.dmg_events[#RT.dmg_events + 1] = event
    end
    event.x, event.y, event.z = x, y, z
    event.object_handle = nil
    event.hits = math.max(0, math.floor(tonumber(target.hits) or 0))
    event.misses = math.max(0, math.floor(tonumber(target.misses) or 0))
    event.ttl = 1.35
    event.max_ttl = 1.35
end

function DMG.onBullet(data)
    if not CV.obj_target_on[0] then return end

    local target = RT.object_target
    local hit, reason = DMG.objectFromBullet(data)
    local shot_x, shot_y, shot_z
    if hit then
        shot_x, shot_y, shot_z = hit.x, hit.y, hit.z
    else
        shot_x, shot_y, shot_z = DMG.bulletEndpoint(data)
    end

    if not target then
        if not hit then
            if not DMG.object_target_miss_reported then
                DMG.object_target_miss_reported = true
                local why = tostring(reason or 'unknown')
                if #why > 110 then why = why:sub(1, 110) end
                DMG.chatObjectTarget('Объект не распознан по трассировке (' .. why .. ').')
            end
            return
        end

        RT.object_target = {
            kind = hit.kind, handle = hit.handle, entity = hit.entity,
            key = hit.key, label = hit.handle and tostring(hit.handle) or 'MAP',
            x = hit.x, y = hit.y, z = hit.z,
            anchor_x = hit.x, anchor_y = hit.y, anchor_z = hit.z,
            hits = 0, misses = 0
        }
        DMG.object_target_miss_reported = false
        return
    end

    if target.kind == 'object' then
        local existsOk, targetExists = pcall(doesObjectExist, target.handle)
        if not existsOk or not targetExists then
            RT.object_target = nil
            return
        end
    end

    local same_target = false
    if hit then
        same_target = hit.key == target.key
        if not same_target and target.kind == 'world' and hit.kind == 'world' then
            local ax = (tonumber(target.anchor_x) or tonumber(target.x) or 0) - (tonumber(hit.x) or 0)
            local ay = (tonumber(target.anchor_y) or tonumber(target.y) or 0) - (tonumber(hit.y) or 0)
            local az = (tonumber(target.anchor_z) or tonumber(target.z) or 0) - (tonumber(hit.z) or 0)
            same_target = (ax * ax + ay * ay + az * az) <= (3.0 * 3.0)
        end
    end

    if same_target then
        target.hits = (tonumber(target.hits) or 0) + 1
    else
        target.misses = (tonumber(target.misses) or 0) + 1
    end
    DMG.pushObjectScore(target, shot_x, shot_y, shot_z)
end

imgui.OnFrame(
function()
    return (CV.dmg_on[0] or CV.obj_target_on[0]) and #RT.dmg_events > 0
end,
function(self)
    self.HideCursor = true
    local dl = imgui.GetBackgroundDrawList()
    local font = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
    local remove = {}
    for i = #RT.dmg_events, 1, -1 do
        local e = RT.dmg_events[i]
        e.ttl = e.ttl - 0.016
        if e.ttl <= 0 then
            remove[#remove + 1] = i
        else
            local x, y, z = nil, nil, nil
            if e.kind == 'object' or e.kind == 'object_score' then
                x, y, z = e.x, e.y, e.z
                if e.kind == 'object' and e.object_handle then
                    local okExists, exists = pcall(doesObjectExist, e.object_handle)
                    if okExists and exists then
                        local px, py, pz = DMG.objectCoordinates(e.object_handle)
                        if type(px) == 'number' and type(py) == 'number' and type(pz) == 'number' then
                            x, y, z = px, py, pz
                        end
                    end
                end
            else
                local handle = nil
                if e.kind == 'out' and e.pid >= 0 and e.pid < 2000 then
                    pcall(function() handle = select(2, sampGetCharHandleBySampPlayerId(e.pid)) end)
                elseif e.kind == 'in' then
                    handle = PLAYER_PED
                end
                if handle and doesCharExist(handle) then
                    x, y, z = DMG.anchor(handle, e.bodypart)
                end
            end
            if x and y and z then
                local z_offset = e.kind == 'object' and 0.35 or 0
                local ok, sx, sy = pcall(convert3DCoordsToScreen, x, y, z + z_offset)
                if ok and type(sx) == 'number' and sx ~= 0 then
                    local a = math.max(0, math.min(1, e.ttl / e.max_ttl))
                    local fsz = CV.dmg_font_sz[0]
                    if e.kind == 'object_score' then
                        local hitText = tostring(math.max(0, math.floor(tonumber(e.hits) or 0)))
                        local slashText = '/'
                        local missText = tostring(math.max(0, math.floor(tonumber(e.misses) or 0)))
                        local hitW = font:CalcTextSizeA(fsz, 1000, 0, hitText).x
                        local slashW = font:CalcTextSizeA(fsz, 1000, 0, slashText).x
                        local missW = font:CalcTextSizeA(fsz, 1000, 0, missText).x
                        local totalW = hitW + slashW + missW
                        local tx = sx - totalW * 0.5
                        local ty = sy - fsz * 0.5
                        local alpha = math.max(0, math.min(1, (tonumber(CV.dmg_color[3]) or 1) * a))
                        local shadow = SC_U32(imgui.ImVec4(0, 0, 0, 0.80 * a))
                        local hitCol = SC_U32(imgui.ImVec4(0.20, 1.00, 0.25, alpha))
                        local slashCol = SC_U32(imgui.ImVec4(0.95, 0.95, 0.95, alpha))
                        local missCol = SC_U32(imgui.ImVec4(1.00, 0.20, 0.20, alpha))
                        local function drawScorePart(text, xpos, color)
                            dl:AddTextFontPtr(font, fsz, imgui.ImVec2(xpos + 1, ty + 1), shadow, text)
                            dl:AddTextFontPtr(font, fsz, imgui.ImVec2(xpos, ty), color, text)
                        end
                        drawScorePart(hitText, tx, hitCol)
                        drawScorePart(slashText, tx + hitW, slashCol)
                        drawScorePart(missText, tx + hitW + slashW, missCol)
                    else
                        local ts = font:CalcTextSizeA(fsz, 1000, 0, e.text)
                        local col = SC_U32(imgui.ImVec4(CV.dmg_color[0], CV.dmg_color[1], CV.dmg_color[2], CV.dmg_color[3] * a))
                        local shad = SC_U32(imgui.ImVec4(0, 0, 0, 0.75 * a))
                        dl:AddTextFontPtr(font, fsz, imgui.ImVec2(sx - ts.x * 0.5 + 1, sy - ts.y * 0.5 + 1), shad, e.text)
                        dl:AddTextFontPtr(font, fsz, imgui.ImVec2(sx - ts.x * 0.5, sy - ts.y * 0.5), col, e.text)
                    end
                end
            end
        end
    end
    if #remove > 0 then
        table.sort(remove, function(a, b) return a > b end)
        for _, idx in ipairs(remove) do table.remove(RT.dmg_events, idx) end
    end
end)
MK.z_offsets = {
    [0] = 0.82, [1] = 0.78, [2] = 0.78, [3] = 0.74, [4] = 0.56,
    [5] = 0.64, [6] = 0.64, [7] = 0.30, [8] = 0.30, [9] = 1.02,
}
function MK.zOffset(bodypart)
    return MK.z_offsets[tonumber(bodypart) or 3] or 0.82
end
function MK.tint()
    if CV.ac_on[0] and CV.ac_marker and CV.ac_marker[0] and RT.aim_on_player then
        return CV.enemy_color
    end
    return nil
end
function MK.tintCol(alpha, tint)
    if tint then
        return UT.argb(alpha * (tint[3] or 1), tint[0] or 1, tint[1] or 1, tint[2] or 1)
    end
    return UT.argb(alpha, 1, 1, 1)
end
function MK.fallbackX(dl, sx, sy, alpha, tint, size, shake)
    local c = MK.tintCol(alpha, tint)
    local h = size or 10
    local off = shake or 0
    dl:AddLine(imgui.ImVec2(sx - h + off, sy - h + off), imgui.ImVec2(sx + h + off, sy + h + off), c, math.max(1, h * 0.16))
    dl:AddLine(imgui.ImVec2(sx - h + off, sy + h + off), imgui.ImVec2(sx + h + off, sy - h + off), c, math.max(1, h * 0.16))
end
function MK.rotImage(dl, sx, sy, size, angle, col)
    if not HM.current then return false end
    local h = size * 0.5
    local c, s = math.cos(angle), math.sin(angle)
    local function rot(dx, dy)
        return imgui.ImVec2(sx + dx * c - dy * s, sy + dx * s + dy * c)
    end
    dl:AddImageQuad(HM.current, rot(-h, -h), rot(h, -h), rot(h, h), rot(-h, h),
        imgui.ImVec2(0, 0), imgui.ImVec2(1, 0), imgui.ImVec2(1, 1), imgui.ImVec2(0, 1), col)
    return true
end
function MK.sprite(dl, sx, sy, alpha, style, age, half)
    local drawHalf = half
    local tint = MK.tint()
    local col = MK.tintCol(alpha, tint)
    local anim = math.max(1, CV.hm_anim_spd[0]) / 10.0
    local now = os.clock()
    if style == 1 then
        local pulse = 0.5 + 0.5 * math.sin(now * (10 * anim))
        drawHalf = half * (0.82 + 0.38 * pulse)
    elseif style == 2 then
        local angle = now * math.pi * 2 * anim
        if MK.rotImage(dl, sx, sy, drawHalf * 2, angle, col) then return end
        local h = half
        local ca, sa = math.cos(angle), math.sin(angle)
        dl:AddLine(imgui.ImVec2(sx + (-h) * ca - (-h) * sa, sy + (-h) * sa + (-h) * ca),
            imgui.ImVec2(sx + h * ca - h * sa, sy + h * sa + h * ca), col, math.max(1, h * 0.18))
        dl:AddLine(imgui.ImVec2(sx + (-h) * ca - h * sa, sy + (-h) * sa + h * ca),
            imgui.ImVec2(sx + h * ca - (-h) * sa, sy + h * sa + (-h) * ca), col, math.max(1, h * 0.18))
        return
    elseif style == 3 then
        local dur_s = math.max(0.1, CV.hm_duration[0] / 1000.0)
        local t = math.min(1, age / dur_s)
        local angle = t * math.pi * 2
        drawHalf = half * (1.0 - 0.65 * t)
        col = MK.tintCol(alpha, tint)
        if MK.rotImage(dl, sx, sy, drawHalf * 2, angle, col) then return end
        local h = drawHalf
        local ca, sa = math.cos(angle), math.sin(angle)
        dl:AddLine(imgui.ImVec2(sx + (-h) * ca - (-h) * sa, sy + (-h) * sa + (-h) * ca),
            imgui.ImVec2(sx + h * ca - h * sa, sy + h * sa + h * ca), col, math.max(1, h * 0.18))
        dl:AddLine(imgui.ImVec2(sx + (-h) * ca - h * sa, sy + (-h) * sa + h * ca),
            imgui.ImVec2(sx + h * ca - (-h) * sa, sy + h * sa + (-h) * ca), col, math.max(1, h * 0.18))
        return
    elseif style == 4 then
        local shake = math.sin(now * (50 * anim)) * 2
        if HM.current then
            dl:AddImage(HM.current, imgui.ImVec2(sx - half + shake, sy - half + shake),
                imgui.ImVec2(sx + half + shake, sy + half + shake), imgui.ImVec2(0, 0), imgui.ImVec2(1, 1), col)
        else
            MK.fallbackX(dl, sx, sy, alpha, tint, half, shake)
        end
        return
    elseif style == 5 then
        col = MK.tintCol(alpha * ((math.sin(now * (20 * anim)) > 0.5) and 1.0 or 0.2), tint)
    end
    if HM.current then
        dl:AddImage(HM.current, imgui.ImVec2(sx - drawHalf, sy - drawHalf),
            imgui.ImVec2(sx + drawHalf, sy + drawHalf), imgui.ImVec2(0, 0), imgui.ImVec2(1, 1), col)
    else
        MK.fallbackX(dl, sx, sy, alpha, tint, drawHalf)
    end
end
function MK.atHandle(dl, handle, alpha, bodypart, age)
    if not handle or not doesCharExist(handle) then return end
    local ok, x, y, z = pcall(getCharCoordinates, handle)
    if not ok or not x then return end
    local mix = (CV.marker_mix and CV.marker_mix[0] or 0) / 100.0
    local res, sx, sy = pcall(convert3DCoordsToScreen, x, y, z + MK.zOffset(bodypart) + mix)
    if res and type(sx) == 'number' and sx > 0 then
        MK.sprite(dl, sx, sy, alpha, CV.hm_style[0], age or 0, math.max(1, CV.hm_size[0]) * 0.5)
    end
end
imgui.OnFrame(
function()
    return CV.hm_enabled[0] and (RT.marker_preview or #RT.hm_events > 0
        or (CV.enabled[0] and not CV.hm_onhit[0] and RT.hm_aim.handle ~= nil))
end,
function(self)
    self.HideCursor = true
    local dl = imgui.GetBackgroundDrawList()
    local now = os.clock()
    local dur = math.max(0.1, CV.hm_duration[0] / 1000.0)
    local remove = {}
    if RT.marker_preview then
        local maxId = 1004
        pcall(function() maxId = sampGetMaxPlayerId() or 1004 end)
        for pid = 0, maxId do
            local connected = false
            pcall(function() connected = sampIsPlayerConnected(pid) end)
            if connected then
                local ok, h = pcall(sampGetCharHandleBySampPlayerId, pid)
                if ok and h and doesCharExist(h) and h ~= PLAYER_PED then
                    MK.atHandle(dl, h, 0.90, 3, 0)
                end
            end
        end
    elseif CV.enabled[0] and not CV.hm_onhit[0] and RT.hm_aim.handle then
        local age = now - (RT.hm_aim.time or now)
        if age < dur then
            MK.atHandle(dl, RT.hm_aim.handle, 1.0 - (age / dur), RT.hm_aim.bodypart or 3, age)
        end
    end
    for i = #RT.hm_events, 1, -1 do
        local e = RT.hm_events[i]
        local age = now - (e.time or now)
        if age >= dur then
            remove[#remove + 1] = i
        else
            local alpha = CV.hm_fade[0] and (1.0 - (age / dur)) or 1.0
            local mix = (CV.marker_mix and CV.marker_mix[0] or 0) / 100.0
            local res, sx, sy = pcall(convert3DCoordsToScreen, e.x, e.y, e.z + MK.zOffset(e.bodypart) + mix)
            if res and type(sx) == 'number' and sx > 0 then
                MK.sprite(dl, sx, sy, alpha, CV.hm_style[0], age, math.max(1, CV.hm_size[0]) * 0.5)
            end
        end
    end
    if #remove > 0 then
        table.sort(remove, function(a, b) return a > b end)
        for _, idx in ipairs(remove) do table.remove(RT.hm_events, idx) end
    end
end)
function sampev.onSendGiveDamage(playerId, damage, weapon, bodypart)
    pcall(HZ_onSendGiveDamage, playerId, damage, weapon, bodypart)
    pcall(CBUGSPEED_onSendGiveDamage, playerId, damage, weapon, bodypart)
    DMG.push('out', playerId, damage, weapon, bodypart)
    if CV.hm_enabled[0] and CV.hm_onhit[0] then
        local h = nil
        pcall(function() h = select(2, sampGetCharHandleBySampPlayerId(playerId)) end)
        if not h or not doesCharExist(h) then h = RT.aim_ped_ptr end
        if h and doesCharExist(h) then
            local ox, oy, oz = getCharCoordinates(h)
            if ox then
                RT.hm_events[#RT.hm_events + 1] = {
                    x = ox, y = oy, z = oz,
                    time = os.clock(),
                    bodypart = bodypart or 3,
                }
            end
        end
    end
end
function sampev.onSendTakeDamage(playerId, damage, weapon, bodypart)
    pcall(HZ_onSendTakeDamage, playerId, damage, weapon, bodypart)
    DMG.push('in', playerId, damage, weapon, bodypart)
end
SC.AUTO_WEAPONS = {[28] = true, [29] = true, [32] = true, [30] = true, [31] = true,
                   [37] = true, [38] = true, [41] = true, [42] = true}
function SYS.hasActiveQueue()
    local midx = math.max(1, math.min(SC.MODE_COUNT, CV.cr_type[0] + 1))
    if #(MD.queue[midx] or {}) > 0 then return true end
    for _, c in ipairs(MD.clones[midx] or {}) do
        if c.enabled[0] and #(c.image_queue or {}) > 0 then return true end
    end
    return false
end
function SYS.queueProcessing()
    if CV.enabled[0] and not AC.enabled and SYS.hasActiveQueue() then
        local wid = RT.ammo_wid
        local hasAmmo = wid > 0 and not RD.NO_AMMO[wid]
        local lmb = isKeyDown(1)
        if hasAmmo then
            local now_t = os.clock()
            local clip_now = RT.ammo_clip or 0
            local clip_prev = RT.prev_ammo_clip or 0
            if SC.AUTO_WEAPONS[wid] then
                if clip_now < clip_prev and clip_prev > 0 then Q.advance() end
            else
                if lmb and not RT.prev_lmb and (now_t - (RT.last_queue_advance or 0)) >= 0.12 then
                    Q.advance()
                    RT.last_queue_advance = now_t
                end
            end
            RT.prev_lmb = lmb
        else
            RT.prev_lmb = false
        end
        RT.prev_ammo_clip = RT.ammo_clip or 0
    else
        RT.prev_lmb = false
        RT.prev_ammo_clip = 0
    end
end
function SYS.autoCycleTick()
    if CV.enabled[0] and AC.enabled then
        local midx = math.max(1, math.min(SC.MODE_COUNT, CV.cr_type[0] + 1))
        if #(MD.queue[midx] or {}) > 0 then
            local now_ms = tonumber(ffi.C.GetTickCount())
            if now_ms and (now_ms - AC.last_ms) >= AC.speed_ms then
                AC.pending_advance = true
            end
        end
    end
end
function SYS.dragModePos()
    if not RT.drag_mode_pos then return end
    sampSetCursorMode(3)
    local idx = math.max(1, math.min(SC.MODE_COUNT, (RT.drag_mode_mode or (MD.currentIdx() - 1)) + 1))
    local mp = MD.pos[idx] or MD.pos[1]
    local mx, my = getCursorPos()
    mp.x[0] = math.floor(mx)
    mp.y[0] = math.floor(my)
    if isKeyJustPressed(1) then
        sampSetCursorMode(0)
        RT.drag_mode_pos = false
        RT.drag_mode_mode = 0
        RT.window[0] = true
    end
    if isKeyJustPressed(2) or isKeyJustPressed(0x1B) then
        sampSetCursorMode(0)
        RT.drag_mode_pos = false
        RT.drag_mode_mode = 0
        RT.window[0] = true
    end
end
function SYS.dragAmmo()
    if not RT.drag_ammo then return end
    sampSetCursorMode(3)
    local mx, my = getCursorPos()
    CV.ammo_pos_x[0] = math.floor(mx)
    CV.ammo_pos_y[0] = math.floor(my)
    if isKeyJustPressed(1) then
        sampSetCursorMode(0)
        RT.drag_ammo = false
        RT.window[0] = true
    end
    if isKeyJustPressed(2) or isKeyJustPressed(0x1B) then
        sampSetCursorMode(0)
        RT.drag_ammo = false
        RT.window[0] = true
    end
end
function SYS.dragClone()
    if not RT.drag_clone then return end
    sampSetCursorMode(3)
    local mode = RT.drag_clone_mode or (MD.currentIdx() - 1)
    local list = MD.clones[(mode or 0) + 1] or MD.currentClones()
    local ec = list[RT.drag_clone_idx]
    if ec then
        local mx, my = getCursorPos()
        local basePos = MD.pos[(mode or 0) + 1] or MD.pos[1]
        ec.offset_x[0] = math.floor(mx - basePos.x[0])
        ec.offset_y[0] = math.floor(my - basePos.y[0])
    end
    if isKeyJustPressed(1) then
        sampSetCursorMode(0)
        RT.drag_clone = false
        RT.drag_clone_idx = 0
        RT.window[0] = true
    end
    if isKeyJustPressed(2) or isKeyJustPressed(0x1B) then
        sampSetCursorMode(0)
        RT.drag_clone = false
        RT.drag_clone_idx = 0
        RT.window[0] = true
    end
end
SCR = {}
function SCR.run()
    while not isSampAvailable() do wait(200) end
    CBUGER_WAIT_RUNTIME_READY()
    wait(150)
    SC_syncGlobalTheme()
    if not SCR_CFG.ini.settings.always_on_fix_v1 then
        CV.enabled[0] = true
        SCR_CFG.ini.settings.always_on_fix_v1 = 1
    end
    sampRegisterChatCommand('scr', function() RT.window[0] = not RT.window[0] end)
    if CV.auto_start[0] then
        CV.enabled[0] = true
        RT.custom_alpha = 1.0
        GTA.syncNative()
    else
        if CV.enabled[0] then GTA.syncNative() else GTA.fullRestore() end
    end
    RT.prev_enabled = CV.enabled[0]
    MD.syncImageSelection(CV.cr_type[0])
    MD.loadTexture(CV.cr_type[0])
    if UT.bool(SCR_CFG.mk.enabled) and SCR_CFG.mk.image_name ~= ' ' then
        for i, tn in ipairs(HM.names) do
            local dec = ' '
            pcall(function() dec = u8:decode(tn) end)
            if dec == SCR_CFG.mk.image_name then
                HM.selected_idx = i
                local fn = HM.files[i - 1]
                if fn then HM.load(fn) end
                break
            end
        end
    end
    if not HM.current and #HM.files > 0 then
        HM.selected_idx = 2
        HM.load(HM.files[1])
    end
    RT.ammo_anim = 0
    RT.ammo_fill = 1.0
    RT.marker_preview = false
    RT.prev_cr_type = CV.cr_type[0]
    while true do
        wait(0)
        SYS.autoSave()
        CL.flushEdit()
        local hk = isKeyDown(0x24)
        if hk and not RT.prev_home then RT.window[0] = not RT.window[0] end
        RT.prev_home = hk
        if CV.cr_type[0] ~= RT.prev_cr_type then
            if AC.enabled then
                AC.enabled = false
                AC.on_img[0] = false
            end
            RT.prev_cr_type = CV.cr_type[0]
        end
        if CV.enabled[0] ~= RT.prev_enabled then
            if CV.enabled[0] then
                RT.custom_alpha = 1.0
                GTA.syncNative()
            else
                RT.custom_alpha = 0.0
                GTA.fullRestore()
            end
            RT.prev_enabled = CV.enabled[0]
        end
        if CV.enabled[0] then
            local isStd = CV.cr_type[0] == 3
            local isVoid = CV.cr_type[0] == 4
            local currentWeapon = 0
            pcall(function() currentWeapon = getCurrentCharWeapon(PLAYER_PED) end)
            currentWeapon = tonumber(currentWeapon) or 0
            local canAim = currentWeapon > 0
            if isStd then
                local visible = CV.always_visible[0] or (isKeyDown(2) and canAim)
                RT.custom_alpha = (MD.imageCfg(3).enabled[0] and TEX.current ~= nil and visible) and 1.0 or 0.0
                GTA.setVisible(visible)
            elseif isVoid then
                GTA.restoreColor()
                GTA.setVisible(false)
                if CV.always_visible[0] then
                    RT.custom_alpha = 1.0
                elseif isKeyDown(2) and canAim then
                    RT.custom_alpha = math.min(1, RT.custom_alpha + RT.fade_speed)
                else
                    RT.custom_alpha = 0.0
                end
            else
                GTA.setVisible(false)
                if CV.always_visible[0] then
                    RT.custom_alpha = 1.0
                elseif isKeyDown(2) and canAim then
                    RT.custom_alpha = math.min(1, RT.custom_alpha + RT.fade_speed)
                else
                    RT.custom_alpha = math.max(0, RT.custom_alpha - RT.fade_speed)
                end
            end
        else
            GTA.setVisible(true)
            GTA.restoreColor()
            RT.custom_alpha = 0.0
        end
        local rt = 1.0
        if CV.recoil_on[0] and isKeyDown(1) then
            rt = 1 + (math.max(0, CV.recoil_scale[0]) / 100)
        end
        local rs = math.max(0.02, math.min(0.5, CV.recoil_spd[0] / 200.0))
        RT.recoil = RT.recoil + (rt - RT.recoil) * rs
        AIM.check()
        if not RT.aim_on_player and not CV.hm_onhit[0] then RT.hm_aim.handle = nil end
        SYS.updateLiveColor()
        SYS.updatePulsation()
        RD.updateAmmo()
        SYS.queueProcessing()
        SYS.autoCycleTick()
        SYS.dragModePos()
        SYS.dragAmmo()
        SYS.dragClone()
    end
end
function SCR.terminate(s, q)
    pcall(SYS.saveIni)
    pcall(memory.setuint8, GTA.HUD, 0x83, true)
    pcall(GTA.restoreColor)
    pcall(writeMemory, 0x58E2FA + 2, 4, GTA.ORIG_X, true)
    pcall(writeMemory, 0x58E319 + 2, 4, GTA.ORIG_Y, true)
    pcall(writeMemory, 0x609D80, 2, 0x087A, true)
    CACHE.release()
    if TEX.current then
        pcall(function() imgui.ReleaseTexture(TEX.current) end)
        TEX.current = nil
    end
    if TEX.pending then
        pcall(function() imgui.ReleaseTexture(TEX.pending) end)
        TEX.pending = nil
    end
    if HM.current then
        pcall(function() imgui.ReleaseTexture(HM.current) end)
        HM.current = nil
    end
end
end
