        label = label:gsub(' (%a)', function(c) return ' ' .. c:upper() end)
        icon_list[#icon_list + 1] = { key = k, label = label, glyph = glyph_map[k] }
    end
end
local icon_index_cache = {}
local function iconIndex(key)
    if icon_index_cache[key] then return icon_index_cache[key] end
    for i, e in ipairs(icon_list) do
        if e.key == key then icon_index_cache[key] = i - 1; return i - 1 end
    end
    return 0
end
local function getIcon(key)
    for _, e in ipairs(icon_list) do
        if e.key == key then return e.glyph or '?' end
