ffi.cdef[[
    int mciSendStringA(const char* lpstrCommand, char* lpstrReturnString, unsigned int uReturnLength, void* hwndCallback);
]]
local mci = ffi.C
local function mci_exec(cmd)
    local buff = ffi.new("char[512]")
    local ok = pcall(function()
        local c = ffi.new("char[?]", #cmd + 1)
        ffi.copy(c, cmd)
        mci.mciSendStringA(c, buff, 512, nil)
    end)
    local out = ""
    pcall(function() out = ffi.string(buff) end)
    return ok, out
end
local function utf8_to_cp1251(s)
    if not s or s == "" then return "" end
    if encoding and encoding.convert then
        local ok, conv = pcall(function() return encoding.convert(s, "UTF-8", "CP1251") end)
        if ok and conv and type(conv) == "string" and conv ~= "" then return conv end
    end
    local out = {}
    local i = 1
    local len = #s
    while i <= len do
        local b1 = string.byte(s, i)
        if not b1 then break end
        if b1 < 128 then table.insert(out, string.char(b1)); i = i + 1
        elseif b1 >= 192 and b1 <= 223 then
            local b2 = string.byte(s, i+1) or 0
            if b1 == 0xD0 then
                if b2 == 0x81 then table.insert(out, string.char(0xA8))
                else table.insert(out, string.char((b2 + 0x30) % 256)) end
            elseif b1 == 0xD1 then
                if b2 == 0x91 then table.insert(out, string.char(0xB8))
                else table.insert(out, string.char((b2 + 0x70) % 256)) end
            else table.insert(out, '?') end
            i = i + 2
        else table.insert(out, '?'); i = i + 1 end
    end
    return table.concat(out)
end
local function sendChat(msg, color)
    if type(msg) ~= "string" then msg = tostring(msg or "") end
    local out = msg
    if encoding and encoding.convert then
        local ok, conv = pcall(function() return encoding.convert(msg, "UTF-8", "CP1251") end)
        if ok and conv and type(conv) == "string" and conv ~= "" then out = conv else out = utf8_to_cp1251(msg) end
    else out = utf8_to_cp1251(msg) end
    pcall(function() sampAddChatMessage(out, color or -1) end)
end
local clamp = CoreUtil.clamp
local lerp = CoreUtil.lerp
local function is_finite(n) return type(n)=="number" and n==n and n~=math.huge and n~=-math.huge end
local function vec_len(x,y,z) return math.sqrt((x or 0)^2 + (y or 0)^2 + (z or 0)^2) end
local function vec_norm(x,y,z) local l = vec_len(x,y,z) if l==0 then return 0,0,0 end return x/l,y/l,z/l end
local function vec_cross(ax,ay,az, bx,by,bz) return ay*bz - az*by, az*bx - ax*bz, ax*by - ay*bx end
local function hsvToRgb(h, s, v)
    h = (h % 1.0) * 6
    local i = math.floor(h)
    local f = h - i
    local p = v * (1 - s)
    local q = v * (1 - f * s)
    local t = v * (1 - (1 - f) * s)
    if i == 0 then return v, t, p
    elseif i == 1 then return q, v, p
    elseif i == 2 then return p, v, t
    elseif i == 3 then return p, q, v
    elseif i == 4 then return t, p, v
    else return v, p, q end
end
local sliderEditState = {
    id           = nil,
    value_str    = "",
    is_float     = true,
    just_entered = false,
    frames_shown = 0,
}
local sliderClickTrack  = {}
local sliderActiveState = {}
local DRAG_THRESHOLD = 3.0
local function SpaceSavingSliderFloat(label, v, v_min, v_max, format, width, flags)
    local uid = "##ssf_" .. label
    if width then imgui.SetNextItemWidth(width) end
    local pos = imgui.GetCursorScreenPos()
    local w   = width or imgui.CalcItemWidth()
    local fh  = imgui.GetFrameHeight()
    local changed = false
    if sliderEditState.id == uid then
        if sliderEditState.just_entered then
            imgui.SetKeyboardFocusHere(0)
            sliderEditState.just_entered = false
        end
        local buf = ffi.new("char[64]", sliderEditState.value_str)
        imgui.PushStyleColor(imgui.Col.FrameBg, PT_ac(0.180, 1.000))
        local entered = imgui.InputText(uid .. "_ed", buf, 64,
            imgui.InputTextFlags.EnterReturnsTrue + imgui.InputTextFlags.AutoSelectAll)
        imgui.PopStyleColor()
        sliderEditState.value_str    = ffi.string(buf)
        sliderEditState.frames_shown = sliderEditState.frames_shown + 1
        local esc = false
        pcall(function() esc = imgui.IsKeyPressed(imgui.Key.Escape) end)
        if not esc then pcall(function() esc = imgui.IsKeyPressed(256) end) end
        if esc then
            sliderEditState.id = nil; sliderEditState.frames_shown = 0
        elseif entered then
            local num = tonumber(ffi.string(buf))
            if num then v[0] = clamp(num, v_min, v_max); changed = true end
            sliderEditState.id = nil; sliderEditState.frames_shown = 0
        elseif sliderEditState.frames_shown >= 4
               and not imgui.IsItemActive() and imgui.IsItemDeactivated() then
            local num = tonumber(ffi.string(buf))
            if num then v[0] = clamp(num, v_min, v_max); changed = true end
            sliderEditState.id = nil; sliderEditState.frames_shown = 0
        end
    else
        local io_r = imgui.GetIO()
        local mx, my = io_r.MousePos.x, io_r.MousePos.y
        local hov  = mx >= pos.x and mx <= pos.x + w and my >= pos.y and my <= pos.y + fh
        local now  = os.clock()
        if hov and imgui.IsMouseClicked(0) then
            local st = sliderClickTrack[uid]
            if st and (now - st.t) < 0.35 then
                imgui.InvisibleButton(uid .. "_dbl", imgui.ImVec2(w, fh))
                sliderClickTrack[uid] = nil; sliderActiveState[uid] = nil
                sliderEditState.id           = uid
                sliderEditState.value_str    = string.format("%.4g", st.val)
                sliderEditState.is_float     = true
                sliderEditState.just_entered = true
                sliderEditState.frames_shown = 0
                local dl = imgui.GetWindowDrawList()
                local ts = imgui.CalcTextSize(label)
                dl:AddText(imgui.ImVec2(pos.x + w/2 - ts.x/2, pos.y + (fh - ts.y)/2),
                    PT_U32(imgui.ImVec4(1,1,1,1)), label)
                return false
            else
                sliderClickTrack[uid] = { t = now, val = v[0] }
            end
        end
        local val_snap = v[0]
        changed = imgui.SliderFloat(uid, v, v_min, v_max, "", flags or 1.0)
        local is_active = imgui.IsItemActive()
        if is_active then
            local ps = sliderActiveState[uid]
            if not ps then
                    sliderActiveState[uid] = { orig = val_snap, dragging = false }
                ps = sliderActiveState[uid]
            end
            if not ps.dragging then
                local drag_ok = false
                pcall(function()
                    local d = imgui.GetMouseDragDelta(0, DRAG_THRESHOLD)
                    drag_ok = (math.abs(d.x) >= DRAG_THRESHOLD or math.abs(d.y) >= DRAG_THRESHOLD)
                end)
                if drag_ok then
                else
                    changed = false
                end
            end
        else
            sliderActiveState[uid] = nil
        end
        local dl  = imgui.GetWindowDrawList()
        local txt = hov and string.format(format, v[0]) or label
        local ts  = imgui.CalcTextSize(txt)
        dl:AddText(imgui.ImVec2(pos.x + w/2 - ts.x/2, pos.y + (fh - ts.y)/2),
            PT_U32(imgui.ImVec4(1,1,1,1)), txt)
    end
    return changed
end
