local function loadIniData()
    local ok, data = pcall(function()
        return inicfg.load(nil, iniFileName)
    end)
    if ok and type(data) == "table" then
        data.settings = data.settings or {}
        data.colors = data.colors or {}
        data.records = data.records or {}
        return data
    end
    return { settings = {}, colors = {}, records = {} }
end
local function saveSettings()
    ensureIniRoot()
    local data = loadIniData()
    for k, v in pairs(pt_cfg) do
        if type(v) == "boolean" then data.settings[k] = tostring(v)
        elseif type(v) == "number" or type(v) == "string" then data.settings[k] = v end
    end
    data.colors.tile_r, data.colors.tile_g, data.colors.tile_b, data.colors.tile_a = unpack(pt_cfg.tile_color)
    data.colors.grid_r, data.colors.grid_g, data.colors.grid_b, data.colors.grid_a = unpack(pt_cfg.grid_bg)
    data.colors.fa_r, data.colors.fa_g, data.colors.fa_b, data.colors.fa_a = unpack(pt_cfg.tile_fa_color)
    data.colors.cr_r, data.colors.cr_g, data.colors.cr_b, data.colors.cr_a = unpack(pt_cfg.crosshair_color)
    local ok, result = pcall(inicfg.save, data, iniFileName)
    return ok and result == true
end
local function loadSettings()
    local data = loadIniData()
    if data and data.settings then
        for k, v in pairs(data.settings) do
            if pt_cfg[k] ~= nil then
                if type(pt_cfg[k]) == "boolean" then pt_cfg[k] = (v == "true" or v == true)
                elseif type(pt_cfg[k]) == "number" then pt_cfg[k] = tonumber(v) or pt_cfg[k]
                elseif type(pt_cfg[k]) == "string" then pt_cfg[k] = tostring(v) end
            end
        end
        if data.colors then
            local function load_rgba(prefix, current)
                current = current or {1, 1, 1, 1}
                return {
                    tonumber(data.colors[prefix .. '_r']) or current[1] or 1,
                    tonumber(data.colors[prefix .. '_g']) or current[2] or 1,
                    tonumber(data.colors[prefix .. '_b']) or current[3] or 1,
                    tonumber(data.colors[prefix .. '_a']) or current[4] or 1,
                }
            end
            if data.colors.tile_r or data.colors.tile_g or data.colors.tile_b or data.colors.tile_a then
                pt_cfg.tile_color = load_rgba('tile', pt_cfg.tile_color)
            end
            if data.colors.grid_r or data.colors.grid_g or data.colors.grid_b or data.colors.grid_a then
                pt_cfg.grid_bg = load_rgba('grid', pt_cfg.grid_bg)
            end
            if data.colors.fa_r or data.colors.fa_g or data.colors.fa_b or data.colors.fa_a then
                pt_cfg.tile_fa_color = load_rgba('fa', pt_cfg.tile_fa_color)
            end
            if data.colors.cr_r or data.colors.cr_g or data.colors.cr_b or data.colors.cr_a then
                pt_cfg.crosshair_color = load_rgba('cr', pt_cfg.crosshair_color)
            end
        end
    end
end
