local playsound = nil
local function escapeRecordField(v)
    v = tostring(v or "")
    v = v:gsub("\\", "\\\\")
    v = v:gsub("\r", "\\r")
    v = v:gsub("\n", "\\n")
    v = v:gsub("\t", "\\t")
    return v
end
local function unescapeRecordField(v)
    v = tostring(v or "")
    v = v:gsub("\\([\\rnt])", function(ch)
        if ch == "\\" then return "\\"
        elseif ch == "r" then return "\r"
        elseif ch == "n" then return "\n"
        elseif ch == "t" then return "\t"
        end
        return ch
    end)
    return v
end
local function saveGameRecords()
    ensureIniRoot()
    local data = loadIniData()
    data.records = {}
    for i, rec in ipairs(pt_gameRecords or {}) do
        local parts = {
            escapeRecordField(rec.songName or ""),
            escapeRecordField(rec.pt_score or 0),
            escapeRecordField(rec.maxCombo or 0),
            escapeRecordField(rec.pt_misses or 0),
            escapeRecordField(rec.result or ""),
            escapeRecordField(rec.duration or "0:00"),
            escapeRecordField(rec.session or i),
        }
        data.records[string.format("record_%03d", i)] = table.concat(parts, "\t")
    end
    local ok, result = pcall(inicfg.save, data, iniFileName)
    local saved = ok and result == true
    pt_records_dirty = not saved
    return saved
end
local function loadGameRecords()
    local data = loadIniData()
    pt_gameRecords = {}
    if not data.records then return end
    local ordered = {}
    for key, value in pairs(data.records) do
        local idx = tonumber(tostring(key):match("^record_(%d+)$"))
        if idx and type(value) == "string" and value ~= "" then
            ordered[#ordered + 1] = { idx = idx, value = value }
        end
    end
    table.sort(ordered, function(a, b) return a.idx < b.idx end)
    for _, item in ipairs(ordered) do
        local fields = {}
        local start_pos = 1
        for _ = 1, 6 do
            local tab_pos = item.value:find("\t", start_pos, true)
            if tab_pos then
                fields[#fields + 1] = item.value:sub(start_pos, tab_pos - 1)
                start_pos = tab_pos + 1
            else
                break
            end
        end
        fields[#fields + 1] = item.value:sub(start_pos)
        while #fields < 7 do fields[#fields + 1] = "" end
        local songName = unescapeRecordField(fields[1])
        local pt_score    = tonumber(unescapeRecordField(fields[2])) or 0
        local maxCombo = tonumber(unescapeRecordField(fields[3])) or 0
        local pt_misses   = tonumber(unescapeRecordField(fields[4])) or 0
        local result   = unescapeRecordField(fields[5])
        local duration = unescapeRecordField(fields[6])
        local session  = tonumber(unescapeRecordField(fields[7])) or #pt_gameRecords + 1
        pt_gameRecords[#pt_gameRecords + 1] = {
            songName = songName,
            pt_score    = pt_score,
            maxCombo = maxCombo,
            pt_misses   = pt_misses,
            result   = result,
            duration = duration,
            session  = session,
        }
    end
end
