local function ensureFolders()
    local root = CBUGER_ROOT .. "PianoTiles"
    if not lfs.attributes(root) then pcall(function() lfs.mkdir(root) end) end
    local spath = pt_cfg.songs_folder
    local ipath = pt_cfg.images_folder
    local tpath = pt_cfg.tiles_folder  or (root .. "\\pt_tiles")
    if not lfs.attributes(spath) then pcall(function() lfs.mkdir(spath) end) end
    if not lfs.attributes(ipath) then pcall(function() lfs.mkdir(ipath) end) end
    if not lfs.attributes(tpath) then pcall(function() lfs.mkdir(tpath) end) end
end
local function saveGameRecord(result)
    local sname = pt_currentSessionSong
    if not sname or sname == "" then sname = S("Без музыки") end
    local secs = math.floor(os.clock() - pt_sessionStartTime)
    local mm   = math.floor(secs / 60)
    local ss   = secs % 60
    local dur  = string.format("%d:%02d", mm, ss)
    table.insert(pt_gameRecords, {
        songName = sname,
        pt_score    = pt_score,
        maxCombo = pt_currentSessionMaxCombo,
        pt_misses   = pt_misses,
        result   = result or S("Проигрыш"),
        duration = dur,
        session  = #pt_gameRecords + 1,
    })
    if #pt_gameRecords > 50 then table.remove(pt_gameRecords, 1) end
    return saveGameRecords()
end
local function scanFolders()
    pt_songsList  = {}
    pt_bgImages   = {}
    pt_tileImages = {}
    ensureFolders()
    for file in lfs.dir(pt_cfg.songs_folder) do
        if file ~= "." and file ~= ".." then
            local ext = (file:match("^.+%.([^%.]+)$") or ""):lower()
            for _,e in ipairs(pt_cfg.supported_exts) do
                if ext == e then table.insert(pt_songsList, { name = file, path = pt_cfg.songs_folder .. "\\" .. file, ext = ext }); break end
            end
        end
    end
    for file in lfs.dir(pt_cfg.images_folder) do
        if file ~= "." and file ~= ".." then
            local ext = (file:match("^.+%.([^%.]+)$") or ""):lower()
            for _,ie in ipairs({ "png", "jpg", "jpeg", "bmp" }) do
                if ext == ie then table.insert(pt_bgImages, { name = file, path = pt_cfg.images_folder .. "\\" .. file, ext = ext }); break end
            end
        end
    end
    local tilesFolder = pt_cfg.tiles_folder or (CBUGER_ROOT .. "PianoTiles\\pt_tiles")
    local ok_dir = pcall(function()
        for file in lfs.dir(tilesFolder) do
            if file ~= "." and file ~= ".." then
                local ext = (file:match("^.+%.([^%.]+)$") or ""):lower()
                for _,ie in ipairs({ "png", "jpg", "jpeg", "bmp" }) do
                    if ext == ie then table.insert(pt_tileImages, { name = file, path = tilesFolder .. "\\" .. file, ext = ext }); break end
                end
            end
        end
    end)
    table.sort(pt_songsList,  function(a,b) return a.name:lower() < b.name:lower() end)
    table.sort(pt_bgImages,   function(a,b) return a.name:lower() < b.name:lower() end)
    table.sort(pt_tileImages, function(a,b) return a.name:lower() < b.name:lower() end)
    local changed_sel = false
    local function fixSel(key, list)
        local cur = pt_cfg[key]
        if type(cur) ~= "string" or cur == "" then return end
        for _, rec in ipairs(list) do if rec.path == cur then return end end
        local base = cur:match("([^\\/]+)$")
        if not base then return end
        local lb = base:lower()
        for _, rec in ipairs(list) do
            if rec.name:lower() == lb then pt_cfg[key] = rec.path; changed_sel = true; return end
        end
    end
    fixSel("bg_selected", pt_bgImages)
    fixSel("normal_tile_img", pt_tileImages)
    if changed_sel then pcall(saveSettings) end
end
local function releaseMoonStream(handle)
    if handle == nil then return end
    if type(setAudioStreamState) == "function" and moon_action then
        pcall(function() setAudioStreamState(handle, moon_action.STOP) end)
    end
        if type(releaseAudioStream) == "function" then
        pcall(function() releaseAudioStream(handle) end)
    end
end
local function freeBassHandle()
    if hasBass and bassHandle then pcall(function() bass.BASS_ChannelStop(bassHandle); bass.BASS_StreamFree(bassHandle) end) end
    bassHandle = nil
    Radio.lastPos = nil
    Radio.lastPosAt = 0
    Radio.lastAudibleAt = 0
end
local function stopMusic(preserveRadioIntent)
    if not preserveRadioIntent then radioPlaybackWanted = false end
    if playsound ~= nil then
        local h = playsound
        playsound = nil
        releaseMoonStream(h)
    end
    freeBassHandle()
    pcall(function() mci_exec("stop " .. musicAlias); mci_exec('stop "' .. musicAlias .. '"'); mci_exec("close " .. musicAlias); mci_exec('close "' .. musicAlias .. '"') end)
    mciOpenedPath = nil; pt_musicPlaying = false; playMethod = nil
    Radio.path = nil; Radio.badSince = nil
end
local function setMusicVolumePercent(percent)
    percent = math.max(0, math.min(100, tonumber(percent) or 0))
    pt_cfg.volume_percent = percent
    saveSettings()
    if playsound ~= nil and type(setAudioStreamVolume) == "function" then
        pcall(function() setAudioStreamVolume(playsound, percent / 100.0) end); return
    end
    if hasBass and bassHandle then
        pcall(function() bass.BASS_ChannelSetAttribute(bassHandle, BASS_ATTRIB_VOL, percent / 100.0) end); return
    end
    local vol = math.floor(percent * 10)
    pcall(function() mci_exec(string.format('setaudio %s volume to %d', musicAlias, vol)); mci_exec(string.format('setaudio "%s" volume to %d', musicAlias, vol)) end)
end
local function radioBackoffSeconds(n)
    return math.min(60.0, 5.0 * (2 ^ math.min(math.max(n, 1) - 1, 4)))
end
local function openAndPlayMusic(path, loop, preferBass, seamless)
    if type(path) ~= "string" or path == "" then return false, "no path" end

    local isUrl = path:lower():match("^https?://") ~= nil
    local isSelectedRadio = isUrl and pt_selectedIsRadio
    if isSelectedRadio then radioPlaybackWanted = true end

            local oldMoon, oldBass, oldMethod
    if seamless and isUrl and (playsound ~= nil or bassHandle ~= nil) then
        oldMoon, oldBass, oldMethod = playsound, bassHandle, playMethod
        playsound, bassHandle = nil, nil
    else
                        stopMusic(isSelectedRadio)
    end
    local function dropOld()
        if oldMoon ~= nil then releaseMoonStream(oldMoon) end
        if oldBass ~= nil and hasBass then
            pcall(function() bass.BASS_ChannelStop(oldBass); bass.BASS_StreamFree(oldBass) end)
        end
    end
    local function restoreOld()
        if oldMoon ~= nil or oldBass ~= nil then
            playsound, bassHandle, playMethod = oldMoon, oldBass, oldMethod
        end
    end

    local function markStarted(method)
        pt_musicPlaying = true
        playMethod = method
        if isUrl then
            local now = os.clock()
            Radio.path = path
            Radio.startedAt = now
            Radio.retryAt = now + Radio.CONNECT_GRACE
            Radio.lastCheckAt = now
            Radio.failCount = 0
            Radio.goodBackend = method
            Radio.badSince = nil
            Radio.lastPos = nil
            Radio.lastPosAt = now
            Radio.lastAudibleAt = now
            if isSelectedRadio then radioPlaybackWanted = true end
            if method == "BASS" and bassHandle and hasBass and bass.BASS_ChannelGetPosition then
                local okPos, pos = pcall(function() return bass.BASS_ChannelGetPosition(bassHandle, 0) end)
                Radio.lastPos = okPos and tonumber(pos) or nil
            end
        end
        return true
    end

    local function tryMoonStream()
        if type(loadAudioStream) ~= "function" or not moon_action then return false end
        local ok, handle = pcall(function() return loadAudioStream(path) end)
        if not ok or not handle then return false end

        local callOk, stateResult = pcall(function()
            if type(setAudioStreamVolume) == "function" then
                setAudioStreamVolume(handle, (tonumber(pt_cfg.volume_percent) or 80) / 100.0)
            end
            return setAudioStreamState(handle, moon_action.PLAY)
        end)
        local started = callOk and stateResult ~= false
            and (stateResult == nil or tonumber(stateResult) ~= 0)
        if started then
            playsound = handle
            return markStarted("MOON")
        end
        releaseMoonStream(handle)
        return false
    end

    local function tryBassStream()
        if not hasBass or not bass then return false end
        local ok, stream = false, nil
        if isUrl then
            if not bass.BASS_StreamCreateURL then return false end
                        ok, stream = pcall(bass.BASS_StreamCreateURL, path, 0, 0, nil, nil)
            if not ok or not stream or stream == 0 then
                                local okShort, streamShort = pcall(bass.BASS_StreamCreateURL, path, 0, 0)
                if okShort and streamShort and streamShort ~= 0 then
                    ok, stream = true, streamShort
                end
            end
        else
            if not bass.BASS_StreamCreateFile then return false end
            ok, stream = pcall(function() return bass.BASS_StreamCreateFile(false, path, 0, 0, 2) end)
        end
        if not ok or not stream or stream == 0 then return false end

        local playCallOk, playResult = pcall(function()
            bass.BASS_ChannelSetAttribute(stream, BASS_ATTRIB_VOL,
                (tonumber(pt_cfg.volume_percent) or 80) / 100.0)
                        return bass.BASS_ChannelPlay(stream, true)
        end)
        local started = playCallOk and playResult ~= false
            and (playResult == nil or tonumber(playResult) ~= 0)
        if started then
            bassHandle = stream
            return markStarted("BASS")
        end
        pcall(function() bass.BASS_ChannelStop(stream); bass.BASS_StreamFree(stream) end)
        return false
    end

                        if isUrl then
        local useBass = preferBass
        if useBass == nil then
                                    useBass = (Radio.path ~= path) or (Radio.goodBackend ~= "MOON")
        end
        local started = false
        if useBass then
            started = tryBassStream()
            if not started then started = tryMoonStream() end
        else
            started = tryMoonStream()
            if not started then started = tryBassStream() end
        end
        if started then
            dropOld()
            return true
        end
        restoreOld()
                if isSelectedRadio then radioPlaybackWanted = true end
        if Radio.failPath ~= path then Radio.failCount = 0; Radio.failPath = path end
        Radio.failCount = Radio.failCount + 1
        Radio.retryAt = os.clock() + radioBackoffSeconds(Radio.failCount)
        return false, "radio stream open failed"
    end

    if tryMoonStream() then return true end
    if tryBassStream() then return true end

    local attempts = {
        string.format('open "%s" alias %s', path, musicAlias),
        string.format('open "%s" type mpegvideo alias %s', path, musicAlias),
        string.format('open "%s" type waveaudio alias %s', path, musicAlias)
    }
    for _,cmd in ipairs(attempts) do
        local ok = pcall(function() mci_exec(cmd) end)
        if ok then
            mciOpenedPath = path
            setMusicVolumePercent(pt_cfg.volume_percent)
            if loop then pcall(function() mci_exec(string.format('play %s REPEAT', musicAlias)) end) end
            pcall(function() mci_exec(string.format('play %s', musicAlias)) end)
            pt_musicPlaying = true
            playMethod = "MCI"
            return true
        end
    end
    return false, "open failed"
end
local function radioStreamPlaying()
    if not pt_musicPlaying then return false end
    if playMethod == "BASS" then
        if not (hasBass and bassHandle and bass.BASS_ChannelIsActive) then return false end
        local ok, st = pcall(bass.BASS_ChannelIsActive, bassHandle)
        st = ok and tonumber(st) or nil
        return st == 1 or st == 4
    elseif playMethod == "MOON" then
        if playsound == nil or type(getAudioStreamState) ~= "function" then return false end
        local ok, st = pcall(getAudioStreamState, playsound)
        st = ok and tonumber(st) or nil
        return st ~= nil and st == (tonumber(moon_status and moon_status.PLAYING) or 1)
    end
    return false
end
local function restartSelectedPianoTilesMusic()
    local path = pt_selectedSongPath
    if not path or path == "" then return false end
        if pt_cfg.radio_mode and not pt_selectedIsRadio then return false end

    lastMusicCheck = 0
    if pt_selectedIsRadio then
                                if Radio.path == path and radioStreamPlaying() then
            radioPlaybackWanted = true
            return true
        end
        local ok = openAndPlayMusic(path, true, nil)
        return ok and true or false
    end
        return openAndPlayMusic(path, true) and true or false
end
local function radioInspect(now, age)
    if playMethod == "BASS" then
        if not (hasBass and bassHandle) then return "no handle" end
        if not bass.BASS_ChannelIsActive then return nil end
        local okS, st = pcall(bass.BASS_ChannelIsActive, bassHandle)
        st = okS and tonumber(st) or nil
        if st == nil then return nil end
        if st == 0 then return "stream ended" end
        if st == 4 then
                        Radio.badSince = nil; Radio.lastPos = nil; Radio.lastPosAt = now; Radio.lastAudibleAt = now
            return nil
        end
        if st == 3 then
            local okP, res = pcall(bass.BASS_ChannelPlay, bassHandle, false)
            if not okP or res == false or tonumber(res) == 0 then return "cannot resume" end
            Radio.badSince = nil; Radio.lastPos = nil; Radio.lastPosAt = now; Radio.lastAudibleAt = now
            return nil
        end
        if st == 2 then
                                    Radio.badSince = Radio.badSince or now
            Radio.lastPos = nil; Radio.lastPosAt = now; Radio.lastAudibleAt = now
            if now - Radio.badSince >= Radio.STALL_SECONDS then return "stalled" end
            return nil
        end
        Radio.badSince = nil
                if bass.BASS_ChannelGetPosition then
            local okP, pos = pcall(bass.BASS_ChannelGetPosition, bassHandle, 0)
            pos = okP and tonumber(pos) or nil
            if pos ~= nil then
                if Radio.lastPos == nil or pos ~= Radio.lastPos then
                    Radio.lastPos = pos; Radio.lastPosAt = now
                elseif now - Radio.lastPosAt >= Radio.STALL_SECONDS then
                    return "no data"
                end
            end
        end
                if bass.BASS_ChannelGetLevel and (tonumber(pt_cfg.volume_percent) or 80) > 0 then
            local okL, lv = pcall(bass.BASS_ChannelGetLevel, bassHandle)
            lv = okL and tonumber(lv) or nil
            if lv and lv >= 0 and lv ~= 0xFFFFFFFF then
                local l, r = lv % 65536, math.floor(lv / 65536) % 65536
                if l > 4 or r > 4 then
                    Radio.lastAudibleAt = now
                elseif now - Radio.lastAudibleAt >= Radio.SILENT_SECONDS then
                    return "silence"
                end
            end
        end
        return nil
    elseif playMethod == "MOON" then
        if playsound == nil then return "no handle" end
        if type(getAudioStreamState) ~= "function" then
            if age >= Radio.MOON_REFRESH_SECONDS then return "refresh" end
            return nil
        end
        local okS, st = pcall(getAudioStreamState, playsound)
        st = okS and tonumber(st) or nil
        local PLAYING = tonumber(moon_status and moon_status.PLAYING) or 1
        local STOPPED = tonumber(moon_status and moon_status.STOPPED) or 0
        local PAUSED  = moon_status and tonumber(moon_status.PAUSED) or nil
        if st == nil or st == -1 or st == STOPPED then return "stream ended" end
        if st == PLAYING then
            Radio.badSince = nil
                                    if age >= Radio.MOON_REFRESH_SECONDS then return "refresh" end
            return nil
        end
        if PAUSED and st == PAUSED then Radio.badSince = nil; return nil end
        Radio.badSince = Radio.badSince or now
        if now - Radio.badSince >= Radio.STALL_SECONDS then return "stalled" end
        return nil
    end
    return "unknown backend"
end
local function radioWatchdog(now)
    if now < Radio.retryAt then return end
    Radio.retryAt = now + Radio.CHECK_INTERVAL
    local frozen = (now - Radio.lastCheckAt) > Radio.MAX_GAP
    Radio.lastCheckAt = now

    local reason, age = nil, now - Radio.startedAt
    if not pt_musicPlaying then
        reason = "stopped"
    elseif Radio.path ~= pt_selectedSongPath then
        reason = "station changed"
    elseif frozen then
                Radio.badSince = nil; Radio.lastPos = nil; Radio.lastPosAt = now; Radio.lastAudibleAt = now
    elseif age >= Radio.GRACE_SECONDS then
        reason = radioInspect(now, age)
    end

    if not reason then
        if age >= 60.0 then Radio.troubleCount = 0 end
        return
    end

    local preferBass = nil
    if reason ~= "refresh" and reason ~= "stopped" and reason ~= "station changed" then
        Radio.troubleCount = Radio.troubleCount + 1
                if Radio.troubleCount >= 3 and Radio.goodBackend then
            preferBass = (Radio.goodBackend ~= "BASS")
            Radio.troubleCount = 0
        end
    end
            openAndPlayMusic(pt_selectedSongPath, true, preferBass, true)
end
local function getWeaponFromBullet(bd)
    if not bd then return nil end
    local ok, v = pcall(function() return bd.weapon end) if ok and v then return v end
    ok, v = pcall(function() return bd.weaponId end) if ok and v then return v end
    ok, v = pcall(function() return bd.weapon_id end) if ok and v then return v end
    ok, v = pcall(function() return bd.w end) if ok and v then return v end
    return nil
end
local function getTargetFromBullet(bd)
    if not bd then return nil end
    local ok,t = pcall(function() return bd.target end)
    if ok and t then
        local okx, vx = pcall(function() return t.x end)
        local oky, vy = pcall(function() return t.y end)
        local okz, vz = pcall(function() return t.z end)
        if okx and oky and okz and is_finite(vx) and is_finite(vy) and is_finite(vz) then return { x = vx, y = vy, z = vz } end
    end
    local okx, vx = pcall(function() return bd.targetX end)
    local oky, vy = pcall(function() return bd.targetY end)
    local okz, vz = pcall(function() return bd.targetZ end)
    if okx and oky and okz and is_finite(vx) and is_finite(vy) and is_finite(vz) then return { x = vx, y = vy, z = vz } end
    return nil
end
local function projectWorld(x,y,z)
    local ok, sx, sy, sZ = convert3DCoordsToScreenEx(x,y,z,false,false)
    if not ok then return false, nil, nil, nil end
    if not is_finite(sx) or not is_finite(sy) or not is_finite(sZ) then return false, nil, nil, nil end
    if sZ <= 0 then return false, nil, nil, nil end
    return true, sx, sy, sZ
end
local function initGrid(wx, wy, wz)
    gridOrigin = { x = wx, y = wy, z = wz }
    lastGridOrigin = { x = wx, y = wy, z = wz }
    local camX, camY, camZ = getActiveCameraCoordinates()
    local dx,dy,dz = camX - wx, camY - wy, camZ - wz
    local ndx,ndy,ndz = vec_norm(dx,dy,dz)
    local upX,upY,upZ = 0,0,1
    if math.abs(ndx*upX + ndy*upY + ndz*upZ) > 0.98 then upX,upY,upZ = 0,1,0 end
    local rx,ry,rz = vec_cross(upX,upY,upZ, ndx,ndy,ndz)
    rx,ry,rz = vec_norm(rx,ry,rz)
    gridRight = { x = rx, y = ry, z = rz }
    local angle = math.rad(pt_cfg.visual_tilt_degrees)
    local ux,uy,uz = gridRight.x, gridRight.y, gridRight.z
    local cosA, sinA = math.cos(angle), math.sin(angle)
    local vx, vy, vz = ndx, ndy, ndz
    local crossX = uy * vz - uz * vy
    local crossY = uz * vx - ux * vz
    local crossZ = ux * vy - uy * vx
    local dot = ux*vx + uy*vy + uz*vz
    local rdx = vx * cosA + crossX * sinA + ux * dot * (1 - cosA)
    local rdy = vy * cosA + crossY * sinA + uy * dot * (1 - cosA)
    local rdz = vz * cosA + crossZ * sinA + uz * dot * (1 - cosA)
    rdx, rdy, rdz = vec_norm(rdx, rdy, rdz)
    gridDirToCam = { x = rdx, y = rdy, z = rdz }
    local ux2,uy2,uz2 = vec_cross(gridRight.x, gridRight.y, gridRight.z, gridDirToCam.x, gridDirToCam.y, gridDirToCam.z)
    ux2,uy2,uz2 = vec_norm(ux2,uy2,uz2)
    gridUp = { x = ux2, y = uy2, z = uz2 }
    gridSpacing = (pt_cfg.tile_width * 0.01) * pt_cfg.grid_scale
    pt_gridInitialized = true
    pt_tilesStopped = false
    pt_stoppedAtTile = nil
    pt_gamePausedForFail = false
    pt_pauseStartTime = nil
    pt_firstFailTile = nil
    pt_endOnFail = false
    pt_gameOver = false
    pt_buttonsShown = false
end
local function recomputeScreen()
    if not pt_gridInitialized then return false end
    local topDepth = -30.0; local bottomDepth = 6.0
    local topScale = 0.6; local bottomScale = 1.0
    local halfWidth = (math.max(1, pt_cfg.lanes) * gridSpacing) / 2 * (pt_cfg.visual_scale or 1.0)
    local topHalf = halfWidth * topScale
    local bottomHalf = halfWidth * bottomScale
    local topCx = gridOrigin.x + gridDirToCam.x * topDepth
    local topCy = gridOrigin.y + gridDirToCam.y * topDepth
    local topCz = gridOrigin.z + gridDirToCam.z * topDepth
    local botCx = gridOrigin.x + gridDirToCam.x * bottomDepth
    local botCy = gridOrigin.y + gridDirToCam.y * bottomDepth
    local botCz = gridOrigin.z + gridDirToCam.z * bottomDepth
    local topLeftX  = topCx - gridRight.x * topHalf
    local topLeftY  = topCy - gridRight.y * topHalf
    local topLeftZ  = topCz - gridRight.z * topHalf
    local topRightX = topCx + gridRight.x * topHalf
    local topRightY = topCy + gridRight.y * topHalf
    local topRightZ = topCz + gridRight.z * topHalf
    local botLeftX  = botCx - gridRight.x * bottomHalf
    local botLeftY  = botCy - gridRight.y * bottomHalf
    local botLeftZ  = botCz - gridRight.z * bottomHalf
    local botRightX = botCx + gridRight.x * bottomHalf
    local botRightY = botCy + gridRight.y * bottomHalf
    local botRightZ = botCz + gridRight.z * bottomHalf
    local ok_tl, sx_tl, sy_tl = projectWorld(topLeftX, topLeftY, topLeftZ)
    local ok_tr, sx_tr, sy_tr = projectWorld(topRightX, topRightY, topRightZ)
    local ok_bl, sx_bl, sy_bl = projectWorld(botLeftX, botLeftY, botLeftZ)
    local ok_br, sx_br, sy_br = projectWorld(botRightX, botRightY, botRightZ)
    screenTopLeft, screenTopRight, screenBotLeft, screenBotRight = nil, nil, nil, nil
    laneTop, laneBot = {}, {}
    if ok_tl and ok_tr and ok_br and ok_bl then
        screenTopLeft = { x = sx_tl, y = sy_tl }
        screenTopRight = { x = sx_tr, y = sy_tr }
        screenBotLeft = { x = sx_bl, y = sy_bl }
        screenBotRight = { x = sx_br, y = sy_br }
        for i=1,pt_cfg.lanes do
            local idx = (i - 0.5) / pt_cfg.lanes
            laneTop[i] = { x = lerp(sx_tl, sx_tr, idx), y = lerp(sy_tl, sy_tr, idx) }
            laneBot[i] = { x = lerp(sx_bl, sx_br, idx), y = lerp(sy_bl, sy_br, idx) }
        end
        return true
    end
    return false
end
local function createTile(lane, spawnDelay)
    if #pt_tiles >= pt_cfg.max_tiles then return end
    lane = clamp(lane or math.random(1, pt_cfg.lanes), 1, pt_cfg.lanes)
    local isLong = pt_cfg.use_long_tiles and (math.random(1,100) <= (pt_cfg.long_tile_chance or 0))
    local duration = spawnDistance / math.max(0.0001, worldMoveSpeed * pt_cfg.tile_speed)
    if isLong then duration = duration * (1 / (pt_cfg.long_tile_speed_mult or 1.0)) end
    local spawnTime = os.clock() + (spawnDelay or 0)
    local r, g, b = pt_cfg.tile_color[1], pt_cfg.tile_color[2], pt_cfg.tile_color[3]
    if pt_cfg.random_tile_color then
        r, g, b = math.random(), math.random(), math.random()
    end
    local fa_r_init = (pt_cfg.tile_fa_color and pt_cfg.tile_fa_color[1]) or 1.0
    local fa_g_init = (pt_cfg.tile_fa_color and pt_cfg.tile_fa_color[2]) or 1.0
    local fa_b_init = (pt_cfg.tile_fa_color and pt_cfg.tile_fa_color[3]) or 1.0
    if pt_cfg.random_fa_color then
        fa_r_init, fa_g_init, fa_b_init = math.random(), math.random(), math.random()
    end
    local fa_glyph_init = pt_cfg.tile_fa_glyph or ""
    local fa_icon_init  = pt_cfg.tile_fa_icon  or ""
    if pt_cfg.use_fa_icons and pt_cfg.random_fa_icon and #icon_list > 0 then
        local ri = icon_list[math.random(1, #icon_list)]
        fa_glyph_init = ri.glyph or ""
        fa_icon_init  = ri.key   or ""
    end
    local now_c = os.clock()
    local color_scatter    = math.random() * clamp(tonumber(pt_cfg.random_tile_color_interval) or 2.0, 0.2, 60)
    local fa_color_scatter = math.random() * clamp(tonumber(pt_cfg.random_fa_color_interval)   or 2.0, 0.2, 60)
    local fa_icon_scatter  = math.random() * clamp(tonumber(pt_cfg.random_fa_icon_interval)    or 3.0, 0.2, 60)
    local t = {
        id = nextTileId, lane = lane, spawnTime = spawnTime, duration = duration,
        type = isLong and "long" or "normal", hitsRemain = isLong and (pt_cfg.long_tile_hits or 3) or 1,
        r = r, g = g, b = b, alpha = (pt_cfg.tile_color[4] ~= nil) and pt_cfg.tile_color[4] or 0.98,
        fa_r = fa_r_init, fa_g = fa_g_init, fa_b = fa_b_init,
        fa_glyph = fa_glyph_init, fa_icon = fa_icon_init,
        nextColorChange  = now_c + color_scatter,
        nextFaColorChange= now_c + fa_color_scatter,
        nextFaIconChange = now_c + fa_icon_scatter,
        hit = false, wasHit = false, red = false, handledReached = false,
        _stoppedTT = nil, removeOnResume = false, toRemoveAfterFade = false,
        tile_img = nil,
    }
    if pt_cfg.random_tile_image and #pt_tileImages > 0 then
        local ri = pt_tileImages[math.random(1, #pt_tileImages)]
        t.tile_img = ri.path
    end
    nextTileId = nextTileId + 1; table.insert(pt_tiles, t)
end
local function spawnPattern()
    if #pt_tiles >= pt_cfg.max_tiles then return end
    local r = math.random()
    if r <= 0.6 or pt_cfg.lanes < 2 then
        local lane = math.random(1, pt_cfg.lanes)
        local tiny_delay = 0; local now = os.clock()
        for _,v in ipairs(pt_tiles) do if math.abs((v.spawnTime or now) - now) < 0.08 then tiny_delay = 0.06 + math.random() * 0.08; break end end
        createTile(lane, tiny_delay)
    else
        local l1 = math.random(1, pt_cfg.lanes)
        local cand = {}
        for i=1,pt_cfg.lanes do if math.abs(i-l1) >= 2 then table.insert(cand,i) end end
        if #cand == 0 then createTile(l1) else
            local l2 = cand[math.random(1,#cand)]
            createTile(l1, 0); createTile(l2, 0.06 + math.random() * 0.12)
        end
    end
end
local function computeButtonsWorld()
    local origin = gridOrigin or lastGridOrigin
    if origin then
        local offsetZ = -3.0
        local buttonLaneRef = 6
        local offsetX = (gridSpacing or (pt_cfg.tile_width * 0.01 * pt_cfg.grid_scale)) * 1.2 * (buttonLaneRef / 4)
        local offsetY = -1.0
        pt_gameButtons.left.world = {
            x = origin.x + (-gridRight.x * offsetX) + (gridUp.x * offsetY) + (gridDirToCam.x * offsetZ),
            y = origin.y + (-gridRight.y * offsetX) + (gridUp.y * offsetY) + (gridDirToCam.y * offsetZ),
            z = origin.z + (-gridRight.z * offsetX) + (gridUp.z * offsetY) + (gridDirToCam.z * offsetZ),
        }
        pt_gameButtons.right.world = {
            x = origin.x + (gridRight.x * offsetX) + (gridUp.x * offsetY) + (gridDirToCam.x * offsetZ),
            y = origin.y + (gridRight.y * offsetX) + (gridUp.y * offsetY) + (gridDirToCam.y * offsetZ),
            z = origin.z + (gridRight.z * offsetX) + (gridUp.z * offsetY) + (gridDirToCam.z * offsetZ),
        }
        local okL, sxL, syL = projectWorld(pt_gameButtons.left.world.x, pt_gameButtons.left.world.y, pt_gameButtons.left.world.z)
        local okR, sxR, syR = projectWorld(pt_gameButtons.right.world.x, pt_gameButtons.right.world.y, pt_gameButtons.right.world.z)
        if okL and okR then
            pt_storedButtonScreen.left.x, pt_storedButtonScreen.left.y = sxL, syL
            pt_storedButtonScreen.right.x, pt_storedButtonScreen.right.y = sxR, syR
            pt_gameButtons.left.screen = { x = sxL, y = syL }; pt_gameButtons.right.screen = { x = sxR, y = syR }
            return true
        end
    end
    local Sx, Sy = getScreenResolution()
    local gap = 140 * (pt_cfg.visual_scale or 1.0)
    pt_storedButtonScreen.left.x  = Sx/2 - gap/2; pt_storedButtonScreen.left.y  = Sy/2
    pt_storedButtonScreen.right.x = Sx/2 + gap/2; pt_storedButtonScreen.right.y = Sy/2
    pt_gameButtons.left.world = nil; pt_gameButtons.right.world = nil
    pt_gameButtons.left.screen = { x = pt_storedButtonScreen.left.x, y = pt_storedButtonScreen.left.y }
    pt_gameButtons.right.screen = { x = pt_storedButtonScreen.right.x, y = pt_storedButtonScreen.right.y }
    return false
end
local function closeSettingsWindow(keepRadio)
    pt_windowSettings[0] = false
    pcall(function() imgui.SwitchContext(); imgui.GetIO().IniFilename = nil; lastGridColorChange = os.clock() end)
    if pt_musicPlaying then
                local keep = keepRadio == true and pt_cfg.radio_mode and pt_selectedIsRadio and radioPlaybackWanted
        if not keep then stopMusic() end
    end
end
local function openSettingsWindow()
    pt_windowSettings[0] = true
    pcall(function() imgui.SwitchContext(); imgui.GetIO().IniFilename = nil; lastGridColorChange = os.clock() end)
    pcall(function() scanFolders() end)
end
local function toggleSettingsWindow()
    if pt_windowSettings[0] then closeSettingsWindow() else openSettingsWindow() end
end
local HUD_CR_ADDR = 0x58E020
local function setGtaCrosshairVisible(on)
    pcall(memory.setuint8, HUD_CR_ADDR, on and 0x83 or 0xC3, true)
end
local function testButtonHit(bullet)
    if not (pt_gameButtons.left.world or pt_gameButtons.right.world or pt_storedButtonScreen.left.x) then return false end
    local target = getTargetFromBullet(bullet)
    if not target then return false end
    if pt_gameButtons.left.world then
        local okL, sxL, syL = projectWorld(pt_gameButtons.left.world.x, pt_gameButtons.left.world.y, pt_gameButtons.left.world.z)
        if okL then pt_gameButtons.left.screen = { x = sxL, y = syL } end
    end
    if pt_gameButtons.right.world then
        local okR, sxR, syR = projectWorld(pt_gameButtons.right.world.x, pt_gameButtons.right.world.y, pt_gameButtons.right.world.z)
        if okR then pt_gameButtons.right.screen = { x = sxR, y = syR } end
    end
    if not pt_gameButtons.left.screen then pt_gameButtons.left.screen = { x = pt_storedButtonScreen.left.x, y = pt_storedButtonScreen.left.y } end
    if not pt_gameButtons.right.screen then pt_gameButtons.right.screen = { x = pt_storedButtonScreen.right.x, y = pt_storedButtonScreen.right.y } end
    local okT, tx, ty = projectWorld(target.x, target.y, target.z)
    if not okT then local Sx,Sy = getScreenResolution(); tx,ty = Sx/2, Sy/2 end
    local function inside(btn)
        return tx >= btn.screen.x - btn.w/2 and tx <= btn.screen.x + btn.w/2 and ty >= btn.screen.y - btn.h/2 and ty <= btn.screen.y + btn.h/2
    end
    if inside(pt_gameButtons.left) then
                        restartSelectedPianoTilesMusic()
        pt_tiles = {}; pt_missTexts = {}; pt_score = 0; pt_combo = 0; pt_misses = 0; pt_initialMarkers = {}
        pt_tilesStopped = false; pt_gamePausedForFail = false; pt_pauseStartTime = nil; pt_firstFailTile = nil; pt_gameOver = false; pt_buttonsShown = false
        if lastGridOrigin then initGrid(lastGridOrigin.x, lastGridOrigin.y, lastGridOrigin.z); createTile(1); lastSpawn = os.clock() end
        pt_isScriptRunning = true
        return true
    elseif inside(pt_gameButtons.right) then
        pt_isScriptRunning = false; pt_gamePausedForFail = false; pt_gameOver = false; pt_buttonsShown = false
        pt_tiles = {}; pt_missTexts = {}; pt_initialMarkers = {}; pt_gridInitialized = false; gridOrigin = nil; pt_tilesStopped = false
        stopMusic(); openSettingsWindow()
        setGtaCrosshairVisible(true)
        return true
    end
    return false
end
local function spawnMissAtScreen(tx, ty)
    table.insert(pt_missTexts, { x = tx + math.random(-6,6), y = ty + math.random(-6,6), start = os.clock(), life = 1.0 })
end
local function processHit(bullet)
    if not pt_gridInitialized then return false end
    local weapon = getWeaponFromBullet(bullet)
    if not weapon or weapon ~= pt_cfg.deagle_weapon_id then return false end
    local target = getTargetFromBullet(bullet)
    if not target then return false end
    local ok, tx, ty = projectWorld(target.x, target.y, target.z)
    if not ok then local Sx,Sy = getScreenResolution(); tx,ty = Sx/2, Sy/2 end
    local nearest, best = nil, nil
    for i=#pt_tiles,1,-1 do
        local t = pt_tiles[i]
        local now = os.clock()
        local tt = clamp((now - t.spawnTime) / math.max(0.0001, t.duration), 0, 1)
        local lane = t.lane
        if laneTop[lane] and laneBot[lane] then
            local sxPos = lerp(laneTop[lane].x, laneBot[lane].x, tt)
            local syPos = lerp(laneTop[lane].y, laneBot[lane].y, tt)
            local dx = tx - sxPos; local dy = ty - syPos
            local d2 = dx*dx + dy*dy
            if not best or d2 < best then best = d2; nearest = i end
        end
    end
    if nearest then
        local t = pt_tiles[nearest]
        local now = os.clock()
        local tt = clamp((now - t.spawnTime) / math.max(0.0001, t.duration), 0, 1)
        local lane = t.lane
        if laneTop[lane] and laneBot[lane] and screenTopRight and screenTopLeft and screenBotRight and screenBotLeft then
            local sxPos = lerp(laneTop[lane].x, laneBot[lane].x, tt)
            local syPos = lerp(laneTop[lane].y, laneBot[lane].y, tt)
            local wTop = math.abs(screenTopRight.x - screenTopLeft.x) / pt_cfg.lanes
            local wBot = math.abs(screenBotRight.x - screenBotLeft.x) / pt_cfg.lanes
            local w = lerp(wTop, wBot, tt) * 0.9
            local h = (t.type=="long") and (w * 0.75 * pt_cfg.long_tile_hits) or (w * 0.75)
            local left, right = sxPos - w/2, sxPos + w/2
            local top, bottom = syPos - h/2, syPos + h/2
            if tx >= left and tx <= right and ty >= top and ty <= bottom then
                t.hit = true; t.hitTime = now; t.wasHit = true
                if t.type == "long" then
                    t.hitsRemain = (t.hitsRemain or pt_cfg.long_tile_hits) - 1
                    if t.hitsRemain <= 0 then t.toRemoveAfterFade = true; t.hitTime = now end
                else t.toRemoveAfterFade = true; t.hitTime = now end
                pt_score = pt_score + 100 + pt_combo * 10; pt_combo = pt_combo + 1
                if pt_combo > pt_currentSessionMaxCombo then pt_currentSessionMaxCombo = pt_combo end
                local base_r = math.max(5, w * 0.15) * hit_circle_shrink_mult
                table.insert(pt_hitCircles, { x = tx, y = ty, start = now, life = hit_circle_life, r0 = base_r, r1 = base_r * hit_circle_growth })
                return true
            end
        end
    end
    spawnMissAtScreen(tx, ty)
    pt_combo = 0; pt_misses = pt_misses + 1
    if pt_misses >= pt_cfg.max_misses and not pt_gamePausedForFail and not pt_gameOver then
        saveGameRecord(S("Проигрыш"))
        pt_isScriptRunning = false; pt_gameOver = true; pt_buttonsShown = true
        if pt_cfg.auto_speed_increase and pt_autoSpeedInitial then
            pt_cfg.tile_speed = pt_autoSpeedInitial; saveSettings()
        end
        pt_autoSpeedInitial = nil
        computeButtonsWorld(); pt_initialMarkers = {}; pt_tiles = {}; stopMusic()
        setGtaCrosshairVisible(true)
    end
    return false
end
ptOnSendBulletSync = function(data)
    if pt_buttonsShown and (pt_gameButtons.left.world or pt_gameButtons.left.screen) then
        local ok,res = pcall(function() return testButtonHit(data) end)
        if ok and res then return end
        return
    end
    if pt_tilesStopped or not pt_isScriptRunning then return end
    if not pt_gridInitialized then
        local target = getTargetFromBullet(data)
        if target then
            local ox, oy, oz = target.x, target.y, target.z
            pcall(function()
                if data.origin and is_finite(data.origin.x) and is_finite(data.origin.y) and is_finite(data.origin.z) then
                    ox, oy, oz = data.origin.x, data.origin.y, data.origin.z
                end
            end)
            table.insert(pt_initialMarkers, {
                origin = { x = ox, y = oy, z = oz },
                base_origin = { x = target.x, y = target.y, z = target.z }
            })
            initGrid(target.x, target.y, target.z)
            setGtaCrosshairVisible(false)
            createTile(math.random(1, pt_cfg.lanes))
            lastSpawn = os.clock()
            restartSelectedPianoTilesMusic()
        end
        return
    end
    pcall(function() processHit(data) end)
end
local function drawCrossAt(DL, px, py, arm, gap, thick, col_u32, ocol_u32, outline_px, dot_sz, dcol_u32)
    local half = thick * 0.5
    if outline_px and outline_px > 0 then
        local oth = outline_px
        DL:AddRectFilled(imgui.ImVec2(px - half - oth, py - gap - arm - oth),
                         imgui.ImVec2(px + half + oth, py - gap), ocol_u32)
        DL:AddRectFilled(imgui.ImVec2(px - half - oth, py + gap),
                         imgui.ImVec2(px + half + oth, py + gap + arm + oth), ocol_u32)
        DL:AddRectFilled(imgui.ImVec2(px - gap - arm - oth, py - half - oth),
                         imgui.ImVec2(px - gap, py + half + oth), ocol_u32)
        DL:AddRectFilled(imgui.ImVec2(px + gap, py - half - oth),
                         imgui.ImVec2(px + gap + arm + oth, py + half + oth), ocol_u32)
    end
    DL:AddRectFilled(imgui.ImVec2(px - half, py - gap - arm), imgui.ImVec2(px + half, py - gap), col_u32)
    DL:AddRectFilled(imgui.ImVec2(px - half, py + gap),       imgui.ImVec2(px + half, py + gap + arm), col_u32)
    DL:AddRectFilled(imgui.ImVec2(px - gap - arm, py - half), imgui.ImVec2(px - gap, py + half), col_u32)
    DL:AddRectFilled(imgui.ImVec2(px + gap, py - half),       imgui.ImVec2(px + gap + arm, py + half), col_u32)
    if dot_sz and dot_sz > 0 then
        DL:AddCircleFilled(imgui.ImVec2(px, py), dot_sz, dcol_u32, 16)
    end
end
local function getGtaCrosshairWorldPos()
    if not CBUGER_NATIVE_READY then return nil end
    local ped = PLAYER_PED
    local ok_ped, exists = pcall(doesCharExist, ped)
    if not ok_ped or not exists then return nil end
    local ok, wx, wy, wz = pcall(function()
        local vec_out = ffi.new("float[3]")
        local tmp_vec = ffi.new("float[3]")
        ffi.cast("void (__thiscall*)(void*, float, float, float, float, float*, float*)", 0x514970)(
            ffi.cast("void*", 0xB6F028),
            500.0,
            tmp_vec[0], tmp_vec[1], tmp_vec[2],
            tmp_vec,
            vec_out
        )
        return vec_out[0], vec_out[1], vec_out[2]
    end)
    if not ok or not wx or not wy or not wz then return nil end
    return wx, wy, wz
end
local function getGtaCrosshairScreenPos()
    local wx, wy, wz = getGtaCrosshairWorldPos()
    if not wx or not wy or not wz then return nil end
    if not is_finite(wx) or not is_finite(wy) or not is_finite(wz) then return nil end
    local ok, sx, sy = pcall(function()
        local ok2, ssx, ssy = convert3DCoordsToScreenEx(wx, wy, wz, false, false)
        if ok2 then return ssx, ssy end
        return nil, nil
    end)
    if ok and sx and sy then return sx, sy end
    local ok2, sx2, sy2 = pcall(function() return convert3DCoordsToScreen(wx, wy, wz) end)
    if ok2 and sx2 and sy2 then return sx2, sy2 end
    return nil
end
local _locked_x = nil
local _locked_y = nil
local function getCrosshairDrawPos(screen_w, screen_h)
    if not _locked_x or not _locked_y then
        local sx, sy = getGtaCrosshairScreenPos()
        if sx and sy and is_finite(sx) and is_finite(sy)
            and sx > 0 and sx < screen_w and sy > 0 and sy < screen_h then
            _locked_x = sx
            _locked_y = sy
        else
            return screen_w * 0.5 + (pt_cfg.crosshair_offset_x or 0),
                   screen_h * 0.5 + (pt_cfg.crosshair_offset_y or 0)
        end
    end
    return _locked_x + (pt_cfg.crosshair_offset_x or 0),
           _locked_y + (pt_cfg.crosshair_offset_y or 0)
end
