end)
function drawAnimatedTabGlow(dl, minp, maxp, t)
    if not dl or not minp or not maxp then return end
    local fx = CBUGER_GET_EFFECTS()
    if not fx then return end
    local waves_on = fx.waves_on and fx.waves_on[0]
    if not waves_on then return end
    local x1, y1 = minp.x, minp.y
    local x2, y2 = maxp.x, maxp.y
    if x2 <= x1 or y2 <= y1 then return end
    local w = x2 - x1
    local h = y2 - y1
    local perim = 2 * (w + h)
    if perim <= 0 then return end
    local speed = CBUGER_GET_EFFECT_SPEED(1.0)
    local mode  = fx.waves_var and tonumber(fx.waves_var[0]) or 0
    local wc    = fx.waves_color or {0.0, 0.8, 1.0, 1.0}
    local wr, wg, wb, wa = wc[1] or 0.0, wc[2] or 0.8, wc[3] or 1.0, wc[4] or 1.0
    local data = type(CB) == 'table' and CB.Data
    local nfn  = data and data.nfn
    if nfn and nfn.draw_wave_strings then
        nfn.draw_wave_strings(dl, minp, maxp, wc, CBUGER_GET_INTERFACE_ALPHA())
    end
    local phase = ((tonumber(t) or os.clock()) * 85.0 * speed) % perim
    if mode % 2 == 1 then phase = (perim - phase) % perim end
    local base = imgui.ImVec4(wr, wg, wb, wa)
    local glow = imgui.ImVec4(math.min(1.0, wr * 0.55), math.min(1.0, wg * 0.55), math.min(1.0, wb * 0.55), wa)
    dl:AddRect(
        imgui.ImVec2(x1 - 1, y1 - 1),
        imgui.ImVec2(x2 + 1, y2 + 1),
        PT_U32(imgui.ImVec4(base.x, base.y, base.z, 0.25 * base.w)),
        5.0, 0, 2.0
    )
    dl:AddRect(
        imgui.ImVec2(x1 - 2, y1 - 2),
        imgui.ImVec2(x2 + 2, y2 + 2),
        PT_U32(imgui.ImVec4(glow.x, glow.y, glow.z, 0.10 * glow.w)),
        5.0, 0, 3.0
    )
    local segs = 42
    local function pointAt(s)
        s = s % perim
        if s < w then return x1 + s, y1 end
        s = s - w
        if s < h then return x2, y1 + s end
        s = s - h
        if s < w then return x2 - s, y2 end
        s = s - w
        return x1, y2 - s
    end
    for i = 0, segs - 1 do
        local s0 = (perim * i) / segs
        local s1 = (perim * (i + 1)) / segs
        local mx = (s0 + s1) * 0.5
        local dist = math.abs(((mx - phase + perim * 0.5) % perim) - perim * 0.5)
        local a = math.max(0.0, 1.0 - dist / (perim * 0.09))
        if a > 0.01 then
            local p0x, p0y = pointAt(s0)
            local p1x, p1y = pointAt(s1)
            local c = imgui.ImVec4(base.x, base.y, base.z, (0.12 + 0.78 * a) * base.w)
            dl:AddLine(imgui.ImVec2(p0x, p0y), imgui.ImVec2(p1x, p1y), PT_U32(c), 2.4)
        end
    end
end
imgui.OnFrame(
  function() return pt_isScriptRunning or pt_windowSettings[0] or pt_gameOver or pt_buttonsShown or pt_crosshairDragMode end,
  function(self)
    if pt_cfg.use_fa_icons and not fa and not fa_warned_missing then
        fa_warned_missing = true
        pcall(function()
            sampAddChatMessage([=[ [PianoTiles] FA-eeiiee ia caa?oceeenu: i?iaa?u moonloader\lib\fAwesome6_solid.lua eee moonloader\lib\fAwesome6.lua ]=], -1)
        end)
    end
    local now = os.clock()
    local sx, sy = getScreenResolution()
    self.HideCursor = (pt_isScriptRunning or pt_gameOver or pt_buttonsShown)
    imgui.SetNextWindowPos(imgui.ImVec2(0, 0), imgui.Cond.Always)
    imgui.SetNextWindowSize(imgui.ImVec2(sx, sy), imgui.Cond.Always)
    imgui.SetNextWindowBgAlpha(0.0)
    local overlay_flags = imgui.WindowFlags.NoDecoration
        + imgui.WindowFlags.NoBackground
        + imgui.WindowFlags.NoMove
        + imgui.WindowFlags.NoInputs
    local begin_ok = imgui.Begin('##dmx_overlay', nil, overlay_flags)
    if begin_ok then
        pcall(function()
        local DL = imgui.GetWindowDrawList()
    if pt_cfg.grid_color_cycle_enabled and pt_cfg.grid_color_cycle_interval and pt_cfg.grid_color_cycle_interval > 0 then
        local interval = clamp(tonumber(pt_cfg.grid_color_cycle_interval) or 0, 1, 100)
        if now - lastGridColorChange >= interval then
            lastGridColorChange = now
            local a = pt_cfg.grid_bg[4] or 1.0
            pt_cfg.grid_bg[1] = math.random(); pt_cfg.grid_bg[2] = math.random(); pt_cfg.grid_bg[3] = math.random(); pt_cfg.grid_bg[4] = a
            saveSettings()
        end
    end
    if pt_cfg.random_tile_color or pt_cfg.random_fa_color or (pt_cfg.use_fa_icons and pt_cfg.random_fa_icon) then
        local tile_interval    = clamp(tonumber(pt_cfg.random_tile_color_interval) or 2.0, 0.2, 60)
        local fa_col_interval  = clamp(tonumber(pt_cfg.random_fa_color_interval)   or 2.0, 0.2, 60)
        local fa_icon_interval = clamp(tonumber(pt_cfg.random_fa_icon_interval)    or 3.0, 0.2, 60)
        for _, tile in ipairs(pt_tiles) do
            if pt_cfg.random_tile_color and tile.nextColorChange and now >= tile.nextColorChange then
                tile.r = math.random(); tile.g = math.random(); tile.b = math.random()
                tile.nextColorChange = now + tile_interval
            end
            if pt_cfg.random_fa_color and tile.nextFaColorChange and now >= tile.nextFaColorChange then
                tile.fa_r = math.random(); tile.fa_g = math.random(); tile.fa_b = math.random()
                tile.nextFaColorChange = now + fa_col_interval
            end
            if pt_cfg.use_fa_icons and pt_cfg.random_fa_icon and #icon_list > 0
               and tile.nextFaIconChange and now >= tile.nextFaIconChange then
                local ri = icon_list[math.random(1, #icon_list)]
                tile.fa_glyph = ri.glyph or ""
                tile.fa_icon  = ri.key   or ""
                tile.nextFaIconChange = now + fa_icon_interval
            end
        end
    end
    if not pt_gridInitialized then
        if pt_isScriptRunning then
            local f = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
            DL:AddTextFontPtr(f, 18.0 * pt_cfg.visual_scale, imgui.ImVec2(18,18), PT_OVERLAY_U32(imgui.ImVec4(1,1,1,1)), S("Ожидание первого нажатия для начала игры"))
            DL:AddTextFontPtr(f, 16.0 * pt_cfg.visual_scale, imgui.ImVec2(18, sy-36), PT_OVERLAY_U32(imgui.ImVec4(1,1,1,1)), string.format("Score: %d   Combo: %d   Misses: %d/%d", pt_score, pt_combo, pt_misses, pt_cfg.max_misses))
        end
        return
    end
    if not self._last then self._last = now end
    local dt = math.max(1e-4, now - self._last); self._last = now
    travelDuration = spawnDistance / math.max(0.0001, worldMoveSpeed * pt_cfg.tile_speed)
    if pt_gridInitialized then recomputeScreen() end
    if pt_cfg.auto_speed_increase and pt_isScriptRunning and not pt_gamePausedForFail
       and not pt_reloadPaused and not pt_gameOver and not pt_tilesStopped then
        local rate = clamp(tonumber(pt_cfg.speed_increase_rate) or 0.01, 0.001, 2.0)
        local maxSpd = clamp(tonumber(pt_cfg.speed_increase_max) or 4.0, 0.0001, 10.0)
        if pt_cfg.tile_speed < maxSpd then
            pt_cfg.tile_speed = clamp(pt_cfg.tile_speed + rate * dt, 0.0001, maxSpd)
            travelDuration = spawnDistance / math.max(0.0001, worldMoveSpeed * pt_cfg.tile_speed)
        end
    end
    if screenTopLeft and screenTopRight and screenBotRight and screenBotLeft and not pt_gameOver then
        local tex = getTexture(pt_cfg.bg_selected)
        if tex then
            local okImg = pcall(function() DL:AddImageQuad(tex, imgui.ImVec2(screenTopLeft.x, screenTopLeft.y), imgui.ImVec2(screenTopRight.x, screenTopRight.y), imgui.ImVec2(screenBotRight.x, screenBotRight.y), imgui.ImVec2(screenBotLeft.x, screenBotLeft.y)) end)
            if not okImg then
                local bg = pt_cfg.grid_bg
                DL:AddQuadFilled(imgui.ImVec2(screenTopLeft.x, screenTopLeft.y), imgui.ImVec2(screenTopRight.x, screenTopRight.y), imgui.ImVec2(screenBotRight.x, screenBotRight.y), imgui.ImVec2(screenBotLeft.x, screenBotLeft.y), PT_OVERLAY_U32(imgui.ImVec4(bg[1],bg[2],bg[3],bg[4])))
            end
        else
            local bg = pt_cfg.grid_bg
            DL:AddQuadFilled(imgui.ImVec2(screenTopLeft.x, screenTopLeft.y), imgui.ImVec2(screenTopRight.x, screenTopRight.y), imgui.ImVec2(screenBotRight.x, screenBotRight.y), imgui.ImVec2(screenBotLeft.x, screenBotLeft.y), PT_OVERLAY_U32(imgui.ImVec4(bg[1],bg[2],bg[3],bg[4])))
        end
    end
    if screenTopLeft and screenTopRight and screenBotRight and screenBotLeft and not pt_gameOver then
        local ln = pt_cfg.grid_line
        for i=1,pt_cfg.lanes-1 do
            local t = i / pt_cfg.lanes
            local xTop = lerp(screenTopLeft.x, screenTopRight.x, t)
            local yTop = lerp(screenTopLeft.y, screenTopRight.y, t)
            local xBot = lerp(screenBotLeft.x, screenBotRight.x, t)
            local yBot = lerp(screenBotLeft.y, screenBotRight.y, t)
            DL:AddLine(imgui.ImVec2(xTop,yTop), imgui.ImVec2(xBot,yBot), PT_OVERLAY_U32(imgui.ImVec4(ln[1],ln[2],ln[3],ln[4])), 2.0)
        end
    end
    if screenBotLeft and screenBotRight and not pt_gameOver then
        DL:AddLine(imgui.ImVec2(screenBotLeft.x, screenBotLeft.y), imgui.ImVec2(screenBotRight.x, screenBotRight.y), PT_OVERLAY_U32(PT_ac(1.0, 1.0)), 3.0)
    end
    if pt_isScriptRunning and not pt_gamePausedForFail and not pt_gameOver and not pt_tilesStopped and not pt_reloadPaused then
        if now - lastSpawn >= pt_cfg.spawn_interval then lastSpawn = now; spawnPattern() end
    end
    for i=#pt_tiles,1,-1 do
        local t = pt_tiles[i]
        local nowt = os.clock()
        if t.hit and t.hitTime and t.toRemoveAfterFade and (nowt - t.hitTime >= hit_fade_duration) then
            table.remove(pt_tiles, i); goto continue_tiles_loop
        end
        local tt
        if pt_tilesStopped or pt_gamePausedForFail then
            tt = clamp(t._stoppedTT ~= nil and t._stoppedTT or ((nowt - t.spawnTime) / math.max(1e-4, t.duration)), 0, 1)
        elseif pt_reloadPaused and pt_reloadPauseStartTime then
            tt = clamp((pt_reloadPauseStartTime - t.spawnTime) / math.max(1e-4, t.duration), 0, 1)
        else
            tt = clamp((nowt - t.spawnTime) / math.max(1e-4, t.duration), 0, 1)
        end
        local lane = t.lane
        if laneTop[lane] and laneBot[lane] and screenTopLeft and screenTopRight and screenBotLeft and screenBotRight then
            local sxPos = lerp(laneTop[lane].x, laneBot[lane].x, tt)
            local syPos = lerp(laneTop[lane].y, laneBot[lane].y, tt)
            local wTop = math.abs(screenTopRight.x - screenTopLeft.x) / pt_cfg.lanes
            local wBot = math.abs(screenBotRight.x - screenBotLeft.x) / pt_cfg.lanes
            local w = lerp(wTop, wBot, tt) * 0.9
            local h = (t.type=="long") and (w * 0.75 * pt_cfg.long_tile_hits) or (w * 0.75)
            if tt >= 1.0 and not t.handledReached and not pt_tilesStopped and not pt_reloadPaused and not pt_gameOver then
                                                                local hitComplete = t.wasHit and
                    (t.type ~= "long" or (tonumber(t.hitsRemain) or 0) <= 0)
                if hitComplete then table.remove(pt_tiles, i); goto continue_tiles_loop end
                if pt_cfg.ghost_tiles then
                    table.remove(pt_tiles, i)
                    goto continue_tiles_loop
                end
                pt_tilesStopped = true; pt_stoppedAtTile = t.id; t.handledReached = true; t.removeOnResume = true
                for _,v in ipairs(pt_tiles) do v._stoppedTT = clamp((nowt - v.spawnTime) / math.max(1e-4, v.duration), 0, 1) end
                pt_firstFailTile = { id = t.id, lane = t.lane, sx = sxPos, sy = syPos, w = w, h = h, start = nowt }
                pt_gamePausedForFail = true; pt_pauseStartTime = nowt; pt_endOnFail = true; break
            end
            local baseR, baseG, baseB = t.r or 0.9, t.g or 0.9, t.b or 0.9
            local alpha = t.alpha or 0.98
            local colorR, colorG, colorB = baseR, baseG, baseB
            if pt_cfg.color_on_hit and t.hit and t.hitTime
               and not (pt_firstFailTile and pt_firstFailTile.id == t.id) then
                local hc = pt_cfg.hit_tile_color
                colorR = hc[1] or 1.0; colorG = hc[2] or 1.0; colorB = hc[3] or 1.0
            end
            if pt_gamePausedForFail and pt_firstFailTile and pt_firstFailTile.id == t.id and pt_pauseStartTime then
                local elapsed = nowt - pt_pauseStartTime
                if elapsed < fail_white_ms then colorR, colorG, colorB, alpha = 1,1,1,1
                elseif elapsed < fail_total then colorR, colorG, colorB, alpha = 1,0,0,1 end
            end
            if pt_cfg.tile_transparent_on_hit and t.toRemoveAfterFade and not (pt_firstFailTile and pt_firstFailTile.id == t.id) then
                local fade = clamp((nowt - (t.hitTime or nowt)) / hit_fade_duration, 0, 1)
                alpha = lerp(alpha, 0.02, fade)
            end
            local colU = PT_OVERLAY_U32(imgui.ImVec4(colorR, colorG, colorB, alpha))
            local tTexPath = t.tile_img
                or pt_cfg.normal_tile_img
            local tTex = getTexture(tTexPath)
            if pt_cfg.use_fa_icons and (fa_font_tiles or fa_font_ui or imgui.GetFont()) then
                local ico = (t.fa_glyph and t.fa_glyph ~= "") and t.fa_glyph
                            or (pt_cfg.tile_fa_glyph ~= "" and pt_cfg.tile_fa_glyph)
                            or nil
                if not ico then goto skip_fa_icon end
                local draw_font = fa_font_tiles or fa_font_ui or imgui.GetFont()
                local fa_r = t.fa_r or ((pt_cfg.tile_fa_color and pt_cfg.tile_fa_color[1]) or 1.0)
                local fa_g = t.fa_g or ((pt_cfg.tile_fa_color and pt_cfg.tile_fa_color[2]) or 1.0)
                local fa_b = t.fa_b or ((pt_cfg.tile_fa_color and pt_cfg.tile_fa_color[3]) or 1.0)
                if pt_gamePausedForFail and pt_firstFailTile and pt_firstFailTile.id == t.id and pt_pauseStartTime then
                    local elapsed = nowt - pt_pauseStartTime
                    if elapsed < fail_white_ms then fa_r, fa_g, fa_b = 1,1,1
                    elseif elapsed < fail_total then fa_r, fa_g, fa_b = 1,0,0 end
                end
                local fa_a = alpha
                if draw_font then
                    local icon_scale = math.max(4.0, math.min(7.2, (h / 11.0)))
                    local ts = imgui.CalcTextSize(ico)
                    local tw, th = ts.x * icon_scale, ts.y * icon_scale
                    imgui.PushStyleColor(imgui.Col.Text, PT_ac_text(1.0, fa_a))
                    imgui.PushFont(draw_font)
                    imgui.SetWindowFontScale(icon_scale)
                    imgui.SetCursorScreenPos(imgui.ImVec2(sxPos - tw * 0.5, syPos - th * 0.5))
                    imgui.TextUnformatted(ico)
                    imgui.SetWindowFontScale(1.0)
                    imgui.PopFont()
                    imgui.PopStyleColor()
                else
                    DL:AddRectFilled(imgui.ImVec2(sxPos - w/2, syPos - h/2), imgui.ImVec2(sxPos + w/2, syPos + h/2), colU, 6.0)
                end
                ::skip_fa_icon::
            elseif tTex then
                local imgColU = colU
                if colorR == baseR and colorG == baseG and colorB == baseB then imgColU = PT_OVERLAY_U32(imgui.ImVec4(1,1,1,alpha)) end
                DL:AddImage(tTex, imgui.ImVec2(sxPos - w/2, syPos - h/2), imgui.ImVec2(sxPos + w/2, syPos + h/2), imgui.ImVec2(0,0), imgui.ImVec2(1,1), imgColU)
            else
                DL:AddRectFilled(imgui.ImVec2(sxPos - w/2, syPos - h/2), imgui.ImVec2(sxPos + w/2, syPos + h/2), colU, 6.0)
            end
        end
        ::continue_tiles_loop::
    end
    for i=#pt_hitCircles,1,-1 do
        local c = pt_hitCircles[i]
        local age = now - c.start
        local life = c.life or hit_circle_life
        local tnorm = clamp(age / life, 0, 1)
        if tnorm >= 1 then table.remove(pt_hitCircles, i) else
            local radius = lerp(c.r0 or 6, c.r1 or (c.r0 or 6)*hit_circle_growth, tnorm)
            local a = 1 - tnorm
            local colorU = PT_OVERLAY_U32(imgui.ImVec4(1,1,1,a))
            local thickness = math.max(1.0, 2.0 * pt_cfg.visual_scale * (1 - tnorm*0.6))
            DL:AddCircle(imgui.ImVec2(c.x, c.y), radius, colorU, 16, thickness)
        end
    end
    if pt_gamePausedForFail and pt_pauseStartTime then
        local elapsed = os.clock() - pt_pauseStartTime
        if elapsed >= fail_total then
            if pt_endOnFail then
                saveGameRecord(S("Проигрыш"))
                pt_isScriptRunning = false; pt_gameOver = true; pt_buttonsShown = true
                if pt_cfg.auto_speed_increase and pt_autoSpeedInitial then pt_cfg.tile_speed = pt_autoSpeedInitial; saveSettings() end
                pt_autoSpeedInitial = nil
                computeButtonsWorld(); pt_initialMarkers = {}; pt_tiles = {}; stopMusic()
                setGtaCrosshairVisible(true)
            else
                local delta = os.clock() - pt_pauseStartTime
                for i=#pt_tiles,1,-1 do if pt_tiles[i] and pt_tiles[i].removeOnResume then table.remove(pt_tiles, i) end end
                for _,v in ipairs(pt_tiles) do
                    if v._stoppedTT ~= nil then v.spawnTime = os.clock() - v._stoppedTT * v.duration; v._stoppedTT = nil
                    else v.spawnTime = (v.spawnTime or os.clock()) + delta end
                end
                lastSpawn = lastSpawn + delta; pt_misses = pt_misses + 1; pt_gamePausedForFail = false; pt_pauseStartTime = nil; pt_tilesStopped = false; pt_stoppedAtTile = nil; pt_firstFailTile = nil
                if pt_misses >= pt_cfg.max_misses then
                    saveGameRecord(S("Проигрыш"))
                    pt_isScriptRunning = false; pt_gameOver = true; pt_buttonsShown = true
                    if pt_cfg.auto_speed_increase and pt_autoSpeedInitial then pt_cfg.tile_speed = pt_autoSpeedInitial; saveSettings() end
                    pt_autoSpeedInitial = nil
                    computeButtonsWorld(); pt_initialMarkers = {}; pt_tiles = {}; stopMusic()
                    setGtaCrosshairVisible(true)
                end
            end
            pt_endOnFail = false
        end
    end
    for i=#pt_missTexts,1,-1 do
        local mt = pt_missTexts[i]
        local age = os.clock() - mt.start
        local a = clamp(1 - (age / mt.life), 0, 1)
        if a <= 0 then table.remove(pt_missTexts, i) else
            local f = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
            DL:AddTextFontPtr(f, 18.0 * pt_cfg.visual_scale, imgui.ImVec2(mt.x, mt.y - age * 30), PT_OVERLAY_U32(imgui.ImVec4(1,1,1,a)), "miss")
        end
    end
    if pt_buttonsShown then
        if pt_gameButtons.left.world then
            local okL, sxL, syL = projectWorld(pt_gameButtons.left.world.x, pt_gameButtons.left.world.y, pt_gameButtons.left.world.z)
            if okL then pt_gameButtons.left.screen = { x = sxL, y = syL } end
        end
        if pt_gameButtons.right.world then
            local okR, sxR, syR = projectWorld(pt_gameButtons.right.world.x, pt_gameButtons.right.world.y, pt_gameButtons.right.world.z)
            if okR then pt_gameButtons.right.screen = { x = sxR, y = syR } end
        end
        local sxL, syL = pt_storedButtonScreen.left.x, pt_storedButtonScreen.left.y
        local sxR, syR = pt_storedButtonScreen.right.x, pt_storedButtonScreen.right.y
        if pt_gameButtons.left.screen and pt_gameButtons.left.screen.x then sxL, syL = pt_gameButtons.left.screen.x, pt_gameButtons.left.screen.y end
        if pt_gameButtons.right.screen and pt_gameButtons.right.screen.x then sxR, syR = pt_gameButtons.right.screen.x, pt_gameButtons.right.screen.y end
        local tileW = (laneBot[2] and laneBot[1]) and math.abs(laneBot[2].x - laneBot[1].x) or (pt_cfg.tile_width * pt_cfg.visual_scale)
        local tileH = math.max(12, tileW * 0.75)
        pt_gameButtons.left.w = tileW * 0.95; pt_gameButtons.left.h = tileH * 0.95
        pt_gameButtons.right.w = tileW * 0.95; pt_gameButtons.right.h = tileH * 0.95
        pt_gameButtons.left.screen = { x = sxL, y = syL }; pt_gameButtons.right.screen = { x = sxR, y = syR }
        local f = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
        DL:AddRectFilled(imgui.ImVec2(sxL - pt_gameButtons.left.w/2, syL - pt_gameButtons.left.h/2), imgui.ImVec2(sxL + pt_gameButtons.left.w/2, syL + pt_gameButtons.left.h/2), PT_OVERLAY_U32(imgui.ImVec4(0.18, 0.62, 0.26, 0.95)), 8.0)
        local tsize = f:CalcTextSizeA(14.0 * pt_cfg.visual_scale,1000,0, pt_gameButtons.left.label)
        DL:AddTextFontPtr(f, 14.0 * pt_cfg.visual_scale, imgui.ImVec2(sxL - tsize.x/2, syL - tsize.y/2), PT_OVERLAY_U32(imgui.ImVec4(1,1,1,1)), pt_gameButtons.left.label)
        DL:AddRectFilled(imgui.ImVec2(sxR - pt_gameButtons.right.w/2, syR - pt_gameButtons.right.h/2), imgui.ImVec2(sxR + pt_gameButtons.right.w/2, syR + pt_gameButtons.right.h/2), PT_OVERLAY_U32(imgui.ImVec4(0.82, 0.20, 0.20, 0.95)), 8.0)
        local tsize2 = f:CalcTextSizeA(14.0 * pt_cfg.visual_scale,1000,0, pt_gameButtons.right.label)
        DL:AddTextFontPtr(f, 14.0 * pt_cfg.visual_scale, imgui.ImVec2(sxR - tsize2.x/2, syR - tsize2.y/2), PT_OVERLAY_U32(imgui.ImVec4(1,1,1,1)), pt_gameButtons.right.label)
    end
    if pt_cfg.show_hud then
        local f = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
        DL:AddTextFontPtr(f, 18.0 * pt_cfg.visual_scale, imgui.ImVec2(18,18), PT_OVERLAY_U32(imgui.ImVec4(1,1,1,1)), string.format("Score: %d    Combo: %d    Misses: %d/%d", pt_score, pt_combo, pt_misses, pt_cfg.max_misses))
    end
        end)
        if pt_crosshairDragMode then
            local mx, my = getCursorPos()
            if mx and my then
                local sx2, sy2 = getScreenResolution()
                local baseX = _locked_x or (sx2 / 2)
                local baseY = _locked_y or (sy2 / 2)
                pt_cfg.crosshair_offset_x = math.floor(mx - baseX)
                pt_cfg.crosshair_offset_y = math.floor(my - baseY)
            end
            if isKeyJustPressed(1) then
                pt_crosshairDragMode = false
                saveSettings()
                pcall(sampSetCursorMode, 0)
                pt_windowSettings[0] = true
            elseif isKeyJustPressed(2) then
                pt_crosshairDragMode = false
                pcall(sampSetCursorMode, 0)
                pt_windowSettings[0] = true
            end
        end
        if (pt_cfg.crosshair_enabled and pt_isScriptRunning and pt_gridInitialized and not pt_gameOver)
            or pt_crosshairDragMode then
            local DL_cr  = imgui.GetForegroundDrawList()
            local cr_col  = PT_OVERLAY_U32(imgui.ImVec4(
                pt_cfg.crosshair_color[1], pt_cfg.crosshair_color[2],
                pt_cfg.crosshair_color[3], pt_cfg.crosshair_color[4]))
            local cr_ocol = PT_OVERLAY_U32(imgui.ImVec4(0.02, 0.03, 0.05, 1.0))
            local oth = pt_cfg.crosshair_outline and math.max(1, pt_cfg.crosshair_outline_px or 2) or 0
            local dsz = pt_cfg.crosshair_dot    and math.max(1, pt_cfg.crosshair_dot_size   or 2) or 0
            local cx, cy = getCrosshairDrawPos(sx, sy)
            drawCrossAt(DL_cr, cx, cy,
                pt_cfg.crosshair_size, pt_cfg.crosshair_gap, pt_cfg.crosshair_thick,
                cr_col, cr_ocol, oth, dsz, cr_col)
        end
        imgui.End()
    end
  end
)
imgui.OnInitialize(function()
    imgui.GetIO().IniFilename = nil
    pcall(function()
        local glyphs = imgui.GetIO().Fonts:GetGlyphRangesCyrillic()
        local basePath = getFolderPath(0x14) or ""
        local candidates = { basePath .. '\\trebuc.ttf', basePath .. '\\trebucbd.ttf', getWorkingDirectory() .. '\\Resource\\trebuc.ttf', getWorkingDirectory() .. '\\trebuc.ttf' }
        for _,fp in ipairs(candidates) do if fp and fp ~= "" and io.open(fp, "rb") then imgui.GetIO().Fonts:AddFontFromFileTTF(fp, 16.0, nil, glyphs); break end end
    end)
    if fa and fa.Init then
        pcall(function() fa_font_small2 = fa.Init(14.0) end)
    end
    imgui.SwitchContext(); imgui.GetIO().IniFilename = nil
end)
pt_radio_name_buf = imgui.new.char[256]()
pt_radio_url_buf  = imgui.new.char[1024]()
pt_lastFolderScanTime = 0
pt_icon_search_bufs = {}
pt_icon_filtered    = {}
local function iconComboWithPreview(id, cfg_tbl)
    if #icon_list == 0 then return false end
    local cur_idx = 1
    for i, e in ipairs(icon_list) do
        if e.key == cfg_tbl.tile_fa_icon then cur_idx = i; break end
    end
    local cur = icon_list[cur_idx]
    if not pt_icon_search_bufs[id] then pt_icon_search_bufs[id] = new.char[64]("") end
    local sbuf  = pt_icon_search_bufs[id]
    local changed = false
    imgui.SetNextItemWidth(220)
    if fa_font_ui then imgui.PushFont(fa_font_ui) end
    local opened = imgui.BeginCombo(S("##ico_"..id), (cur.glyph or "?") .. " " .. cur.label)
    if fa_font_ui then imgui.PopFont() end
    if opened then
        imgui.SetNextItemWidth(215)
        local input_changed = imgui.InputText(S("##srch_"..id), sbuf, ffi.sizeof(sbuf))
        local filter = ffi.string(sbuf):lower()
        if input_changed or not pt_icon_filtered[id] or pt_icon_filtered[id.."_f"] ~= filter then
            local t = {}
            for i, e in ipairs(icon_list) do
                if filter == "" or e.label:lower():find(filter,1,true) or e.key:lower():find(filter,1,true) then
                    t[#t+1] = { i=i, e=e }
                end
            end
            pt_icon_filtered[id]       = t
            pt_icon_filtered[id.."_f"] = filter
        end
        local list  = pt_icon_filtered[id] or {}
        local shown = 0
        for _, item in ipairs(list) do
            local sel = (cfg_tbl.tile_fa_icon == item.e.key)
            if sel then
                imgui.PushStyleColor(imgui.Col.Header,        PT_ac(0.380, 0.880))
                imgui.PushStyleColor(imgui.Col.HeaderHovered, PT_ac(0.500, 0.960))
            end
            if fa_font_ui then imgui.PushFont(fa_font_ui) end
            if imgui.Selectable((item.e.glyph or "?") .. " " .. item.e.label .. "##s_"..id..item.i, sel, 0, imgui.ImVec2(0,18)) then
                cfg_tbl.tile_fa_icon  = item.e.key
                cfg_tbl.tile_fa_glyph = item.e.glyph or ""
                pt_icon_filtered[id]     = nil
                changed = true
            end
            if fa_font_ui then imgui.PopFont() end
            if sel then imgui.PopStyleColor(2); imgui.SetItemDefaultFocus() end
            shown = shown + 1
            if shown >= 200 then
                imgui.TextDisabled(string.format(S("... ещё %d — уточните поиск"), #list - 200))
                break
            end
        end
        imgui.EndCombo()
    end
    return changed
end
local FA_PREVIEW_BOX = 84.0
local function renderFaPreviewBox()
    local p   = imgui.GetCursorScreenPos()
    local DL  = imgui.GetWindowDrawList()
    local p2  = imgui.ImVec2(p.x + FA_PREVIEW_BOX, p.y + FA_PREVIEW_BOX)
    local cxb = p.x + FA_PREVIEW_BOX * 0.5
    local cyb = p.y + FA_PREVIEW_BOX * 0.5
    local base_bc = (type(fx_cfg) == 'table' and fx_cfg.global_base_color) or {0.0, 0.8, 1.0}
    local border_r, border_g, border_b, border_a = base_bc[1] or 0, base_bc[2] or 0, base_bc[3] or 0, 0.70
    if pt_cfg.random_fa_color then
        border_r, border_g, border_b = hsvToRgb((os.clock() * 0.25) % 1.0, 0.8, 1.0)
        border_a = 1.0
    elseif pt_cfg.random_fa_icon then
        local pulse = (math.sin(os.clock() * 4.0) + 1.0) * 0.5
        border_r, border_g, border_b = 1.0, 1.0, 1.0
        border_a = 0.4 + pulse * 0.6
    end
    DL:AddRectFilled(p, p2,
        PT_U32(PT_ac(0.09, 1.0)), 6)
    DL:AddRect(p, p2,
        PT_U32(imgui.ImVec4(border_r, border_g, border_b, border_a)), 6, 0, 2.0)
    local glyph
    if pt_cfg.random_fa_icon and #icon_list > 0 then
            local now_p = os.clock()
        local pi_interval = clamp(tonumber(pt_cfg.random_fa_icon_interval) or 3.0, 0.2, 60)
        if previewFaGlyph == "" or now_p >= previewFaNextChange then
            local ri = icon_list[math.random(1, #icon_list)]
            previewFaGlyph     = ri.glyph or ""
            previewFaNextChange = now_p + pi_interval
        end
        glyph = previewFaGlyph
    else
        glyph = pt_cfg.tile_fa_glyph or ""
    end
    if glyph ~= "" then
        local draw_font = fa_font_tiles or fa_font_ui or imgui.GetFont()
        local fsz = FA_PREVIEW_BOX * 0.42
        local fa_r, fa_g, fa_b, fa_a
        if pt_cfg.random_fa_color then
            fa_r, fa_g, fa_b = hsvToRgb((os.clock() * 0.4) % 1.0, 0.9, 1.0)
            fa_a = 1.0
        else
            fa_r = (pt_cfg.tile_fa_color and pt_cfg.tile_fa_color[1]) or 1.0
            fa_g = (pt_cfg.tile_fa_color and pt_cfg.tile_fa_color[2]) or 1.0
            fa_b = (pt_cfg.tile_fa_color and pt_cfg.tile_fa_color[3]) or 1.0
            fa_a = (pt_cfg.tile_fa_color and pt_cfg.tile_fa_color[4]) or 1.0
        end
        local col = PT_U32(imgui.ImVec4(fa_r, fa_g, fa_b, fa_a))
        local ts  = draw_font:CalcTextSizeA(fsz, 1000, 0, glyph)
        DL:PushClipRect(imgui.ImVec2(p.x+2, p.y+2), imgui.ImVec2(p2.x-2, p2.y-2), true)
        DL:AddTextFontPtr(draw_font, fsz, imgui.ImVec2(cxb - ts.x*0.5, cyb - ts.y*0.5), col, glyph)
        DL:PopClipRect()
    else
        local no  = S("нет")
        local f2  = CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont())
        local fs2 = 13
        local ts2 = f2:CalcTextSizeA(fs2, 1000, 0, no)
        DL:AddTextFontPtr(f2, fs2, imgui.ImVec2(cxb - ts2.x*0.5, cyb - ts2.y*0.5),
            PT_U32(PT_ac_text(1.0, 1.0)), no)
    end
    imgui.Dummy(imgui.ImVec2(FA_PREVIEW_BOX, FA_PREVIEW_BOX))
end
local CROSS_PREVIEW_BOX = 84.0
local function renderCrossPreviewBox()
    local p   = imgui.GetCursorScreenPos()
    local DL  = imgui.GetWindowDrawList()
    local p2  = imgui.ImVec2(p.x + CROSS_PREVIEW_BOX, p.y + CROSS_PREVIEW_BOX)
    local cxb = p.x + CROSS_PREVIEW_BOX * 0.5
    local cyb = p.y + CROSS_PREVIEW_BOX * 0.5
    DL:AddRectFilled(p, p2,
        PT_U32(PT_ac(0.09, 1.0)), 6)
    DL:AddRect(p, p2,
        PT_U32(PT_ac(1.30, 0.70)), 6)
    DL:PushClipRect(imgui.ImVec2(p.x + 2, p.y + 2), imgui.ImVec2(p2.x - 2, p2.y - 2), true)
    local r  = pt_cfg.crosshair_color[1]
    local g  = pt_cfg.crosshair_color[2]
    local b  = pt_cfg.crosshair_color[3]
    local a  = pt_cfg.crosshair_color[4]
    local col_u32  = PT_U32(imgui.ImVec4(r, g, b, a))
    local ocol_u32 = PT_U32(imgui.ImVec4(0.02, 0.03, 0.05, 1.0))
    local oth  = pt_cfg.crosshair_outline and math.max(1, pt_cfg.crosshair_outline_px or 2) or 0
    local dsz  = pt_cfg.crosshair_dot and math.max(1, pt_cfg.crosshair_dot_size or 2) or 0
    drawCrossAt(DL, cxb, cyb,
        pt_cfg.crosshair_size, pt_cfg.crosshair_gap, pt_cfg.crosshair_thick,
        col_u32, ocol_u32, oth, dsz, col_u32)
    DL:PopClipRect()
    imgui.Dummy(imgui.ImVec2(CROSS_PREVIEW_BOX, CROSS_PREVIEW_BOX))
end
local function pushSliderColorForNorm(norm)
    norm = clamp(norm, 0, 1)
    local r = lerp(0, 1, norm); local g = lerp(1, 0, norm); local b = 0
    pcall(function()
        imgui.PushStyleColor(imgui.Col.SliderGrab,       imgui.ImVec4(r,g,b,1))
        imgui.PushStyleColor(imgui.Col.SliderGrabActive, imgui.ImVec4(r*0.8,g*0.8,b,1))
    end)
end
local function popSliderColor() pcall(function() imgui.PopStyleColor(2) end) end
local function renderSection_Appearance()
    if not imgui.CollapsingHeader(S("Оформление (Фон и Плитки)")) then return end
    local function bgImageCombo(label, currentPath, callback)
        local currentName = S("Нет (цвет)")
        for _, rec in ipairs(pt_bgImages) do if rec.path == currentPath then currentName = S(rec.name); break end end
        imgui.SetNextItemWidth(200)
        if CBUGER_MarqueeBeginCombo(label, currentName) then
            if imgui.Selectable(S("Нет (цвет)"), currentPath == "" or currentPath == nil) then callback(""); saveSettings() end
            for _, rec in ipairs(pt_bgImages) do
                if CBUGER_MarqueeSelectable(S(rec.name), "ptimg_" .. tostring(rec.path), currentPath == rec.path) then callback(rec.path); saveSettings() end
            end
            imgui.EndCombo()
        end
    end
    local function tileImageCombo(label, currentPath, callback)
        local currentName = S("Нет (цвет)")
        for _, rec in ipairs(pt_tileImages) do if rec.path == currentPath then currentName = S(rec.name); break end end
        imgui.SetNextItemWidth(200)
        if CBUGER_MarqueeBeginCombo(label, currentName) then
            if imgui.Selectable(S("Нет (цвет)"), currentPath == "" or currentPath == nil) then callback(""); saveSettings() end
            for _, rec in ipairs(pt_tileImages) do
                if CBUGER_MarqueeSelectable(S(rec.name), "ptimg_" .. tostring(rec.path), currentPath == rec.path) then callback(rec.path); saveSettings() end
