                pt_cfg.tile_fa_color[1], pt_cfg.tile_fa_color[2], pt_cfg.tile_fa_color[3], pt_cfg.tile_fa_color[4] = fa_c[0], fa_c[1], fa_c[2], fa_c[3]; saveSettings()
