        end
        imgui.Spacing()
        local rfi_icon = new.bool(pt_cfg.random_fa_icon)
        if imgui.Checkbox(S("Случайная смена иконки##rfa_icon_en"), rfi_icon) then pt_cfg.random_fa_icon = rfi_icon[0]; saveSettings() end
        if pt_cfg.random_fa_icon then
