                pt_cfg.random_fa_icon_interval = clamp(rfii[0], 0.2, 10.0); saveSettings()
            end
            popSliderColor()
        end
        imgui.EndGroup()
    else
        local lib_name = fa_module_name or 'fAwesome6_solid / fAwesome6'
        imgui.TextDisabled(S('FA-иконки недоступны — не найдена библиотека ' .. lib_name))
    end
end
