    if SpaceSavingSliderInt(S("Размер"), cr_sz, 2, 30, S("%d px"), 200) then pt_cfg.crosshair_size = clamp(cr_sz[0], 2, 30); saveSettings() end
    popSliderColor()
    local cr_gap = new.int(pt_cfg.crosshair_gap)
