                end
                if imgui.Button(S("Сбросить##fa_color_reset")) then pt_cfg.tile_fa_color={1.0,1.0,1.0,1.0}; saveSettings() end
                imgui.EndPopup()
            end
            imgui.Spacing()
            local rfi_icon = new.bool(pt_cfg.random_fa_icon)
