            popSliderColor()
        end
        imgui.SameLine(0,14)
        local cr_dot = new.bool(pt_cfg.crosshair_dot)
        if imgui.Checkbox(S("  Точка##cr_dot"), cr_dot) then pt_cfg.crosshair_dot=cr_dot[0]; saveSettings() end
        imgui.Spacing()
