                pt_cfg.crosshair_color[3]=cr_c[2]; pt_cfg.crosshair_color[4]=cr_c[3]; saveSettings()
            end
            imgui.EndPopup()
        end
        imgui.EndGroup()
    end
    if tab == 1 then
        renderTab_Game()
    elseif tab == 2 then
        renderTab_Display()
    elseif tab == 3 then
