    pcall(function() if n_style_vars and n_style_vars > 0 then imgui.PopStyleVar(n_style_vars) end end)
    pcall(function() for i=1,32 do imgui.PopStyleColor() end end)
    imgui.PopStyleVar()
  end
)
PT = {}
function PT.run()
    if not isSampLoaded() or not isSampfuncsLoaded() then return end
    while not isSampAvailable() do wait(100) end
    CBUGER_WAIT_RUNTIME_READY()
    wait(150)
    setGtaCrosshairVisible(true)
    pcall(stopMusic)
    ensureFolders()
    scanFolders()
    loadGameRecords()
    local lastRecordSaveRetry = os.clock()
    pt_windowSettings[0] = false
    sampRegisterChatCommand("piano", function() toggleSettingsWindow() end)
    while true do
        wait(0)
        local nowMain = os.clock()
        if pt_records_dirty and (nowMain - lastRecordSaveRetry) >= 5 then
            lastRecordSaveRetry = nowMain
            pcall(saveGameRecords)
        end
        travelDuration = spawnDistance / math.max(0.0001, worldMoveSpeed * pt_cfg.tile_speed)
        if pt_isScriptRunning and pt_gridInitialized and not pt_gameOver then
            setGtaCrosshairVisible(false)
        else
            setGtaCrosshairVisible(true)
        end
        if pt_cfg.pause_on_reload and pt_isScriptRunning and pt_gridInitialized and not pt_gameOver
           and not pt_tilesStopped and not pt_gamePausedForFail then
            local NO_AMMO_WID = {[0]=true,[1]=true,[2]=true,[3]=true,[4]=true,
                                 [5]=true,[6]=true,[7]=true,[8]=true,[9]=true}
            local curClip = -1
            pcall(function()
                local wid = getCurrentCharWeapon(playerPed)
                if not wid or wid == 0 or NO_AMMO_WID[wid] then return end
                local ptr = getCharPointer(playerPed)
                if not ptr or ptr == 0 then return end
                local slot = getWeapontypeSlot(wid)
                curClip = memory.getuint32(ptr + 0x5A0 + slot * 0x1C + 0x8)
            end)
            if curClip >= 0 then
                if not pt_reloadPaused and pt_prevAmmoClip > 0 and curClip == 0 then
                    pt_reloadPaused = true
                    pt_reloadPauseStartTime = nowMain
                end
                pt_prevAmmoClip = curClip
            end
            if pt_reloadPaused and pt_reloadPauseStartTime then
                local dur = clamp(tonumber(pt_cfg.reload_pause_duration) or 1.0, 0.0001, 30.0)
                if nowMain - pt_reloadPauseStartTime >= dur then
                    local delta = nowMain - pt_reloadPauseStartTime
                    for _, tile in ipairs(pt_tiles) do
                        tile.spawnTime = (tile.spawnTime or nowMain) + delta
                    end
                    lastSpawn = lastSpawn + delta
                    pt_reloadPaused = false
                    pt_reloadPauseStartTime = nil
                end
            end
        elseif not pt_isScriptRunning then
            pt_prevAmmoClip = -1; pt_reloadPaused = false; pt_reloadPauseStartTime = nil
        end
        if radioPlaybackWanted and pt_cfg.radio_mode and pt_selectedIsRadio
           and pt_selectedSongPath and pt_selectedSongPath ~= "" then
                                                radioWatchdog(nowMain)
        elseif pt_isScriptRunning and pt_musicPlaying and pt_selectedSongPath and not pt_selectedIsRadio then
            if nowMain - lastMusicCheck > 2.0 then
                lastMusicCheck = nowMain
                if playMethod == "MCI" then
                    pcall(function()
                        local buf = ffi.new("char[128]")
                        mci.mciSendStringA("status " .. musicAlias .. " mode", buf, 128, nil)
                        local status = ffi.string(buf)
                        if status == "stopped" or status == "" then
                            openAndPlayMusic(pt_selectedSongPath, true)
                        end
                    end)
                elseif playMethod == "MOON" and playsound ~= nil and moon_action then
                    pcall(function()
                        if type(getAudioStreamState) == "function" then
                            local st = getAudioStreamState(playsound)
                            if st == -1 or st == moon_action.STOP then
                                openAndPlayMusic(pt_selectedSongPath, true)
                            end
                        end
                    end)
                end
            end
        end
    end
end
function PT.terminate(s, q)
    pcall(setGtaCrosshairVisible, true)
    pcall(stopMusic)
    pcall(saveSettings)
    if pt_records_dirty or type(pt_gameRecords) == 'table' then
        pcall(saveGameRecords)
    end
end
end
