}
local fn = {}
fn.record_width = function(w)
    if state.current_rendering_window == "main" then
        local padding = state.is_discord_layout and 200 or 100
        state.current_frame_max_w = math.max(state.current_frame_max_w, w + padding)
    elseif state.current_rendering_window == "editor" then
        state.editor_current_frame_max_w = math.max(state.editor_current_frame_max_w, w + 100)
    end
end
fn.set_hand_cursor = function()
    local cursor_id = (imgui.MouseCursor and imgui.MouseCursor.Hand) or 7
    pcall(function() imgui.SetMouseCursor(cursor_id) end)
end
fn.set_resize_cursor = function()
    local cursor_id = (imgui.MouseCursor and imgui.MouseCursor.ResizeNWSE) or 6
    pcall(function() imgui.SetMouseCursor(cursor_id) end)
end
fn.lerp = function(a, b, t) return a + (b - a) * t end
fn.pack_color = function(r, g, b, a, ignore_fade, mult)
    local alpha_mult = (ignore_fade and 1.0 or state.global_alpha) * (mult or 1.0)
    local final_a = (a or 1.0) * alpha_mult
    local R = math.floor(math.max(0, math.min(1, r)) * 255)
    local G = math.floor(math.max(0, math.min(1, g)) * 255)
    local B = math.floor(math.max(0, math.min(1, b)) * 255)
    local A = math.floor(math.max(0, math.min(1, final_a)) * 255)
    return A * 16777216 + B * 65536 + G * 256 + R
end
fn.SetStyleColorSafe = function(id, r, g, b, a)
    if id ~= nil then active_colors[id] = {r, g, b, a} end
end
fn.anim_update = function(current, target, speed)
    local sp = speed or 12.0
    return fn.lerp(current, target, 1 - math.exp(-sp * ui_anim.dt))
end
fn.bezier = function(t, p0, p1, p2, p3)
    local u = 1 - t; local tt = t*t; local uu = u*u; local uuu = uu*u; local ttt = tt*t
    local p = {x = uuu*p0.x, y = uuu*p0.y}
    p.x = p.x + 3*uu*t*p1.x; p.y = p.y + 3*uu*t*p1.y
    p.x = p.x + 3*u*tt*p2.x; p.y = p.y + 3*u*tt*p2.y
    p.x = p.x + ttt*p3.x;    p.y = p.y + ttt*p3.y
    return imgui.ImVec2(p.x, p.y)
end
fn.draw_safe_bezier = function(dl, p0, p1, p2, p3, col, thickness)
    local prev = p0
    for i = 1, 15 do
        local curr = fn.bezier(i/15, p0, p1, p2, p3)
        dl:AddLine(prev, curr, col, thickness)
        prev = curr
    end
end
fn.SafeCombo = function(label, int_ptr, items)
    label = Fn.T(label)
    if items and #items > 0 then
        local translated_items = Fn.translateList(items)
        local items_arr = ffi.new("const char*[?]", #translated_items, translated_items)
        imgui.Combo(label, int_ptr, items_arr, #translated_items)
        fn.record_width(imgui.CalcTextSize(label).x + 150)
    end
end
