fn.CustomColorPicker = function(label, id_string, color_ref, has_alpha_deprecated, alpha_mult)
    label = Fn.T(label)
    local w, h = 24, 24
    local p  = imgui.GetCursorScreenPos()
    local dl = imgui.GetWindowDrawList()
    local center = imgui.ImVec2(p.x + w/2, p.y + h/2)
    local popup_id = "cp_popup_" .. id_string
    imgui.InvisibleButton("btn_"..id_string, imgui.ImVec2(w, h))
    local hovered = imgui.IsItemHovered()
    local clicked = imgui.IsItemClicked()
    if hovered then fn.set_hand_cursor() end
    if clicked  then imgui.OpenPopup(popup_id) end
    local u32_col = fn.pack_color(color_ref[1], color_ref[2], color_ref[3], color_ref[4] or 1.0, true, alpha_mult or 1.0)
    dl:AddCircleFilled(center, w/2 - 2, u32_col, 24)
    dl:AddCircle(center, w/2 - 2, fn.pack_color(1,1,1,hovered and 1.0 or 0.4,true,alpha_mult or 1.0), 24, 1.5)
    imgui.SameLine(0, 10)
    imgui.SetCursorPosY(imgui.GetCursorPosY() + 2)
    imgui.Text(label)
    fn.record_width(imgui.CalcTextSize(label).x + 80)
    local changed = false
    imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, alpha_mult or 1.0)
    imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1.0, 1.0, 1.0, 1.0))
    if imgui.BeginPopup(popup_id) then
        local t_col = active_colors[imgui.Col.Text] or {1.0, 1.0, 1.0, 1.0}
        imgui.TextColored(imgui.ImVec4(t_col[1], t_col[2], t_col[3], 1.0), label)
        imgui.Separator()
        if not color_pickers_state[id_string] then
            color_pickers_state[id_string] = imgui.new.float[4](
                color_ref[1] or 1.0, color_ref[2] or 1.0,
                color_ref[3] or 1.0, color_ref[4] or 1.0)
        end
        local st = color_pickers_state[id_string]
        local _ga = CBUGER_GET_INTERFACE_ALPHA()
        local _base_a = math.max(0.0, math.min(1.0, tonumber(color_ref[4]) or 1.0))
        st[0] = color_ref[1] or 1.0
        st[1] = color_ref[2] or 1.0
        st[2] = color_ref[3] or 1.0
        st[3] = _base_a * _ga
        local cp_flags = 0
        if imgui.ColorEditFlags and imgui.ColorEditFlags.AlphaBar then
            cp_flags = imgui.ColorEditFlags.AlphaBar
        end
        if imgui.ColorPicker4("##picker_"..id_string, st, cp_flags) then
            color_ref[1] = st[0]; color_ref[2] = st[1]
            color_ref[3] = st[2]
            if _ga > 0.0001 then
                color_ref[4] = math.max(0.0, math.min(1.0, st[3] / _ga))
            else
                color_ref[4] = 0.0
            end
            changed = true
        end
        imgui.EndPopup()
    end
    imgui.PopStyleColor(1)
    imgui.PopStyleVar(1)
    return changed
end
fn.DrawAutoText = function(text, wrapped, is_header)
    text = Fn.T(text)
    if is_header then
        local tc = fx_cfg.title_color
        imgui.TextColored(imgui.ImVec4(tc[1] or 1.0, tc[2] or 1.0, tc[3] or 1.0, (tc[4] or 1.0) * state.global_alpha), text)
        fn.record_width(imgui.CalcTextSize(text).x)
    elseif wrapped then
        imgui.TextWrapped(text)
    else
        imgui.Text(text)
        fn.record_width(imgui.CalcTextSize(text).x)
    end
end
fn.draw_enhanced_cursor = function(draw_list, global_alpha_mult, do_update)
    if not fx_cfg.sparks_on[0] then return end
    local mouse_pos = imgui.GetIO().MousePos
    if mouse_pos.x <= 0 or mouse_pos.y <= 0 then return end
    if do_update then
        local dx = mouse_pos.x - state.last_mouse_pos.x
        local dy = mouse_pos.y - state.last_mouse_pos.y
        local speed = math.sqrt(dx*dx + dy*dy)
        state.last_mouse_pos = {x = mouse_pos.x, y = mouse_pos.y}
        if speed > 0.5 then
            state.particle_tick = state.particle_tick + 1
            for i = 1, 2 do
                local color     = fx_cfg.sparks_color
                local mult      = fx_cfg.sparks_speed[0]
                local size_base = fx_cfg.sparks_size[0]
                local p_size, vX, vY, shrink_rate
                local c_var = fx_cfg.cursor_fx_var[0]
                if     c_var ==  0 then p_size=(math.random(5,15)/10)*size_base;  vX=(math.random()-.5)*1.8*mult; vY=(math.random()-.5)*1.8*mult; shrink_rate=1.6*mult
                elseif c_var ==  1 then p_size=(math.random(8,20)/10)*size_base;  vX=(math.random()-.5)*1.0*mult; vY=(math.random(10,25)/10)*mult; shrink_rate=2.0*mult
                elseif c_var ==  2 then p_size=(math.random(10,30)/10)*size_base; vX=(math.random()-.5)*2.0*mult; vY=-(math.random(10,20)/10)*mult; shrink_rate=1.0*mult
                elseif c_var ==  3 then p_size=(math.random(4,10)/10)*size_base;  vX=0; vY=(math.random(15,30)/10)*mult; shrink_rate=1.5*mult
                elseif c_var ==  4 then p_size=(math.random(3,8)/10)*size_base;   vX=(math.random()-.5)*.5*mult; vY=(math.random()-.5)*.5*mult; shrink_rate=0.8*mult
                elseif c_var ==  5 then p_size=(math.random(15,25)/10)*size_base; vX=(math.random()-.5)*1.0*mult; vY=-(math.random(10,25)/10)*mult; shrink_rate=2.5*mult
                elseif c_var ==  6 then p_size=(math.random(20,40)/10)*size_base; vX=0; vY=0; shrink_rate=4.0*mult
                elseif c_var ==  7 then p_size=(math.random(2,6)/10)*size_base;   vX=(math.random()-.5)*5.0*mult; vY=(math.random()-.5)*5.0*mult; shrink_rate=3.0*mult
                elseif c_var ==  8 then p_size=(math.random(4,12)/10)*size_base;  vX=(math.random()-.5)*.8*mult; vY=(math.random(5,15)/10)*mult; shrink_rate=0.5*mult
                elseif c_var ==  9 then p_size=(math.random(10,30)/10)*size_base; vX=(math.random()-.5)*1.5*mult; vY=0; shrink_rate=5.0*mult
                elseif c_var == 10 then p_size=(math.random(8,16)/10)*size_base;  vX=(math.random()-.5)*3.0; vY=(math.random()-.5)*3.0; shrink_rate=0.8*mult
                elseif c_var == 11 then p_size=(math.random(4,12)/10)*size_base;  vX=(math.random()-.5)*2.0; vY=(math.random()-.5)*2.0; shrink_rate=1.0*mult
                elseif c_var == 12 then p_size=(math.random(10,20)/10)*size_base; vX=0; vY=(math.random(5,15)/10)*mult; shrink_rate=2.0*mult
                elseif c_var == 13 then p_size=(math.random(10,25)/10)*size_base; vX=(math.random(15,30)/10)*mult; vY=(math.random(15,30)/10)*mult; shrink_rate=3.0*mult
                elseif c_var == 14 then p_size=(math.random(10,30)/10)*size_base; vX=(math.random()-.5)*5.0*mult; vY=(math.random()-.5)*5.0*mult; shrink_rate=4.0*mult
                elseif c_var == 15 then p_size=(math.random(5,15)/10)*size_base;  vX=(math.random()-.5)*3.0; vY=(math.random()-.5)*3.0; shrink_rate=1.2*mult
                elseif c_var == 16 then p_size=(math.random(10,40)/10)*size_base; vX=0; vY=0; shrink_rate=2.0*mult
                elseif c_var == 17 then p_size=(math.random(5,15)/10)*size_base;  vX=(math.random()-.5)*2.0; vY=(math.random()-.5)*2.0; shrink_rate=1.5*mult
                elseif c_var == 18 then p_size=(math.random(6,14)/10)*size_base;  vX=(math.random()-.5)*3.0*mult; vY=-(math.random(10,20)/10)*mult; shrink_rate=1.2*mult
                else                    p_size=(math.random(20,50)/10)*size_base; vX=0; vY=0; shrink_rate=5.0*mult
                end
                table.insert(trail_particles, {
                    x=mouse_pos.x, y=mouse_pos.y, life=1.0,
                    size=p_size, velX=vX, velY=vY,
                    shrink=shrink_rate,
                    col={color[1], color[2], color[3], color[4] or 1.0},
                    mode=c_var
                })
            end
        end
        for i = #trail_particles, 1, -1 do
            local p = trail_particles[i]
            p.life = p.life - ui_anim.dt * p.shrink
            p.x = p.x + p.velX
            p.y = p.y + p.velY
            if p.mode == 4  and p.life > 0.1 then p.velX = p.velX + math.sin(os.clock()*5+p.life*10)*0.05 end
            if p.mode == 8  and p.life > 0.1 then p.velX = p.velX + math.sin(os.clock()*2+p.y*0.05)*0.1 end
            if p.mode == 10 and p.life > 0.1 then p.velX=p.velX+(mouse_pos.x-p.x)*0.05; p.velY=p.velY+(mouse_pos.y-p.y)*0.05 end
            if p.mode == 11 and p.life > 0.1 then p.velX=p.velX+(math.random()-.5)*.5; p.velY=p.velY+(math.random()-.5)*.5 end
            if p.mode == 15 and p.life > 0.1 then local dX=mouse_pos.x-p.x; local dY=mouse_pos.y-p.y; p.velX=p.velX+dY*0.1; p.velY=p.velY-dX*0.1 end
            if p.mode == 17 and p.life > 0.1 then p.x=p.x+math.sin(p.life*20)*2.0 end
            if p.mode == 18 then p.velY=p.velY+0.1 end
            if p.life <= 0 then table.remove(trail_particles, i) end
        end
    end
    for i = 1, #trail_particles do
        local p   = trail_particles[i]
        local u32 = fn.pack_color(p.col[1], p.col[2], p.col[3], p.life*p.col[4], true, global_alpha_mult)
        local m   = p.mode
        if     m == 1  then
            draw_list:AddLine(imgui.ImVec2(p.x-p.size*p.life, p.y), imgui.ImVec2(p.x+p.size*p.life, p.y), u32, 1.5)
            draw_list:AddLine(imgui.ImVec2(p.x, p.y-p.size*p.life), imgui.ImVec2(p.x, p.y+p.size*p.life), u32, 1.5)
        elseif m == 2  then draw_list:AddCircle(imgui.ImVec2(p.x,p.y), p.size*p.life, u32, 12, 1.5)
        elseif m == 3  then draw_list:AddRectFilled(imgui.ImVec2(p.x,p.y), imgui.ImVec2(p.x+2, p.y+p.size*p.life), u32)
        elseif m == 5  then draw_list:AddCircleFilled(imgui.ImVec2(p.x,p.y), p.size*p.life, fn.pack_color(1.0,p.life*.8,0,p.life*p.col[4],true,global_alpha_mult), 8)
        elseif m == 6 or m == 16 then draw_list:AddCircle(imgui.ImVec2(p.x,p.y), p.size*(1-p.life), u32, 16, 2.0)
        elseif m == 7 or m == 13 or m == 14 then draw_list:AddLine(imgui.ImVec2(p.x,p.y), imgui.ImVec2(p.x+p.velX*2, p.y+p.velY*2), u32, 1.5)
        elseif m == 9 or m == 12 then draw_list:AddRectFilled(imgui.ImVec2(p.x-p.size,p.y-1), imgui.ImVec2(p.x+p.size,p.y+1), u32)
        elseif m == 18 then
            local col18 = fn.pack_color(math.random(), math.random(), math.random(), p.life, true, global_alpha_mult)
            draw_list:AddRectFilled(imgui.ImVec2(p.x-p.size*p.life, p.y-p.size*p.life), imgui.ImVec2(p.x+p.size*p.life, p.y+p.size*p.life), col18)
        elseif m == 19 then
            local s = p.size
            local pp1=imgui.ImVec2(p.x,p.y-s); local pp2=imgui.ImVec2(p.x+s*.866,p.y-s*.5)
            local pp3=imgui.ImVec2(p.x+s*.866,p.y+s*.5); local pp4=imgui.ImVec2(p.x,p.y+s)
            local pp5=imgui.ImVec2(p.x-s*.866,p.y+s*.5); local pp6=imgui.ImVec2(p.x-s*.866,p.y-s*.5)
            draw_list:AddLine(pp1,pp2,u32,1.5); draw_list:AddLine(pp2,pp3,u32,1.5); draw_list:AddLine(pp3,pp4,u32,1.5)
            draw_list:AddLine(pp4,pp5,u32,1.5); draw_list:AddLine(pp5,pp6,u32,1.5); draw_list:AddLine(pp6,pp1,u32,1.5)
        else draw_list:AddCircleFilled(imgui.ImVec2(p.x,p.y), p.size*p.life, u32, 6)
        end
    end
    draw_list:AddCircleFilled(mouse_pos, 2.5,
        fn.pack_color(fx_cfg.sparks_color[1], fx_cfg.sparks_color[2], fx_cfg.sparks_color[3],
                      fx_cfg.sparks_color[4] or 1.0, true, global_alpha_mult), 16)
end
local function CBUGER_IsCursorVisible()
    if type(isCursorActive) == 'function' then
        local ok, active = pcall(isCursorActive)
        if ok then return active and true or false end
    end
    if type(sampIsCursorActive) == 'function' then
        local ok, active = pcall(sampIsCursorActive)
        if ok then return active and true or false end
    end
    return false
end
local cbuger_cursor_particles_frame = imgui.OnFrame(
    function()
        local fx = CBUGER_GET_EFFECTS()
        return type(fx) == 'table' and fx.sparks_on ~= nil and fx.sparks_on[0]
            and CBUGER_IsCursorVisible() and true or false
    end,
    function(self)
        self.HideCursor = true
        local io = imgui.GetIO()
        local dt = math.max(tonumber(io.DeltaTime) or 0.016, 0.001)
        ui_anim.dt = dt
        local draw_list = imgui.GetForegroundDrawList()
        if not draw_list then return end
        fn.draw_enhanced_cursor(draw_list, 1.0, true)
    end
)
cbuger_cursor_particles_frame.HideCursor = true
fn.draw_police_ambient = function(draw_list, p_min, p_max, global_alpha_mult)
    if not fx_cfg.ambient_on[0] then return end
    local time  = os.clock() * fx_cfg.ambient_speed[0]
    local a_var = fx_cfg.ambient_var[0]
    local c1, c2 = fx_cfg.ambient_color_1, fx_cfg.ambient_color_2
    local cx = p_min.x + (p_max.x - p_min.x)/2
    local cy = p_min.y + (p_max.y - p_min.y)/2
    local max_r = math.max(p_max.x - p_min.x, p_max.y - p_min.y)
    if a_var == 0 then
        local phase = math.sin(time*3)
        local int1 = math.max(0, phase)*0.15*(c1[4] or 1)
        local int2 = math.max(0,-phase)*0.15*(c2[4] or 1)
        draw_list:AddRectFilledMultiColor(p_min, p_max,
            fn.pack_color(c1[1],c1[2],c1[3],int1,false,global_alpha_mult),
            fn.pack_color(c2[1],c2[2],c2[3],int2,false,global_alpha_mult),
            fn.pack_color(c2[1],c2[2],c2[3],int2,false,global_alpha_mult),
            fn.pack_color(c1[1],c1[2],c1[3],int1,false,global_alpha_mult))
    elseif a_var == 1 then
        local phase = time % 1.0; local is_red = phase < 0.5
        local int = (phase%0.25 > 0.125) and 0.2 or 0.0
        local c = is_red and c2 or c1
        draw_list:AddRectFilled(p_min, p_max, fn.pack_color(c[1],c[2],c[3],int*(c[4] or 1),false,global_alpha_mult), 15)
    elseif a_var == 2 then
        local y_pos = p_min.y + ((math.sin(time*2)+1)/2)*(p_max.y-p_min.y)
        local int = 0.3*(c1[4] or 1)
        draw_list:AddRectFilledMultiColor(imgui.ImVec2(p_min.x,y_pos-30), imgui.ImVec2(p_max.x,y_pos),
            fn.pack_color(c1[1],c1[2],c1[3],0,false,global_alpha_mult), fn.pack_color(c1[1],c1[2],c1[3],0,false,global_alpha_mult),
            fn.pack_color(c1[1],c1[2],c1[3],int,false,global_alpha_mult), fn.pack_color(c1[1],c1[2],c1[3],int,false,global_alpha_mult))
        draw_list:AddRectFilledMultiColor(imgui.ImVec2(p_min.x,y_pos), imgui.ImVec2(p_max.x,y_pos+30),
            fn.pack_color(c1[1],c1[2],c1[3],int,false,global_alpha_mult), fn.pack_color(c1[1],c1[2],c1[3],int,false,global_alpha_mult),
            fn.pack_color(c1[1],c1[2],c1[3],0,false,global_alpha_mult), fn.pack_color(c1[1],c1[2],c1[3],0,false,global_alpha_mult))
    elseif a_var == 3 then
        local int = ((math.sin(time*2)+1)/2)*0.2*(c1[4] or 1)
        draw_list:AddRectFilled(p_min, p_max, fn.pack_color(c1[1],c1[2],c1[3],int,false,global_alpha_mult), 15)
    elseif a_var == 4 then
        local flash = (time%1 < 0.1) and 0.4 or 0.0
        draw_list:AddRectFilled(p_min, p_max, fn.pack_color(c1[1],c1[2],c1[3],flash*(c1[4] or 1),false,global_alpha_mult), 15)
    elseif a_var == 5 then
        for i = 0, 3 do
            local x_pos = p_min.x + ((math.sin(time*.5+i)+1)/2)*(p_max.x-p_min.x)
            local int = 0.1*(c1[4] or 1)
            draw_list:AddRectFilledMultiColor(imgui.ImVec2(x_pos-50,p_min.y), imgui.ImVec2(x_pos,p_max.y),
                fn.pack_color(c1[1],c1[2],c1[3],0,false,global_alpha_mult), fn.pack_color(c1[1],c1[2],c1[3],int,false,global_alpha_mult),
                fn.pack_color(c1[1],c1[2],c1[3],int,false,global_alpha_mult), fn.pack_color(c1[1],c1[2],c1[3],0,false,global_alpha_mult))
        end
    elseif a_var == 6 then
        local radius = ((time*2)%1)*max_r; local int = (1-((time*2)%1))*0.2*(c1[4] or 1)
        draw_list:AddCircleFilled(imgui.ImVec2(cx,cy), radius, fn.pack_color(c1[1],c1[2],c1[3],int,false,global_alpha_mult), 32)
    elseif a_var == 7 then
        local angle = time*2; local px = cx+math.cos(angle)*(max_r*.3); local py = cy+math.sin(angle)*(max_r*.3)
        draw_list:AddCircleFilled(imgui.ImVec2(px,py), 100, fn.pack_color(c1[1],c1[2],c1[3],0.2*(c1[4] or 1),false,global_alpha_mult), 32)
    elseif a_var == 8 then
        local pulse = math.abs(math.sin(time*3))^10; local int = pulse*0.3*(c1[4] or 1)
        draw_list:AddRectFilled(p_min, p_max, fn.pack_color(c1[1],c1[2],c1[3],int,false,global_alpha_mult), 15)
    elseif a_var == 9 then
        if math.random() > 0.95 then
            draw_list:AddRectFilled(imgui.ImVec2(p_min.x,cy-10), imgui.ImVec2(p_max.x,cy+10), fn.pack_color(c1[1],c1[2],c1[3],0.3*(c1[4] or 1),false,global_alpha_mult))
        end
    elseif a_var == 10 then
        local flicker = (math.random() > 0.1) and 0.2 or 0.0
        draw_list:AddRectFilled(p_min, p_max, fn.pack_color(c1[1],c1[2],c1[3],flicker*(c1[4] or 1),false,global_alpha_mult), 15)
    elseif a_var == 11 then
        local sweep = (math.sin(time*2)+1)/2; local wx = p_min.x+sweep*(p_max.x-p_min.x)
        draw_list:AddRectFilled(imgui.ImVec2(wx-20,p_min.y), imgui.ImVec2(wx+20,p_max.y), fn.pack_color(c1[1],c1[2],c1[3],0.2*(c1[4] or 1),false,global_alpha_mult))
    elseif a_var == 12 then
        local shift = (math.sin(time)+1)/2; local c = (shift > 0.5) and c1 or c2
        draw_list:AddRectFilled(p_min, p_max, fn.pack_color(c[1],c[2],c[3],0.1*(c[4] or 1),false,global_alpha_mult), 15)
    elseif a_var == 13 then
        draw_list:AddCircle(imgui.ImVec2(cx,cy), max_r*.6, fn.pack_color(c1[1],c1[2],c1[3],0.3*(c1[4] or 1),false,global_alpha_mult), 32, 20)
    elseif a_var == 14 then
        local int = (math.sin(time*10) > 0.8) and 0.2*(c1[4] or 1) or 0
        draw_list:AddRectFilled(p_min, p_max, fn.pack_color(c1[1],c1[2],c1[3],int,false,global_alpha_mult), 15)
    elseif a_var == 15 then
        draw_list:AddRectFilledMultiColor(p_min, p_max,
            fn.pack_color(c1[1],c1[2],c1[3],0.2*(c1[4] or 1),false,global_alpha_mult), fn.pack_color(0,0,0,0),
            fn.pack_color(c2[1],c2[2],c2[3],0.2*(c2[4] or 1),false,global_alpha_mult), fn.pack_color(0,0,0,0))
    end
end
fn.draw_neon_border = function(draw_list, p_min, p_max, global_alpha_mult)
    local border_color = fn.pack_color(fx_cfg.neon_border_color[1], fx_cfg.neon_border_color[2],
        fx_cfg.neon_border_color[3], fx_cfg.neon_border_color[4] or 1, true, global_alpha_mult)
    draw_list:AddRect(p_min, p_max, border_color, 20, 15, 2.5)
    local tc = fx_cfg.tabs_color; local ab = tc[4] or 1
    for i = 1, 4 do
        local alpha  = 0.25*(1-(i/4))*ab
        local col    = fn.pack_color(tc[1],tc[2],tc[3],alpha,true,global_alpha_mult)
        local offset = i*1.5
        draw_list:AddRect(imgui.ImVec2(p_min.x-offset,p_min.y-offset), imgui.ImVec2(p_max.x+offset,p_max.y+offset), col, 20+offset, 15, 1.0)
    end
end
fn.draw_neon_glow = function(draw_list, p_min, p_max, color_rgb, thickness, intensity, alpha_mult)
    local ab = color_rgb[4] or 1
    for i = 1, thickness do
        local alpha = (intensity/thickness)*(thickness-i+1)*0.3*ab
        local col   = fn.pack_color(color_rgb[1],color_rgb[2],color_rgb[3],alpha,true,alpha_mult)
        draw_list:AddRect(imgui.ImVec2(p_min.x-i,p_min.y-i), imgui.ImVec2(p_max.x+i,p_max.y+i), col, 20, 15, 1.0)
    end
end
fn.draw_wave_strings = function(draw_list, p_min, p_max, color_rgb, global_alpha_mult)
    if not fx_cfg.waves_on[0] then return end
    local time = os.clock()*2*fx_cfg.waves_speed[0]
    local h, w = p_max.y-p_min.y, p_max.x-p_min.x
    local centerY = p_min.y + h/2
    local col_r, col_g, col_b, col_a = color_rgb[1], color_rgb[2], color_rgb[3], color_rgb[4] or 1
    imgui.PushClipRect(imgui.ImVec2(p_min.x+10,p_min.y+2), imgui.ImVec2(p_max.x-10,p_max.y-2), true)
    local w_var = fx_cfg.waves_var[0]
    if w_var == 0 then
        for i = 1, 3 do
            local speed, amplitude, frequency = i*.5, h*.15, 0.05
            local prev_p = nil
            for x = p_min.x, p_max.x, 4 do
                local y = centerY + math.sin(time*speed+(x-p_min.x)*frequency)*amplitude
                local curr = imgui.ImVec2(x,y)
                if prev_p then draw_list:AddLine(prev_p, curr, fn.pack_color(col_r,col_g,col_b,(0.4-i*.1)*col_a,false,global_alpha_mult), 1) end
                prev_p = curr
            end
        end
    elseif w_var == 1 then
        local bars = 15; local step = w/bars
        for i = 0, bars do
            local x = p_min.x+i*step; local phase = math.sin(time+i*.4); local bh = h*.4*math.abs(phase)
            draw_list:AddRectFilled(imgui.ImVec2(x+2,centerY-bh), imgui.ImVec2(x+step-2,centerY+bh),
                fn.pack_color(col_r,col_g,col_b,0.4*math.abs(phase)*col_a,false,global_alpha_mult), 2)
        end
    elseif w_var == 2 then
        local num_circles = 3; local mr = w > h and w or h
        for i = 1, num_circles do
            local phase = (time*.5+i/num_circles)%1; local radius = phase*mr; local alpha = (1-phase)*.5*col_a
            draw_list:AddCircle(imgui.ImVec2(p_min.x+w/2,centerY), radius, fn.pack_color(col_r,col_g,col_b,alpha,false,global_alpha_mult), 24, 2)
        end
    elseif w_var == 3 then
        local bs = 8
        for x = p_min.x, p_max.x, bs*1.5 do
            for y = p_min.y, p_max.y, bs*1.5 do
                local noise = math.sin(x*12.3+y*4.5+time*3)
                if noise > 0.6 then draw_list:AddRectFilled(imgui.ImVec2(x,y), imgui.ImVec2(x+bs,y+bs), fn.pack_color(col_r,col_g,col_b,(noise-.6)*2*col_a*.5,false,global_alpha_mult), 2) end
            end
        end
    elseif w_var == 4 then
        local prev_p = nil
        for x = p_min.x, p_max.x, 2 do
            local norm_x = (x-p_min.x)/w; local phase = (norm_x-time*.5)%1; local y_offset = 0
            if phase > 0.45 and phase < 0.55 then y_offset = math.sin((phase-.45)*10*math.pi)*(h*.4) end
            local curr = imgui.ImVec2(x, centerY-y_offset)
            if prev_p then draw_list:AddLine(prev_p, curr, fn.pack_color(col_r,col_g,col_b,.5*col_a,false,global_alpha_mult), 1.5) end
            prev_p = curr
        end
    elseif w_var == 5 then
        for x = p_min.x, p_max.x, 8 do
            local y1 = centerY+math.sin(time*2+x*.05)*(h*.25); local y2 = centerY+math.sin(time*2+x*.05+math.pi)*(h*.25)
            draw_list:AddLine(imgui.ImVec2(x,y1), imgui.ImVec2(x,y2), fn.pack_color(col_r,col_g,col_b,.2*col_a,false,global_alpha_mult), 1)
            draw_list:AddCircleFilled(imgui.ImVec2(x,y1), 2, fn.pack_color(col_r,col_g,col_b,.6*col_a,false,global_alpha_mult), 8)
            draw_list:AddCircleFilled(imgui.ImVec2(x,y2), 2, fn.pack_color(col_r,col_g,col_b,.6*col_a,false,global_alpha_mult), 8)
        end
    elseif w_var == 6 then
        local ccx, ccy = p_min.x+w/2, centerY; local angle = time*3
        draw_list:AddCircle(imgui.ImVec2(ccx,ccy), h*.4, fn.pack_color(col_r,col_g,col_b,.3*col_a,false,global_alpha_mult), 24, 1)
        draw_list:AddLine(imgui.ImVec2(ccx,ccy), imgui.ImVec2(ccx+math.cos(angle)*h*.4, ccy+math.sin(angle)*h*.4),
            fn.pack_color(col_r,col_g,col_b,.8*col_a,false,global_alpha_mult), 2)
    elseif w_var == 7 then
        local hex_s = 10
        for x = p_min.x, p_max.x, hex_s*1.5 do
            for y = p_min.y, p_max.y, hex_s*1.732 do
                local off_y = (math.floor(x/(hex_s*1.5))%2 == 1) and (hex_s*.866) or 0
                local alpha = (math.sin(x*.1+y*.1+time)+1)*.25*col_a
                draw_list:AddCircle(imgui.ImVec2(x,y+off_y), hex_s*.9, fn.pack_color(col_r,col_g,col_b,alpha,false,global_alpha_mult), 6, 1)
            end
        end
    elseif w_var == 8 then
        for i = 1, 4 do
            local ccx = p_min.x+w/2+math.sin(time+i)*(w*.3); local ccy = centerY+math.cos(time*1.3+i*2)*(h*.3)
            draw_list:AddCircleFilled(imgui.ImVec2(ccx,ccy), h*.4, fn.pack_color(col_r,col_g,col_b,.15*col_a,false,global_alpha_mult), 24)
        end
    elseif w_var == 9 then
        local pp1, pp2, pp3 = nil, nil, nil
        for x = p_min.x, p_max.x, 3 do
            local n_x = x*.05
            local y1 = centerY+math.sin(time*3+n_x)*h*.3
            local y2 = centerY+math.sin(time*2-n_x*1.5)*h*.2
            local y3 = centerY+math.sin(time*4+n_x*2)*h*.1
            if pp1 then draw_list:AddLine(pp1, imgui.ImVec2(x,y1), fn.pack_color(col_r,col_g,col_b,.3*col_a,false,global_alpha_mult), 1) end
            if pp2 then draw_list:AddLine(pp2, imgui.ImVec2(x,y2), fn.pack_color(col_r,col_g,col_b,.4*col_a,false,global_alpha_mult), 1.5) end
            if pp3 then draw_list:AddLine(pp3, imgui.ImVec2(x,y3), fn.pack_color(col_r,col_g,col_b,.5*col_a,false,global_alpha_mult), 2) end
            pp1, pp2, pp3 = imgui.ImVec2(x,y1), imgui.ImVec2(x,y2), imgui.ImVec2(x,y3)
        end
    elseif w_var == 10 then
        local ccx, ccy = p_min.x+w/2, centerY; local prev_p = nil
        for a = 0, 30, 0.2 do
            local r = a*2; local px = ccx+math.cos(a+time*5)*r; local py = ccy+math.sin(a+time*5)*r
            local curr = imgui.ImVec2(px,py)
            if prev_p then draw_list:AddLine(prev_p, curr, fn.pack_color(col_r,col_g,col_b,.4*col_a,false,global_alpha_mult), 1.5) end
            prev_p = curr
        end
    elseif w_var == 11 then
        local ccx = p_min.x+w/2; local angle = math.sin(time*2)*.8+math.pi/2
        local px = ccx+math.cos(angle)*h; local py = p_min.y+math.sin(angle)*h
        draw_list:AddLine(imgui.ImVec2(ccx,p_min.y), imgui.ImVec2(px,py), fn.pack_color(col_r,col_g,col_b,.5*col_a,false,global_alpha_mult), 2)
        draw_list:AddCircleFilled(imgui.ImVec2(px,py), 6, fn.pack_color(col_r,col_g,col_b,col_a,false,global_alpha_mult), 16)
    elseif w_var == 12 then
        for x = p_min.x, p_max.x, 15 do
            for y = p_min.y, p_max.y, 15 do
                local dir = math.floor(math.sin(x*y+time)*2)%2
                if dir == 0 then draw_list:AddLine(imgui.ImVec2(x,y), imgui.ImVec2(x+15,y+15), fn.pack_color(col_r,col_g,col_b,.4*col_a,false,global_alpha_mult), 1.5)
                else draw_list:AddLine(imgui.ImVec2(x+15,y), imgui.ImVec2(x,y+15), fn.pack_color(col_r,col_g,col_b,.4*col_a,false,global_alpha_mult), 1.5) end
            end
        end
    elseif w_var == 13 then
        for i = 1, 30 do
            local sx = p_min.x+((i*43+time*50)%w); local sy = p_min.y+((i*17)%h)
            draw_list:AddCircleFilled(imgui.ImVec2(sx,sy), 1.5, fn.pack_color(col_r,col_g,col_b,(math.sin(time*3+i)+1)*.4*col_a,false,global_alpha_mult), 8)
        end
    elseif w_var == 14 then
        for i = 1, 15 do
            local ccx = p_min.x+((i*101+math.sin(time)*20)%w); local ccy = p_min.y+((i*73+math.cos(time)*20)%h)
            draw_list:AddCircle(imgui.ImVec2(ccx,ccy), math.abs(math.sin(time*2+i))*10+2, fn.pack_color(col_r,col_g,col_b,.5*col_a,false,global_alpha_mult), 12, 1)
        end
    elseif w_var == 15 then
        for x = p_min.x, p_max.x, 20 do
            local y_off = math.sin(x*.05+time*3)*15; local y = centerY+y_off
            local col   = fn.pack_color(col_r,col_g,col_b,.6*col_a,false,global_alpha_mult)
            local pp1=imgui.ImVec2(x,y-5); local pp2=imgui.ImVec2(x+4,y-2); local pp3=imgui.ImVec2(x+4,y+2)
            local pp4=imgui.ImVec2(x,y+5); local pp5=imgui.ImVec2(x-4,y+2); local pp6=imgui.ImVec2(x-4,y-2)
            draw_list:AddLine(pp1,pp2,col,1.5); draw_list:AddLine(pp2,pp3,col,1.5); draw_list:AddLine(pp3,pp4,col,1.5)
            draw_list:AddLine(pp4,pp5,col,1.5); draw_list:AddLine(pp5,pp6,col,1.5); draw_list:AddLine(pp6,pp1,col,1.5)
        end
    elseif w_var == 16 then
        for x = p_min.x, p_max.x, 6 do
            local val = math.abs(math.sin(x*.1+time*5)*math.cos(x*.02-time))
            draw_list:AddLine(imgui.ImVec2(x,p_max.y), imgui.ImVec2(x,p_max.y-val*h), fn.pack_color(col_r,col_g,col_b,.5*col_a,false,global_alpha_mult), 3)
        end
    elseif w_var == 17 then
        local prev_p = nil
        for t_p = 0, math.pi*2, 0.05 do
            local px = p_min.x+w/2+math.sin(t_p*3+time*2)*w*.4
            local py = centerY+math.sin(t_p*4+time*3)*h*.4
            local curr = imgui.ImVec2(px,py)
            if prev_p then draw_list:AddLine(prev_p, curr, fn.pack_color(col_r,col_g,col_b,.5*col_a,false,global_alpha_mult), 1.5) end
            prev_p = curr
        end
    elseif w_var == 18 then
        for y = p_min.y, p_max.y, 10 do
            local prev_p = nil
            for x = p_min.x, p_max.x, 5 do
                local dy = y-centerY; local curr_y = y+math.sin(x*.05+time*3)*(dy*.3)
                local curr = imgui.ImVec2(x, curr_y)
                if prev_p then draw_list:AddLine(prev_p, curr, fn.pack_color(col_r,col_g,col_b,.3*col_a,false,global_alpha_mult), 1) end
                prev_p = curr
            end
        end
    end
    imgui.PopClipRect()
end
fn.draw_animated_settings_icon = function(draw_list, center, radius, hover_factor, time, global_alpha_mult)
    local g_c = fx_cfg.icon_gear_color; local ab = g_c[4] or 1
    local rot1 = time*(1.5+hover_factor*8)
    local rot2 = -time*(2+hover_factor*10)
    for i = 1, 3 do
        local angle_start = rot1+(i-1)*(math.pi*2/3)
        local angle_end   = angle_start+(math.pi*2/3)*.5
        draw_list:PathArcTo(center, radius, angle_start, angle_end, 15)
        local r_arc = .5+.5*math.sin(time*4+i*2)
        local g_arc = .5+.5*math.sin(time*4+i*2+2)
        local b_arc = .5+.5*math.sin(time*4+i*2+4)
        draw_list:PathStroke(fn.pack_color(r_arc,g_arc,b_arc,(0.4+0.6*hover_factor)*ab,false,global_alpha_mult), 0, 2+hover_factor)
    end
    for i = 1, 6 do
        local angle = rot2+(i-1)*(math.pi*2/6)
        local p_out = imgui.ImVec2(center.x+math.cos(angle)*(radius*.7), center.y+math.sin(angle)*(radius*.7))
        local p_in  = imgui.ImVec2(center.x+math.cos(angle+.3)*(radius*.3), center.y+math.sin(angle+.3)*(radius*.3))
        draw_list:AddLine(p_out, p_in, fn.pack_color(g_c[1],g_c[2],g_c[3],(0.6+0.4*hover_factor)*ab,false,global_alpha_mult), 1.5)
    end
    draw_list:AddCircleFilled(center, radius*.25, fn.pack_color(g_c[1],g_c[2],g_c[3],ab,false,global_alpha_mult), 12)
end
fn.draw_cross = function(dl, center, radius, hovered, global_alpha_mult)
    local hf = hovered and 1.0 or 0.0; local c_c = fx_cfg.icon_cross_color
    local col = fn.pack_color(c_c[1],c_c[2],c_c[3],(0.4+hf*.6)*(c_c[4] or 1),false,global_alpha_mult)
    local r = radius*.45; local t = 2+hf*.8
    dl:AddLine(imgui.ImVec2(center.x-r,center.y-r), imgui.ImVec2(center.x+r,center.y+r), col, t)
    dl:AddLine(imgui.ImVec2(center.x+r,center.y-r), imgui.ImVec2(center.x-r,center.y+r), col, t)
end
fn.draw_eye = function(dl, center, radius, closed_t, hovered, global_alpha_mult)
    local hf = hovered and 1.0 or 0.0; local e_c = fx_cfg.icon_eye_color
    local col = fn.pack_color(e_c[1],e_c[2],e_c[3],(0.4+hf*.6)*(e_c[4] or 1),false,global_alpha_mult)
    local p0  = imgui.ImVec2(center.x-radius, center.y)
    local p3  = imgui.ImVec2(center.x+radius, center.y)
    local ty  = radius*(1.1-closed_t*1.1)
    fn.draw_safe_bezier(dl, p0, imgui.ImVec2(center.x-radius/2,center.y-ty), imgui.ImVec2(center.x+radius/2,center.y-ty), p3, col, 2+hf*.5)
    fn.draw_safe_bezier(dl, p0, imgui.ImVec2(center.x-radius/2,center.y+ty), imgui.ImVec2(center.x+radius/2,center.y+ty), p3, col, 2+hf*.5)
    if closed_t < 0.9 then
        local mp  = imgui.GetIO().MousePos
        local dx  = mp.x-center.x; local dy = mp.y-center.y
        local dist = math.sqrt(dx*dx+dy*dy)
        local max_dist = radius*.4*(1-closed_t)
        local p_x, p_y = center.x, center.y
        if dist > 0 then local md = math.min(dist, max_dist); p_x=center.x+(dx/dist)*md; p_y=center.y+(dy/dist)*md end
        local cy = radius*.8*(1-closed_t)
        if p_y > center.y+cy then p_y=center.y+cy end
        if p_y < center.y-cy then p_y=center.y-cy end
        dl:AddCircleFilled(imgui.ImVec2(p_x,p_y), radius*.4*(1-closed_t),
            fn.pack_color(e_c[1],e_c[2],e_c[3],(1-closed_t)*(e_c[4] or 1),false,global_alpha_mult), 16)
    end
end
fn.ios_slider = function(label, val_ptr, min_v, max_v, global_alpha_mult)
    label = Fn.T(label)
    local f_bg  = active_colors[imgui.Col.FrameBg]
    local f_act = active_colors[imgui.Col.FrameBgActive]
    local bg_col   = fn.pack_color(f_bg[1],f_bg[2],f_bg[3],f_bg[4],false,global_alpha_mult)
    local fill_col = fn.pack_color(f_act[1],f_act[2],f_act[3],f_act[4],false,global_alpha_mult)
    local glow_c   = {f_act[1],f_act[2],f_act[3],f_act[4]}
    local avail_w  = imgui.GetContentRegionAvail().x
    local w_orig   = avail_w*.8; local offset_x = (avail_w-w_orig)/2
    imgui.SetCursorPosX(imgui.GetCursorPosX()+offset_x)
    imgui.BeginGroup()
    local h_orig, p_orig, dl = 26, imgui.GetCursorScreenPos(), imgui.GetWindowDrawList()
    imgui.InvisibleButton("slider_"..label, imgui.ImVec2(w_orig, h_orig))
    local active  = imgui.IsItemActive()
    local hovered = imgui.IsItemHovered()
    if active then
        state.is_any_slider_active = true
        val_ptr[0] = math.max(min_v, math.min(max_v, (imgui.GetIO().MousePos.x-p_orig.x)/w_orig*(max_v-min_v)+min_v))
    end
    if hovered then fn.set_hand_cursor() end
    slider_scale_anims[label] = fn.anim_update(slider_scale_anims[label] or 1.0, active and 1.03 or 1.0, 15)
    local scale = slider_scale_anims[label]
    local w, h = w_orig*scale, h_orig*scale
    local p = imgui.ImVec2(p_orig.x+(w_orig-w)/2, p_orig.y+(h_orig-h)/2)
    dl:AddRectFilled(p, imgui.ImVec2(p.x+w, p.y+h), bg_col, h/2)
    local progress = (val_ptr[0]-min_v)/(max_v-min_v)
    if progress > 0 then
        local fill_w = math.max(h, w*progress)
        dl:AddRectFilled(p, imgui.ImVec2(p.x+fill_w, p.y+h), fill_col, h/2)
        if active or hovered then fn.draw_neon_glow(dl, p, imgui.ImVec2(p.x+fill_w,p.y+h), glow_c, 5, 0.3, global_alpha_mult) end
    end
    button_anims[label] = fn.anim_update(button_anims[label] or 0.0, (hovered or active) and 1 or 0, 15)
    local t = button_anims[label]
    local val_text = string.format("%d%%", val_ptr[0]*100)
    local label_size = imgui.CalcTextSize(label); local val_size = imgui.CalcTextSize(val_text)
    fn.record_width(label_size.x+100)
    local txt_col = active_colors[imgui.Col.Text]
    local c = progress > 0.5 and 0.1 or txt_col[1]
    if (1-t) > 0.01 then dl:AddText(imgui.ImVec2(p.x+(w-label_size.x)/2, p.y+(h-label_size.y)/2), fn.pack_color(txt_col[1],txt_col[2],txt_col[3],1-t,active,global_alpha_mult), label) end
    if t > 0.01     then dl:AddText(imgui.ImVec2(p.x+(w-val_size.x)/2,   p.y+(h-val_size.y)/2),   fn.pack_color(c,c,c,t,active,global_alpha_mult), val_text) end
    imgui.EndGroup()
end
fn.ios_toggle = function(label, bool_ptr, global_alpha_mult)
    label = Fn.T(label)
    local dl  = imgui.GetWindowDrawList()
    local h, w = 18, 33
    local txt_col = active_colors[imgui.Col.Text] or {1,1,1,1}
    imgui.BeginGroup()
    imgui.SetWindowFontScale(0.9)
    imgui.TextColored(imgui.ImVec4(txt_col[1] or 1, txt_col[2] or 1, txt_col[3] or 1, 0.7*state.global_alpha*global_alpha_mult), label)
    imgui.SetWindowFontScale(1.0)
    fn.record_width(imgui.CalcTextSize(label).x+100)
    imgui.SameLine(imgui.GetWindowContentRegionMax().x-w-25)
    local p, id = imgui.GetCursorScreenPos(), "toggle_"..label
    imgui.InvisibleButton(id, imgui.ImVec2(w, h))
    if imgui.IsItemClicked() then bool_ptr[0] = not bool_ptr[0] end
    if imgui.IsItemHovered() then fn.set_hand_cursor() end
    button_anims[id] = fn.anim_update(button_anims[id] or (bool_ptr[0] and 1 or 0), bool_ptr[0] and 1 or 0, 15)
    local t = button_anims[id]
    local bg_off = active_colors[imgui.Col.FrameBg]
    local bg_on  = active_colors[imgui.Col.CheckMark]
    local cur_r = fn.lerp(bg_off[1],bg_on[1],t); local cur_g = fn.lerp(bg_off[2],bg_on[2],t); local cur_b = fn.lerp(bg_off[3],bg_on[3],t)
    local glow_c = {bg_on[1],bg_on[2],bg_on[3],bg_on[4]}
    dl:AddRectFilled(p, imgui.ImVec2(p.x+w,p.y+h), fn.pack_color(cur_r,cur_g,cur_b,bg_off[4],false,global_alpha_mult), h/2)
    if t > 0.1 then fn.draw_neon_glow(dl, p, imgui.ImVec2(p.x+w,p.y+h), glow_c, 3, t*.1, global_alpha_mult) end
    dl:AddCircleFilled(imgui.ImVec2(fn.lerp(p.x+h/2, p.x+w-h/2, t), p.y+h/2), h/2-2,
        fn.pack_color(0.9,0.9,0.9,1,true,global_alpha_mult), 24)
    imgui.EndGroup()
end
local function FontCombo(label, idx_ptr)
    label = Fn.T(label)
    local names = loaded_font_names
    if #names == 0 then return end
    local items_arr = ffi.new("const char*[?]", #names, names)
    if idx_ptr[0] >= #names then idx_ptr[0] = 0 end
    imgui.PushItemWidth(250)
    imgui.Combo(label, idx_ptr, items_arr, #names)
    imgui.PopItemWidth()
    fn.record_width(imgui.CalcTextSize(label).x + 150)
end
local CFG = {
    R_IN        = 94,
    R_OUT       = 211,
    SEP_GAP     = 0.010,
    SEG_Q       = 48,
    TILT_MAX    = 23,
    TILT_SQUISH = 0.10,
    OPEN_SPEED  = 10,
    CLOSE_SPEED = 12,
    HOVER_SPEED = 9,
    KEY_HOLD    = 0x33,
    HUE_R_THIN  = 4,
    HUE_R_FAT   = 13,
    HUE_HANDLE  = 8,
}
local function col(r,g,b,a)
        a = math.floor(math.max(0, math.min(255, a)) + 0.5)
    return (a*0x1000000)+(b*0x10000)+(g*0x100)+r
end
local function hsv2rgb(h,s,v)
    h=h%1.0; local i=math.floor(h*6); local f=h*6-i
    local p=v*(1-s); local q=v*(1-f*s); local tv=v*(1-(1-f)*s)
    local r,g,b; local m=i%6
    if m==0 then r,g,b=v,tv,p elseif m==1 then r,g,b=q,v,p
    elseif m==2 then r,g,b=p,v,tv elseif m==3 then r,g,b=p,q,v
    elseif m==4 then r,g,b=tv,p,v else r,g,b=v,p,q end
    return math.floor(r*255),math.floor(g*255),math.floor(b*255)
end
local lerp = CoreUtil.lerp
local function lerp01(a, b, t) return lerp(a, b, CoreUtil.clamp01(t)) end
local function lerpI(a,b,t) return math.floor(lerp01(a,b,t)) end
G_HUE=0.5333333333; G_SAT=1.0; G_TIME=0.0; G_FX=1
local N = #items
local bindings, bindingsVk = {}, {}
for i = 1, N do bindings[i] = ''; bindingsVk[i] = 0 end
local ini_path = CBUGER_CONFIG .. 'Wheel.ini'
local function wheel_saveSettings()
    local out = { string.format('hue=%.4f\nsat=%.4f\nfx=%d\n', G_HUE, G_SAT, G_FX) }
    for i = 1, N do
        out[#out + 1] = string.format('bindvk_%d=%d\n', i, bindingsVk[i] or 0)
    end
    return CBUGER_SAFE_WRITE_FILE(ini_path, table.concat(out))
end
local function wheel_loadSettings()
    local content = CBUGER_SAFE_READ_TEXT(ini_path, function(raw)
        return raw:match('hue=[%+%-]?[%d%.]+') ~= nil
            and raw:match('sat=[%+%-]?[%d%.]+') ~= nil
            and raw:match('fx=%d+') ~= nil
    end)
    if type(content) ~= 'string' then return end
    for line in (content .. '\n'):gmatch('([^\r\n]*)\r?\n') do
        local k,v = line:match('^(%w+)=(.+)$')
        if k=='hue' then G_HUE=tonumber(v) or 0 end
        if k=='sat' then G_SAT=tonumber(v) or 1 end
        if k=='fx'  then G_FX =tonumber(v) or 1 end
        local bi = k and k:match('^bindvk_(%d+)$')
        if bi then
            bi = tonumber(bi)
            if bi and bi >= 1 and bi <= N then bindingsVk[bi] = tonumber(v) or 0 end
        end
    end
end
wheel_loadSettings()
local PAL = {
    seg_idle = {h=0.0,  s=0.80, v=0.06, a=210},
    seg_hov  = {h=0.12, s=0.35, v=0.55, a=240},
    rim_out  = {h=0.0,  s=0.90, v=0.83, a=255},
    rim_in   = {h=0.0,  s=0.80, v=0.36, a=200},
    sep      = {h=0.0,  s=0.85, v=0.47, a=190},
    ctr_fill = {h=0.0,  s=0.80, v=0.04, a=230},
}
local function Pc(key)
    local b=PAL[key]; local h=(G_HUE+b.h)%1
    local r,g,bv=hsv2rgb(h,b.s*G_SAT,b.v); return col(r,g,bv,b.a)
end
local function sectorColor(t)
    local b1=PAL.seg_idle; local b2=PAL.seg_hov
    local h1=(G_HUE+b1.h)%1; local h2=(G_HUE+b2.h)%1
    local r1,g1,bv1=hsv2rgb(h1,b1.s*G_SAT,b1.v)
    local r2,g2,bv2=hsv2rgb(h2,b2.s*G_SAT,b2.v)
    return col(lerpI(r1,r2,t), lerpI(g1,g2,t), lerpI(bv1,bv2,t), lerpI(b1.a,b2.a,t))
end
local bind_conflict_msg_time=0
local S={
    visible=false, open=false, locked=false, anim=0,
    hover_t={}, hovered=-1, cx=0, cy=0,
    tilt_nx=0, tilt_ny=0, tilt_infl=0,
    mouse_over=false,
    bind_target=-1, waiting_key=false,
    bind_pulse_time=0, bind_cancelled=false, bind_conflict=false,
    hold_consumed=false,
    hue_dragging=false, hue_dragging_prev=false,
    sat_dragging=false, sat_dragging_prev=false,
    hue_hover_t=0, sat_hover_t=0,
    fx_t={},
}
for i=1,N do S.hover_t[i]=0; S.fx_t[i]=0 end
local function easeOutBack(t)
    t=math.max(0,math.min(1,t)); local s=1.70158; local u=t-1
    return u*u*((s+1)*u+s)+1
end
local vkNames={
    [0x41]='A',[0x42]='B',[0x43]='C',[0x44]='D',[0x45]='E',[0x46]='F',
    [0x47]='G',[0x48]='H',[0x49]='I',[0x4A]='J',[0x4B]='K',[0x4C]='L',
    [0x4D]='M',[0x4E]='N',[0x4F]='O',[0x50]='P',[0x51]='Q',[0x52]='R',
    [0x53]='S',[0x54]='T',[0x55]='U',[0x56]='V',[0x57]='W',[0x58]='X',
    [0x59]='Y',[0x5A]='Z',[0x30]='0',[0x31]='1',[0x32]='2',[0x33]='3',
    [0x34]='4',[0x35]='5',[0x36]='6',[0x37]='7',[0x38]='8',[0x39]='9',
    [0x70]='F1',[0x71]='F2',[0x72]='F3',[0x73]='F4',[0x74]='F5',[0x75]='F6',
    [0x76]='F7',[0x77]='F8',[0x78]='F9',[0x79]='F10',[0x7A]='F11',[0x7B]='F12',
    [0x20]='Space',[0x0D]='Enter',[0x1B]='Esc',[0x10]='Shift',[0x11]='Ctrl',
    [0x12]='Alt',[0x25]='Left',[0x26]='Up',[0x27]='Right',[0x28]='Down',
}
local function wheelKeyName(vk)
    if not vk or vk == 0 then return '' end
    return vkNames[vk] or string.format('VK%02X', vk)
end
for i = 1, N do
    if bindingsVk[i] and bindingsVk[i] ~= 0 then bindings[i] = wheelKeyName(bindingsVk[i]) end
end
local function makeVtxFn(cx,cy,nx,ny,infl,scale)
    return function(ang,r)
        local vx=math.cos(ang); local vy=math.sin(ang)
        local dot=vx*nx+vy*ny
        local push=dot*CFG.TILT_MAX*infl*scale
        local sf=1.0-CFG.TILT_SQUISH*infl*(0.5-dot*0.5)
        return cx+vx*r*sf+nx*push, cy+vy*r*sf+ny*push
    end
end
local function fillSector(dl, a0, a1, r_in, r_out, Q, color, vtx)
    local da=(a1-a0)/Q
    dl:PrimReserve(Q*6,(Q+1)*2)
    for s=0,Q do
        local ang=a0+s*da
        local xi,yi=vtx(ang,r_in)
        local xo,yo=vtx(ang,r_out)
        if s<Q then
            local idx=dl._VtxCurrentIdx
            dl:PrimWriteIdx(idx+0) dl:PrimWriteIdx(idx+2) dl:PrimWriteIdx(idx+1)
            dl:PrimWriteIdx(idx+3) dl:PrimWriteIdx(idx+2) dl:PrimWriteIdx(idx+1)
        end
        dl:PrimWriteVtx(ImVec2(xi,yi),ImVec2(0,0),color)
        dl:PrimWriteVtx(ImVec2(xo,yo),ImVec2(0,0),color)
    end
end
local function sectorAABB(a0,a1,r_in,r_out,vtx)
    local minx,miny,maxx,maxy
    for s=0,128 do
        local ang=a0+s*(a1-a0)/128
        for _,r in ipairs({r_in, r_out}) do
            local x,y=vtx(ang,r)
            if not minx then minx,miny,maxx,maxy=x,y,x,y
            else
                if x<minx then minx=x end; if x>maxx then maxx=x end
                if y<miny then miny=y end; if y>maxy then maxy=y end
            end
        end
    end
    for rs=0,20 do
        local r=r_in+rs*(r_out-r_in)/20
        for _,ang in ipairs({a0, a1}) do
            local x,y=vtx(ang,r)
            if x<minx then minx=x end; if x>maxx then maxx=x end
            if y<miny then miny=y end; if y>maxy then maxy=y end
        end
    end
    return minx+4, miny+4, maxx-4, maxy-4
end
local function drawSectorFX(dl,i,t,a0,a1,r_in,r_out,vtx,dt)
    if t<0.01 then return end
    S.fx_t[i]=S.fx_t[i]+dt
    local ft=S.fx_t[i]; local amid=(a0+a1)*0.5; local da=a1-a0
    local ba=math.floor(t*150); local Q2=12
    local cx1,cy1,cx2,cy2=sectorAABB(a0,a1,r_in,r_out,vtx)
    dl:PushClipRect(ImVec2(cx1,cy1),ImVec2(cx2,cy2),true)
    if G_FX==1 then
        for k=1,3 do
            local ra=math.max(a0+0.01,math.min(a1-0.01,amid+da*(k/4-0.5)+math.sin(ft*1.2+k)*0.09))
            local px,py
            for s=0,10 do
                local rx,ry=vtx(ra,r_in+(r_out-r_in)*s/10)
                if px then
                    local rr,rg,rb=hsv2rgb((G_HUE+k*0.1+s/30)%1,0.5,1)
                    dl:AddLine(ImVec2(px,py),ImVec2(rx,ry),col(rr,rg,rb,math.floor(ba*(1-s/10)*0.8)),1.5+t*1.5)
                end; px,py=rx,ry
            end
        end
    elseif G_FX==2 then
        for k=1,3 do
            local ph=(ft*1.8+k/3)%1.0; local rf=r_in+(r_out-r_in)*ph
            local aa=math.floor(ba*math.sin(ph*math.pi)*0.9)
            if aa>4 then
                local rr,rg,rb=hsv2rgb((G_HUE+k*0.15)%1,0.7,1); local ac=col(rr,rg,rb,aa)
                local px,py
                for s=0,Q2 do
                    local ax,ay=vtx(a0+s*da/Q2,rf)
                    if px then dl:AddLine(ImVec2(px,py),ImVec2(ax,ay),ac,1.5+t) end; px,py=ax,ay
                end
            end
        end
    elseif G_FX==3 then
        for k=1,6 do
            local ph=(ft*0.6+k/6)%1.0; local rf=r_in+(r_out-r_in)*ph
            local sa=math.max(a0+0.01,math.min(a1-0.01,a0+da*(k/7)+math.sin(ft*1.5+k)*0.05))
            local sx2,sy2=vtx(sa,rf); local aa=math.floor(ba*math.sin(ph*math.pi))
            if aa>8 then
                local rr,rg,rb=hsv2rgb((G_HUE+k*0.12+ph*0.2)%1,0.4,1)
                dl:AddCircleFilled(ImVec2(sx2,sy2),(1.5+t*2)*(0.5+ph*0.5),col(rr,rg,rb,aa),6)
            end
        end
    elseif G_FX==4 then
        local px,py
        for s=0,8 do
            local rf=r_in+(r_out-r_in)*s/8
            local ang2=math.max(a0+0.01,math.min(a1-0.01,amid+(s%2==0 and 1 or -1)*da*0.14*math.sin(ft*4+s)))
            local zx,zy=vtx(ang2,rf)
            if px then
                local rr,rg,rb=hsv2rgb((G_HUE+0.1)%1,0.2,1)
                dl:AddLine(ImVec2(px,py),ImVec2(zx,zy),col(rr,rg,rb,math.floor(ba*(1-s/8)*0.9)),1+t*2)
            end; px,py=zx,zy
        end
    elseif G_FX==5 then
        local tail  = 18
        local head  = (ft * 1.4) % 1.0
        local ro    = r_out - 2
        for s = 0, tail do
            local frac = (head - s / tail * 0.55) % 1.0
            local ang  = a0 + frac * da
            local fade = (1 - s / tail)
            local aa   = math.floor(ba * fade * fade)
            if aa > 3 then
                local wx, wy = vtx(ang, ro)
                local rr, rg, rb = hsv2rgb((G_HUE + fade * 0.08) % 1, lerp(0.6, 0.0, fade), 1.0)
                local sz = (2.5 + t * 2) * fade
                dl:AddCircleFilled(ImVec2(wx, wy), sz * 1.8, col(rr, rg, rb, math.floor(aa * 0.25)), 8)
                dl:AddCircleFilled(ImVec2(wx, wy), sz,       col(rr, rg, rb, aa),                    8)
            end
        end
    elseif G_FX==6 then
        for k=1,2 do
            local op=ft*(0.8+k*0.3)+k*math.pi
            local orb_margin=(r_out-r_in)*0.12
            local or2=r_in+orb_margin+(r_out-r_in-2*orb_margin)*(0.5+0.38*math.sin(op*0.7+k))
            local oa=math.max(a0+0.01,math.min(a1-0.01,amid+da*0.22*math.cos(op)*(k==1 and 1 or -1)))
            local ox,oy=vtx(oa,or2)
            local rr,rg,rb=hsv2rgb((G_HUE+k*0.25+op*0.05)%1,0.6,1)
            local sz=math.min(2+t*2, (r_out-r_in)*0.18)
            dl:AddCircleFilled(ImVec2(ox,oy),sz,col(rr,rg,rb,ba),8)
            for tr=1,4 do
                local tp=op-tr*0.25
                local tr2=r_in+orb_margin+(r_out-r_in-2*orb_margin)*(0.5+0.38*math.sin(tp*0.7+k))
                local ta=math.max(a0+0.01,math.min(a1-0.01,amid+da*0.22*math.cos(tp)*(k==1 and 1 or -1)))
                local tx,ty=vtx(ta,tr2)
                dl:AddCircleFilled(ImVec2(tx,ty),sz*(1-tr/5),col(rr,rg,rb,math.floor(ba*(1-tr/5)*0.5)),6)
            end
        end
    elseif G_FX==7 then
        for k=1,3 do
            local ca=a0+da*(k/4); local dp=(ft*0.9+k*0.33)%1.0
            for dr=0,4 do
                local ph=(dp-dr*0.1)%1.0; local rf=r_in+(r_out-r_in)*ph
                local dx,dy=vtx(ca,rf)
                local aa=math.floor(ba*(1-dr/5)*math.sin(ph*math.pi)*0.9)
                if aa>4 then
                    local rr,rg,rb=hsv2rgb((G_HUE+0.35)%1,dr==0 and 0 or 0.7,dr==0 and 1 or 0.8)
                    dl:AddCircleFilled(ImVec2(dx,dy),1.5+t*(dr==0 and 2 or 1),col(rr,rg,rb,aa),5)
                end
            end
        end
    elseif G_FX==8 then
        for k=1,5 do
            local ph=(ft*0.7+k*0.2)%1.0; local rf=r_in+(r_out-r_in)*ph*0.9
            local ea=math.max(a0+0.01,math.min(a1-0.01,amid+math.sin(ft*1.8+k*1.3)*da*0.13))
            local ex,ey=vtx(ea,rf); local aa=math.floor(ba*math.sin(ph*math.pi)*0.85)
            if aa>5 then
                local rr,rg,rb=hsv2rgb((G_HUE+ph*0.12)%1,0.8,1); local sz=(3+t*2)*(1-ph*0.5)
                dl:AddCircleFilled(ImVec2(ex,ey),sz,col(rr,rg,rb,aa),7)
                dl:AddCircleFilled(ImVec2(ex,ey),sz*2,col(rr,rg,rb,math.floor(aa*0.2)),7)
            end
        end
    elseif G_FX==9 then
        local hs=ft*1.5
        local particle_r=1.8+t*1.2
        local rf_min=r_in+particle_r+2
        local rf_max=r_out-particle_r-2
        for s=0,10 do
            local rf=r_in+(r_out-r_in)*(s/10)
            rf=math.max(rf_min,math.min(rf_max,rf))
            local swing=da*0.18*math.sin(hs+s*0.7)
            local ha=math.max(a0+0.02,math.min(a1-0.02,amid+swing))
            local hb=math.max(a0+0.02,math.min(a1-0.02,amid-swing))
            local hx1,hy1=vtx(ha,rf); local hx2,hy2=vtx(hb,rf)
            local aa=math.floor(ba*0.85)
            local rr1,rg1,rb1=hsv2rgb(G_HUE,0.7,1)
            local rr2,rg2,rb2=hsv2rgb((G_HUE+0.5)%1,0.7,1)
            dl:AddCircleFilled(ImVec2(hx1,hy1),particle_r,col(rr1,rg1,rb1,aa),6)
            dl:AddCircleFilled(ImVec2(hx2,hy2),particle_r,col(rr2,rg2,rb2,aa),6)
        end
    elseif G_FX==10 then
        local stars={}
        for k=1,5 do
            local ak=math.max(a0+0.01,math.min(a1-0.01,a0+da*(k-0.5)/5))
            local sx2,sy2=vtx(ak,r_in+(r_out-r_in)*(0.2+0.6*((k*137)%100/100)))
            stars[k]={x=sx2,y=sy2,p=0.6+0.4*math.sin(ft*1.3+k*1.7)}
        end
        for k=1,5 do
            local s2=stars[k]; local rr,rg,rb=hsv2rgb((G_HUE+k*0.09)%1,0.5,1)
            dl:AddCircleFilled(ImVec2(s2.x,s2.y),(1.5+t*2)*s2.p,col(rr,rg,rb,math.floor(ba*s2.p)),8)
            if k<5 then
                local s3=stars[k+1]
                dl:AddLine(ImVec2(s2.x,s2.y),ImVec2(s3.x,s3.y),col(rr,rg,rb,math.floor(ba*0.35)),1.0)
            end
        end
    end
    dl:PopClipRect()
end
local function drawHueRing(dl,cx,cy,scale,dt,vtx)
    local ring_r=(CFG.R_IN-8)*scale
    local half_w=lerp(CFG.HUE_R_THIN,CFG.HUE_R_FAT,S.hue_hover_t)*scale*0.5
    local ri=ring_r-half_w; local ro=ring_r+half_w
    local segs=64; local sda=2*math.pi/segs
    local mouse=imgui.GetIO().MousePos
    local mdx=mouse.x-cx; local mdy=mouse.y-cy
    local md=math.sqrt(math.max(mdx*mdx+mdy*mdy,1))
    local in_ring=md>=(ri-6) and md<=(ro+6)
    S.hue_hover_t=lerp(S.hue_hover_t,(in_ring or S.hue_dragging) and 1 or 0,dt*12)
    local ring_alpha=math.floor(lerp(130,215,S.hue_hover_t))
    dl:PrimReserve(segs*6,(segs+1)*2)
    for s=0,segs do
        local ang=s*sda-math.pi*0.5; local h2=s/segs
        local r2,g2,b2=hsv2rgb(h2,0.9,0.9); local c2=col(r2,g2,b2,ring_alpha)
        local xi,yi=vtx(ang,ri); local xo,yo=vtx(ang,ro)
        if s<segs then
            local idx=dl._VtxCurrentIdx
            dl:PrimWriteIdx(idx+0) dl:PrimWriteIdx(idx+2) dl:PrimWriteIdx(idx+1)
            dl:PrimWriteIdx(idx+3) dl:PrimWriteIdx(idx+2) dl:PrimWriteIdx(idx+1)
        end
        dl:PrimWriteVtx(ImVec2(xi,yi),ImVec2(0,0),c2); dl:PrimWriteVtx(ImVec2(xo,yo),ImVec2(0,0),c2)
    end
    local rim_a=math.floor(lerp(50,110,S.hue_hover_t)); local ppxi,ppyi,ppxo,ppyo
    for s=0,segs do
        local ang=s*sda-math.pi*0.5
        local xi2,yi2=vtx(ang,ri); local xo2,yo2=vtx(ang,ro)
        if ppxi then
            dl:AddLine(ImVec2(ppxi,ppyi),ImVec2(xi2,yi2),col(80,80,80,rim_a),1.0)
            dl:AddLine(ImVec2(ppxo,ppyo),ImVec2(xo2,yo2),col(80,80,80,rim_a),1.0)
        end; ppxi,ppyi=xi2,yi2; ppxo,ppyo=xo2,yo2
    end
    local ha=math.floor(S.hue_hover_t*255)
    if ha>5 then
        local hue_ang=G_HUE*2*math.pi-math.pi*0.5; local hx,hy=vtx(hue_ang,ring_r)
        local hr2,hg2,hb2=hsv2rgb(G_HUE,0.9,0.9); local hs=CFG.HUE_HANDLE*scale*S.hue_hover_t
        dl:AddCircleFilled(ImVec2(hx,hy),hs+2,col(255,255,255,ha),14)
        dl:AddCircleFilled(ImVec2(hx,hy),hs,col(hr2,hg2,hb2,ha),14)
        dl:AddCircle(ImVec2(hx,hy),hs+2,col(0,0,0,ha),14,1.5)
    end
    if imgui.IsMouseClicked(0) and in_ring then S.hue_dragging=true end
    if not imgui.IsMouseDown(0) then S.hue_dragging=false end
    if S.hue_dragging then G_HUE=(math.atan2(mdy,mdx)+math.pi*0.5)/(2*math.pi)%1.0 end
    if not imgui.IsMouseDown(0) and S.hue_dragging_prev then wheel_saveSettings() end
    S.hue_dragging_prev = S.hue_dragging
end
local function drawWheel(dl,cx,cy,scale,dt)
    G_TIME=G_TIME+dt
    if S.waiting_key then
        S.bind_pulse_time = S.bind_pulse_time + dt
    else
        S.bind_pulse_time = 0
    end
    local r_in=CFG.R_IN; local r_out=CFG.R_OUT; local Q=CFG.SEG_Q
    local mouse=imgui.GetIO().MousePos
    local mdx=mouse.x-cx; local mdy=mouse.y-cy; local md2=mdx*mdx+mdy*mdy
    local base_a=-math.pi*0.5; local arc=2*math.pi/N
    local hov=-1
    if md2>=r_in*r_in and md2<r_out*r_out then
        local a=(math.atan2(mdy,mdx)-base_a)%(2*math.pi)
        hov=math.floor(a/arc)+1; if hov>N then hov=N end
    end
    S.hovered=hov
    if S.waiting_key and hov >= 1 and hov ~= S.bind_target then
        S.waiting_key = false
        S.bind_target = -1
        S.bind_pulse_time = 0
        S.bind_cancelled = true
    end
    local dist=math.sqrt(math.max(md2,1))
    local over_wheel = dist <= r_out * 1.5
    if over_wheel then
        S.tilt_nx=lerp(S.tilt_nx,mdx/dist,dt*7)
        S.tilt_ny=lerp(S.tilt_ny,mdy/dist,dt*7)
        S.tilt_infl=lerp(S.tilt_infl,math.min(dist/(r_out*1.2),1.0),dt*7)
    else
        S.tilt_infl=lerp(S.tilt_infl,0,dt*5)
    end
    local vtx=makeVtxFn(cx,cy,S.tilt_nx,S.tilt_ny,S.tilt_infl,scale)
    for i=1,N do S.hover_t[i]=lerp(S.hover_t[i],(i==hov) and 1 or 0,dt*CFG.HOVER_SPEED) end
    do
        local dark_col = col(18,20,36,230)
        local Qr=96; local dar=2*math.pi/Qr
        dl:PrimReserve(Qr*6,(Qr+1)*2)
        for s=0,Qr do
            local ang=s*dar
            local xi,yi=vtx(ang,r_in); local xo,yo=vtx(ang,r_out)
            if s<Qr then
                local idx=dl._VtxCurrentIdx
                dl:PrimWriteIdx(idx+0) dl:PrimWriteIdx(idx+2) dl:PrimWriteIdx(idx+1)
                dl:PrimWriteIdx(idx+3) dl:PrimWriteIdx(idx+2) dl:PrimWriteIdx(idx+1)
            end
            dl:PrimWriteVtx(ImVec2(xi,yi),ImVec2(0,0),dark_col)
            dl:PrimWriteVtx(ImVec2(xo,yo),ImVec2(0,0),dark_col)
        end
    end
    for i=1,N do
        local t=S.hover_t[i]
        local a0=base_a+(i-1)*arc+CFG.SEP_GAP
        local a1=base_a+i*arc-CFG.SEP_GAP
        fillSector(dl,a0,a1,r_in,r_out,Q,sectorColor(t),vtx)
        drawSectorFX(dl,i,t,a0,a1,r_in,r_out,vtx,dt)
        if t>0.02 then
            do local nr,ng,nb=hsv2rgb(G_HUE,0.9,0.8); local ga=math.floor(100*t)
                if ga>0 then local px,py
                    for s=0,Q do local xo2,yo2=vtx(a0+s*(a1-a0)/Q,r_out)
                        if px then dl:AddLine(ImVec2(px,py),ImVec2(xo2,yo2),col(nr,ng,nb,ga),12*t) end; px,py=xo2,yo2
                    end
                end
            end
            do local nr2,ng2,nb2=hsv2rgb((G_HUE+0.05)%1,0.5,1.0); local ga=math.floor(180*t)
                if ga>0 then local px,py
                    for s=0,Q do local xo2,yo2=vtx(a0+s*(a1-a0)/Q,r_out)
                        if px then dl:AddLine(ImVec2(px,py),ImVec2(xo2,yo2),col(nr2,ng2,nb2,ga),5*t) end; px,py=xo2,yo2
                    end
                end
            end
        else
            local nr,ng,nb=hsv2rgb(G_HUE,0.85,0.85); local px,py
            for s=0,Q do local xo2,yo2=vtx(a0+s*(a1-a0)/Q,r_out)
                if px then dl:AddLine(ImVec2(px,py),ImVec2(xo2,yo2),col(nr,ng,nb,200),2.5) end; px,py=xo2,yo2
            end
        end
        local fa_fnt = rawget(_G,'icon')
        if fa_fnt then
            if items[i].icon_char == nil then
                items[i].icon_char = getIcon(items[i].icon_key) or false
            end
            local ico = items[i].icon_char
            if ico then
                local amid2  = (a0+a1)*0.5
                local icon_r = (r_in+r_out)*0.5
                local ix, iy = vtx(amid2, icon_r)
                local isz = 36*scale
                local icon_scale = 1.0
                local icon_alpha = 1.0
                if S.waiting_key then
                    if i == S.bind_target then
                        local wave = (S.bind_pulse_time * 2.6) % (math.pi * 2)
                        local pulse = (math.sin(wave) + 1.0) * 0.5
                        icon_scale = lerp(0.9, 1.4, pulse)
                        icon_alpha = lerp(0.15, 1.0, pulse)
                    else
                        icon_scale = 0.7
                        icon_alpha = 1.0
                        local drift_t = S.bind_pulse_time * (0.62 + (i % 3) * 0.08) + i * 1.73
                        local drift_r = (7.0 + (i % 4) * 2.5) * scale
                        local drift_x = math.cos(drift_t * 1.13) * drift_r + math.sin(drift_t * 0.63 + i) * drift_r * 0.35
                        local drift_y = math.sin(drift_t * 0.91) * drift_r * 0.72 + math.cos(drift_t * 0.57 + i * 0.8) * drift_r * 0.28
                        ix = ix + drift_x
                        iy = iy + drift_y
                    end
                end
                local draw_sz = isz * icon_scale
                local alpha = lerp(0.65, 1.0, t) * icon_alpha
                local ir,ig,ib = hsv2rgb(G_HUE, lerp(0.18, 0.0, t), 1.0)
                local c1 = CBUGER_ApplyOverlayAlphaU32(imgui.ColorConvertFloat4ToU32(imgui.ImVec4(ir/255,ig/255,ib/255,alpha)))
                local c0 = CBUGER_ApplyOverlayAlphaU32(imgui.ColorConvertFloat4ToU32(imgui.ImVec4(0,0,0,alpha*0.4)))
                local tsz2 = fa_fnt:CalcTextSizeA(draw_sz,1000,0,ico)
                dl:AddTextFontPtr(fa_fnt,draw_sz,imgui.ImVec2(ix-tsz2.x*0.5+1,iy-tsz2.y*0.5+1),c0,ico)
                dl:AddTextFontPtr(fa_fnt,draw_sz,imgui.ImVec2(ix-tsz2.x*0.5,  iy-tsz2.y*0.5),  c1,ico)
            end
        end
        if t>0.01 then
            local amid=(a0+a1)*0.5
            local lbl=items[i].label
            local la=math.floor(t*255); local ls=math.floor(t*160)
            local fnt = CBUGER_GET_GLOBAL_FONT()
            local has_wheel_font = fnt ~= nil
            if has_wheel_font then imgui.PushFont(fnt) end
            local tsz=imgui.CalcTextSize(lbl)
            local angx, angy = math.cos(amid), math.sin(amid)
            local half_proj = (tsz.x * 0.5) * math.abs(angx) + (tsz.y * 0.5) * math.abs(angy)
            local label_gap = (70 + (items[i].label_extra or 0)) * 0.405 * scale
            local label_r = r_out + label_gap + half_proj
            local lox=cx + angx*label_r
            local loy=cy + angy*label_r
            dl:AddText(ImVec2(lox-tsz.x*0.5+1,loy-tsz.y*0.5+1),col(0,0,0,ls),lbl)
            local lr,lg,lb = hsv2rgb(G_HUE,0.18,1.0)
            dl:AddText(ImVec2(lox-tsz.x*0.5,  loy-tsz.y*0.5),  col(lr,lg,lb,la),lbl)
            if has_wheel_font then imgui.PopFont() end
        end
    end
    for i=1,N do
        local sep_ang=base_a+(i-1)*arc
        local xi2,yi2=vtx(sep_ang,r_in); local xo2,yo2=vtx(sep_ang,r_out)
        local tL=S.hover_t[((i-2)%N)+1]; local tR=S.hover_t[i]
        local tm=math.max(tL,tR)
        local sr,sg,sb=hsv2rgb(G_HUE,0.9*G_SAT,0.8)
        local sa=math.floor(lerp(200,255,tm))
        local sc2=col(math.floor(lerp(0,sr,tm)),math.floor(lerp(0,sg,tm)),math.floor(lerp(0,sb,tm)),sa)
        dl:AddLine(ImVec2(xi2,yi2),ImVec2(xo2,yo2),sc2,3.0)
    end
    local s2=96; local d2=2*math.pi/s2; local pxi,pyi,pxo,pyo
    for s=0,s2 do
        local ang=s*d2
        local xi2,yi2=vtx(ang,r_in); local xo2,yo2=vtx(ang,r_out)
        if pxi then
            dl:AddLine(ImVec2(pxi,pyi),ImVec2(xi2,yi2),Pc('rim_in'),2.0)
            dl:AddLine(ImVec2(pxo,pyo),ImVec2(xo2,yo2),Pc('rim_out'),3.5)
        end; pxi,pyi=xi2,yi2; pxo,pyo=xo2,yo2
    end
    for i=1,N do
        local t=S.hover_t[i]
        if t>0.01 then
            local a0=base_a+(i-1)*arc+CFG.SEP_GAP
            local a1=base_a+i*arc-CFG.SEP_GAP
            local px,py
            for s=0,Q do
                local ang2=a0+s*(a1-a0)/Q
                local xo2,yo2=vtx(ang2,r_out)
                if px then
                    dl:AddLine(ImVec2(px,py),ImVec2(xo2,yo2),col(180,210,255,math.floor(t*140)),9)
                    dl:AddLine(ImVec2(px,py),ImVec2(xo2,yo2),col(255,255,255,math.floor(t*255)),3.5)
                end
                px,py=xo2,yo2
            end
        end
    end
    drawHueRing(dl,cx,cy,scale,dt,vtx)
end
local function drawSatRing(dl,ccx,ccy,cr,dt)
    local ring_r = cr
    local thin_h = 2.5
    local fat_h  = 6
    local half_w = lerp(thin_h, fat_h, S.sat_hover_t) * 0.5
    local ri = ring_r - half_w
    local ro = ring_r + half_w
    local segs = 64
    local sda = 2*math.pi / segs
    local mouse = imgui.GetIO().MousePos
    local mdx = mouse.x - ccx; local mdy = mouse.y - ccy
    local md  = math.sqrt(math.max(mdx*mdx + mdy*mdy, 1))
    local in_ring = md >= (ri - 5) and md <= (ro + 5)
    S.sat_hover_t = lerp(S.sat_hover_t, (in_ring or S.sat_dragging) and 1 or 0, dt*12)
    if imgui.IsMouseClicked(0) and in_ring and not S.hue_dragging then
        S.sat_dragging = true
    end
    if not imgui.IsMouseDown(0) then
        if S.sat_dragging_prev then wheel_saveSettings() end
        S.sat_dragging = false
    end
    S.sat_dragging_prev = S.sat_dragging
    if S.sat_dragging then
        G_SAT = math.max(0, math.min(1,
            ((math.atan2(mdy, mdx) + math.pi*0.5) / (2*math.pi)) % 1.0))
    end
    local ring_alpha = math.floor(lerp(160, 230, S.sat_hover_t))
    dl:PrimReserve(segs*6, (segs+1)*2)
    for s = 0, segs do
        local ang = s * sda - math.pi*0.5
        local sat_here = (s / segs)
        local r2,g2,b2 = hsv2rgb(G_HUE, sat_here, 0.90)
        local c2 = col(r2, g2, b2, ring_alpha)
        local xi = ccx + math.cos(ang)*ri; local yi = ccy + math.sin(ang)*ri
        local xo = ccx + math.cos(ang)*ro; local yo = ccy + math.sin(ang)*ro
        if s < segs then
            local idx = dl._VtxCurrentIdx
            dl:PrimWriteIdx(idx+0) dl:PrimWriteIdx(idx+2) dl:PrimWriteIdx(idx+1)
            dl:PrimWriteIdx(idx+3) dl:PrimWriteIdx(idx+2) dl:PrimWriteIdx(idx+1)
        end
        dl:PrimWriteVtx(ImVec2(xi,yi), ImVec2(0,0), c2)
        dl:PrimWriteVtx(ImVec2(xo,yo), ImVec2(0,0), c2)
    end
    local ha = math.floor(lerp(180, 255, S.sat_hover_t))
    local handle_ang = G_SAT * 2*math.pi - math.pi*0.5
    local hx = ccx + math.cos(handle_ang) * ring_r
    local hy = ccy + math.sin(handle_ang) * ring_r
    local hr2,hg2,hb2 = hsv2rgb(G_HUE, G_SAT, 0.95)
    local hs = lerp(3.5, 6, S.sat_hover_t)
    dl:AddCircleFilled(ImVec2(hx,hy), hs+2, col(0,0,0,200), 12)
    dl:AddCircleFilled(ImVec2(hx,hy), hs,   col(hr2,hg2,hb2,ha), 12)
    dl:AddCircle(ImVec2(hx,hy), hs+2, col(255,255,255,ha), 12, 1.5)
end
local function drawCenter(dl,cx,cy,scale,dt)
    local cr=(CFG.R_IN-12)*0.88
    local ccx=cx+S.tilt_nx*S.tilt_infl*8*scale
    local ccy=cy+S.tilt_ny*S.tilt_infl*8*scale
    local mouse=imgui.GetIO().MousePos
    local dcx=mouse.x-cx; local dcy=mouse.y-cy
    if imgui.IsMouseClicked(0) and (dcx*dcx+dcy*dcy)<(cr*cr) and not S.hue_dragging then
        G_FX=(G_FX%10)+1; wheel_saveSettings()
    end
    local pulse=0.7+0.3*math.sin(G_TIME*2.5)
    local pr,pg,pb=hsv2rgb(G_HUE,0.8,0.7)
    dl:AddCircleFilled(ImVec2(ccx,ccy),cr*1.08,col(pr,pg,pb,math.floor(35*pulse)),48)
    dl:AddCircleFilled(ImVec2(ccx,ccy),cr,Pc('ctr_fill'),48)
    drawSatRing(dl,ccx,ccy,cr,dt)
    local over_center = (dcx*dcx+dcy*dcy) < (cr*cr)
    local function at(x,y,c,s)
        local fnt = CBUGER_GET_GLOBAL_FONT()
        if fnt then
            imgui.PushFont(fnt)
            dl:AddText(ImVec2(x,y),c,s)
            imgui.PopFont()
        else
            dl:AddText(ImVec2(x,y),c,s)
        end
    end
    if S.waiting_key then
        local l1=items[S.bind_target].label; local sz1=imgui.CalcTextSize(l1)
        at(ccx-sz1.x*0.5+1,ccy-sz1.y-1,col(0,0,0,150),l1)
        at(ccx-sz1.x*0.5,ccy-sz1.y-1,col(255,100,100,255),l1)
        local showConflict = S.bind_conflict and (os.clock() - bind_conflict_msg_time) < 1.6
        local l2 = showConflict and u8"< клавиша уже занята >" or u8"< нажмите клавишу >"
        local sz2=imgui.CalcTextSize(l2)
        at(ccx-sz2.x*0.5+1,ccy+3,col(0,0,0,130),l2)
        if showConflict then
            at(ccx-sz2.x*0.5,ccy+3,col(255,80,80,240),l2)
        else
            local pr2,pg2,pb2=hsv2rgb(G_HUE,0.35,1.0)
            at(ccx-sz2.x*0.5,ccy+3,col(pr2,pg2,pb2,230),l2)
        end
    elseif S.hovered>=1 then
        local l1=items[S.hovered].label; local sz1=imgui.CalcTextSize(l1)
        at(ccx-sz1.x*0.5+1,ccy-sz1.y*0.5,col(0,0,0,150),l1)
        at(ccx-sz1.x*0.5,ccy-sz1.y*0.5,col(255,230,100,240),l1)
        if bindings[S.hovered]~='' then
            local l2='['..bindings[S.hovered]..']'; local sz2=imgui.CalcTextSize(l2)
            at(ccx-sz2.x*0.5+1,ccy+sz1.y*0.5+3,col(0,0,0,120),l2)
            at(ccx-sz2.x*0.5,ccy+sz1.y*0.5+3,col(180,220,255,200),l2)
        end
    end
    if S.waiting_key then
        local wave_period = 3.0
        local wave_t = (S.bind_pulse_time % wave_period) / wave_period
        local wave_r = cr * (0.12 + wave_t * 1.20)
        local wave_a = math.floor(95 * (1.0 - wave_t) * (1.0 - wave_t))
        local rr, gg, bb = hsv2rgb(G_HUE, G_SAT, 1.0)
        if wave_a > 0 then
            dl:AddCircle(ImVec2(ccx, ccy), wave_r, col(rr,gg,bb,wave_a), 64, math.max(1.2, 2.5 * scale))
        end
        local white_t = (math.sin((S.bind_pulse_time / wave_period) * math.pi * 2.0 - math.pi * 0.5) + 1.0) * 0.5
        local pulse_a = math.floor((4 + 26 * white_t * white_t) * 0.15)
        dl:AddCircleFilled(ImVec2(ccx, ccy), cr * 0.98, col(rr,gg,bb,pulse_a), 48)
    end
    if not S.waiting_key then
        local dring=cr*0.68
        local wave_speed=3.0
        for k=1,10 do
            local da=(k-1)/10*2*math.pi-math.pi*0.5
            local dx=ccx+math.cos(da)*dring; local dy=ccy+math.sin(da)*dring
            local dr,dg,db=hsv2rgb((G_HUE+k*0.08)%1,0.8,0.9)
            local active=(k==G_FX)
            if over_center then
                if active then dl:AddCircleFilled(ImVec2(dx,dy),5*scale*2,col(dr,dg,db,50),10) end
                dl:AddCircleFilled(ImVec2(dx,dy),active and 5*scale or 3*scale,col(dr,dg,db,active and 240 or 70),10)
            else
                local phase=G_TIME*wave_speed-(k-1)/10*2*math.pi
                local pulse_t=(math.sin(phase)+1)*0.5
                local base_r = active and 5*scale or 3*scale
                local pulse_r = base_r + pulse_t*(active and 3*scale or 2*scale)
                local base_a = active and 240 or 70
                local pulse_a = math.floor(base_a + pulse_t*(255-base_a)*0.6)
                if active then dl:AddCircleFilled(ImVec2(dx,dy),pulse_r*1.6,col(dr,dg,db,math.floor(pulse_t*60)),10) end
                dl:AddCircleFilled(ImVec2(dx,dy),pulse_r,col(dr,dg,db,pulse_a),10)
            end
        end
    end
end
local hm_window_open = new.bool(false)
local hm_isRunning   = false
local hm_autoCycle   = { enabled=false, speed_ms=2000, last_ms=0 }
local hm_hotkey      = new.int(0)
local hm_bullets, hm_initialMarkers, hm_bulletHoles = {}, {}, {}
local hm_lastMarkerPlace = -1
local hm_ci          = nil
local HM_IMG_QUEUE   = {}
local hm_imgQueueAdvance
local function closeModulesForRadial()
    if type(CB) == 'table' and type(CB.neon) == 'table' then
        if CB.neon.target_main then CB.neon.target_main[0] = false end
        if CB.neon.target_editor then CB.neon.target_editor[0] = false end
        if CB.neon.target_combo_editor then CB.neon.target_combo_editor[0] = false end
    end
    if mainWindow then mainWindow[0] = false end
    if hz_mainWindow then hz_mainWindow[0] = false end
    if statsWindowOpen then statsWindowOpen[0] = false end
    if compareOpen then compareOpen[0] = false end
    if window_state then window_state[0] = false end
    if RT and RT.window then RT.window[0] = false end
    if hm_window_open then hm_window_open[0] = false end
    if pt_windowSettings then pt_windowSettings[0] = false end
    cbug_just_opened = false
    hz_just_opened = false
end
local function activateWheelItem(idx)
    closeModulesForRadial()
    if idx == 1 then
        CB.neon.target_main[0] = true
        imgui.Process = true
        S.open = false
        S.locked = false
    elseif idx == 2 then
        mainWindow[0] = true
        imgui.Process = true
        S.open = false
        S.locked = false
        cbug_just_opened = true
    elseif idx == 3 then
        window_state[0] = true
        imgui.Process = true
        if not S.locked then S.open = false end
    elseif idx == 4 then
        hz_mainWindow[0] = true
        imgui.Process = true
        S.open = false
        S.locked = false
        hz_just_opened = true
    elseif idx == 5 then
        RT.window[0] = true
        imgui.Process = true
        S.open = false
        S.locked = false
    elseif idx == 6 then
        hm_window_open[0] = true
        imgui.Process = true
        S.open = false
        S.locked = false
        S.visible = false
    elseif idx == 7 then
        pt_windowSettings[0] = true
        imgui.Process = true
        S.open = false
        S.locked = false
    end
end
local render=imgui.OnFrame(
    function() return S.visible end,
    function(player)
        local io=imgui.GetIO(); local sw=io.DisplaySize.x; local sh=io.DisplaySize.y
        local dt=math.max(io.DeltaTime,0.001)
        if S.open then S.anim=math.min(S.anim+dt*CFG.OPEN_SPEED,1.0)
        else S.anim=math.max(S.anim-dt*CFG.CLOSE_SPEED,0.0)
            if S.anim<=0.001 then S.visible=false end
        end
        local scale=easeOutBack(S.anim); if scale<0 then scale=0 end
        imgui.SetNextWindowPos(ImVec2(0,0)); imgui.SetNextWindowSize(ImVec2(sw,sh))
        imgui.PushStyleColor(imgui.Col.WindowBg,ImVec4(0,0,0,0))
        imgui.PushStyleColor(imgui.Col.Border,ImVec4(0,0,0,0))
        imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding,0)
        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding,ImVec2(0,0))
        imgui.Begin('##sw',nil,
            imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoResize+
            imgui.WindowFlags.NoScrollbar+imgui.WindowFlags.NoInputs+
            imgui.WindowFlags.NoSavedSettings+imgui.WindowFlags.NoBringToFrontOnFocus)
        local dl=imgui.GetWindowDrawList()
        dl:PushClipRectFullScreen()
        if S.anim>0 then dl:AddRectFilled(ImVec2(0,0),ImVec2(sw,sh),col(0,0,0,math.floor(45*S.anim))) end
        if scale>0.01 then
            local ri0,ro0=CFG.R_IN,CFG.R_OUT
            CFG.R_IN=ri0*scale; CFG.R_OUT=ro0*scale
            drawWheel(dl,S.cx,S.cy,scale,dt)
            drawCenter(dl,S.cx,S.cy,scale,dt)
            CFG.R_IN=ri0; CFG.R_OUT=ro0
        end
        dl:PopClipRect()
        imgui.End(); imgui.PopStyleColor(2); imgui.PopStyleVar(2)
        if S.open and imgui.IsMouseReleased(1) and S.hovered>=1 then
            if S.waiting_key and S.hovered == S.bind_target then
                S.waiting_key = false
                S.bind_target = -1
                S.bind_pulse_time = 0
                S.bind_cancelled = true
                S.bind_conflict = false
            elseif not S.waiting_key then
                S.bind_target = S.hovered
                S.waiting_key = true
                S.bind_pulse_time = 0
                S.bind_cancelled = false
                S.bind_conflict = false
            end
        end
        if S.open and imgui.IsMouseReleased(0) and S.hovered>=1 and not S.waiting_key and not S.hue_dragging then
            activateWheelItem(S.hovered)
        end
    end
)
local newFrame = imgui.OnFrame(
    function() return state.target_main[0] or state.target_editor[0]
                   or (state.main_alpha > 0.01) or (state.editor_alpha > 0.01)
                   or CBUGER_MODULE_ACTIVE('headicons', window_state[0], CBUGER_GET_ANIM_RATE(15))
                   or CBUGER_MODULE_ACTIVE('hitmarker', hm_window_open[0], CBUGER_GET_ANIM_RATE(15))
                   or CBUGER_MODULE_ACTIVE('cbug_speed', mainWindow[0], CBUGER_GET_ANIM_RATE(15))
                   or CBUGER_MODULE_ACTIVE('hitzones_main', hz_mainWindow[0], CBUGER_GET_ANIM_RATE(15))
        or CBUGER_MODULE_ACTIVE('hitzones_stats', statsWindowOpen[0], CBUGER_GET_ANIM_RATE(15))
        or CBUGER_MODULE_ACTIVE('hitzones_compare', compareOpen[0], CBUGER_GET_ANIM_RATE(15))
                   or (hm_autoCycle and hm_autoCycle.enabled and not hm_isRunning) end,
    function(player)
        local style = imgui.GetStyle()
        if state.is_first_frame then
            for _, col in ipairs(lists.imgui_colors) do
                if col.id ~= nil then
                    local c = style.Colors[col.id]
                    active_colors[col.id] = {c.x, c.y, c.z, c.w}
                end
            end
            fn.ApplyGlobalTheme(fx_cfg.global_base_color[1], fx_cfg.global_base_color[2], fx_cfg.global_base_color[3])
            state.is_first_frame = false
        end
        for id, clr in pairs(active_colors) do
            style.Colors[id] = imgui.ImVec4(clr[1] or 1, clr[2] or 1, clr[3] or 1, clr[4] or 1)
        end
        ui_anim.dt = os.clock() - ui_anim.last_time
        ui_anim.last_time = os.clock()
        state.settings_time = state.settings_time + ui_anim.dt
        if CBUGER_GET_SMOOTH_CLOSE() then
            state.main_alpha   = fn.anim_update(state.main_alpha,   state.target_main[0]   and 1 or 0, CBUGER_GET_ANIM_RATE(15))
            state.editor_alpha = fn.anim_update(state.editor_alpha, state.target_editor[0] and 1 or 0, CBUGER_GET_ANIM_RATE(15))
        else
            state.main_alpha   = state.target_main[0]   and 1 or 0
            state.editor_alpha = state.target_editor[0] and 1 or 0
        end
        local io = imgui.GetIO()
        if not imgui.IsMouseDown(0) then
            state.is_dragging      = false; state.is_resizing      = false
            state.is_scrolling_bar = false; state.editor_is_dragging = false
            state.editor_is_resizing = false
        end
        pcall(function() style.WindowRounding = 20 end)
        pcall(function() style.FrameRounding  =  8 end)
        pcall(function() style.GrabRounding   =  8 end)
        pcall(function() style.ChildRounding  =  8 end)
        pcall(function() style.WindowBorderSize = 1 end)
        pcall(function() style.FrameBorderSize  = 1 end)
        pcall(function() style.ChildBorderSize  = 1 end)
        local popup_alpha = math.max(state.main_alpha, state.editor_alpha)
        pcall(function() style.PopupBorderSize = popup_alpha < 0.5 and 0 or 1 end)
        local win_bg_color = active_colors[imgui.Col.WindowBg]
        local updated_cursor = false
        local function render_state_main_window()
        if state.main_alpha > 0.01 then
            state.current_rendering_window = "main"
            state.current_frame_max_w = 400
            local main_draw_alpha = state.main_alpha * CBUGER_GET_INTERFACE_ALPHA()
            local target_global_alpha = 1.0
            if state.is_collapsed then target_global_alpha = 0.3
            elseif state.is_any_slider_active then target_global_alpha = 0.6 end
            state.global_alpha = fn.anim_update(state.global_alpha, target_global_alpha, CBUGER_GET_ANIM_RATE(10))
            state.is_any_slider_active = false
            state.eye_anim_state = fn.anim_update(state.eye_anim_state, state.is_collapsed and 1 or 0, CBUGER_GET_ANIM_RATE(10))
            local actual_h = state.window_size.h - (state.window_size.h-50)*state.eye_anim_state
            if state.is_resizing then
                state.window_size.w = math.max(350, state.resize_start_size.w+(io.MousePos.x-state.resize_start_mouse.x))
                state.window_size.h = math.max(400, state.resize_start_size.h+(io.MousePos.y-state.resize_start_mouse.y))
                actual_h = state.window_size.h
            else
                if not state.is_collapsed and state.eye_anim_state < 0.1 then
                    state.content_max_w = fn.anim_update(state.content_max_w, state.current_frame_max_w, 5)
                end
                state.window_size.w = fn.anim_update(state.window_size.w, math.max(state.window_size.w, state.content_max_w), 10)
            end
            if state.is_dragging then
                imgui.SetNextWindowPos(imgui.ImVec2(io.MousePos.x-state.drag_offset.x, io.MousePos.y-state.drag_offset.y), imgui.Cond.Always)
            end
            imgui.SetNextWindowSize(imgui.ImVec2(state.window_size.w, actual_h), imgui.Cond.Always)
            local pushes_count = 0
            imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0,0,0,0)); pushes_count=pushes_count+1
            local pop_b_col = active_colors[imgui.Col.Border] or {1,1,1,1}
            imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(pop_b_col[1],pop_b_col[2],pop_b_col[3],(pop_b_col[4] or 1)*main_draw_alpha)); pushes_count=pushes_count+1
            if imgui.Col.PopupBg then
                local pbc = active_colors[imgui.Col.PopupBg] or {0.08,0.08,0.1,0.98}
                imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(pbc[1],pbc[2],pbc[3],(pbc[4] or 0.98)*main_draw_alpha)); pushes_count=pushes_count+1
            end
            imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0,0))
            imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, main_draw_alpha)
            imgui.Begin("Neon Window Fix", nil,
                imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize +
                imgui.WindowFlags.NoMove   + imgui.WindowFlags.NoScrollbar)
                local dl       = imgui.GetWindowDrawList()
                local win_pos  = imgui.GetWindowPos()
                local win_size = imgui.GetWindowSize()
                local p_min    = win_pos
                local p_max    = imgui.ImVec2(win_pos.x+win_size.x, win_pos.y+win_size.y)
                local DYNAMIC_COLOR_BG = fn.pack_color(win_bg_color[1],win_bg_color[2],win_bg_color[3],win_bg_color[4],true,main_draw_alpha)
                local mp = io.MousePos
                local is_inside = (mp.x>=p_min.x and mp.x<=p_max.x and mp.y>=p_min.y and mp.y<=p_max.y)
                if (imgui.IsWindowHovered() or is_inside) and io.MouseWheel ~= 0 then
                    state.scroll_target = math.max(0, math.min(state.max_scroll, state.scroll_target - io.MouseWheel*45))
                end
                dl:AddRectFilled(p_min, p_max, DYNAMIC_COLOR_BG, 20)
                local b_col = active_colors[imgui.Col.Border]
                local border_col_u32 = fn.pack_color(b_col[1],b_col[2],b_col[3],b_col[4],false,main_draw_alpha)
                dl:AddRect(p_min, p_max, border_col_u32, 20, 15, 1)
                fn.draw_police_ambient(dl, p_min, p_max, main_draw_alpha)
                fn.draw_neon_border(dl, p_min, p_max, main_draw_alpha)
                local title_text = u8"Exclusive Design"
                local title_pos  = imgui.ImVec2(p_min.x+20, p_min.y+15)
                imgui.SetCursorScreenPos(title_pos)
                if imgui.InvisibleButton("##title_btn", imgui.CalcTextSize(title_text)) then
                    state.is_discord_layout = not state.is_discord_layout
                end
                state.title_anim_state = fn.anim_update(state.title_anim_state, imgui.IsItemHovered() and 1 or 0, CBUGER_GET_ANIM_RATE(15))
                imgui.SetWindowFontScale(1+(0.05*state.title_anim_state))
                imgui.SetCursorScreenPos(title_pos)
                local tc_c = fx_cfg.title_button_color
                imgui.TextColored(imgui.ImVec4(
                    fn.lerp(tc_c[1],1,state.title_anim_state),
                    fn.lerp(tc_c[2],1,state.title_anim_state),
                    fn.lerp(tc_c[3],1,state.title_anim_state),
                    (tc_c[4] or 1)*state.global_alpha), title_text)
                imgui.SetWindowFontScale(1.0)
                local cross_p = imgui.ImVec2(p_min.x+state.window_size.w-25, p_min.y+25)
                imgui.SetCursorScreenPos(imgui.ImVec2(cross_p.x-15, cross_p.y-15))
                if imgui.InvisibleButton("##closecross", imgui.ImVec2(30,30)) then state.target_main[0]=false end
                fn.draw_cross(dl, cross_p, 12, imgui.IsItemHovered(), main_draw_alpha)
                local eye_p = imgui.ImVec2(p_min.x+state.window_size.w-65, p_min.y+25)
                imgui.SetCursorScreenPos(imgui.ImVec2(eye_p.x-15, eye_p.y-15))
                if imgui.InvisibleButton("##closeeye", imgui.ImVec2(30,30)) then state.is_collapsed = not state.is_collapsed end
                fn.draw_eye(dl, eye_p, 12, state.eye_anim_state, imgui.IsItemHovered(), main_draw_alpha)
                local settings_p = imgui.ImVec2(p_min.x+state.window_size.w/2, p_min.y+25)
                imgui.SetCursorScreenPos(imgui.ImVec2(settings_p.x-12, settings_p.y-12))
                if imgui.InvisibleButton("##settings_btn", imgui.ImVec2(24,24)) then state.target_editor[0] = not state.target_editor[0] end
                state.settings_icon_anim = fn.anim_update(state.settings_icon_anim, imgui.IsItemHovered() and 1 or 0, CBUGER_GET_ANIM_RATE(10))
                fn.draw_animated_settings_icon(dl, settings_p, 11, state.settings_icon_anim, state.settings_time, main_draw_alpha)
                if imgui.IsMouseClicked(0) and imgui.IsWindowHovered() then
                    if mp.y >= p_min.y and mp.y <= p_min.y+45 and mp.x >= p_min.x and mp.x <= p_min.x+state.window_size.w then
                        state.is_dragging = true
                        state.drag_offset.x = mp.x - win_pos.x
                        state.drag_offset.y = mp.y - win_pos.y
                    end
                end
                imgui.SetCursorPos(imgui.ImVec2(20, 55))
                state.slider_pos = fn.anim_update(state.slider_pos, state.current_tab, CBUGER_GET_ANIM_RATE(14))
                local tp   = imgui.ImVec2(p_min.x+20, p_min.y+55)
                local tc   = fx_cfg.tabs_color
                local tb_c = fx_cfg.tab_buttons_text_color
                if state.is_discord_layout then
                    local sidebar_w = 110
                    dl:AddRectFilled(tp, imgui.ImVec2(tp.x+sidebar_w, tp.y+state.window_size.h-75), fn.pack_color(1,1,1,0.04,false,main_draw_alpha), 15)
                    dl:AddRect(tp, imgui.ImVec2(tp.x+sidebar_w, tp.y+state.window_size.h-75), border_col_u32, 15, 15, 1)
                    local item_h = 42
                    local s_min = imgui.ImVec2(tp.x+3, tp.y+(item_h*(state.slider_pos-1))+3)
                    local s_max = imgui.ImVec2(tp.x+sidebar_w-3, tp.y+(item_h*state.slider_pos)-3)
                    dl:AddRectFilled(s_min, s_max, fn.pack_color(tc[1],tc[2],tc[3],0.15,false,main_draw_alpha), 12)
                    fn.draw_wave_strings(dl, s_min, s_max, fx_cfg.waves_color, main_draw_alpha)
                    local mask_col = fn.pack_color(win_bg_color[1]+.04,win_bg_color[2]+.04,win_bg_color[3]+.04,win_bg_color[4],false,main_draw_alpha)
                    dl:AddRect(s_min, s_max, mask_col, 12, 15, 6)
                    dl:AddRect(s_min, s_max, fn.pack_color(tc[1],tc[2],tc[3],0.6,false,main_draw_alpha), 12, 15, 1.2)
                    for i = 1, 3 do
                        imgui.SetCursorScreenPos(imgui.ImVec2(tp.x, tp.y+item_h*(i-1)))
                        if imgui.InvisibleButton("t "..i, imgui.ImVec2(sidebar_w, item_h)) then state.current_tab=i end
                        if imgui.IsItemHovered() then fn.set_hand_cursor() end
                        local tsz = imgui.CalcTextSize(lists.tabs[i])
                        local tb_alpha = state.current_tab==i and 1 or 0.4
                        dl:AddText(imgui.ImVec2(tp.x+(sidebar_w-tsz.x)/2, tp.y+item_h*(i-1)+(item_h-tsz.y)/2),
                            fn.pack_color(tb_c[1],tb_c[2],tb_c[3],tb_alpha*(tb_c[4] or 1),false,main_draw_alpha), lists.tabs[i])
                    end
                else
                    local tw = state.window_size.w-40
                    dl:AddRectFilled(tp, imgui.ImVec2(tp.x+tw, tp.y+42), fn.pack_color(1,1,1,0.04,false,main_draw_alpha), 21)
                    dl:AddRect(tp, imgui.ImVec2(tp.x+tw, tp.y+42), border_col_u32, 21, 15, 1)
                    local iw = tw/3
                    local s_min = imgui.ImVec2(tp.x+iw*(state.slider_pos-1)+3, tp.y+3)
                    local s_max = imgui.ImVec2(tp.x+iw*state.slider_pos-3, tp.y+39)
                    dl:AddRectFilled(s_min, s_max, fn.pack_color(tc[1],tc[2],tc[3],0.15,false,main_draw_alpha), 18)
                    fn.draw_wave_strings(dl, s_min, s_max, fx_cfg.waves_color, main_draw_alpha)
                    local mask_col = fn.pack_color(win_bg_color[1]+.04,win_bg_color[2]+.04,win_bg_color[3]+.04,win_bg_color[4],false,main_draw_alpha)
                    dl:AddRect(s_min, s_max, mask_col, 18, 15, 6)
                    dl:AddRect(s_min, s_max, fn.pack_color(tc[1],tc[2],tc[3],0.6,false,main_draw_alpha), 18, 15, 1.2)
                    for i = 1, 3 do
                        imgui.SetCursorScreenPos(imgui.ImVec2(tp.x+iw*(i-1), tp.y))
                        if imgui.InvisibleButton("t "..i, imgui.ImVec2(iw, 42)) then state.current_tab=i end
                        if imgui.IsItemHovered() then fn.set_hand_cursor() end
                        local tsz = imgui.CalcTextSize(lists.tabs[i])
                        local tb_alpha = state.current_tab==i and 1 or 0.4
                        dl:AddText(imgui.ImVec2(tp.x+iw*(i-1)+(iw-tsz.x)/2, tp.y+(42-tsz.y)/2),
                            fn.pack_color(tb_c[1],tb_c[2],tb_c[3],tb_alpha*(tb_c[4] or 1),false,main_draw_alpha), lists.tabs[i])
                    end
                end
                local content_x = state.is_discord_layout and 140 or 20
                local content_y = state.is_discord_layout and 55  or 110
                local child_w   = state.is_discord_layout and (state.window_size.w-160) or (state.window_size.w-40)
                local child_h   = state.is_discord_layout and (state.window_size.h-90)  or (state.window_size.h-140)
                imgui.SetCursorPos(imgui.ImVec2(content_x, content_y))
                imgui.BeginChild("MainArea", imgui.ImVec2(child_w, child_h), false, imgui.WindowFlags.NoScrollbar)
                    local cw = child_w
                    state.anim_tab_pos = fn.anim_update(state.anim_tab_pos, state.current_tab, CBUGER_GET_ANIM_RATE(12))
                    local sx = -(state.anim_tab_pos-1)*(cw+40)
                    local function draw_p(idx, cb)
                        imgui.SetCursorPos(imgui.ImVec2(sx+(cw+40)*(idx-1), -state.scroll_pos))
                        imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(20,20))
                        imgui.BeginChild("Page_"..idx, imgui.ImVec2(cw, child_h+state.max_scroll), false, imgui.WindowFlags.NoScrollbar)
                        imgui.SetCursorPos(imgui.ImVec2(10,15))
                        imgui.BeginGroup()
                        cb()
                        imgui.EndGroup()
                        imgui.EndChild()
                        imgui.PopStyleVar()
                    end
                    draw_p(1, function()
                        fn.DrawAutoText(u8"Основные настройки", false, true)
                        imgui.Dummy(imgui.ImVec2(0,10))
                        fn.DrawAutoText(u8"Описание", false, true)
                        fn.DrawAutoText(u8"Настройте цвета, эффекты и другие параметры в визуальном редакторе.", true, false)
                        imgui.Dummy(imgui.ImVec2(0,10))
                        for i = 1, 25 do fn.DrawAutoText(u8"Пример строки # "..i, false, false) end
                    end)
                    draw_p(2, function()
                        fn.ios_toggle(u8"Привязка по HWID", settings.hwid, main_draw_alpha); imgui.Dummy(imgui.ImVec2(0,15))
                        fn.ios_slider(u8"Громкость", settings.volume, 0, 1, main_draw_alpha); imgui.Dummy(imgui.ImVec2(0,20))
                        fn.ios_slider(u8"Яркость", settings.brightness, 0, 1, main_draw_alpha)
                    end)
                    draw_p(3, function()
                        fn.DrawAutoText(u8"Пусто здесь. Будет заполнено разработчиком.", true, false)
                    end)
                imgui.EndChild()
                local scroll_x      = p_min.x+state.window_size.w-12
                local scroll_area_y = state.is_discord_layout and (win_pos.y+55) or (win_pos.y+110)
                imgui.SetCursorScreenPos(imgui.ImVec2(scroll_x-5, scroll_area_y))
                imgui.InvisibleButton("##scrollzone", imgui.ImVec2(15, child_h))
                if imgui.IsItemActive() then
                    state.scroll_target = math.max(0, math.min(state.max_scroll,
                        (io.MousePos.y-scroll_area_y-25)/(child_h-50)*state.max_scroll))
                end
                state.scroll_pos = fn.anim_update(state.scroll_pos, state.scroll_target, CBUGER_GET_ANIM_RATE(12))
                local thumb_y = scroll_area_y+(state.scroll_pos/state.max_scroll)*(child_h-50)
                local c_sb_bg   = active_colors[imgui.Col.ScrollbarBg]
                local c_sb_grab = active_colors[imgui.Col.ScrollbarGrab]
                dl:AddRectFilled(imgui.ImVec2(scroll_x+1,scroll_area_y), imgui.ImVec2(scroll_x+3,scroll_area_y+child_h),
                    fn.pack_color(c_sb_bg[1],c_sb_bg[2],c_sb_bg[3],c_sb_bg[4],false,main_draw_alpha), 1.5)
                dl:AddRectFilled(imgui.ImVec2(scroll_x,thumb_y), imgui.ImVec2(scroll_x+4,thumb_y+50),
                    fn.pack_color(c_sb_grab[1],c_sb_grab[2],c_sb_grab[3],c_sb_grab[4],false,main_draw_alpha), 2)
                if state.eye_anim_state < 0.05 then
                    imgui.SetCursorPos(imgui.ImVec2(state.window_size.w-20, state.window_size.h-20))
                    imgui.InvisibleButton("##resizer", imgui.ImVec2(20,20))
                    if imgui.IsItemClicked() then
                        state.is_resizing = true
                        state.resize_start_size.w, state.resize_start_size.h = state.window_size.w, state.window_size.h
                        state.resize_start_mouse.x, state.resize_start_mouse.y = io.MousePos.x, io.MousePos.y
                    end
                    if imgui.IsItemHovered() or state.is_resizing then fn.set_resize_cursor() end
                    dl:AddLine(imgui.ImVec2(p_min.x+state.window_size.w-5, p_min.y+state.window_size.h-2),
                               imgui.ImVec2(p_min.x+state.window_size.w-2, p_min.y+state.window_size.h-5), accentU32(nil, 1.0, 0.67*main_draw_alpha), 1.5)
                end
                local author_text = "by Pryanix"
                local author_size = imgui.CalcTextSize(author_text)
                local footer_y    = state.window_size.h-25
                local center_x    = p_min.x+state.window_size.w/2
                local hover_w     = author_size.x+100
                imgui.SetCursorPos(imgui.ImVec2((state.window_size.w-hover_w)/2, footer_y-5))
                imgui.InvisibleButton("##footer_hover", imgui.ImVec2(hover_w, author_size.y+10))
                if imgui.IsItemHovered() then state.footer_timer=1.0
                elseif state.footer_timer > 0 then state.footer_timer=state.footer_timer-ui_anim.dt end
                local show_icons = state.footer_timer > 0
                state.footer_anim_state = fn.anim_update(state.footer_anim_state, show_icons and 1 or 0, CBUGER_GET_ANIM_RATE(10))
                local footer_txt_col = active_colors[imgui.Col.Text]
                dl:AddText(imgui.ImVec2(center_x-author_size.x/2, p_min.y+footer_y),
                    fn.pack_color(footer_txt_col[1],footer_txt_col[2],footer_txt_col[3],1-state.footer_anim_state,false,main_draw_alpha), author_text)
                if state.footer_anim_state > 0.01 then
                    local icon_alpha  = state.footer_anim_state*main_draw_alpha
                    local slide_off   = 20+25*state.footer_anim_state
                    local yt_center   = imgui.ImVec2(center_x-slide_off, p_min.y+footer_y+author_size.y/2)
                    local tg_center   = imgui.ImVec2(center_x+slide_off, p_min.y+footer_y+author_size.y/2)
                    local yt_hovered, tg_hovered = false, false
                    if show_icons then
                        imgui.SetCursorScreenPos(imgui.ImVec2(yt_center.x-12, yt_center.y-12))
                        if imgui.InvisibleButton("##yt_btn", imgui.ImVec2(24,24)) then os.execute("explorer https://youtube.com/") end
                        if imgui.IsItemHovered() then fn.set_hand_cursor(); yt_hovered=true; state.footer_timer=1 end
                        imgui.SetCursorScreenPos(imgui.ImVec2(tg_center.x-12, tg_center.y-12))
                        if imgui.InvisibleButton("##tg_btn", imgui.ImVec2(24,24)) then os.execute("explorer https://t.me/pryanix_dev") end
                        if imgui.IsItemHovered() then fn.set_hand_cursor(); tg_hovered=true; state.footer_timer=1 end
                    end
                    local yt_bg = yt_hovered and fn.pack_color(1,0,0,icon_alpha,true,1) or fn.pack_color(.6,.6,.6,icon_alpha,true,1)
                    local fg    = fn.pack_color(1,1,1,icon_alpha,true,1)
                    dl:AddRectFilled(imgui.ImVec2(yt_center.x-10,yt_center.y-7), imgui.ImVec2(yt_center.x+10,yt_center.y+7), yt_bg, 4)
                    dl:AddTriangleFilled(imgui.ImVec2(yt_center.x-3,yt_center.y-4), imgui.ImVec2(yt_center.x-3,yt_center.y+4), imgui.ImVec2(yt_center.x+4,yt_center.y), fg)
                    local tg_bg = tg_hovered and fn.pack_color(.15,.65,.9,icon_alpha,true,1) or fn.pack_color(.6,.6,.6,icon_alpha,true,1)
                    dl:AddCircleFilled(tg_center, 10, tg_bg, 24)
                    dl:AddTriangleFilled(imgui.ImVec2(tg_center.x-4,tg_center.y+2), imgui.ImVec2(tg_center.x+5,tg_center.y-5), imgui.ImVec2(tg_center.x,tg_center.y+1), fg)
                    dl:AddTriangleFilled(imgui.ImVec2(tg_center.x+5,tg_center.y-5), imgui.ImVec2(tg_center.x+2,tg_center.y+5), imgui.ImVec2(tg_center.x,tg_center.y+1), fg)
                    dl:AddLine(imgui.ImVec2(tg_center.x,tg_center.y+1), imgui.ImVec2(tg_center.x-1,tg_center.y+4), fg, 1)
                end
            imgui.End()
            imgui.PopStyleColor(pushes_count)
            imgui.PopStyleVar(2)
        end
        end
        render_state_main_window()
        local function render_state_editor_window()
        if state.editor_alpha > 0.01 then
            state.current_rendering_window = "editor"
            state.editor_current_frame_max_w = 400
            local editor_draw_alpha = state.editor_alpha * CBUGER_GET_INTERFACE_ALPHA()
            if state.editor_is_resizing then
                state.editor_window_size.w = math.max(350, state.editor_resize_start_size.w+(io.MousePos.x-state.editor_resize_start_mouse.x))
                state.editor_window_size.h = math.max(400, state.editor_resize_start_size.h+(io.MousePos.y-state.editor_resize_start_mouse.y))
            else
                state.editor_content_max_w = fn.anim_update(state.editor_content_max_w, state.editor_current_frame_max_w, 5)
                state.editor_window_size.w = fn.anim_update(state.editor_window_size.w, math.max(state.editor_window_size.w, state.editor_content_max_w), 10)
            end
            if state.editor_is_dragging then
                imgui.SetNextWindowPos(imgui.ImVec2(io.MousePos.x-state.editor_drag_offset.x, io.MousePos.y-state.editor_drag_offset.y), imgui.Cond.Always)
            end
            imgui.SetNextWindowSize(imgui.ImVec2(state.editor_window_size.w, state.editor_window_size.h), imgui.Cond.Always)
            local pushes_e_count = 0
            imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0,0,0,0)); pushes_e_count=pushes_e_count+1
            local pop_b_col = active_colors[imgui.Col.Border] or {1,1,1,1}
            imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(pop_b_col[1],pop_b_col[2],pop_b_col[3],(pop_b_col[4] or 1)*editor_draw_alpha)); pushes_e_count=pushes_e_count+1
            if imgui.Col.PopupBg then
                local pbc = active_colors[imgui.Col.PopupBg] or {0.08,0.08,0.1,0.98}
                imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(pbc[1],pbc[2],pbc[3],(pbc[4] or 0.98)*editor_draw_alpha)); pushes_e_count=pushes_e_count+1
            end
            imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, editor_draw_alpha)
            imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(0,0))
            imgui.Begin("##style_editor_anim", nil,
                imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoCollapse +
                imgui.WindowFlags.NoResize   + imgui.WindowFlags.NoMove)
                local ed_p = imgui.GetWindowPos()
                local ed_s = imgui.GetWindowSize()
                local dl   = imgui.GetWindowDrawList()
                local ep_min = ed_p
                local ep_max = imgui.ImVec2(ed_p.x+ed_s.x, ed_p.y+ed_s.y)
                dl:AddRectFilled(ep_min, ep_max,
                    fn.pack_color(win_bg_color[1],win_bg_color[2],win_bg_color[3],win_bg_color[4],true,editor_draw_alpha), 15)
                local b_col = active_colors[imgui.Col.Border]
                local border_col_u32 = fn.pack_color(b_col[1],b_col[2],b_col[3],b_col[4],false,editor_draw_alpha)
                dl:AddRect(ep_min, ep_max, border_col_u32, 15, 15, 1)
                fn.draw_police_ambient(dl, ep_min, ep_max, editor_draw_alpha)
                fn.draw_neon_border(dl, ep_min, ep_max, editor_draw_alpha)
                local header_hovered = false
                local cross_p = imgui.ImVec2(ep_max.x-25, ep_min.y+25)
                imgui.SetCursorScreenPos(imgui.ImVec2(cross_p.x-15, cross_p.y-15))
                if imgui.InvisibleButton("##closeeditor", imgui.ImVec2(30,30)) then state.target_editor[0]=false end
                if imgui.IsItemHovered() then header_hovered=true; fn.set_hand_cursor() end
                fn.draw_cross(dl, cross_p, 12, imgui.IsItemHovered(), editor_draw_alpha)
                if imgui.IsMouseClicked(0) and not header_hovered and imgui.IsWindowHovered() then
                    if io.MousePos.y >= ep_min.y and io.MousePos.y <= ep_min.y+45 and
                       io.MousePos.x >= ep_min.x and io.MousePos.x <= ep_max.x then
                        state.editor_is_dragging = true
                        state.editor_drag_offset.x = io.MousePos.x - ed_p.x
                        state.editor_drag_offset.y = io.MousePos.y - ed_p.y
                    end
                end
                imgui.SetCursorPos(imgui.ImVec2(15, 20))
                imgui.TextColored(accentVec4(getTabAccent(), 1.0, 1.0), Fn.T(u8"Редактор стиля"))
                imgui.SetCursorPos(imgui.ImVec2(15, 50))
                local tab_w = (ed_s.x-40)/2
                local active_tab_col   = imgui.ImVec4(fx_cfg.tabs_color[1] or 1, fx_cfg.tabs_color[2] or 1, fx_cfg.tabs_color[3] or 1, 0.6)
                local inactive_tab_col = accentVec4(getTabAccent(), 0.08, 0.55)
                imgui.PushStyleColor(imgui.Col.Button, state.editor_tab==1 and active_tab_col or inactive_tab_col)
                if imgui.Button(Fn.T(u8"Цвета"), imgui.ImVec2(tab_w, 35)) then state.editor_tab=1 end
                imgui.PopStyleColor(1)
                if imgui.IsItemHovered() then fn.set_hand_cursor() end
                imgui.SameLine(15+tab_w+10)
                imgui.PushStyleColor(imgui.Col.Button, state.editor_tab==2 and active_tab_col or inactive_tab_col)
                if imgui.Button(Fn.T(u8"Эффекты"), imgui.ImVec2(tab_w, 35)) then state.editor_tab=2 end
                imgui.PopStyleColor(1)
                if imgui.IsItemHovered() then fn.set_hand_cursor() end
                imgui.SetCursorPos(imgui.ImVec2(15, 95))
                local old_scroll_size     = style.ScrollbarSize
                local old_scroll_rounding = style.ScrollbarRounding
                style.ScrollbarSize = 6; style.ScrollbarRounding = 12
                imgui.BeginChild("##style_scroll", imgui.ImVec2(ed_s.x-30, ed_s.y-110), false)
                    imgui.Indent(10)
                    if state.editor_tab == 1 then
                        imgui.TextColored(accentVec4(getTabAccent(), 1.0, 1.0), Fn.T(u8"Общие настройки"))
                        imgui.Dummy(imgui.ImVec2(0,5))
                        fn.ios_toggle(u8"Плавное закрытие окна", settings.smooth_close, editor_draw_alpha)
                        imgui.Dummy(imgui.ImVec2(0,5))
                        if fn.CustomColorPicker(u8"Базовый цвет интерфейса", "global_base", fx_cfg.global_base_color, true, editor_draw_alpha) then
                            fn.ApplyGlobalTheme(fx_cfg.global_base_color[1], fx_cfg.global_base_color[2], fx_cfg.global_base_color[3])
                        end
                        imgui.Dummy(imgui.ImVec2(0,5))
                        FontCombo(u8"Выбор шрифта", state.current_font_idx)
                        imgui.Dummy(imgui.ImVec2(0,10)); imgui.Separator(); imgui.Dummy(imgui.ImVec2(0,10))
                        imgui.TextColored(accentVec4(getTabAccent(), 1.0, 1.0), Fn.T(u8"Расширенные настройки цветов"))
                        imgui.Dummy(imgui.ImVec2(0,5))
                        local categories = {
                            {id=1, name="Фон и окна"},  {id=2, name="Кнопки и элементы"},
                            {id=3, name="Флажки и шапки"}, {id=4, name="Скроллбар"}, {id=5, name="Текст и рамки"},
                        }
                        for _, cat in ipairs(categories) do
                            fn.record_width(imgui.CalcTextSize(u8(cat.name)).x+100)
                            if imgui.TreeNodeStr(Fn.T(u8(cat.name))) then
                                imgui.Dummy(imgui.ImVec2(0,3))
                                for _, col in ipairs(lists.imgui_colors) do
                                    if col.cat == cat.id and col.id ~= nil then
                                        imgui.PushID("cat_"..tostring(col.id))
                                        local clr_table = active_colors[col.id]
                                        if clr_table then fn.CustomColorPicker(u8(col.name), "custom_"..tostring(col.id), clr_table, true, editor_draw_alpha) end
                                        imgui.PopID()
                                        imgui.Dummy(imgui.ImVec2(0,3))
                                        if col.id == imgui.Col.Text then
                                            fn.CustomColorPicker(u8"Текст на кнопках (вкладки)", "tab_btn_text_col", fx_cfg.tab_buttons_text_color, true, editor_draw_alpha)
                                            imgui.Dummy(imgui.ImVec2(0,3))
                                        end
                                    end
                                end
                                imgui.TreePop()
                            end
                            imgui.Dummy(imgui.ImVec2(0,2))
                        end
                        imgui.Dummy(imgui.ImVec2(0,5))
                        fn.record_width(imgui.CalcTextSize(u8"Иконки и элементы").x+100)
                        if imgui.TreeNodeStr(Fn.T(u8"Иконки и элементы")) then
                            imgui.Dummy(imgui.ImVec2(0,3))
                            fn.CustomColorPicker(u8"Неоновая рамка окна",    "neon_border_col",   fx_cfg.neon_border_color,   true, editor_draw_alpha); imgui.Dummy(imgui.ImVec2(0,3))
                            fn.CustomColorPicker(u8"Цвет вкладок (ползунок волн)", "tabs_col",    fx_cfg.tabs_color,          true, editor_draw_alpha); imgui.Dummy(imgui.ImVec2(0,3))
                            fn.CustomColorPicker(u8"Цвет заголовка редактора","title_col",        fx_cfg.title_color,         true, editor_draw_alpha); imgui.Dummy(imgui.ImVec2(0,3))
                            fn.CustomColorPicker(u8"Цвет кнопки Exclusive Design","title_button_col", fx_cfg.title_button_color, true, editor_draw_alpha); imgui.Dummy(imgui.ImVec2(0,3))
                            fn.CustomColorPicker(u8"Крестик (закрытие)",     "cross_col",         fx_cfg.icon_cross_color,    true, editor_draw_alpha); imgui.Dummy(imgui.ImVec2(0,3))
                            fn.CustomColorPicker(u8"Глаз (свернуть)",        "eye_col",           fx_cfg.icon_eye_color,      true, editor_draw_alpha); imgui.Dummy(imgui.ImVec2(0,3))
                            fn.CustomColorPicker(u8"Шестерёнка (настройки)", "gear_col",          fx_cfg.icon_gear_color,     true, editor_draw_alpha)
                            imgui.TreePop()
                        end
                        imgui.Dummy(imgui.ImVec2(0,10))
                    elseif state.editor_tab == 2 then
                        fn.ios_toggle(u8"Курсор-частицы", fx_cfg.sparks_on, editor_draw_alpha)
                        if fx_cfg.sparks_on[0] then
                            imgui.Dummy(imgui.ImVec2(0,5)); fn.ios_slider(u8"Скорость частиц", fx_cfg.sparks_speed, 0.1, 3, editor_draw_alpha)
                            imgui.Dummy(imgui.ImVec2(0,5)); fn.ios_slider(u8"Размер частиц",   fx_cfg.sparks_size,  0.5, 3, editor_draw_alpha)
                            imgui.Dummy(imgui.ImVec2(0,5)); fn.SafeCombo(u8"Режим курсора", fx_cfg.cursor_fx_var, lists.cursor_fx)
                            imgui.Dummy(imgui.ImVec2(0,5)); fn.CustomColorPicker(u8"Цвет частиц", "sparks_col", fx_cfg.sparks_color, true, editor_draw_alpha)
                        end
                        imgui.Dummy(imgui.ImVec2(0,15)); fn.ios_toggle(u8"Анимация вкладок", fx_cfg.waves_on, editor_draw_alpha)
                        if fx_cfg.waves_on[0] then
                            imgui.Dummy(imgui.ImVec2(0,5)); fn.ios_slider(u8"Скорость анимации", fx_cfg.waves_speed, 0.1, 3, editor_draw_alpha)
                            imgui.Dummy(imgui.ImVec2(0,5)); fn.SafeCombo(u8"Режим анимации", fx_cfg.waves_var, lists.waves_modes)
                            imgui.Dummy(imgui.ImVec2(0,5)); fn.CustomColorPicker(u8"Цвет анимации", "waves_col", fx_cfg.waves_color, true, editor_draw_alpha)
                        end
                        imgui.Dummy(imgui.ImVec2(0,15)); fn.ios_toggle(u8"Фоновое свечение (Ambient)", fx_cfg.ambient_on, editor_draw_alpha)
                        if fx_cfg.ambient_on[0] then
                            imgui.Dummy(imgui.ImVec2(0,5)); fn.ios_slider(u8"Скорость", fx_cfg.ambient_speed, 0.1, 3, editor_draw_alpha)
                            imgui.Dummy(imgui.ImVec2(0,5)); fn.SafeCombo(u8"Режим свечения", fx_cfg.ambient_var, lists.ambient_modes)
                            imgui.Dummy(imgui.ImVec2(0,5)); fn.CustomColorPicker(u8"Основной цвет (1)", "ambient_col_1", fx_cfg.ambient_color_1, true, editor_draw_alpha)
                            imgui.Dummy(imgui.ImVec2(0,3)); fn.CustomColorPicker(u8"Дополнительный цвет (2)", "ambient_col_2", fx_cfg.ambient_color_2, true, editor_draw_alpha)
                        end
                    end
                    imgui.Unindent(10)
                imgui.EndChild()
                style.ScrollbarSize = old_scroll_size; style.ScrollbarRounding = old_scroll_rounding
                imgui.SetCursorPos(imgui.ImVec2(state.editor_window_size.w-20, state.editor_window_size.h-20))
                imgui.InvisibleButton("##editor_resizer", imgui.ImVec2(20,20))
                if imgui.IsItemClicked() then
                    state.editor_is_resizing = true
                    state.editor_resize_start_size.w, state.editor_resize_start_size.h = state.editor_window_size.w, state.editor_window_size.h
                    state.editor_resize_start_mouse.x, state.editor_resize_start_mouse.y = io.MousePos.x, io.MousePos.y
                end
                if imgui.IsItemHovered() or state.editor_is_resizing then fn.set_resize_cursor() end
                dl:AddLine(imgui.ImVec2(ep_min.x+state.editor_window_size.w-5, ep_min.y+state.editor_window_size.h-2),
                           imgui.ImVec2(ep_min.x+state.editor_window_size.w-2, ep_min.y+state.editor_window_size.h-5), accentU32(nil, 1.0, 0.67*editor_draw_alpha), 1.5)
            imgui.End()
            imgui.PopStyleColor(pushes_e_count)
            imgui.PopStyleVar(2)
        end
        end
        render_state_editor_window()
        if has_pushed_font then
            pcall(imgui.PopFont)
        end
        renderHeadIcons()
        renderCbugWindow()
        renderHzWindow()
    end
)
local function openWheel(locked)
    closeModulesForRadial()
    local sw2,sh2=getScreenResolution()
    S.cx=sw2/2; S.cy=sh2/2; S.open=true; S.visible=true
    S.locked=locked; S.anim=0; S.hovered=-1
    S.waiting_key=false; S.bind_target=-1; S.bind_pulse_time=0; S.bind_cancelled=false; S.bind_conflict=false
    S.tilt_nx=0; S.tilt_ny=0; S.tilt_infl=0
    for i=1,N do S.hover_t[i]=0 end
    imgui.Process=true
end
imgui.OnInitialize(function()
    pcall(CBUGER_HEADICONS_REFRESH_FONTS)
end)
function main()
    if type(CB) ~= 'table' then CB = {} end
    if type(CB.ui) ~= 'table' then CB.ui = {} end
    while not isSampAvailable() do wait(100) end
    CBUGER_RUNTIME_READY = false
    CBUGER_NATIVE_READY  = false
    CBUGER_RENDER_READY  = false
    local stable_ticks = 0
    while stable_ticks < 10 do
        if CBUGER_IS_GAME_STABLE() then
            stable_ticks = stable_ticks + 1
        else
            stable_ticks = 0
        end
        wait(100)
    end
    CBUGER_RUNTIME_READY = true
    CBUGER_NATIVE_READY  = true
    CBUGER_RENDER_READY  = true
    pcall(function()
        my_samp_id = select(2, sampGetPlayerIdByCharHandle(PLAYER_PED))
    end)
    sampRegisterChatCommand('icons', function()
        window_state[0] = not window_state[0]
        pcall(sampSetCursorMode, 0)
        saveSettings()
    end)
    sampRegisterChatCommand('okno', function()
        if S.locked then S.locked=false; S.open=false; imgui.Process=false
        else openWheel(true) end
    end)
    wait(500)
    cbug_playtime_start    = os.clock()
    cbug_run.session_start = os.clock()
    sampRegisterChatCommand("cbug", function(args)
        if args == "set" then
            mainWindow[0] = not mainWindow[0]
        else
            cbug_cfg.settings.active = not cbug_cfg.settings.active
            cbug_session.shots = 0; cbug_session.active = false
            sampAddChatMessage("{32CD32}[CBug Speed]{FFFFFF} Трекер: " ..
                (cbug_cfg.settings.active and "{00FF00}Включён" or "{FF0000}Выключен"), -1)
            inicfg.save(cbug_cfg, cbug_cfg_name)
        end
    end)
    local dl_status = CBUGER_CORE.libs.moonloader.download_status
    hz_cbug_playtime_start    = os.clock()
    hz_cbug_run.session_start = os.clock()
    lua_thread.create(pkill)
    wait(75)
    if not doesFileExist((CBUGER_CONFIG .. "icons_cbuger.png")) then
        downloadUrlToFile("https://raw.githubusercontent.com/pryanixscript/CBUGER/main/icons.png",
            CBUGER_CONFIG .. "icons_cbuger.png",
            function(_, status)
                if status == dl_status.STATUS_ENDDOWNLOADDATA then
                    icons_tex_path = (CBUGER_CONFIG .. "icons_cbuger.png")
                end
            end)
    else
        icons_tex_path = (CBUGER_CONFIG .. "icons_cbuger.png")
    end
    sampRegisterChatCommand("hz", function()
        hz_mainWindow[0] = not hz_mainWindow[0]
    end)
    pkillFont = renderCreateFont(hz_cfg.main.pkillfont, hz_cfg.main.pkillfontsize, hz_cfg.main.pkillfontflag)
    ownFont   = renderCreateFont(hz_cfg.main.ownstatefont, hz_cfg.main.ownstatefontsize, hz_cfg.main.ownstatefontflag)
    lua_thread.create(SCR.run)
    wait(150)
    lua_thread.create(PT.run)
    wait(150)
    lua_thread.create(CB.run)
    local function CBUGER_ANY_MODULE_OPEN()
    return state.target_main[0] or state.target_editor[0]
        or CBUGER_MODULE_ACTIVE('cbug_speed', mainWindow[0], CBUGER_GET_ANIM_RATE(15))
        or CBUGER_MODULE_ACTIVE('hitzones_main', hz_mainWindow[0], CBUGER_GET_ANIM_RATE(15))
        or CBUGER_MODULE_ACTIVE('hitzones_stats', statsWindowOpen[0], CBUGER_GET_ANIM_RATE(15))
        or CBUGER_MODULE_ACTIVE('hitzones_compare', compareOpen[0], CBUGER_GET_ANIM_RATE(15))
        or CBUGER_MODULE_ACTIVE('hitmarker', hm_window_open[0], CBUGER_GET_ANIM_RATE(15))
        or CBUGER_MODULE_ACTIVE('headicons', window_state[0], CBUGER_GET_ANIM_RATE(15))
        or CBUGER_MODULE_ACTIVE('smart_crosshair', RT.window[0], CBUGER_GET_ANIM_RATE(15))
        or CBUGER_MODULE_ACTIVE('pianotiles', pt_windowSettings[0], CBUGER_GET_ANIM_RATE(15))
        or CBUGER_MODULE_ACTIVE('cbuger_neon',
            CB.neon.target_main[0] or CB.neon.target_editor[0], CBUGER_GET_ANIM_RATE(15))
end
    local function CBUGER_CB_UI_REQUIRES_PROCESS()
        local cb_ui = type(CB) == 'table' and CB.ui or nil
        if type(cb_ui) ~= 'table' then return false end

        local function ptr_enabled(ptr)
            if ptr == nil then return false end
            local ok, value = pcall(function() return ptr[0] end)
            return ok and value and true or false
        end

        for _, field in ipairs({'guide_open', 'keyboard', 'mouse', 'show_logs'}) do
            if ptr_enabled(cb_ui[field]) then return true end
        end
        local combo_visible = ptr_enabled(cb_ui.show_combo_window)
        local cb_state = type(CB.state) == 'table' and CB.state or nil
        return combo_visible and cb_state ~= nil and cb_state.current_combo ~= nil
    end

    local function CBUGER_CB_UI_INTERACTIVE()
        local cb_neon = type(CB) == 'table' and CB.neon or nil
        local cb_ui = type(CB) == 'table' and CB.ui or nil
        local function on(ptr)
            if ptr == nil then return false end
            local ok, value = pcall(function() return ptr[0] end)
            return ok and value and true or false
        end
        if type(cb_ui) == 'table' and on(cb_ui.guide_open) then return true end
        if type(cb_neon) ~= 'table' then return false end
        if on(cb_neon.target_main) or on(cb_neon.target_editor) or on(cb_neon.target_combo_editor) then return true end
        return (tonumber(cb_neon.main_alpha) or 0) > 0.01
            or (tonumber(cb_neon.editor_alpha) or 0) > 0.01
            or (tonumber(cb_neon.combo_editor_alpha) or 0) > 0.01
    end

    local was_in_game = false
    local hi_timer = 0
    local next_cbug_stats_save = os.clock() + 30
    while true do
        wait(0)
        if CBUGER_RETRY_PENDING_WRITES then pcall(CBUGER_RETRY_PENDING_WRITES) end
        local now_c = os.clock()
        if now_c >= next_cbug_stats_save then
            next_cbug_stats_save = now_c + 30
            if type(cbugerSaveCbugHzStats) == 'function' then pcall(cbugerSaveCbugHzStats) end
        end
        if now_c - hi_timer >= 0.1 then
            hi_timer = now_c
            local in_game = doesCharExist(PLAYER_PED)
            if in_game and not was_in_game then
                if auto_enable_on_join[0] then script_enabled[0] = true end
            end
            was_in_game = in_game
            local ok_id, sid = pcall(function()
                return select(2, sampGetPlayerIdByCharHandle(PLAYER_PED))
            end)
            if ok_id and sid then my_samp_id = sid end
            if pending_placement_target ~= nil then
                local tgt = pending_placement_target
                pending_placement_target = nil
                startPlacementMode(tgt)
            end
            if placement_mode.active then pcall(sampSetCursorMode, 3) end
        end
        if S.waiting_key and S.bind_target >= 1 then
            for vk = 0x08, 0xFE do
                if vk~=0x01 and vk~=0x02 and vk~=0x04 and vk~=CFG.KEY_HOLD and vk~=0x1B then
                    if isKeyJustPressed(vk) then
                        local usedBy = -1
                        for j = 1, N do
                            if j ~= S.bind_target and bindingsVk[j] == vk then usedBy = j; break end
                        end
                        if usedBy == -1 then
                            bindingsVk[S.bind_target] = vk
                            bindings[S.bind_target]   = wheelKeyName(vk)
                            wheel_saveSettings()
                            S.waiting_key=false; S.bind_target=-1; S.bind_pulse_time=0
                        else
                            S.bind_conflict = true
                            bind_conflict_msg_time = os.clock()
                            pcall(sampAddChatMessage,
                                u8('{FF4444}[Cbuger] ') .. u8('Эта клавиша уже занята пунктом «') ..
                                (items[usedBy] and items[usedBy].label or ('#'..usedBy)) .. u8('»'), -1)
                        end
                        break
                    end
                end
            end
            if isKeyJustPressed(0x1B) then S.waiting_key=false; S.bind_target=-1; S.bind_pulse_time=0; S.bind_conflict=false end
        end
                        local wheelInputBlocked = false
        local wantsTyping = false
        local ok_wk, captured_wk = pcall(function()
            local io_wk = imgui.GetIO()
            return io_wk and io_wk.WantCaptureKeyboard or false
        end)
        if ok_wk then wantsTyping = captured_wk and true or false end
        local chatOrDialog = false
        pcall(function() chatOrDialog = sampIsChatInputActive() or sampIsDialogActive() end)
        local pauseActive = false
        pcall(function() pauseActive = isPauseMenuActive() end)
        wheelInputBlocked = wantsTyping or chatOrDialog or pauseActive

        if not S.waiting_key and not wheelInputBlocked then
            for i = 1, N do
                if bindingsVk[i] ~= 0 and isKeyJustPressed(bindingsVk[i]) then
                    activateWheelItem(i)
                    break
                end
            end
        end
        local held = isKeyDown(CFG.KEY_HOLD)
        if cbug_just_opened and not held then cbug_just_opened = false end
        if hz_just_opened   and not held then hz_just_opened   = false end
        if not held then
            S.hold_consumed = false
        end
        local cbuger_module_open = CBUGER_ANY_MODULE_OPEN()
        if not wheelInputBlocked and not S.waiting_key
           and held and not S.hold_consumed and cbuger_module_open
           and not S.open and not S.locked and isKeyJustPressed(CFG.KEY_HOLD) then
            state.target_main[0] = false
            state.target_editor[0] = false
            mainWindow[0] = false
            hz_mainWindow[0] = false
            statsWindowOpen[0] = false
            compareOpen[0] = false
            hm_window_open[0] = false
            window_state[0] = false
            RT.window[0] = false
            pt_windowSettings[0] = false
            S.hold_consumed = true
            imgui.Process = true
            openWheel(false)
        elseif not wheelInputBlocked and not S.waiting_key
           and held and not S.hold_consumed and not S.open and not S.locked
           and not cbuger_module_open and not cbug_just_opened and not hz_just_opened
           and isKeyJustPressed(CFG.KEY_HOLD) then
            S.hold_consumed = true
            openWheel(false)
        end
        if not held and S.open and not S.locked and not S.waiting_key then S.open=false end
        local cursor_ui_needed = S.open or S.locked or placement_mode.active or CBUGER_ANY_MODULE_OPEN() or CBUGER_CB_UI_INTERACTIVE()
        imgui.Process = cursor_ui_needed or CBUGER_CB_UI_REQUIRES_PROCESS()
        if S._cursor_was_needed and not cursor_ui_needed then
            CBUGER_FORCE_HIDE_CURSOR()
        end
        S._cursor_was_needed = cursor_ui_needed and true or false
    end
end
do
    local function HM_U32(c) return CBUGER_ApplyOverlayAlphaU32(imgui.ColorConvertFloat4ToU32(c)) end
    local lfs_hm = require("lfs")
    local ffi_hm = ffi
    pcall(function() ffi.cdef[[ unsigned long GetTickCount(); ]] end)
    local imagesFolder_hm = CBUGER_ROOT .. "HitMarker"
    local hm_globalMarkerTexture  = nil
    local hm_selectedGlobalMarker = nil
    local hm_globalHoleTexture    = nil
    local hm_selectedGlobalHole   = nil
    local hm_textureCache = {}
    local HM_IMG_QUEUE_IDX = 1
    local hm_ac_enabled = new.bool(false)
    local hm_ac_speed   = new.int(2000)
    local hm_isCapturingKey = false
    local hm_selBulletIdx   = new.int(1)
    local hm_selHoleIdx     = new.int(1)
    local HM_VK_NAMES = {
        [0x01]="LButton",[0x02]="RButton",[0x08]="Backspace",[0x09]="Tab",
        [0x0D]="Enter",[0x10]="Shift",[0x11]="Ctrl",[0x12]="Alt",
