        [0x60]="Num0",[0x61]="Num1",[0x62]="Num2",[0x63]="Num3",[0x64]="Num4",
        [0x65]="Num5",[0x66]="Num6",[0x67]="Num7",[0x68]="Num8",[0x69]="Num9",
    }
    local function hm_getKeyName(vk)
        if vk==0 then return u8("Не назначена") end
        return HM_VK_NAMES[vk] or string.format("VK_%d",vk)
    end
    local function hm_ensureFolder()
        if not doesDirectoryExist(imagesFolder_hm) then createDirectory(imagesFolder_hm) end
    end
    local function hm_getImagesList()
        local files={}; table.insert(files,"")
        if doesDirectoryExist(imagesFolder_hm) then
            for file in lfs_hm.dir(imagesFolder_hm) do
                if file~="." and file~=".." then
                    local ext=file:match("^.+%.([^%.]+)$")
                    if ext then ext=ext:lower()
                        if ext=="png" or ext=="jpg" or ext=="jpeg" then
                            table.insert(files,file)
                        end
                    end
                end
            end
        end
        return files
    end
    local function hm_loadTex(filename)
        if not filename or filename=="" then return nil end
        if hm_textureCache[filename] then return hm_textureCache[filename] end
        local p=imagesFolder_hm.."\\"..filename
        if doesFileExist(p) then
            local t=imgui.CreateTextureFromFile(p)
            if t then hm_textureCache[filename]=t; return t end
        end
        return nil
    end
    local function hm_releaseTex()
        for _,t in pairs(hm_textureCache) do imgui.ReleaseTexture(t) end
        hm_textureCache={}
        hm_globalMarkerTexture=nil; hm_selectedGlobalMarker=nil
        hm_globalHoleTexture=nil;   hm_selectedGlobalHole=nil
    end
    local function hm_getFixPos(p1,p2,d)
        d=math.abs(d)
        local dir={x=p2.x-p1.x,y=p2.y-p1.y,z=p2.z-p1.z}
        local len=math.sqrt(dir.x^2+dir.y^2+dir.z^2)
        if len==0 then return p1 end
        dir.x,dir.y,dir.z=dir.x/len,dir.y/len,dir.z/len
        return {x=p1.x+dir.x*d,y=p1.y+dir.y*d,z=p1.z+dir.z*d}
    end
    local function hm_colorEdit4(label,ct,flags)
        local buf=new.float[4](ct[1],ct[2],ct[3],ct[4])
        flags=flags or (imgui.ColorEditFlags.NoInputs+imgui.ColorEditFlags.AlphaBar)
        if imgui.ColorEdit4(label,buf,flags) then
            ct[1]=buf[0];ct[2]=buf[1];ct[3]=buf[2];ct[4]=buf[3]; return true
        end
        return false
    end
    local function hm_drawMarker(DL,tex,cx,cy,radius,colorU32,segs)
        if tex then
            if segs>3 and DL.AddImageRounded then
                DL:AddImageRounded(tex,imgui.ImVec2(cx-radius,cy-radius),imgui.ImVec2(cx+radius,cy+radius),
                    imgui.ImVec2(0,0),imgui.ImVec2(1,1),colorU32,radius,imgui.DrawCornerFlags_All,segs)
            else
                DL:AddImage(tex,imgui.ImVec2(cx-radius,cy-radius),imgui.ImVec2(cx+radius,cy+radius),
                    imgui.ImVec2(0,0),imgui.ImVec2(1,1),colorU32)
            end
        else
            if segs>2 then DL:AddCircleFilled(imgui.ImVec2(cx,cy),radius,colorU32,segs)
            elseif segs==0 then DL:AddRectFilled(imgui.ImVec2(cx-radius,cy-radius),imgui.ImVec2(cx+radius,cy+radius),colorU32,0.0,imgui.DrawFlags_None)
            else DL:AddCircleFilled(imgui.ImVec2(cx,cy),radius,colorU32,12) end
        end
    end
    local function hm_resolveTex(obj,globalTex)
        if obj.selectedTex and obj.selectedTex~="" then return hm_loadTex(obj.selectedTex) end
        return globalTex
    end
    local hm_config = {}
    function hm_config:default()
        return {
            version=11, hotkey_vk=0,
            global_marker_texture=nil, global_hole_texture=nil,
            my_bullets={
                draw=true,hide_all=false,thickness=1.4,circle_radius=4,
                degree_polygon=32,max_markers=20,marker_transparency=1.0,max_hits=0,
                use_custom_markers=false,
                color_all={0.8,0.8,0.8,1.0},color_hit={1.0,0.0,0.0,1.0},color_text={1.0,1.0,1.0,1.0},
                additional={movement_type=0,movement_distance=20,speed=1.0,
                    random_hit_colors=false,enable_tracers=true,
                    marker_text="",marker_text_size=10.0}
            },
            bullet_holes={
                enabled=true,use_custom_texture=false,use_marker_style=true,radius=3.0,max_holes=30,
                fade_time=10.0,hole_transparency=1.0,color={0.1,0.1,0.1,1.0},degree_polygon=8
            },
            image_queue={names="",auto_on=false,auto_ms=2000},
            folderpath_config=CBUGER_CONFIG:gsub("\\$",""),
            filepath_json=CBUGER_CONFIG.."HitMarker.json",
        }
    end
    function hm_config:update(cur,def)
        local out={}
        for k,v in pairs(def) do
            if type(v)=="table" and not v[1] and not def[k][1] then out[k]=hm_config:update({},v)
            else out[k]=v end
        end
        for k,v in pairs(cur) do
            if def[k]~=nil then
                if type(v)=="table" and type(def[k])=="table" and not v[1] and not def[k][1] then
                    out[k]=hm_config:update(v,def[k])
                else out[k]=v end
            end
        end
        return out
    end
    function hm_config:save(t)
        local p = self:default().filepath_json
        local ok, js = pcall(encodeJson, t)
        if not ok or type(js) ~= 'string' then return false end
        return CBUGER_SAFE_WRITE_FILE(p, js)
    end
    function hm_config:load()
        local def = self:default()
        local jc = CBUGER_SAFE_LOAD_JSON(def.filepath_json, function(value)
            return type(value.my_bullets) == 'table' or type(value.bullet_holes) == 'table'
                or type(value.image_queue) == 'table'
        end)
        if type(jc) == 'table' then
            if not jc.version or jc.version < def.version then
                local upd = hm_config:update(jc, def)
                upd.version = def.version
                pcall(hm_config.save, hm_config, upd)
                return upd
            end
            return hm_config:update(jc, def)
        end
        pcall(hm_config.save, hm_config, def)
        return def
    end
    function hm_config:to_imgui(conf)
        local def=self:default(); conf=self:update(conf,def)
        local ig={}; ig.version=new.int(conf.version)
        local mb=conf.my_bullets
        ig.my_bullets={
            draw=new.bool(mb.draw),hide_all=new.bool(mb.hide_all or false),
            thickness=new.float(mb.thickness),circle_radius=new.float(mb.circle_radius),
            degree_polygon=new.int(math.min(mb.degree_polygon or 32,40)),
            max_markers=new.int(mb.max_markers),marker_transparency=new.float(mb.marker_transparency),
            max_hits=new.int(mb.max_hits),use_custom_markers=new.bool(mb.use_custom_markers),
            color_all={mb.color_all[1],mb.color_all[2],mb.color_all[3],mb.color_all[4]},
            color_hit={mb.color_hit[1],mb.color_hit[2],mb.color_hit[3],mb.color_hit[4]},
            color_text={mb.color_text[1],mb.color_text[2],mb.color_text[3],mb.color_text[4]},
            additional={
                movement_type=new.int(math.min(mb.additional.movement_type,3)),
                movement_distance=new.float(mb.additional.movement_distance),
                speed=new.float(mb.additional.speed),
                random_hit_colors=new.bool(mb.additional.random_hit_colors),
                enable_tracers=new.bool(mb.additional.enable_tracers),
                marker_text_buffer=new.char[256](),
                marker_text_size=new.float(mb.additional.marker_text_size),
            }
        }
        local raw=mb.additional.marker_text or ""
        local tbuf=raw
        do
            local nc=false
            for i=1,#raw do if raw:byte(i)>0x7F then nc=true; break end end
            if nc then local ok,r=pcall(u8,raw); if ok and r then tbuf=r end end
        end
        local cl=math.min(#tbuf,255); ffi.copy(ig.my_bullets.additional.marker_text_buffer,tbuf,cl)
        ig.my_bullets.additional.marker_text_buffer[cl]=0
        local bh=conf.bullet_holes
        ig.bullet_holes={
            enabled=new.bool(bh.enabled),use_custom_texture=new.bool(bh.use_custom_texture),
            use_marker_style=new.bool(bh.use_marker_style == true or bh.use_marker_style == 1),
            radius=new.float(math.max(0.5,math.min(80,tonumber(bh.radius) or 3.0))),max_holes=new.int(bh.max_holes),
            fade_time=new.float(bh.fade_time),hole_transparency=new.float(bh.hole_transparency or 1.0),
            degree_polygon=new.int(math.min(bh.degree_polygon or 8,40)),
            color={bh.color[1],bh.color[2],bh.color[3],bh.color[4]},
        }
        return ig
    end
    function hm_config:to_table(ci)
        local t={}; t.version=ci.version[0]; t.hotkey_vk=hm_hotkey[0]
        t.global_marker_texture=hm_selectedGlobalMarker; t.global_hole_texture=hm_selectedGlobalHole
        local mb=ci.my_bullets; local mba=mb.additional
        t.my_bullets={
            draw=mb.draw[0],hide_all=mb.hide_all[0],thickness=mb.thickness[0],
            circle_radius=mb.circle_radius[0],degree_polygon=mb.degree_polygon[0],
            max_markers=mb.max_markers[0],marker_transparency=mb.marker_transparency[0],
            max_hits=mb.max_hits[0],use_custom_markers=mb.use_custom_markers[0],
            color_all={mb.color_all[1],mb.color_all[2],mb.color_all[3],mb.color_all[4]},
            color_hit={mb.color_hit[1],mb.color_hit[2],mb.color_hit[3],mb.color_hit[4]},
            color_text={mb.color_text[1],mb.color_text[2],mb.color_text[3],mb.color_text[4]},
            additional={
                movement_type=mba.movement_type[0],movement_distance=mba.movement_distance[0],
                speed=mba.speed[0],random_hit_colors=mba.random_hit_colors[0],
                enable_tracers=mba.enable_tracers[0],marker_text=ffi.string(mba.marker_text_buffer),
                marker_text_size=mba.marker_text_size[0],
            }
        }
        local bh=ci.bullet_holes
        t.bullet_holes={
            enabled=bh.enabled[0],use_custom_texture=bh.use_custom_texture[0],
            use_marker_style=bh.use_marker_style[0],
            radius=math.max(0.5,math.min(80,bh.radius[0])),max_holes=bh.max_holes[0],fade_time=bh.fade_time[0],
            hole_transparency=bh.hole_transparency[0],degree_polygon=bh.degree_polygon[0],
            color={bh.color[1],bh.color[2],bh.color[3],bh.color[4]},
        }
        local def=self:default(); t.folderpath_config=def.folderpath_config; t.filepath_json=def.filepath_json
        local parts={}; for _,nm in ipairs(HM_IMG_QUEUE) do parts[#parts+1]=nm end
        t.image_queue={names=table.concat(parts,"|"),auto_on=hm_autoCycle.enabled,auto_ms=hm_autoCycle.speed_ms}
        return t
    end
    local function hm_ensureDir()
        local def = hm_config:default()
        if not doesDirectoryExist(def.folderpath_config) then
            pcall(createDirectory, def.folderpath_config)
        end
    end
    hm_ensureDir()
    local hm_ct  = hm_config:load()
    hm_ct.bullet_holes.use_marker_style = true
    hm_config:save(hm_ct)
    hm_ci  = hm_config:to_imgui(hm_ct)
    hm_ci.bullet_holes.use_marker_style[0] = true
    local hm_lastJson = nil
    local function hm_saveNow()
        hm_ci.bullet_holes.use_marker_style[0] = true
        local payload=hm_config:to_table(hm_ci)
        local ok,js=pcall(encodeJson,payload)
        if ok and js and js==hm_lastJson then return end
        local saved = hm_config:save(payload)
        if saved and ok and js then hm_lastJson = js end
    end
    hm_hotkey[0]=hm_ct.hotkey_vk or 0
    if hm_ct.global_marker_texture and hm_ct.global_marker_texture~="" then
        hm_selectedGlobalMarker=hm_ct.global_marker_texture
        hm_globalMarkerTexture=hm_loadTex(hm_selectedGlobalMarker)
    end
    if hm_ct.global_hole_texture and hm_ct.global_hole_texture~="" then
        hm_selectedGlobalHole=hm_ct.global_hole_texture
        hm_globalHoleTexture=hm_loadTex(hm_selectedGlobalHole)
    end
    do
        local iq=hm_ct.image_queue or {}; local raw=iq.names or ""
        if type(raw)=="string" and raw~="" then
            for nm in raw:gmatch("[^|]+") do if nm~="" then HM_IMG_QUEUE[#HM_IMG_QUEUE+1]=nm end end
        end
        hm_autoCycle.enabled=iq.auto_on==true or iq.auto_on==1
        hm_autoCycle.speed_ms=math.max(1,math.min(30000,tonumber(iq.auto_ms) or 2000))
        hm_ac_enabled[0]=hm_autoCycle.enabled; hm_ac_speed[0]=hm_autoCycle.speed_ms
    end
    pcall(function()
        local payload=hm_config:to_table(hm_ci)
        local ok,js=pcall(encodeJson,payload)
        if ok and type(js)=="string" then
            local saved=hm_config:save(payload)
            if saved then hm_lastJson=js end
        end
    end)
    local hm_slEdit={}; local hm_slFocus={}
    local function hm_slLabel(l) return l:match("^(.-)##") or l, l:match("##(.+)$") or l end
    local function hm_eDragFloat(label,v,spd,vmin,vmax,fmt,w)
        local vis,id=hm_slLabel(label); local key="hmdf_"..id
        imgui.SetNextItemWidth(w or 200)
        if hm_slEdit[key] then
            if hm_slFocus[key] then imgui.SetKeyboardFocusHere(0); hm_slFocus[key]=nil end
            local fl=imgui.InputTextFlags.EnterReturnsTrue+imgui.InputTextFlags.AutoSelectAll
            local ch=imgui.InputFloat("##hme_"..id,v,0,0,fmt or "%.2f",fl)
            if ch or imgui.IsItemDeactivated() then v[0]=math.max(vmin,math.min(vmax,v[0])); hm_slEdit[key]=nil end
            imgui.SameLine(0,8); imgui.TextDisabled(vis); return ch
        else
            local ch=imgui.DragFloat(label,v,spd or 1.0,vmin,vmax,fmt or "%.2f")
            if imgui.IsItemHovered() and imgui.IsMouseDoubleClicked(0) then hm_slEdit[key]=true; hm_slFocus[key]=true end
            return ch
        end
    end
    local function hm_eDragInt(label,v,spd,vmin,vmax,fmt,w)
        local vis,id=hm_slLabel(label); local key="hmdi_"..id
        imgui.SetNextItemWidth(w or 200)
        if hm_slEdit[key] then
            if hm_slFocus[key] then imgui.SetKeyboardFocusHere(0); hm_slFocus[key]=nil end
            local fl=imgui.InputTextFlags.EnterReturnsTrue+imgui.InputTextFlags.AutoSelectAll
            local ch=imgui.InputInt("##hme_"..id,v,0,0,fl)
            if ch or imgui.IsItemDeactivated() then v[0]=math.max(vmin,math.min(vmax,v[0])); hm_slEdit[key]=nil end
            imgui.SameLine(0,8); imgui.TextDisabled(vis); return ch
        else
            local ch=imgui.DragInt(label,v,spd or 1,vmin,vmax,fmt or "%d")
            if imgui.IsItemHovered() and imgui.IsMouseDoubleClicked(0) then hm_slEdit[key]=true; hm_slFocus[key]=true end
            return ch
        end
    end
    local function hm_texCombo(labelId,curFile,tint,popId,psz)
        local dn=(curFile and curFile~="") and curFile or u8("-- Отключить --")
        local chosen=nil
        imgui.SetNextWindowSizeConstraints(imgui.ImVec2(280,0), imgui.ImVec2(320,300))
        if CBUGER_MarqueeBeginCombo(labelId, dn) then
            local list=hm_getImagesList(); local tc=tint or {1,1,1,1}
            imgui.BeginChild("##hmtexlist",imgui.ImVec2(300,math.min(#list*26+8,260)),false)
            for _,fn2 in ipairs(list) do
                local isSel=(curFile==fn2)
                local showName=(fn2=="") and u8("-- Отключить --") or fn2
                local tex2=(fn2~="") and hm_loadTex(fn2) or nil
                if tex2 then
                    local sz=psz or 20
                    imgui.Image(tex2,imgui.ImVec2(sz,sz),imgui.ImVec2(0,0),imgui.ImVec2(1,1),
                        imgui.ImVec4(tc[1],tc[2],tc[3],tc[4])); imgui.SameLine()
                end
                if CBUGER_MarqueeSelectable(showName, popId..fn2, isSel) then chosen=fn2 end
                if isSel then imgui.SetItemDefaultFocus() end
            end
            imgui.EndChild()
            imgui.EndCombo()
        end
        return chosen
    end
    local function hm_imgQueuePos(name)
        for i,n in ipairs(HM_IMG_QUEUE) do if n==name then return i end end; return nil
    end
    local function hm_imgQueueToggle(name)
        local pos=hm_imgQueuePos(name)
        if pos then
            table.remove(HM_IMG_QUEUE,pos)
            if HM_IMG_QUEUE_IDX>#HM_IMG_QUEUE and #HM_IMG_QUEUE>0 then HM_IMG_QUEUE_IDX=1 end
        else HM_IMG_QUEUE[#HM_IMG_QUEUE+1]=name end
    end
    hm_imgQueueAdvance = function()
        if #HM_IMG_QUEUE==0 then return end
        HM_IMG_QUEUE_IDX=(HM_IMG_QUEUE_IDX%#HM_IMG_QUEUE)+1
        local nm=HM_IMG_QUEUE[HM_IMG_QUEUE_IDX]
        if nm and nm~="" then
            hm_selectedGlobalMarker=nm; hm_globalMarkerTexture=hm_loadTex(nm)
            if not hm_ci.my_bullets.use_custom_markers[0] then hm_ci.my_bullets.use_custom_markers[0]=true end
            hm_saveNow()
        end
    end
    local function hm_processHit(data)
        if not hm_isRunning then return false end
        local con=hm_ci.my_bullets; local maxH=con.max_hits[0]
        local hv,hX,hY,hZ=convert3DCoordsToScreenEx(data.target.x,data.target.y,data.target.z,false,false)
        if not hv or hZ<=0 then return false end
        local hitDone=false; local toRem={}
        for i=#hm_bullets,1,-1 do
            local m=hm_bullets[i]
            if m.isVisible and m.screenX and m.screenY then
                local r=con.circle_radius[0]; local dx=hX-m.screenX; local dy=hY-m.screenY
                if dx*dx+dy*dy<=r*r then
                    hitDone=true; m.hitTime=os.clock()
                    if con.additional.random_hit_colors[0] then
                        m.hitColor={math.random(),math.random(),math.random(),con.color_hit[4]}
                    else local ch=con.color_hit; m.hitColor={ch[1],ch[2],ch[3],ch[4]} end
                    m.hits=m.hits+1
                    local bhcfg=hm_ci.bullet_holes
                    if bhcfg.enabled[0] then
                        local mx=bhcfg.max_holes[0]
                        if mx>0 then while #hm_bulletHoles>=mx do table.remove(hm_bulletHoles,1) end end
                        table.insert(hm_bulletHoles,{
                            worldPos={x=data.target.x,y=data.target.y,z=data.target.z},
                            markerRef=m,
                            screenOffset={x=hX-m.screenX,y=hY-m.screenY},
                            hitColor={m.hitColor[1],m.hitColor[2],m.hitColor[3],m.hitColor[4]},
                            spawnTime=os.clock(),selectedTex=m.selectedTex,
                        })
                    end
                    if maxH>0 and m.hits>=maxH then table.insert(toRem,i) end
                    break
                end
            end
        end
        if #toRem>0 then
            table.sort(toRem,function(a,b) return a>b end)
            for _,idx in ipairs(toRem) do table.remove(hm_bullets,idx) end
            if #hm_bullets==0 and #hm_initialMarkers>0 then
                local ca=con.color_all
                for _,ip in ipairs(hm_initialMarkers) do
                    table.insert(hm_bullets,{startTime=os.clock(),hits=0,hitTime=nil,hitColor={0,0,0,0},
                        currentColor={ca[1],ca[2],ca[3],ca[4]},
                        origin={x=ip.origin.x,y=ip.origin.y,z=ip.origin.z},
                        target={x=ip.base_origin.x,y=ip.base_origin.y,z=ip.base_origin.z},
                        base_origin={x=ip.base_origin.x,y=ip.base_origin.y,z=ip.base_origin.z},
                        thickness=con.thickness[0],circle_radius=con.circle_radius[0],
                        isVisible=false,screenX=nil,screenY=nil,selectedTex=nil,
                    })
                end
            end
        end
        return hitDone
    end
    HM_onSendBulletSync = function(data)
        if not hm_isRunning or not hm_ci or not hm_ci.my_bullets
            or not hm_ci.my_bullets.draw[0] or not data or not data.target or not data.origin then return end
        if #hm_bullets>0 then if hm_processHit(data) then return end end
        local con=hm_ci.my_bullets; local maxM=con.max_markers[0]
        local nowPlace=os.clock()
        if nowPlace-hm_lastMarkerPlace<0.5 then return end
        if maxM==0 or #hm_initialMarkers<maxM then
            hm_lastMarkerPlace=nowPlace
            table.insert(hm_initialMarkers,{
                origin={x=data.origin.x,y=data.origin.y,z=data.origin.z},
                base_origin={x=data.target.x,y=data.target.y,z=data.target.z}
            })
            local ca=con.color_all
            table.insert(hm_bullets,{startTime=os.clock(),hits=0,hitTime=nil,hitColor={0,0,0,0},
                currentColor={ca[1],ca[2],ca[3],ca[4]},
                origin={x=data.origin.x,y=data.origin.y,z=data.origin.z},
                target={x=data.target.x,y=data.target.y,z=data.target.z},
                base_origin={x=data.target.x,y=data.target.y,z=data.target.z},
                thickness=con.thickness[0],circle_radius=con.circle_radius[0],
                isVisible=false,screenX=nil,screenY=nil,selectedTex=nil,
            })
        end
    end
    imgui.OnFrame(
        function()
            return hm_isRunning or (hm_autoCycle and hm_autoCycle.enabled)
        end,
        function(self)
            self.HideCursor = true
            if hm_hotkey[0]~=0 and not hm_window_open[0] and not isPauseMenuActive() then
                if isKeyJustPressed(hm_hotkey[0]) then
                    hm_isRunning = not hm_isRunning
                    hm_lastMarkerPlace = -1
                    if not hm_isRunning then hm_bullets={}; hm_initialMarkers={}; hm_bulletHoles={} end
                end
            end
            if hm_isRunning and hm_autoCycle.enabled and #HM_IMG_QUEUE>0
               and hm_ci and hm_ci.my_bullets.use_custom_markers[0] then
                local now_ms = ffi.C.GetTickCount()
                if (now_ms - hm_autoCycle.last_ms) >= hm_autoCycle.speed_ms then
                    hm_autoCycle.last_ms = now_ms
                    hm_imgQueueAdvance()
                end
            end
            if not hm_isRunning or (#hm_bullets==0 and #hm_bulletHoles==0) then return end
            local DL=imgui.GetBackgroundDrawList()
            local mb=hm_ci.my_bullets; local bh=hm_ci.bullet_holes
            local now=os.clock(); local hideAll=mb.hide_all[0]
            local mt=mb.additional.movement_type[0]
            local md_v=mb.additional.movement_distance[0]
            local ms=mb.additional.speed[0]
            for i=1,#hm_bullets do
                local m=hm_bullets[i]; local t=now-m.startTime
                if mt==1 then m.target.x=m.base_origin.x+md_v*math.sin(t*ms); m.target.y=m.base_origin.y; m.target.z=m.base_origin.z
                elseif mt==2 then m.target.x=m.base_origin.x; m.target.y=m.base_origin.y+md_v*math.sin(t*ms); m.target.z=m.base_origin.z
                elseif mt==3 then m.target.x=m.base_origin.x+md_v*math.sin(t*ms); m.target.y=m.base_origin.y+md_v*math.cos(t*ms); m.target.z=m.base_origin.z
                else m.target.x=m.base_origin.x; m.target.y=m.base_origin.y; m.target.z=m.base_origin.z end
            end
            local mbUseCustom=mb.use_custom_markers[0]; local enableTracers=mb.additional.enable_tracers[0]
            for i=1,#hm_bullets do
                local m=hm_bullets[i]
                local ov,oX,oY,_=convert3DCoordsToScreenEx(m.origin.x,m.origin.y,m.origin.z,false,false)
                local tv,tX,tY,tZ=convert3DCoordsToScreenEx(m.target.x,m.target.y,m.target.z,false,false)
                local onScreen=tv and tZ>0
                if onScreen then m.screenX,m.screenY=tX,tY; m.isVisible=true
                else m.screenX,m.screenY=nil,nil; m.isVisible=false end
                if not onScreen or hideAll then goto hm_cont end
                do
                    if enableTracers then
                        local sX,sY=oX,oY
                        if not ov then
                            local fp=hm_getFixPos(m.origin,m.target,tZ)
                            local fv,fX,fY=convert3DCoordsToScreenEx(fp.x,fp.y,fp.z,false,false)
                            if fv then sX,sY=fX,fY end
                        end
                        local ca=mb.color_all
                        DL:AddLine(imgui.ImVec2(sX,sY),imgui.ImVec2(tX,tY),
                            HM_U32(imgui.ImVec4(ca[1],ca[2],ca[3],ca[4])),mb.thickness[0])
                    end
                    local radius=mb.circle_radius[0]; local transp=mb.marker_transparency[0]
                    local mcv
                    if m.hitTime and (now-m.hitTime<0.15) then
                        local hc=m.hitColor; mcv=imgui.ImVec4(hc[1],hc[2],hc[3],hc[4]*transp)
                    else
                        local ca=mb.color_all; mcv=imgui.ImVec4(ca[1],ca[2],ca[3],ca[4]*transp)
                        if m.hitTime then m.hitTime=nil end
                    end
                    local mcu32=HM_U32(mcv)
                    local mTex=nil; if mbUseCustom then mTex=hm_resolveTex(m,hm_globalMarkerTexture) end
                    hm_drawMarker(DL,mTex,tX,tY,radius,mcu32,mb.degree_polygon[0])
                    local mtext=ffi.string(mb.additional.marker_text_buffer)
                    if #mtext>0 then
                        local ct=mb.color_text
                        local tcu32=HM_U32(imgui.ImVec4(ct[1],ct[2],ct[3],ct[4]*transp))
                        local font2=CBUGER_GET_GLOBAL_FONT_OR(imgui.GetFont()); local scale2=mb.additional.marker_text_size[0]/150.0
                        local fsize=math.max(4.0,math.min(radius*scale2,100.0))
                        local tsz=font2:CalcTextSizeA(fsize,10000.0,0.0,mtext)
                        DL:AddTextFontPtr(font2,fsize,imgui.ImVec2(tX-tsz.x/2,tY-tsz.y/2),tcu32,mtext)
                    end
                end
                ::hm_cont::
            end
            if bh.enabled[0] and not hideAll then
                local fadeTime=bh.fade_time[0]
                local useMarkerStyle=bh.use_marker_style[0]
                local hRadius=math.max(0.5,math.min(80,bh.radius[0]))
                local hSegs=useMarkerStyle and mb.degree_polygon[0] or bh.degree_polygon[0]
                local hAlpha=useMarkerStyle and mb.marker_transparency[0] or bh.hole_transparency[0]
                local bhUseCustom=useMarkerStyle and mb.use_custom_markers[0] or bh.use_custom_texture[0]
                local holeGlobalTexture=useMarkerStyle and hm_globalMarkerTexture or hm_globalHoleTexture
                for i=#hm_bulletHoles,1,-1 do
                    local h=hm_bulletHoles[i]; local elapsed=now-h.spawnTime
                    if fadeTime>0 and elapsed>=fadeTime then table.remove(hm_bulletHoles,i)
                    else
                        local hSX,hSY
                        if h.markerRef and h.screenOffset then
                            local m2=h.markerRef
                            if m2.screenX and m2.screenY then
                                hSX=m2.screenX+h.screenOffset.x
                                hSY=m2.screenY+h.screenOffset.y
                            end
                        else
                            local wx,wy,wz=h.worldPos.x,h.worldPos.y,h.worldPos.z
                            if mt~=0 and h.markerIdx and hm_bullets[h.markerIdx] and h.localOffset then
                                local m2=hm_bullets[h.markerIdx]
                                wx=m2.target.x+h.localOffset.x; wy=m2.target.y+h.localOffset.y; wz=m2.target.z+h.localOffset.z
                            end
                            local hv2,sx2,sy2,sz2=convert3DCoordsToScreenEx(wx,wy,wz,false,false)
                            if hv2 and sz2>0 then hSX,hSY=sx2,sy2 end
                        end
                        local hColor
                        if useMarkerStyle then
                            hColor=mb.additional.random_hit_colors[0] and (h.hitColor or mb.color_hit) or mb.color_hit
                        else
                            hColor=bh.color
                        end
                        local alpha
                        if fadeTime<=0 then alpha=hColor[4]
                        else alpha=math.max(0,1.0-(elapsed/fadeTime))*hColor[4] end
                        alpha=alpha*(hAlpha or 1.0)
                        if hSX and hSY then
                            local cu32=HM_U32(imgui.ImVec4(hColor[1],hColor[2],hColor[3],alpha))
                            local holeTex=nil
                            if bhUseCustom then
                                local textureSource=(useMarkerStyle and h.markerRef) or h
                                holeTex=hm_resolveTex(textureSource,holeGlobalTexture)
                            end
                            hm_drawMarker(DL,holeTex,hSX,hSY,hRadius,cu32,hSegs)
                        end
                    end
                end
            end
        end
    )
    local function hm_renderWindow()
        local module_alpha = CBUGER_UPDATE_MODULE_FADE('hitmarker', hm_window_open[0], CBUGER_GET_ANIM_RATE(15))
        if module_alpha <= 0.01 then return end
        local sx,sy=getScreenResolution()
        imgui.SetNextWindowPos(imgui.ImVec2(sx/2,sy/2),imgui.Cond.FirstUseEver,imgui.ImVec2(0.5,0.5))
        local hm_rst = CBUGER_APPLY_WINDOW_SIZE("hitmarker_main", 520, 420)
        imgui.SetNextWindowSizeConstraints(imgui.ImVec2(420,300),imgui.ImVec2(700,800))
        local ac=getTabAccent()
        imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, CBUGER_GET_INTERFACE_ALPHA() * module_alpha)
        imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding,    8.0)
        imgui.PushStyleVarFloat(imgui.StyleVar.FrameRounding,     5.0)
        imgui.PushStyleVarFloat(imgui.StyleVar.PopupRounding,    10.0)
        imgui.PushStyleVarFloat(imgui.StyleVar.ChildRounding,     6.0)
        imgui.PushStyleVarFloat(imgui.StyleVar.GrabRounding,      4.0)
        imgui.PushStyleVarFloat(imgui.StyleVar.ScrollbarRounding, 4.0)
        local style = imgui.GetStyle()
        local prev_pad   = imgui.ImVec2(style.WindowPadding.x,    style.WindowPadding.y)
        local prev_align = imgui.ImVec2(style.WindowTitleAlign.x,  style.WindowTitleAlign.y)
        style.WindowPadding    = imgui.ImVec2(14, prev_pad.y)
        style.WindowTitleAlign = imgui.ImVec2(0.5, 0.5)
        local hm_open_ptr = hm_window_open[0] and hm_window_open or nil
        imgui.Begin(Fn.T(u8("HitMarker  ::  by Pryanix")),hm_open_ptr,
            imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoResize)
        CBUGER_DRAW_INVISIBLE_RESIZER("hitmarker_main", hm_rst, 420, 300, CBUGER_GET_INTERFACE_ALPHA(), true)
        do
            local mdl = imgui.GetWindowDrawList()
            local mp  = imgui.GetWindowPos()
            local ms  = imgui.GetWindowSize()
            CBUGER_DRAW_GLOBAL_AMBIENT(mdl, mp, imgui.ImVec2(mp.x + ms.x, mp.y + ms.y), CBUGER_GET_INTERFACE_ALPHA())
        end
        style.WindowPadding    = prev_pad
        style.WindowTitleAlign = prev_align
        imgui.PopStyleVar(6)
        local sc=hm_isRunning and imgui.ImVec4(0.3,1.0,0.4,1.0) or imgui.ImVec4(1.0,0.35,0.35,1.0)
        imgui.TextColored(sc,Fn.T(u8(hm_isRunning and "АКТИВЕН" or "ВЫКЛЮЧЕН")))
        imgui.SameLine()
        imgui.TextDisabled(string.format(Fn.T(u8("| Меток: %d  | Дыр: %d")), #hm_bullets, #hm_bulletHoles))
        if hm_hotkey[0]~=0 then
            imgui.SameLine()
            imgui.TextColored(accentVec4(ac,0.85,1.0),string.format("[%s]",hm_getKeyName(hm_hotkey[0])))
        end
        imgui.SameLine(); imgui.TextDisabled("|"); imgui.SameLine()
        if imgui.Checkbox(Fn.T(u8("Слайдшоу##hmqs")),hm_ac_enabled) then
            hm_autoCycle.enabled=hm_ac_enabled[0]; hm_autoCycle.last_ms=ffi_hm.C.GetTickCount(); hm_saveNow()
        end
        if imgui.IsItemHovered() then
            imgui.BeginTooltip()
            imgui.TextUnformatted(Fn.T(u8(#HM_IMG_QUEUE>0
                and string.format("Авто-слайдшоу: %d изобр., %d мс",#HM_IMG_QUEUE,hm_autoCycle.speed_ms)
                or "Авто-слайдшоу (очередь пуста)")))
            imgui.EndTooltip()
        end
        imgui.Spacing()
        local function hm_tabMarkers()
                drawAnimatedTabGlow(imgui.GetWindowDrawList(), imgui.GetItemRectMin(), imgui.GetItemRectMax(), os.clock())
                imgui.Spacing()
                local iw=200
                imgui.TextColored(accentVec4(ac,1.0,1.0),Fn.T(u8("Параметры метки")))
                imgui.Separator(); imgui.Spacing()
                hm_eDragFloat(u8("Радиус метки##hmradius"),hm_ci.my_bullets.circle_radius,0.2,0.5,200,"%.1f",iw)
                hm_eDragInt(u8("Макс. кол-во меток (0=?)##hmmaxm"),hm_ci.my_bullets.max_markers,1,0,200,"%d",iw)
                hm_eDragFloat(u8("Прозрачность (1=непрозр.)##hmtransp"),hm_ci.my_bullets.marker_transparency,0.01,0.0,1.0,"%.2f",iw)
                hm_eDragInt(u8("Попаданий до удаления (0=?)##hmmaxhits"),hm_ci.my_bullets.max_hits,1,0,200,"%d",iw)
                hm_eDragInt(u8("Углы (0=квадрат)##hmpoly"),hm_ci.my_bullets.degree_polygon,1,0,40,"%d",iw)
                imgui.Spacing()
                imgui.Checkbox(Fn.T(u8("Скрыть (метки и дыры)##hmhideAll")),hm_ci.my_bullets.hide_all)
                imgui.Spacing()
                imgui.TextColored(accentVec4(ac,1.0,1.0),Fn.T(u8("Текст внутри метки")))
                imgui.Separator(); imgui.Spacing()
                imgui.SetNextItemWidth(iw+60)
                imgui.InputText(Fn.T(u8("Текст##hmmt")),hm_ci.my_bullets.additional.marker_text_buffer,256)
                hm_eDragFloat(u8("Размер текста##hmtextsz"),hm_ci.my_bullets.additional.marker_text_size,0.5,5.0,100.0,"%.1f",iw)
